mkdir -p /workspace/src && cat > /workspace/src/lexer.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"math/big"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type TokKind int

const (
	TEOF TokKind = iota
	TIdent
	TKeyword
	TPunct
	TNumber
	TBigInt
	TString
	TTemplate // template chunk
	TRegExp
	TPrivateName
)

type Token struct {
	Kind    TokKind
	Val     string // identifier name / punctuator / keyword / string cooked value
	Raw     string // raw source text
	Num     float64
	Big     *big.Int
	Pos     int // byte offset
	Line    int
	Col     int
	NLBefore bool // newline before this token
	// template
	TplTail   bool
	TplCooked *string // nil if invalid escape
	// regexp
	ReFlags string
	// string literal has escape (for use-strict directive check), or ident had escapes
	HasEscape bool
	LegacyOctal bool
}

type SyntaxError struct {
	Msg  string
	Line int
	Col  int
}

func (e *SyntaxError) Error() string { return e.Msg }

type Lexer struct {
	src     string
	pos     int
	line    int
	lineStart int
	tok     Token
	prevEnd int
	// for the parser
	fileName string
	inTemplateDepth int
}

func NewLexer(src string) *Lexer {
	l := &Lexer{src: src, line: 1}
	// hashbang
	if strings.HasPrefix(src, "#!") {
		for l.pos < len(src) && src[l.pos] != '\n' && src[l.pos] != '\r' {
			l.pos++
		}
	}
	return l
}

func (l *Lexer) errAt(pos int, format string, args ...interface{}) {
	line, col := l.lineCol(pos)
	panic(&SyntaxError{Msg: fmt.Sprintf(format, args...), Line: line, Col: col})
}

func (l *Lexer) lineCol(pos int) (int, int) {
	// compute from scratch (only for errors)
	line := 1
	ls := 0
	for i := 0; i < pos && i < len(l.src); i++ {
		c := l.src[i]
		if c == '\n' {
			line++
			ls = i + 1
		} else if c == '\r' {
			if i+1 < len(l.src) && l.src[i+1] == '\n' {
				continue
			}
			line++
			ls = i + 1
		} else if c == 0xE2 && i+2 < len(l.src) && l.src[i+1] == 0x80 && (l.src[i+2] == 0xA8 || l.src[i+2] == 0xA9) {
			line++
			ls = i + 3
		}
	}
	return line, utf8.RuneCountInString(l.src[ls:pos]) + 1
}

func isIDStart(r rune) bool {
	if r < 128 {
		return r == '$' || r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
	}
	return unicode.IsLetter(r) || unicode.Is(unicode.Nl, r) || unicode.Is(unicode.Other_ID_Start, r)
}

func isIDPart(r rune) bool {
	if r < 128 {
		return r == '$' || r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9')
	}
	return isIDStart(r) || unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Mc, r) || unicode.Is(unicode.Nd, r) || unicode.Is(unicode.Pc, r) || unicode.Is(unicode.Other_ID_Continue, r) || r == 0x200C || r == 0x200D
}

func isLineTerm(r rune) bool {
	return r == '\n' || r == '\r' || r == 0x2028 || r == 0x2029
}

func isWS(r rune) bool {
	switch r {
	case ' ', '\t', '\v', '\f', 0xA0, 0xFEFF:
		return true
	}
	if r >= 128 {
		return unicode.Is(unicode.Zs, r)
	}
	return false
}

var keywords = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true, "const": true, "continue": true,
	"debugger": true, "default": true, "delete": true, "do": true, "else": true, "enum": true, "export": true,
	"extends": true, "false": true, "finally": true, "for": true, "function": true, "if": true,
	"import": true, "in": true, "instanceof": true, "new": true, "null": true, "return": true,
	"super": true, "switch": true, "this": true, "throw": true, "true": true, "try": true,
	"typeof": true, "var": true, "void": true, "while": true, "with": true,
}

func (l *Lexer) peekRune() (rune, int) {
	if l.pos >= len(l.src) {
		return -1, 0
	}
	c := l.src[l.pos]
	if c < 0x80 {
		return rune(c), 1
	}
	return utf8.DecodeRuneInString(l.src[l.pos:])
}

func (l *Lexer) runeAt(p int) (rune, int) {
	if p >= len(l.src) {
		return -1, 0
	}
	c := l.src[p]
	if c < 0x80 {
		return rune(c), 1
	}
	return utf8.DecodeRuneInString(l.src[p:])
}

// skipSpace skips whitespace and comments; returns whether a newline was seen
func (l *Lexer) skipSpace() bool {
	nl := false
	for l.pos < len(l.src) {
		r, sz := l.peekRune()
		if r == '\n' {
			l.pos++
			l.line++
			l.lineStart = l.pos
			nl = true
		} else if r == '\r' {
			l.pos++
			if l.pos < len(l.src) && l.src[l.pos] == '\n' {
				l.pos++
			}
			l.line++
			l.lineStart = l.pos
			nl = true
		} else if r == 0x2028 || r == 0x2029 {
			l.pos += sz
			l.line++
			l.lineStart = l.pos
			nl = true
		} else if isWS(r) {
			l.pos += sz
		} else if r == '/' && l.pos+1 < len(l.src) && l.src[l.pos+1] == '/' {
			l.pos += 2
			for l.pos < len(l.src) {
				r2, sz2 := l.peekRune()
				if isLineTerm(r2) {
					break
				}
				l.pos += sz2
			}
		} else if r == '/' && l.pos+1 < len(l.src) && l.src[l.pos+1] == '*' {
			start := l.pos
			l.pos += 2
			closed := false
			for l.pos < len(l.src) {
				r2, sz2 := l.peekRune()
				if r2 == '*' && l.pos+1 < len(l.src) && l.src[l.pos+1] == '/' {
					l.pos += 2
					closed = true
					break
				}
				if r2 == '\n' || r2 == 0x2028 || r2 == 0x2029 {
					nl = true
					l.line++
					l.lineStart = l.pos + sz2
				} else if r2 == '\r' {
					nl = true
					l.line++
					if l.pos+1 < len(l.src) && l.src[l.pos+1] == '\n' {
						l.pos++
					}
					l.lineStart = l.pos + 1
				}
				l.pos += sz2
			}
			if !closed {
				l.errAt(start, "unexpected end of comment")
			}
		} else if r == '<' && strings.HasPrefix(l.src[l.pos:], "<!--") {
			// HTML-like comment
			l.pos += 4
			for l.pos < len(l.src) {
				r2, sz2 := l.peekRune()
				if isLineTerm(r2) {
					break
				}
				l.pos += sz2
			}
		} else if r == '-' && (nl || l.prevEnd == 0 || l.onlyWSBeforeOnLine()) && strings.HasPrefix(l.src[l.pos:], "-->") {
			l.pos += 3
			for l.pos < len(l.src) {
				r2, sz2 := l.peekRune()
				if isLineTerm(r2) {
					break
				}
				l.pos += sz2
			}
		} else {
			break
		}
	}
	return nl
}

func (l *Lexer) onlyWSBeforeOnLine() bool {
	for i := l.lineStart; i < l.pos; i++ {
		c := l.src[i]
		if c != ' ' && c != '\t' {
			return false
		}
	}
	return l.lineStart <= l.pos && l.line >= 1 && (l.pos == l.lineStart || true) && l.lineStart > 0 || l.lineStart == 0 && l.prevEnd == 0
}

// Next scans the next token.
func (l *Lexer) Next() Token {
	nl := l.skipSpace()
	tok := Token{Pos: l.pos, Line: l.line, Col: utf8.RuneCountInString(l.src[l.lineStart:l.pos]) + 1, NLBefore: nl}
	if l.pos >= len(l.src) {
		tok.Kind = TEOF
		l.tok = tok
		return tok
	}
	r, sz := l.peekRune()
	start := l.pos
	switch {
	case isIDStart(r) || r == '\\':
		name, hasEsc := l.scanIdentName()
		tok.Val = name
		tok.HasEscape = hasEsc
		tok.Raw = l.src[start:l.pos]
		if keywords[name] && !hasEsc {
			tok.Kind = TKeyword
		} else {
			tok.Kind = TIdent
		}
	case r == '#':
		l.pos++
		r2, _ := l.peekRune()
		if !(isIDStart(r2) || r2 == '\\') {
			l.errAt(start, "invalid character")
		}
		name, _ := l.scanIdentName()
		tok.Kind = TPrivateName
		tok.Val = name
		tok.Raw = l.src[start:l.pos]
	case r >= '0' && r <= '9' || (r == '.' && l.pos+1 < len(l.src) && l.src[l.pos+1] >= '0' && l.src[l.pos+1] <= '9'):
		l.scanNumber(&tok)
		tok.Raw = l.src[start:l.pos]
	case r == '"' || r == '\'':
		l.scanString(&tok, byte(r))
		tok.Raw = l.src[start:l.pos]
	case r == '`':
		l.pos++
		l.scanTemplate(&tok)
		tok.Raw = l.src[start:l.pos]
	default:
		_ = sz
		l.scanPunct(&tok)
	}
	l.prevEnd = l.pos
	l.tok = tok
	return tok
}

func (l *Lexer) scanIdentName() (string, bool) {
	var sb strings.Builder
	hasEsc := false
	first := true
	for l.pos < len(l.src) {
		r, sz := l.peekRune()
		if r == '\\' {
			start := l.pos
			if l.pos+1 >= len(l.src) || l.src[l.pos+1] != 'u' {
				l.errAt(start, "invalid escape sequence in identifier")
			}
			l.pos += 2
			cp := l.scanUnicodeEscapeBody(start)
			if first {
				if !isIDStart(cp) {
					l.errAt(start, "invalid first character of identifier")
				}
			} else if !isIDPart(cp) {
				l.errAt(start, "invalid character in identifier")
			}
			sb.WriteRune(cp)
			hasEsc = true
		} else if (first && isIDStart(r)) || (!first && isIDPart(r)) {
			sb.WriteRune(r)
			l.pos += sz
		} else {
			break
		}
		first = false
	}
	return sb.String(), hasEsc
}

// after "\u"
func (l *Lexer) scanUnicodeEscapeBody(start int) rune {
	if l.pos < len(l.src) && l.src[l.pos] == '{' {
		l.pos++
		var v rune
		n := 0
		for l.pos < len(l.src) && l.src[l.pos] != '}' {
			d := hexVal(l.src[l.pos])
			if d < 0 {
				l.errAt(start, "invalid Unicode escape")
			}
			v = v*16 + rune(d)
			if v > 0x10FFFF {
				l.errAt(start, "invalid Unicode escape")
			}
			l.pos++
			n++
		}
		if n == 0 || l.pos >= len(l.src) {
			l.errAt(start, "invalid Unicode escape")
		}
		l.pos++
		return v
	}
	if l.pos+4 > len(l.src) {
		l.errAt(start, "invalid Unicode escape")
	}
	var v rune
	for i := 0; i < 4; i++ {
		d := hexVal(l.src[l.pos])
		if d < 0 {
			l.errAt(start, "invalid Unicode escape")
		}
		v = v*16 + rune(d)
		l.pos++
	}
	return v
}

func hexVal(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'F':
		return int(c-'A') + 10
	}
	return -1
}

func (l *Lexer) scanNumber(tok *Token) {
	start := l.pos
	src := l.src
	tok.Kind = TNumber
	isBig := false
	radix := 10
	legacyOctal := false
	if src[l.pos] == '0' && l.pos+1 < len(src) {
		c := src[l.pos+1] | 0x20
		if c == 'x' {
			radix = 16
			l.pos += 2
		} else if c == 'o' {
			radix = 8
			l.pos += 2
		} else if c == 'b' {
			radix = 2
			l.pos += 2
		} else if src[l.pos+1] >= '0' && src[l.pos+1] <= '9' {
			// legacy octal or decimal with leading zero
			legacyOctal = true
			j := l.pos + 1
			isOct := true
			for j < len(src) && src[j] >= '0' && src[j] <= '9' {
				if src[j] >= '8' {
					isOct = false
				}
				j++
			}
			if isOct {
				radix = 8
				l.pos++
				tok.LegacyOctal = true
			}
		} else if src[l.pos+1] == '_' {
			l.errAt(start, "invalid number literal")
		}
	}
	digitsStart := l.pos
	var sb strings.Builder
	lastUnderscore := false
	ndig := 0
	for l.pos < len(src) {
		c := src[l.pos]
		if c == '_' {
			if tok.LegacyOctal || lastUnderscore || ndig == 0 {
				l.errAt(start, "invalid number literal")
			}
			lastUnderscore = true
			l.pos++
			continue
		}
		d := hexVal(c)
		if d < 0 || d >= radix {
			break
		}
		lastUnderscore = false
		sb.WriteByte(c)
		ndig++
		l.pos++
	}
	if lastUnderscore {
		l.errAt(start, "invalid number literal")
	}
	if radix != 10 && ndig == 0 {
		l.errAt(start, "invalid number literal")
	}
	isFloat := false
	if radix == 10 && !tok.LegacyOctal {
		if l.pos < len(src) && src[l.pos] == '.' {
			isFloat = true
			sb.WriteByte('.')
			l.pos++
			lastUnderscore = false
			fd := 0
			for l.pos < len(src) {
				c := src[l.pos]
				if c == '_' {
					if lastUnderscore || fd == 0 {
						l.errAt(start, "invalid number literal")
					}
					lastUnderscore = true
					l.pos++
					continue
				}
				if c < '0' || c > '9' {
					break
				}
				lastUnderscore = false
				sb.WriteByte(c)
				fd++
				l.pos++
			}
			if lastUnderscore {
				l.errAt(start, "invalid number literal")
			}
		}
		if l.pos < len(src) && (src[l.pos] == 'e' || src[l.pos] == 'E') {
			j := l.pos + 1
			if j < len(src) && (src[j] == '+' || src[j] == '-') {
				j++
			}
			if j < len(src) && src[j] >= '0' && src[j] <= '9' {
				isFloat = true
				sb.WriteString("e")
				l.pos++
				if src[l.pos] == '+' || src[l.pos] == '-' {
					sb.WriteByte(src[l.pos])
					l.pos++
				}
				lastUnderscore = false
				for l.pos < len(src) {
					c := src[l.pos]
					if c == '_' {
						if lastUnderscore {
							l.errAt(start, "invalid number literal")
						}
						lastUnderscore = true
						l.pos++
						continue
					}
					if c < '0' || c > '9' {
						break
					}
					lastUnderscore = false
					sb.WriteByte(c)
					l.pos++
				}
				if lastUnderscore {
					l.errAt(start, "invalid number literal")
				}
			} else {
				l.errAt(start, "invalid number literal")
			}
		}
	}
	if l.pos < len(src) && src[l.pos] == 'n' && !isFloat && !legacyOctal {
		isBig = true
		l.pos++
	}
	_ = digitsStart
	// identifier char directly after number is an error
	if l.pos < len(src) {
		r, _ := l.peekRune()
		if isIDStart(r) || (r >= '0' && r <= '9') || r == '\\' {
			l.errAt(start, "invalid number literal")
		}
		if r == '.' && legacyOctal && tok.LegacyOctal {
			// "017." is error? Actually 017.5 -> syntax error in JS. Treat as number followed by '.'
		}
	}
	digits := sb.String()
	if isBig {
		b := new(big.Int)
		if _, ok := b.SetString(digits, radix); !ok {
			l.errAt(start, "invalid number literal")
		}
		tok.Kind = TBigInt
		tok.Big = b
		return
	}
	if radix == 10 {
		if digits == "" {
			l.errAt(start, "invalid number literal")
		}
		f, err := strconv.ParseFloat(digits, 64)
		if err != nil {
			// may be out of range -> Inf
			if ne, ok := err.(*strconv.NumError); ok && ne.Err == strconv.ErrRange {
				tok.Num = f
				return
			}
			l.errAt(start, "invalid number literal")
		}
		tok.Num = f
	} else {
		tok.Num = parseIntRadix(digits, radix)
	}
}

func parseIntRadix(digits string, radix int) float64 {
	// exact for up to 2^53, approximate beyond via big
	if len(digits) <= 12 {
		v, _ := strconv.ParseUint(digits, radix, 64)
		return float64(v)
	}
	b := new(big.Int)
	b.SetString(digits, radix)
	f, _ := new(big.Float).SetInt(b).Float64()
	return f
}

func (l *Lexer) scanString(tok *Token, quote byte) {
	start := l.pos
	l.pos++
	tok.Kind = TString
	var sb strings.Builder
	for {
		if l.pos >= len(l.src) {
			l.errAt(start, "unexpected end of string")
		}
		c := l.src[l.pos]
		if c == quote {
			l.pos++
			break
		}
		if c == '\n' || c == '\r' {
			l.errAt(start, "unexpected end of string")
		}
		if c == '\\' {
			tok.HasEscape = true
			l.pos++
			if l.pos >= len(l.src) {
				l.errAt(start, "unexpected end of string")
			}
			l.scanEscape(&sb, start, false, tok)
			continue
		}
		if c < 0x80 {
			sb.WriteByte(c)
			l.pos++
		} else {
			r, sz := l.peekRune()
			sb.WriteRune(r)
			l.pos += sz
		}
	}
	tok.Val = sb.String()
}

// scanEscape handles the char after a backslash. Writes cooked output to sb.
// Returns false if invalid escape (only in template mode, where errors are deferred).
func (l *Lexer) scanEscape(sb *strings.Builder, start int, template bool, tok *Token) bool {
	c := l.src[l.pos]
	switch c {
	case 'n':
		sb.WriteByte('\n')
		l.pos++
	case 't':
		sb.WriteByte('\t')
		l.pos++
	case 'r':
		sb.WriteByte('\r')
		l.pos++
	case 'b':
		sb.WriteByte('\b')
		l.pos++
	case 'f':
		sb.WriteByte('\f')
		l.pos++
	case 'v':
		sb.WriteByte('\v')
		l.pos++
	case '\r':
		l.pos++
		if l.pos < len(l.src) && l.src[l.pos] == '\n' {
			l.pos++
		}
		l.line++
		l.lineStart = l.pos
	case '\n':
		l.pos++
		l.line++
		l.lineStart = l.pos
	case 'x':
		l.pos++
		if l.pos+2 > len(l.src) || hexVal(l.src[l.pos]) < 0 || hexVal(l.src[l.pos+1]) < 0 {
			if template {
				return false
			}
			l.errAt(start, "malformed escape sequence in string literal")
		}
		v := hexVal(l.src[l.pos])*16 + hexVal(l.src[l.pos+1])
		l.pos += 2
		writeCodeUnit(sb, rune(v))
	case 'u':
		l.pos++
		if template {
			// validate manually
			save := l.pos
			ok := true
			func() {
				defer func() {
					if r := recover(); r != nil {
						ok = false
					}
				}()
				cp := l.scanUnicodeEscapeBody(start)
				writeCodeUnit(sb, cp)
			}()
			if !ok {
				l.pos = save
				return false
			}
		} else {
			cp := l.scanUnicodeEscapeBody(start)
			writeCodeUnit(sb, cp)
		}
	default:
		if c >= '0' && c <= '7' {
			// \0 or legacy octal
			if c == '0' && (l.pos+1 >= len(l.src) || l.src[l.pos+1] < '0' || l.src[l.pos+1] > '9') {
				sb.WriteByte(0)
				l.pos++
				return true
			}
			if template {
				return false
			}
			if tok != nil {
				tok.LegacyOctal = true
			}
			v := 0
			n := 0
			maxn := 3
			if c >= '4' {
				maxn = 2
			}
			for n < maxn && l.pos < len(l.src) && l.src[l.pos] >= '0' && l.src[l.pos] <= '7' {
				v = v*8 + int(l.src[l.pos]-'0')
				l.pos++
				n++
			}
			writeCodeUnit(sb, rune(v))
			return true
		}
		if c == '8' || c == '9' {
			if template {
				return false
			}
			if tok != nil {
				tok.LegacyOctal = true
			}
			sb.WriteByte(c)
			l.pos++
			return true
		}
		if c == 0xE2 && l.pos+2 < len(l.src) && l.src[l.pos+1] == 0x80 && (l.src[l.pos+2] == 0xA8 || l.src[l.pos+2] == 0xA9) {
			// line separator continuation
			l.pos += 3
			return true
		}
		r, sz := l.peekRune()
		sb.WriteRune(r)
		l.pos += sz
	}
	return true
}

// writeCodeUnit writes a code point (possibly a lone surrogate) into sb using WTF-8
func writeCodeUnit(sb *strings.Builder, r rune) {
	if r >= 0xD800 && r <= 0xDFFF {
		// encode lone surrogate as 3-byte sequence (WTF-8)
		sb.WriteByte(byte(0xE0 | (r >> 12)))
		sb.WriteByte(byte(0x80 | ((r >> 6) & 0x3F)))
		sb.WriteByte(byte(0x80 | (r & 0x3F)))
		return
	}
	sb.WriteRune(r)
}

// scanTemplate scans a template chunk after '`' or '}' until '${' or '`'
func (l *Lexer) scanTemplate(tok *Token) {
	start := l.pos - 1
	tok.Kind = TTemplate
	var sb strings.Builder
	var raw strings.Builder
	valid := true
	for {
		if l.pos >= len(l.src) {
			l.errAt(start, "unexpected end of string")
		}
		c := l.src[l.pos]
		if c == '`' {
			l.pos++
			tok.TplTail = true
			break
		}
		if c == '$' && l.pos+1 < len(l.src) && l.src[l.pos+1] == '{' {
			l.pos += 2
			tok.TplTail = false
			break
		}
		if c == '\\' {
			escStart := l.pos
			l.pos++
			if l.pos >= len(l.src) {
				l.errAt(start, "unexpected end of string")
			}
			if !l.scanEscape(&sb, start, true, nil) {
				valid = false
				// skip the bad escape char
				l.pos++
			}
			rawPart := l.src[escStart:l.pos]
			// normalize CRLF/CR to LF in raw
			rawPart = strings.ReplaceAll(rawPart, "\r\n", "\n")
			rawPart = strings.ReplaceAll(rawPart, "\r", "\n")
			raw.WriteString(rawPart)
			continue
		}
		if c == '\r' {
			l.pos++
			if l.pos < len(l.src) && l.src[l.pos] == '\n' {
				l.pos++
			}
			sb.WriteByte('\n')
			raw.WriteByte('\n')
			l.line++
			l.lineStart = l.pos
			continue
		}
		if c == '\n' {
			l.line++
			l.lineStart = l.pos + 1
		}
		if c < 0x80 {
			sb.WriteByte(c)
			raw.WriteByte(c)
			l.pos++
		} else {
			r, sz := l.peekRune()
			if r == 0x2028 || r == 0x2029 {
				l.line++
				l.lineStart = l.pos + sz
			}
			sb.WriteRune(r)
			raw.WriteRune(r)
			l.pos += sz
		}
	}
	tok.Val = raw.String()
	if valid {
		s := sb.String()
		tok.TplCooked = &s
	}
}

// ScanTemplateContinue is called by the parser after the '}' closing a substitution
func (l *Lexer) ScanTemplateContinue() Token {
	// l.pos should be right after the '}' token; we rescan from the '}' position
	tok := Token{Pos: l.pos, Line: l.line, Col: utf8.RuneCountInString(l.src[l.lineStart:l.pos]) + 1}
	start := l.pos
	l.scanTemplate(&tok)
	tok.Raw = l.src[start:l.pos]
	l.prevEnd = l.pos
	l.tok = tok
	return tok
}

var puncts = []string{
	">>>=", "...", "===", "!==", "**=", "<<=", ">>=", ">>>", "&&=", "||=", "??=",
	"=>", "==", "!=", "<=", ">=", "&&", "||", "??", "?.", "++", "--", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<", ">>", "**",
	"{", "}", "(", ")", "[", "]", ";", ",", "<", ">", "+", "-", "*", "/", "%", "&", "|", "^", "!", "~", "?", ":", "=", ".", "@",
}

func (l *Lexer) scanPunct(tok *Token) {
	tok.Kind = TPunct
	rest := l.src[l.pos:]
	for _, p := range puncts {
		if strings.HasPrefix(rest, p) {
			// special: "?." followed by digit is "?" then ".5"
			if p == "?." && len(rest) > 2 && rest[2] >= '0' && rest[2] <= '9' {
				continue
			}
			tok.Val = p
			tok.Raw = p
			l.pos += len(p)
			return
		}
	}
	r, _ := l.peekRune()
	if r == utf8.RuneError || r == -1 {
		l.errAt(l.pos, "unexpected character")
	}
	l.errAt(l.pos, "unexpected character")
}

// ScanRegExp rescans from the current '/' token position as a regexp literal
func (l *Lexer) ScanRegExp(tok Token) Token {
	start := tok.Pos
	l.pos = start + 1
	inClass := false
	for {
		if l.pos >= len(l.src) {
			l.errAt(start, "unexpected end of regexp")
		}
		c := l.src[l.pos]
		if c == '\n' || c == '\r' {
			l.errAt(start, "unexpected line terminator in regexp")
		}
		if c == '\\' {
			l.pos++
			if l.pos >= len(l.src) {
				l.errAt(start, "unexpected end of regexp")
			}
			c2 := l.src[l.pos]
			if c2 == '\n' || c2 == '\r' {
				l.errAt(start, "unexpected line terminator in regexp")
			}
			_, sz := l.peekRune()
			l.pos += sz
			continue
		}
		if c == '[' {
			inClass = true
		} else if c == ']' {
			inClass = false
		} else if c == '/' && !inClass {
			break
		}
		if c >= 0x80 {
			r, sz := l.peekRune()
			if r == 0x2028 || r == 0x2029 {
				l.errAt(start, "unexpected line terminator in regexp")
			}
			l.pos += sz
		} else {
			l.pos++
		}
	}
	body := l.src[start+1 : l.pos]
	l.pos++
	fstart := l.pos
	for l.pos < len(l.src) {
		r, sz := l.peekRune()
		if !isIDPart(r) {
			break
		}
		l.pos += sz
	}
	flags := l.src[fstart:l.pos]
	t := Token{Kind: TRegExp, Val: body, ReFlags: flags, Pos: start, Line: tok.Line, Col: tok.Col, NLBefore: tok.NLBefore}
	t.Raw = l.src[start:l.pos]
	l.prevEnd = l.pos
	l.tok = t
	return t
}

// Reset lexer position to a token (for backtracking)
func (l *Lexer) ResetTo(pos int, line int, lineStart int) {
	l.pos = pos
	l.line = line
	l.lineStart = lineStart
}

func (l *Lexer) State() (int, int, int) { return l.pos, l.line, l.lineStart }

var _ = math.Inf
EOF
echo done

