	LexNames      []LexName   // top-level lexical declarations of the body
	UsesArguments bool
	UsesThis      bool // this/super/new.target referenced (arrows inherit)
	UsesEval      bool // direct eval present -> dynamic scoping
	HasSuperCall  bool
	Source        string // source text for toString
	SrcStart, SrcEnd int
	IsExpr        bool // function expression (name binding scope)
	ClassFields   []*ClassMember // for class constructors: instance fields to init
	HomeObjectNeeded bool
	NameIsComputed bool
	EndPos int
	IsStaticBlock bool
	Line, Col int
	// scope analysis
	BlockHasLex bool
}

type LexName struct {
	Name    string
	IsConst bool
	IsFunc  bool // function declaration in block (lexical in blocks)
	IsClass bool
}

type ClassMember struct {
	NodeBase
	Kind      PropKind // PropInit (field), PropMethod, PropGet, PropSet
	Static    bool
	Key       Node
	Computed  bool
	KeyName   string
	IsPrivate bool
	Value     Node // *FuncNode for methods; initializer expr for fields (may be nil)
	IsStaticBlock bool
	Block     *FuncNode
