}

type ClassNode struct {
	NodeBase
	Name        string
	SuperClass  Node
	Constructor *FuncNode
	Members     []*ClassMember
	Source      string
	IsExpr      bool
	HasName     bool
}

type UnaryExpr struct {
	NodeBase
	Op string
	X  Node
}
type UpdateExpr struct {
	NodeBase
	Op     string // "++" or "--"
	Prefix bool
	X      Node
}
type BinaryExpr struct {
	NodeBase
	Op   string
	L, R Node
}
type LogicalExpr struct {
	NodeBase
	Op   string // && || ??
	L, R Node
}
type AssignExpr struct {
	NodeBase
	Op     string // = += etc
	Target Node   // pattern or member/ident
	Value  Node
}
type CondExpr struct {
	NodeBase
	Test, Cons, Alt Node
}
type SeqExpr struct {
	NodeBase
	Exprs []Node
}
type CallExpr struct {
	NodeBase
	Callee   Node
	Args     []Node
	Optional bool // callee?.()
	InChain  bool
	IsDirectEval bool
}
type NewExpr struct {
	NodeBase
	Callee Node
	Args   []Node
}
type MemberExpr struct {
	NodeBase
	Obj      Node
	Prop     Node   // Ident (name) when !Computed, else expression
	Name     string // when !Computed
	Computed bool
	Optional bool // obj?.prop
	InChain  bool
}
type PrivateMemberExpr struct {
	NodeBase
	Obj      Node
	Name     string
	Optional bool
	InChain  bool
}
type PrivateInExpr struct {
	NodeBase
	Name string
	R    Node
}
type OptionalChain struct { // wraps whole chain for short-circuit
	NodeBase
	X Node
}
type YieldExpr struct {
	NodeBase
	Arg      Node
	Delegate bool
}
type AwaitExpr struct {
	NodeBase
	Arg Node
}
type ParenExpr struct { // kept for cover grammar validation only
	NodeBase
	X Node
}

// Patterns
type ObjectPattern struct {
	NodeBase
	Props []*PatternProp
	Rest  Node // target for ...rest
}
type PatternProp struct {
	Key      Node
	Computed bool
	KeyName  string
	Target   Node // pattern (may be *AssignPattern)
}
type ArrayPattern struct {
	NodeBase
	Elems []Node // nil = hole, *AssignPattern, *RestElement
}
type AssignPattern struct {
	NodeBase
	Target  Node
	Default Node
}
type RestElement struct {
	NodeBase
	Target Node
}

// ---------- Statements ----------

type VarDecl struct {
	NodeBase
	Kind  string // var let const
	Decls []*Declarator
}
type Declarator struct {
	NodeBase
	Target Node
	Init   Node
}
type FuncDecl struct {
	NodeBase
	Func *FuncNode
}
type ClassDecl struct {
	NodeBase
	Class *ClassNode
}
type ExprStmt struct {
	NodeBase
	X Node
}
type BlockStmt struct {
	NodeBase
	Body     []Node
	Lex      []LexName
	FuncDecls []*FuncNode
}
type EmptyStmt struct{ NodeBase }
type IfStmt struct {
	NodeBase
	Test       Node
	Cons, Alt  Node
}
type ForStmt struct {
	NodeBase
	Init   Node // VarDecl or expression or nil
	Test   Node
	Update Node
	Body   Node
	Lex    []LexName // let/const in init
}
type ForInStmt struct {
	NodeBase
	Left  Node // VarDecl (single declarator, no init) or pattern/lhs expr
	Right Node
	Body  Node
	Of    bool
	Await bool
	Lex   []LexName
}
type WhileStmt struct {
	NodeBase
	Test Node
	Body Node
}
type DoWhileStmt struct {
	NodeBase
	Body Node
	Test Node
}
type ReturnStmt struct {
	NodeBase
	Arg Node
}
type BreakStmt struct {
	NodeBase
	Label string
}
type ContinueStmt struct {
	NodeBase
	Label string
}
type ThrowStmt struct {
	NodeBase
	Arg Node
}
type TryStmt struct {
	NodeBase
	Block     *BlockStmt
	Param     Node // pattern or nil
	Handler   *BlockStmt
	Finalizer *BlockStmt
	ParamLex  []LexName
}
type SwitchCase struct {
	Test Node // nil for default
	Body []Node
}
type SwitchStmt struct {
	NodeBase
	Disc  Node
	Cases []*SwitchCase
	Lex   []LexName
	FuncDecls []*FuncNode
}
type LabeledStmt struct {
	NodeBase
	Label string
	Body  Node
}
type WithStmt struct {
	NodeBase
	Obj  Node
	Body Node
}
type DebuggerStmt struct{ NodeBase }

// Modules
type ImportSpec struct {
	Imported string // "*" for namespace, "default"
	Local    string
}
type ImportDecl struct {
	NodeBase
	Specs  []ImportSpec
	Source string
}
type ExportSpec struct {
	Local    string // local name (or imported name when re-exporting)
	Exported string
}
type ExportDecl struct {
	NodeBase
	Decl      Node   // VarDecl / FuncDecl / ClassDecl
	Default   Node   // expression for export default (or FuncDecl/ClassDecl)
	IsDefault bool
	Specs     []ExportSpec
	Source    string // for re-exports; "" if none
	StarAs    string // export * as ns from
	IsStar    bool
}

// Program
type Program struct {
	Body      []Node
	Strict    bool
	IsModule  bool
	VarNames  []string
	FuncDecls []*FuncNode
	Lex       []LexName
	Source    string
	HasTLA    bool
	Imports   []*ImportDecl
	Exports   []*ExportDecl
}
