import (
	"fmt"
	"strings"
)

type funcCtx struct {
	fn          *FuncNode
	varNames    map[string]bool
	varList     []string
	funcDecls   []*FuncNode
	isAsync     bool
	isGenerator bool
	isArrow     bool
	strict      bool
	inClassFieldInit bool
	allowSuperProp bool
	allowSuperCall bool
	allowNewTarget bool
	usesArguments bool
	usesThis    bool
	usesEval    bool
	hasSuperCall bool
	labels      []labelInfo
	loopDepth   int
	switchDepth int
	isModuleTop bool
	isScriptTop bool
	paramNames  map[string]bool
	inParams    bool
	awaitAsIdentDepth int
}

type labelInfo struct {
	name   string
	isLoop bool
}

type blockCtx struct {
	lex       []LexName
	lexSet    map[string]bool
	funcDecls []*FuncNode
	isFuncBody bool
	parent    *blockCtx
}

type Parser struct {
	lex      *Lexer
	tok      Token
	prevTok  Token
	fc       *funcCtx
	fcs      []*funcCtx
	bc       *blockCtx
	fileName string
	isModule bool
	src      string
	noIn     bool
	privateNames []map[string]bool
	classDepth int
	hasTLA bool
	inDecorator bool
}

func NewParser(src, fileName string, isModule bool) *Parser {
	p := &Parser{lex: NewLexer(src), fileName: fileName, isModule: isModule, src: src}
	return p
}

func (p *Parser) errAt(pos int, format string, args ...interface{}) {
	line, col := p.lex.lineCol(pos)
	panic(&SyntaxError{Msg: fmt.Sprintf(format, args...), Line: line, Col: col})
}

func (p *Parser) err(format string, args ...interface{}) {
	p.errAt(p.tok.Pos, format, args...)
}

func (p *Parser) next() {
	p.prevTok = p.tok
	p.tok = p.lex.Next()
}

func (p *Parser) is(kind TokKind, val string) bool {
	return p.tok.Kind == kind && p.tok.Val == val
}

func (p *Parser) isPunct(val string) bool {
	return p.tok.Kind == TPunct && p.tok.Val == val
}

func (p *Parser) isKw(val string) bool {
	return p.tok.Kind == TKeyword && p.tok.Val == val
}

func (p *Parser) isIdent(val string) bool {
	return p.tok.Kind == TIdent && p.tok.Val == val && !p.tok.HasEscape
}

func (p *Parser) expectPunct(val string) Token {
	if !p.isPunct(val) {
		p.err("expecting '%s'", val)
	}
	t := p.tok
	p.next()
	return t
}

func (p *Parser) expectKw(val string) {
	if !p.isKw(val) {
		p.err("expecting '%s'", val)
	}
	p.next()
}

func (p *Parser) tokDesc() string {
	switch p.tok.Kind {
	case TEOF:
		return "''"
	case TString:
		return "'" + p.tok.Raw + "'"
	default:
		return "'" + p.tok.Raw + "'"
	}
}

// consume semicolon with ASI
func (p *Parser) semicolon() {
	if p.isPunct(";") {
		p.next()
		return
	}
	if p.isPunct("}") || p.tok.Kind == TEOF || p.tok.NLBefore {
		return
	}
	p.err("expecting ';'")
}

func (p *Parser) pushFunc(fn *FuncNode) *funcCtx {
	fc := &funcCtx{fn: fn, varNames: map[string]bool{}, paramNames: map[string]bool{}}
	if p.fc != nil {
		fc.strict = p.fc.strict
		if fn != nil && fn.IsArrow {
			fc.allowSuperProp = p.fc.allowSuperProp
			fc.allowSuperCall = p.fc.allowSuperCall
			fc.allowNewTarget = p.fc.allowNewTarget
			fc.inClassFieldInit = p.fc.inClassFieldInit
		}
	}
	p.fcs = append(p.fcs, fc)
	p.fc = fc
	return fc
}

func (p *Parser) popFunc() {
	p.fcs = p.fcs[:len(p.fcs)-1]
	if len(p.fcs) > 0 {
		p.fc = p.fcs[len(p.fcs)-1]
	} else {
		p.fc = nil
	}
}

func (p *Parser) pushBlock(isFuncBody bool) *blockCtx {
	bc := &blockCtx{parent: p.bc, isFuncBody: isFuncBody, lexSet: map[string]bool{}}
	p.bc = bc
	return bc
}

func (p *Parser) popBlock() *blockCtx {
	bc := p.bc
	p.bc = bc.parent
	return bc
}

func (p *Parser) declareLex(name string, pos int, isConst bool, isFunc bool, isClass bool) {
	if name == "let" {
		p.errAt(pos, "'let' is not a valid lexical identifier")
	}
	bc := p.bc
	if bc.lexSet[name] {
		// function redeclaration in sloppy mode blocks is allowed at function top-level? (not for lexical)
		if isFunc && !p.fc.strict {
			for _, l := range bc.lex {
				if l.Name == name && l.IsFunc {
					return
				}
			}
		}
		p.errAt(pos, "invalid redefinition of lexical identifier")
	}
	if bc.isFuncBody {
		if p.fc.varNames[name] && !(isFunc && !p.fc.strict) {
			p.errAt(pos, "invalid redefinition of lexical identifier")
		}
		if p.fc.paramNames[name] && !isFunc {
			p.errAt(pos, "invalid redefinition of lexical identifier")
		}
	} else {
		// var declared in nested scope conflicts if var hoists through this block; check later via varNames at that time
		if bc.varsInBlock != nil && bc.varsInBlock[name] && !isFunc {
			p.errAt(pos, "invalid redefinition of lexical identifier")
		}
	}
	bc.lexSet[name] = true
	bc.lex = append(bc.lex, LexName{Name: name, IsConst: isConst, IsFunc: isFunc, IsClass: isClass})
}

func (p *Parser) declareVar(name string, pos int) {
	// check conflicts with lexical declarations in enclosing blocks up to function body
	for bc := p.bc; bc != nil; bc = bc.parent {
		if bc.lexSet[name] {
			isFn := false
			for _, l := range bc.lex {
				if l.Name == name && l.IsFunc && bc.isFuncBody && !p.fc.strict {
					isFn = true
				}
			}
			if !isFn {
				p.errAt(pos, "invalid redefinition of lexical identifier")
			}
		}
		if bc.varsInBlock == nil {
			bc.varsInBlock = map[string]bool{}
		}
		bc.varsInBlock[name] = true
		if bc.isFuncBody {
			break
		}
	}
	if !p.fc.varNames[name] {
		p.fc.varNames[name] = true
		p.fc.varList = append(p.fc.varList, name)
	}
}

// ---------- Program ----------

func (p *Parser) ParseProgram() (prog *Program, err error) {
	defer func() {
		if r := recover(); r != nil {
			if se, ok := r.(*SyntaxError); ok {
				prog = nil
				err = se
				return
			}
			panic(r)
		}
	}()
	prog = &Program{IsModule: p.isModule, Source: p.src}
	fc := p.pushFunc(nil)
	fc.isModuleTop = p.isModule
	fc.isScriptTop = !p.isModule
	fc.allowNewTarget = false
	if p.isModule {
		fc.strict = true
		fc.isAsync = true // top-level await
	}
	bc := p.pushBlock(true)
	p.next()
	body := p.parseDirectivesAndBody(func() bool { return p.tok.Kind == TEOF }, prog)
	prog.Body = body
	prog.Strict = fc.strict
	prog.VarNames = fc.varList
	prog.FuncDecls = bc.funcDecls
	prog.Lex = bc.lex
	prog.HasTLA = p.hasTLA
	p.popBlock()
	p.popFunc()
	// collect imports/exports
	for _, s := range body {
		switch d := s.(type) {
		case *ImportDecl:
			prog.Imports = append(prog.Imports, d)
		case *ExportDecl:
			prog.Exports = append(prog.Exports, d)
		}
	}
	return prog, nil
}

// parse directives prologue then statements until done()
func (p *Parser) parseDirectivesAndBody(done func() bool, prog *Program) []Node {
	var body []Node
	// directive prologue
	for p.tok.Kind == TString && !done() {
		save := p.tok
		state := p.lexState()
		p.next()
		// a directive must be a complete expression statement
		if p.isPunct(";") || p.isPunct("}") || p.tok.Kind == TEOF || p.tok.NLBefore {
			if save.Raw[1:len(save.Raw)-1] == "use strict" && !save.HasEscape {
				if p.fc.fn != nil && !p.fc.fn.SimpleParams {
					p.errAt(save.Pos, "\"use strict\" not allowed in function with default or destructuring parameter")
				}
				p.fc.strict = true
				if p.fc.fn != nil {
					p.fc.fn.Strict = true
				}
			}
			if save.LegacyOctal && p.fc.strict {
				p.errAt(save.Pos, "octal escape sequences are not allowed in strict mode")
			}
			if p.isPunct(";") {
				p.next()
			}
			body = append(body, &ExprStmt{NodeBase{save.Pos}, &StringLit{NodeBase{save.Pos}, NewStringFromGo(save.Val)}})
			continue
		}
		// not a directive; restore and parse as statement
		p.restoreLexState(state)
		p.tok = save
		break
	}
	for !done() {
		if p.tok.Kind == TEOF {
			p.err("unexpected end of input")
		}
		body = append(body, p.parseStatementListItem())
	}
	return body
}

type lexState struct {
	pos, line, lineStart int
	tok, prevTok         Token
}

func (p *Parser) lexState() lexState {
	pos, line, ls := p.lex.State()
	return lexState{pos, line, ls, p.tok, p.prevTok}
}

func (p *Parser) restoreLexState(s lexState) {
	p.lex.ResetTo(s.pos, s.line, s.lineStart)
	p.tok = s.tok
	p.prevTok = s.prevTok
}

// ---------- Statements ----------

func (p *Parser) parseStatementListItem() Node {
	switch {
	case p.isKw("function"):
		return p.parseFunctionDeclaration(false)
	case p.isIdent("async") && p.peekIsFunctionNoNL():
		return p.parseFunctionDeclaration(true)
	case p.isKw("class"):
		return p.parseClassDeclaration()
	case p.isKw("const"):
		return p.parseLexicalDeclaration("const")
	case p.isIdent("let") && p.letIsDeclaration():
		return p.parseLexicalDeclaration("let")
	case p.isKw("import") && p.importIsDeclaration():
		if !p.isModule || !p.fc.isModuleTop || p.bc.parent != nil {
			if !p.isModule {
				p.err("expecting '('")
			}
			p.err("import declaration must be at top level")
		}
		return p.parseImportDeclaration()
	case p.isKw("export"):
		if !p.isModule {
			p.err("unsupported keyword: export")
		}
		if !p.fc.isModuleTop || p.bc.parent != nil {
			p.err("export declaration must be at top level")
		}
		return p.parseExportDeclaration()
	}
	return p.parseStatement()
}

func (p *Parser) peekIsFunctionNoNL() bool {
	st := p.lexState()
	p.next()
	r := p.isKw("function") && !p.tok.NLBefore
	p.restoreLexState(st)
	return r
}

func (p *Parser) letIsDeclaration() bool {
	st := p.lexState()
	p.next()
	r := false
	if p.tok.Kind == TIdent || p.isPunct("[") || p.isPunct("{") {
		r = true
		if p.tok.Kind == TIdent && p.tok.NLBefore {
			// `let \n x` is still declaration unless x is 'in'/'instanceof'
			r = true
		}
	} else if p.tok.Kind == TKeyword && (p.tok.Val == "yield" || p.tok.Val == "await") {
		r = true
	}
	if p.tok.Kind == TIdent && p.tok.Val == "in" {
		r = false
	}
	p.restoreLexState(st)
	return r
}

func (p *Parser) importIsDeclaration() bool {
	st := p.lexState()
	p.next()
	r := !(p.isPunct("(") || p.isPunct("."))
	p.restoreLexState(st)
	return r
}

func (p *Parser) parseStatement() Node {
	pos := p.tok.Pos
	switch p.tok.Kind {
	case TPunct:
		switch p.tok.Val {
		case "{":
			return p.parseBlock()
		case ";":
			p.next()
			return &EmptyStmt{NodeBase{pos}}
		}
	case TKeyword:
		switch p.tok.Val {
		case "var":
			p.next()
			d := p.parseVarDeclarations("var", pos)
			p.semicolon()
			return d
		case "if":
			return p.parseIf()
		case "for":
			return p.parseFor()
		case "while":
			p.next()
			p.expectPunct("(")
			test := p.parseExpression()
			p.expectPunct(")")
			body := p.parseLoopBody()
			return &WhileStmt{NodeBase{pos}, test, body}
		case "do":
			p.next()
			body := p.parseLoopBody()
			p.expectKw("while")
			p.expectPunct("(")
			test := p.parseExpression()
			p.expectPunct(")")
			if p.isPunct(";") {
				p.next()
			}
			return &DoWhileStmt{NodeBase{pos}, body, test}
		case "continue":
			p.next()
			label := ""
			if p.tok.Kind == TIdent && !p.tok.NLBefore {
				label = p.tok.Val
				if !p.hasLabel(label, true) {
					p.err("continue must be inside loop")
				}
				p.next()
			} else if p.fc.loopDepth == 0 {
				p.err("continue must be inside loop")
			}
			p.semicolon()
			return &ContinueStmt{NodeBase{pos}, label}
		case "break":
			p.next()
			label := ""
			if p.tok.Kind == TIdent && !p.tok.NLBefore {
				label = p.tok.Val
				if !p.hasLabel(label, false) {
					p.errAt(p.tok.Pos, "break label not found")
				}
				p.next()
			} else if p.fc.loopDepth == 0 && p.fc.switchDepth == 0 {
				p.err("break must be inside loop or switch")
			}
			p.semicolon()
			return &BreakStmt{NodeBase{pos}, label}
		case "return":
			if p.fc.fn == nil {
				p.err("return not in a function")
			}
			p.next()
			var arg Node
			if !p.isPunct(";") && !p.isPunct("}") && p.tok.Kind != TEOF && !p.tok.NLBefore {
				arg = p.parseExpression()
			}
			p.semicolon()
			return &ReturnStmt{NodeBase{pos}, arg}
		case "throw":
			p.next()
			if p.tok.NLBefore {
				p.err("line terminator not allowed after throw")
			}
			arg := p.parseExpression()
			p.semicolon()
			return &ThrowStmt{NodeBase{pos}, arg}
		case "try":
			return p.parseTry()
		case "switch":
			return p.parseSwitch()
		case "with":
			if p.fc.strict {
				p.err("invalid keyword: with")
			}
			p.next()
			p.expectPunct("(")
			obj := p.parseExpression()
			p.expectPunct(")")
			p.fc.usesEval = true
			body := p.parseStatement()
			return &WithStmt{NodeBase{pos}, obj, body}
		case "debugger":
			p.next()
			p.semicolon()
			return &DebuggerStmt{NodeBase{pos}}
		case "function":
			p.err("function declarations can't appear in single-statement context")
		case "class":
			p.err("class declarations can't appear in single-statement context")
		case "const":
			p.err("unexpected token in expression: 'const'")
		case "import":
			if !p.importIsDeclaration() {
				break
			}
			p.err("unexpected token in expression: 'import'")
		case "export":
			p.err("unsupported keyword: export")
		}
	case TIdent:
		if p.isIdent("let") && p.letIsDeclaration() {
			if p.fc.strict {
				p.err("lexical declarations can't appear in single-statement context")
			}
			p.err("lexical declarations can't appear in single-statement context")
		}
		if p.isIdent("async") && p.peekIsFunctionNoNL() {
			p.err("function declarations can't appear in single-statement context")
		}
		// labeled statement?
		if p.tok.Kind == TIdent {
			st := p.lexState()
			name := p.tok.Val
			p.next()
			if p.isPunct(":") {
				p.next()
				return p.parseLabeled(name, pos)
			}
			p.restoreLexState(st)
		}
	}
	// expression statement
	expr := p.parseExpression()
	p.semicolon()
	return &ExprStmt{NodeBase{pos}, expr}
}

func (p *Parser) hasLabel(name string, needLoop bool) bool {
	for i := len(p.fc.labels) - 1; i >= 0; i-- {
		if p.fc.labels[i].name == name {
			if needLoop && !p.fc.labels[i].isLoop {
				return false
			}
			return true
		}
	}
	return false
}

func (p *Parser) parseLabeled(name string, pos int) Node {
	if name == "yield" && (p.fc.isGenerator || p.fc.strict) {
		p.errAt(pos, "unexpected token in expression: 'yield'")
	}
	if name == "await" && (p.fc.isAsync || p.isModule) {
		p.errAt(pos, "unexpected token in expression: 'await'")
	}
	for _, l := range p.fc.labels {
		if l.name == name {
			p.errAt(pos, "duplicate label name")
		}
	}
	isLoop := p.isKw("for") || p.isKw("while") || p.isKw("do")
	p.fc.labels = append(p.fc.labels, labelInfo{name, isLoop})
	var body Node
	if p.isKw("function") {
		if p.fc.strict {
			p.err("function declarations can't appear in single-statement context")
		}
		body = p.parseFunctionDeclaration(false)
	} else {
		body = p.parseStatement()
	}
	p.fc.labels = p.fc.labels[:len(p.fc.labels)-1]
	return &LabeledStmt{NodeBase{pos}, name, body}
}

func (p *Parser) parseLoopBody() Node {
	p.fc.loopDepth++
	// labels directly preceding loop are already marked
	body := p.parseStatement()
	p.fc.loopDepth--
	return body
}

func (p *Parser) parseBlock() *BlockStmt {
	pos := p.tok.Pos
	p.expectPunct("{")
	bc := p.pushBlock(false)
	var body []Node
	for !p.isPunct("}") {
		if p.tok.Kind == TEOF {
			p.err("expecting '}'")
		}
		body = append(body, p.parseStatementListItem())
	}
	p.next()
	p.popBlock()
	return &BlockStmt{NodeBase{pos}, body, bc.lex, bc.funcDecls}
}

func (p *Parser) parseVarDeclarations(kind string, pos int) *VarDecl {
	d := &VarDecl{NodeBase{pos}, kind, nil}
	for {
		dpos := p.tok.Pos
		target := p.parseBindingTarget(kind)
		var init Node
		if p.isPunct("=") {
			p.next()
			init = p.parseAssignExpr()
			if id, ok := target.(*Ident); ok {
				setFuncName(init, id.Name)
			}
		} else {
			if kind == "const" && !p.inForInit {
				p.err("missing initializer for const")
			}
			if _, ok := target.(*Ident); !ok && !p.inForInit {
				p.err("missing initializer in destructuring declaration")
			}
		}
		d.Decls = append(d.Decls, &Declarator{NodeBase{dpos}, target, init})
		if !p.isPunct(",") {
			break
		}
		p.next()
	}
	return d
}

func (p *Parser) parseLexicalDeclaration(kind string) Node {
	pos := p.tok.Pos
	p.next()
	d := p.parseVarDeclarations(kind, pos)
	p.semicolon()
	return d
}

// parseBindingTarget parses a binding identifier or pattern and declares names
func (p *Parser) parseBindingTarget(kind string) Node {
	pos := p.tok.Pos
	if p.isPunct("[") || p.isPunct("{") {
		pat := p.parseBindingPattern(kind)
		return pat
	}
	name := p.parseBindingIdentifier()
	p.declareBinding(name, pos, kind)
	return &Ident{NodeBase{pos}, name}
}

func (p *Parser) declareBinding(name string, pos int, kind string) {
	switch kind {
	case "var":
		p.declareVar(name, pos)
	case "let":
		p.declareLex(name, pos, false, false, false)
	case "const":
		p.declareLex(name, pos, true, false, false)
	case "param":
		if p.fc.paramNames[name] {
			p.fc.dupParams = true
		}
		p.fc.paramNames[name] = true
		p.fc.fn.ParamNames = append(p.fc.fn.ParamNames, name)
	case "catch":
		p.declareLex(name, pos, false, false, false)
	case "none":
	}
}

func (p *Parser) parseBindingIdentifier() string {
	t := p.tok
	if t.Kind == TIdent {
		name := t.Val
		p.checkBindingName(name, t.Pos)
		p.next()
		return name
	}
	if t.Kind == TKeyword && (t.Val == "yield" || t.Val == "await") {
		// handled as idents in sloppy mode
	}
	p.err("unexpected token in expression: %s", p.tokDesc())
	return ""
}

var strictReserved = map[string]bool{"implements": true, "interface": true, "let": true, "package": true, "private": true, "protected": true, "public": true, "static": true, "yield": true}

func (p *Parser) checkBindingName(name string, pos int) {
	if p.fc.strict {
		if name == "eval" || name == "arguments" {
			p.errAt(pos, "invalid variable name in strict mode")
		}
		if strictReserved[name] {
			p.errAt(pos, "invalid variable name in strict mode")
		}
	}
	if name == "yield" && (p.fc.isGenerator || p.fc.strict) {
		p.errAt(pos, "yield is a reserved identifier")
	}
	if name == "await" && (p.fc.isAsync || p.isModule) {
		p.errAt(pos, "await is a reserved identifier")
	}
	if name == "enum" {
		p.errAt(pos, "unexpected token in expression: 'enum'")
	}
}

func (p *Parser) parseBindingPattern(kind string) Node {
	pos := p.tok.Pos
	if p.isPunct("[") {
		p.next()
		ap := &ArrayPattern{NodeBase: NodeBase{pos}}
		for !p.isPunct("]") {
			if p.isPunct(",") {
				p.next()
				ap.Elems = append(ap.Elems, nil)
				continue
			}
			if p.isPunct("...") {
				rpos := p.tok.Pos
				p.next()
				t := p.parseBindingTarget(kind)
				ap.Elems = append(ap.Elems, &RestElement{NodeBase{rpos}, t})
				if p.isPunct(",") {
					p.err("rest element must be the last one")
				}
				break
			}
			epos := p.tok.Pos
			t := p.parseBindingTarget(kind)
			if p.isPunct("=") {
				p.next()
				def := p.parseAssignExpr()
				if id, ok := t.(*Ident); ok {
					setFuncName(def, id.Name)
				}
				t = &AssignPattern{NodeBase{epos}, t, def}
			}
			ap.Elems = append(ap.Elems, t)
			if !p.isPunct("]") {
				p.expectPunct(",")
			}
		}
		p.expectPunct("]")
		return ap
	}
	p.expectPunct("{")
	op := &ObjectPattern{NodeBase: NodeBase{pos}}
	for !p.isPunct("}") {
		if p.isPunct("...") {
			p.next()
			tpos := p.tok.Pos
			name := p.parseBindingIdentifier()
			p.declareBinding(name, tpos, kind)
			op.Rest = &Ident{NodeBase{tpos}, name}
			if !p.isPunct("}") {
				p.err("rest element must be the last one")
			}
			break
		}
		pp := &PatternProp{}
		kpos := p.tok.Pos
		if p.isPunct("[") {
			p.next()
			pp.Key = p.parseAssignExpr()
			pp.Computed = true
			p.expectPunct("]")
		} else {
			keyName, keyNode, isIdent := p.parsePropertyName()
			pp.Key = keyNode
			pp.KeyName = keyName
			if isIdent && !p.isPunct(":") {
				// shorthand
				p.checkBindingName(keyName, kpos)
				if p.tok.Kind == TKeyword && keywords[keyName] && keyName != "yield" && keyName != "await" {
					p.errAt(kpos, "invalid binding name")
				}
				if keywords[keyName] && keyName != "yield" && keyName != "await" {
					p.errAt(kpos, "unexpected token in expression: '%s'", keyName)
				}
				p.declareBinding(keyName, kpos, kind)
				var t Node = &Ident{NodeBase{kpos}, keyName}
				if p.isPunct("=") {
					p.next()
					def := p.parseAssignExpr()
					setFuncName(def, keyName)
					t = &AssignPattern{NodeBase{kpos}, t, def}
				}
				pp.Target = t
				op.Props = append(op.Props, pp)
				if !p.isPunct("}") {
					p.expectPunct(",")
				}
				continue
			}
		}
		p.expectPunct(":")
		tpos := p.tok.Pos
		t := p.parseBindingTarget(kind)
		if p.isPunct("=") {
			p.next()
			def := p.parseAssignExpr()
			if id, ok := t.(*Ident); ok {
				setFuncName(def, id.Name)
			}
			t = &AssignPattern{NodeBase{tpos}, t, def}
		}
		pp.Target = t
		op.Props = append(op.Props, pp)
		if !p.isPunct("}") {
			p.expectPunct(",")
		}
	}
	p.expectPunct("}")
	return op
}

// parsePropertyName parses a property name (identifier, string, number, keyword) -- not computed.
// returns name, node, and whether it was a plain identifier (for shorthand)
func (p *Parser) parsePropertyName() (string, Node, bool) {
	t := p.tok
	switch t.Kind {
	case TIdent, TKeyword:
		p.next()
		return t.Val, &StringLit{NodeBase{t.Pos}, NewStringFromGo(t.Val)}, t.Kind == TIdent || t.Val == "yield" || t.Val == "await" || !keywords[t.Val]
	case TString:
		p.next()
		return t.Val, &StringLit{NodeBase{t.Pos}, NewStringFromGo(t.Val)}, false
	case TNumber:
		p.next()
		s := numberToString(t.Num)
		return s, &StringLit{NodeBase{t.Pos}, NewStringFromGo(s)}, false
	case TBigInt:
		p.next()
		s := t.Big.String()
		return s, &StringLit{NodeBase{t.Pos}, NewStringFromGo(s)}, false
	case TPrivateName:
		p.err("private class field forbidden here")
	}
	p.err("unexpected token in expression: %s", p.tokDesc())
	return "", nil, false
}

func (p *Parser) parseIf() Node {
	pos := p.tok.Pos
	p.next()
	p.expectPunct("(")
	test := p.parseExpression()
	p.expectPunct(")")
	cons := p.parseSubStatement()
	var alt Node
	if p.isKw("else") {
		p.next()
		alt = p.parseSubStatement()
	}
	return &IfStmt{NodeBase{pos}, test, cons, alt}
}

// sub-statement of if (allows function declaration in sloppy mode)
func (p *Parser) parseSubStatement() Node {
	if p.isKw("function") && !p.fc.strict {
		// Annex B: treat as block
		pos := p.tok.Pos
		bc := p.pushBlock(false)
		fd := p.parseFunctionDeclaration(false)
		p.popBlock()
		return &BlockStmt{NodeBase{pos}, []Node{fd}, bc.lex, bc.funcDecls}
	}
	return p.parseStatement()
}

func (p *Parser) parseFor() Node {
	pos := p.tok.Pos
	p.next()
	isAwait := false
	if p.isIdent("await") || p.isKw("await") {
		if !p.fc.isAsync {
			p.err("unexpected 'await' keyword")
		}
		isAwait = true
		p.markTLA()
		p.next()
	}
	p.expectPunct("(")
	bc := p.pushBlock(false)
	var init Node
	if p.isPunct(";") {
		if isAwait {
			p.err("expecting 'of'")
		}
	} else {
		isDecl := false
		kind := ""
		if p.isKw("var") {
			isDecl = true
			kind = "var"
		} else if p.isKw("const") {
			isDecl = true
			kind = "const"
		} else if p.isIdent("let") && p.letIsDeclaration() {
			isDecl = true
			kind = "let"
		}
		if isDecl {
			dpos := p.tok.Pos
			p.next()
			p.inForInit = true
			p.noIn = true
			vd := p.parseVarDeclarations(kind, dpos)
			p.noIn = false
			p.inForInit = false
			if (p.isIdent("of") || p.isKw("in")) && len(vd.Decls) == 1 {
				of := p.isIdent("of")
				if vd.Decls[0].Init != nil {
					if of || p.fc.strict || kind != "var" {
						p.err("for-in/of initializer not allowed")
					}
					if _, ok := vd.Decls[0].Target.(*Ident); !ok {
						p.err("for-in/of initializer not allowed")
					}
				}
				if isAwait && !of {
					p.err("expecting 'of'")
				}
				p.next()
				var right Node
				if of {
					right = p.parseAssignExpr()
				} else {
					right = p.parseExpression()
				}
				p.expectPunct(")")
				body := p.parseLoopBody()
				p.popBlock()
				return &ForInStmt{NodeBase{pos}, vd, right, body, of, isAwait, bc.lex}
			}
			if isAwait {
				p.err("expecting 'of'")
			}
			for _, d := range vd.Decls {
				if d.Init == nil {
					if kind == "const" {
						p.errAt(d.Pos(), "missing initializer for const")
					}
					if _, ok := d.Target.(*Ident); !ok {
						p.errAt(d.Pos(), "missing initializer in destructuring declaration")
					}
				}
			}
			init = vd
		} else {
			// expression or lhs
			p.noIn = true
			epos := p.tok.Pos
			startsWithLet := p.isIdent("let")
			startsWithAsync := p.isIdent("async")
			expr := p.parseExpressionNoValidate()
			p.noIn = false
			if p.isIdent("of") || p.isKw("in") {
				of := p.isIdent("of")
				if of && startsWithLet {
					p.errAt(epos, "'let' is not a valid lexical identifier")
				}
				if of && startsWithAsync && !isAwait {
					if id, ok := expr.(*Ident); ok && id.Name == "async" {
						p.errAt(epos, "unexpected token in expression: 'of'")
					}
				}
				if isAwait && !of {
					p.err("expecting 'of'")
				}
				target := p.toAssignTarget(expr, true)
				p.next()
				var right Node
				if of {
					right = p.parseAssignExpr()
				} else {
					right = p.parseExpression()
				}
				p.expectPunct(")")
				body := p.parseLoopBody()
				p.popBlock()
				return &ForInStmt{NodeBase{pos}, target, right, body, of, isAwait, nil}
			}
			if isAwait {
				p.err("expecting 'of'")
			}
			p.validateExpr(expr)
			init = expr
		}
	}
	p.expectPunct(";")
	var test, update Node
	if !p.isPunct(";") {
		test = p.parseExpression()
	}
	p.expectPunct(";")
	if !p.isPunct(")") {
		update = p.parseExpression()
	}
	p.expectPunct(")")
	body := p.parseLoopBody()
	p.popBlock()
	return &ForStmt{NodeBase{pos}, init, test, update, body, bc.lex}
}

func (p *Parser) markTLA() {
	if p.fc.isModuleTop {
		p.hasTLA = true
	}
}

func (p *Parser) parseTry() Node {
	pos := p.tok.Pos
	p.next()
	block := p.parseBlock()
	ts := &TryStmt{NodeBase: NodeBase{pos}, Block: block}
	if p.isKw("catch") {
		p.next()
		bc := p.pushBlock(false)
		if p.isPunct("(") {
			p.next()
			ts.Param = p.parseBindingTarget("catch")
			p.expectPunct(")")
		}
		// catch body shares scope check with param: parse block manually
		bpos := p.tok.Pos
		p.expectPunct("{")
		var body []Node
		for !p.isPunct("}") {
			if p.tok.Kind == TEOF {
				p.err("expecting '}'")
			}
			body = append(body, p.parseStatementListItem())
		}
		p.next()
		p.popBlock()
		ts.Handler = &BlockStmt{NodeBase{bpos}, body, bc.lex, bc.funcDecls}
	}
	if p.isKw("finally") {
		p.next()
		ts.Finalizer = p.parseBlock()
	}
	if ts.Handler == nil && ts.Finalizer == nil {
		p.err("expecting catch or finally")
	}
	return ts
}

func (p *Parser) parseSwitch() Node {
	pos := p.tok.Pos
	p.next()
	p.expectPunct("(")
	disc := p.parseExpression()
	p.expectPunct(")")
	p.expectPunct("{")
	bc := p.pushBlock(false)
	p.fc.switchDepth++
	ss := &SwitchStmt{NodeBase: NodeBase{pos}, Disc: disc}
	hasDefault := false
	for !p.isPunct("}") {
		c := &SwitchCase{}
		if p.isKw("case") {
			p.next()
			c.Test = p.parseExpression()
		} else if p.isKw("default") {
			if hasDefault {
				p.err("duplicate default")
			}
			hasDefault = true
			p.next()
		} else {
			p.err("invalid switch statement")
		}
		p.expectPunct(":")
		for !p.isPunct("}") && !p.isKw("case") && !p.isKw("default") {
			if p.tok.Kind == TEOF {
				p.err("expecting '}'")
			}
			c.Body = append(c.Body, p.parseStatementListItem())
		}
		ss.Cases = append(ss.Cases, c)
	}
	p.next()
	p.fc.switchDepth--
	p.popBlock()
	ss.Lex = bc.lex
	ss.FuncDecls = bc.funcDecls
	return ss
}

// ---------- Functions ----------

func (p *Parser) parseFunctionDeclaration(isAsync bool) Node {
	pos := p.tok.Pos
	if isAsync {
		p.next() // async
	}
	p.next() // function
	isGen := false
	if p.isPunct("*") {
		isGen = true
		p.next()
	}
	if p.tok.Kind != TIdent && !(p.tok.Kind == TKeyword && (p.tok.Val == "yield" || p.tok.Val == "await")) {
		p.err("function name expected")
	}
	namePos := p.tok.Pos
	name := p.tok.Val
	// name restrictions: evaluated in enclosing context
	p.checkBindingName(name, namePos)
	p.next()
	fn := p.parseFunctionRest(pos, name, FuncNormal, isAsync, isGen, false)
	fn.IsExpr = false
	// declaration: hoist
	if p.bc.isFuncBody {
		// var-scoped function declaration
		if p.bc.lexSet[name] {
			p.errAt(namePos, "invalid redefinition of lexical identifier")
		}
		if !p.fc.varNames[name] {
			p.fc.varNames[name] = true
			p.fc.varList = append(p.fc.varList, name)
		}
		p.bc.funcDecls = append(p.bc.funcDecls, fn)
	} else {
		// block-level function: lexical
		p.declareLex(name, namePos, false, true, false)
		p.bc.funcDecls = append(p.bc.funcDecls, fn)
		if !p.fc.strict {
			// Annex B: also var-declare in function scope if no conflict
			conflict := false
			for bc := p.bc.parent; bc != nil; bc = bc.parent {
				if bc.lexSet[name] && !bc.isFuncBody {
					conflict = true
				}
				if bc.isFuncBody {
					if bc.lexSet[name] {
						conflict = true
					}
					break
				}
			}
			if !conflict && !p.fc.paramNames[name] {
				if !p.fc.varNames[name] {
					p.fc.varNames[name] = true
					p.fc.varList = append(p.fc.varList, name)
				}
				fn.AnnexB = true
			}
		}
	}
	return &FuncDecl{NodeBase{pos}, fn}
}

// parseFunctionRest parses params and body. Current token is '('.
func (p *Parser) parseFunctionRest(pos int, name string, kind FuncKind, isAsync, isGen bool, isMethodLike bool) *FuncNode {
	fn := &FuncNode{NodeBase: NodeBase{pos}, Name: name, Kind: kind, IsAsync: isAsync, IsGenerator: isGen, SrcStart: pos}
	fn.Line, fn.Col = p.lex.lineCol(pos)
	fc := p.pushFunc(fn)
	fc.isAsync = isAsync
	fc.isGenerator = isGen
	fc.allowNewTarget = true
	if kind == FuncMethod || kind == FuncGetter || kind == FuncSetter || kind == FuncClassConstructor || kind == FuncDerivedConstructor || kind == FuncClassFieldInit {
		fc.allowSuperProp = true
	}
	if kind == FuncDerivedConstructor {
		fc.allowSuperCall = true
	}
	fc.inClassFieldInit = false
	bc := p.pushBlock(true)
	p.expectPunct("(")
	p.parseFormalParams(fn)
	p.expectPunct(")")
	if kind == FuncGetter && len(fn.Params) != 0 {
		p.errAt(pos, "getter must have no params")
	}
	if kind == FuncSetter && (len(fn.Params) != 1 || isRest(fn.Params[0])) {
		p.errAt(pos, "setter must have exactly one param")
	}
	if !p.isPunct("{") {
		p.err("expecting '{'")
	}
	p.next()
	fn.Body = p.parseDirectivesAndBody(func() bool { return p.isPunct("}") }, nil)
	if fc.strict {
		fn.Strict = true
		// re-check param names under strict
		for _, pn := range fn.ParamNames {
			if pn == "eval" || pn == "arguments" || strictReserved[pn] {
				p.errAt(pos, "invalid variable name in strict mode")
			}
		}
		if fc.dupParams {
			p.errAt(pos, "duplicate parameter names not allowed in this context")
		}
		if name == "eval" || name == "arguments" {
			if kind == FuncNormal {
				p.errAt(pos, "invalid variable name in strict mode")
			}
		}
	}
	if fc.dupParams && (!fn.SimpleParams || isMethodLike || fn.IsArrow) {
		p.errAt(pos, "duplicate parameter names not allowed in this context")
	}
	fn.EndPos = p.tok.Pos + 1
	fn.SrcEnd = fn.EndPos
	fn.Source = p.src[fn.SrcStart:fn.SrcEnd]
	p.next() // }
	p.popBlock()
	fn.VarNames = fc.varList
	fn.FuncDecls = bc.funcDecls
	fn.LexNames = bc.lex
	fn.UsesArguments = fc.usesArguments
	fn.UsesThis = fc.usesThis
	fn.UsesEval = fc.usesEval
	fn.HasSuperCall = fc.hasSuperCall
	p.popFunc()
	if fc.usesEval && p.fc != nil {
		p.fc.usesEval = true // conservative
	}
	if fn.IsArrow && p.fc != nil {
		if fc.usesArguments {
			p.fc.usesArguments = true
		}
		if fc.usesThis {
			p.fc.usesThis = true
		}
		if fc.hasSuperCall {
			p.fc.hasSuperCall = true
		}
	}
	return fn
}

func isRest(n Node) bool {
	_, ok := n.(*RestElement)
	return ok
}

func (p *Parser) parseFormalParams(fn *FuncNode) {
	fn.SimpleParams = true
	p.fc.inParams = true
	for !p.isPunct(")") {
		if p.isPunct("...") {
			rpos := p.tok.Pos
			p.next()
			fn.SimpleParams = false
			t := p.parseBindingTarget("param")
			fn.Params = append(fn.Params, &RestElement{NodeBase{rpos}, t})
			if !p.isPunct(")") {
				p.err("rest parameter must be the last one")
			}
			break
		}
		ppos := p.tok.Pos
		t := p.parseBindingTarget("param")
		if _, ok := t.(*Ident); !ok {
			fn.SimpleParams = false
		}
		if p.isPunct("=") {
			fn.SimpleParams = false
			p.next()
			def := p.parseAssignExpr()
			if id, ok := t.(*Ident); ok {
				setFuncName(def, id.Name)
			}
			t = &AssignPattern{NodeBase{ppos}, t, def}
		}
		fn.Params = append(fn.Params, t)
		if !p.isPunct(")") {
			p.expectPunct(",")
		}
	}
	p.fc.inParams = false
}

// Arrow function: params already parsed as nodes
func (p *Parser) parseArrowBody(pos int, params []Node, isAsync bool, simple bool) *FuncNode {
	fn := &FuncNode{NodeBase: NodeBase{pos}, Kind: FuncArrow, IsArrow: true, IsAsync: isAsync, SrcStart: pos, Params: params, SimpleParams: simple}
	fn.Line, fn.Col = p.lex.lineCol(pos)
	fc := p.pushFunc(fn)
	fc.isAsync = isAsync
	fc.isGenerator = false
	bc := p.pushBlock(true)
	// declare param names
	collectBoundNames(params, func(n string, npos int) {
		if fc.paramNames[n] {
			fc.dupParams = true
		}
		fc.paramNames[n] = true
		fn.ParamNames = append(fn.ParamNames, n)
		p.checkBindingName(n, npos)
	})
	if fc.dupParams {
		p.errAt(pos, "duplicate parameter names not allowed in this context")
	}
	if p.isPunct("{") {
		p.next()
		fn.Body = p.parseDirectivesAndBody(func() bool { return p.isPunct("}") }, nil)
		fn.EndPos = p.tok.Pos + 1
		p.next()
	} else {
		fn.ExprBody = true
		saveNoIn := p.noIn
		p.noIn = false
		expr := p.parseAssignExpr()
		p.noIn = saveNoIn
		fn.Body = []Node{&ReturnStmt{NodeBase{expr.Pos()}, expr}}
		fn.EndPos = p.prevTok.Pos + len(p.prevTok.Raw)
	}
	if fc.strict {
		fn.Strict = true
		for _, pn := range fn.ParamNames {
			if pn == "eval" || pn == "arguments" || strictReserved[pn] {
				p.errAt(pos, "invalid variable name in strict mode")
			}
		}
	}
	fn.SrcEnd = fn.EndPos
	fn.Source = p.src[fn.SrcStart:fn.SrcEnd]
	p.popBlock()
	fn.VarNames = fc.varList
	fn.FuncDecls = bc.funcDecls
	fn.LexNames = bc.lex
	fn.UsesArguments = fc.usesArguments
	fn.UsesThis = fc.usesThis
	fn.UsesEval = fc.usesEval
	fn.HasSuperCall = fc.hasSuperCall
	p.popFunc()
	if p.fc != nil {
		if fc.usesArguments {
			p.fc.usesArguments = true
		}
		if fc.usesThis {
			p.fc.usesThis = true
		}
		if fc.usesEval {
			p.fc.usesEval = true
		}
		if fc.hasSuperCall {
			p.fc.hasSuperCall = true
		}
	}
	return fn
}

func collectBoundNames(nodes []Node, f func(string, int)) {
	for _, n := range nodes {
		collectBoundNamesNode(n, f)
	}
}

func collectBoundNamesNode(n Node, f func(string, int)) {
	switch t := n.(type) {
	case nil:
	case *Ident:
		f(t.Name, t.P)
	case *AssignPattern:
		collectBoundNamesNode(t.Target, f)
	case *RestElement:
		collectBoundNamesNode(t.Target, f)
	case *ArrayPattern:
		for _, e := range t.Elems {
			collectBoundNamesNode(e, f)
		}
	case *ObjectPattern:
		for _, pr := range t.Props {
			collectBoundNamesNode(pr.Target, f)
		}
		if t.Rest != nil {
			collectBoundNamesNode(t.Rest, f)
		}
	}
}

// ---------- Classes ----------

func (p *Parser) parseClassDeclaration() Node {
	pos := p.tok.Pos
	p.next()
	if p.tok.Kind != TIdent {
		p.err("class name expected")
	}
	namePos := p.tok.Pos
	name := p.tok.Val
	saveStrict := p.fc.strict
	p.fc.strict = true
	p.checkBindingName(name, namePos)
	p.fc.strict = saveStrict
	p.next()
	p.declareLex(name, namePos, false, false, true)
	cls := p.parseClassRest(pos, name, true)
	cls.IsExpr = false
	return &ClassDecl{NodeBase{pos}, cls}
}

func (p *Parser) parseClassRest(pos int, name string, hasName bool) *ClassNode {
	cls := &ClassNode{NodeBase: NodeBase{pos}, Name: name, HasName: hasName}
	saveStrict := p.fc.strict
	p.fc.strict = true
	if p.isKw("extends") {
		p.next()
		cls.SuperClass = p.parseLeftHandSideExpr()
	}
	p.expectPunct("{")
	p.privateNames = append(p.privateNames, map[string]bool{})
	p.classDepth++
	seenCtor := false
	for !p.isPunct("}") {
		if p.isPunct(";") {
			p.next()
			continue
		}
		mpos := p.tok.Pos
		m := &ClassMember{NodeBase: NodeBase{mpos}, Kind: PropMethod}
		isStatic := false
		if p.isIdent("static") {
			st := p.lexState()
			p.next()
			if p.isPunct("(") || p.isPunct("=") || p.isPunct(";") || p.isPunct("}") {
				p.restoreLexState(st)
			} else if p.isPunct("{") {
				// static block
				m.IsStaticBlock = true
				m.Static = true
				fn := &FuncNode{NodeBase: NodeBase{mpos}, Kind: FuncMethod, IsStaticBlock: true, SimpleParams: true, SrcStart: mpos}
				fn.Line, fn.Col = p.lex.lineCol(mpos)
				fc := p.pushFunc(fn)
				fc.allowSuperProp = true
				fc.allowNewTarget = true
				fc.inClassFieldInit = true
				fc.isAsync = false
				bc := p.pushBlock(true)
				p.next()
				for !p.isPunct("}") {
					if p.tok.Kind == TEOF {
						p.err("expecting '}'")
					}
					fn.Body = append(fn.Body, p.parseStatementListItem())
				}
				fn.EndPos = p.tok.Pos + 1
				fn.SrcEnd = fn.EndPos
				fn.Source = p.src[fn.SrcStart:fn.SrcEnd]
				p.next()
				p.popBlock()
				fn.Strict = true
				fn.VarNames = fc.varList
				fn.FuncDecls = bc.funcDecls
				fn.LexNames = bc.lex
				fn.UsesArguments = fc.usesArguments
				fn.UsesThis = true
				fn.UsesEval = fc.usesEval
				p.popFunc()
				m.Block = fn
				cls.Members = append(cls.Members, m)
				continue
			} else {
				isStatic = true
			}
		}
		m.Static = isStatic
		isAsync := false
		isGen := false
		kind := PropMethod
		if p.isIdent("async") {
			st := p.lexState()
			p.next()
			if (p.isPunct("(") || p.isPunct("=") || p.isPunct(";") || p.isPunct("}")) || p.tok.NLBefore {
				p.restoreLexState(st)
			} else {
				isAsync = true
			}
		}
		if p.isPunct("*") {
			isGen = true
			p.next()
		}
		if !isAsync && !isGen && (p.isIdent("get") || p.isIdent("set")) {
			st := p.lexState()
			which := p.tok.Val
			p.next()
			if p.isPunct("(") || p.isPunct("=") || p.isPunct(";") || p.isPunct("}") {
				p.restoreLexState(st)
			} else {
				if which == "get" {
					kind = PropGet
				} else {
					kind = PropSet
				}
			}
		}
		// key
		kpos := p.tok.Pos
		if p.tok.Kind == TPrivateName {
			m.IsPrivate = true
			m.KeyName = p.tok.Val
			if m.KeyName == "constructor" {
				p.err("invalid private name")
			}
			pn := p.privateNames[len(p.privateNames)-1]
			// allow getter+setter pair
			key := m.KeyName
			if pn[key] {
				okPair := false
				if kind == PropGet && pn[key+"\x00set"] && !pn[key+"\x00get"] {
					okPair = true
				}
				if kind == PropSet && pn[key+"\x00get"] && !pn[key+"\x00set"] {
					okPair = true
				}
				if !okPair {
					p.err("duplicate private name")
				}
			}
			pn[key] = true
			if kind == PropGet {
				pn[key+"\x00get"] = true
			} else if kind == PropSet {
				pn[key+"\x00set"] = true
			} else {
				pn[key+"\x00get"] = true
				pn[key+"\x00set"] = true
			}
			if isStatic {
				pn[key+"\x00static"] = true
			}
			p.next()
		} else if p.isPunct("[") {
			p.next()
			m.Key = p.parseAssignExpr()
			m.Computed = true
			p.expectPunct("]")
		} else {
			keyName, keyNode, _ := p.parsePropertyName()
			m.Key = keyNode
			m.KeyName = keyName
		}
		if p.isPunct("(") {
			// method
			fkind := FuncMethod
			isCtor := false
			if !m.Computed && !m.IsPrivate && !isStatic && m.KeyName == "constructor" {
				if kind != PropMethod || isAsync || isGen {
					p.errAt(kpos, "invalid constructor")
				}
				if seenCtor {
					p.errAt(kpos, "property constructor appears more than once")
				}
				seenCtor = true
				isCtor = true
				if cls.SuperClass != nil {
					fkind = FuncDerivedConstructor
				} else {
					fkind = FuncClassConstructor
				}
			} else if kind == PropGet {
				fkind = FuncGetter
			} else if kind == PropSet {
				fkind = FuncSetter
			}
			if !m.Computed && isStatic && m.KeyName == "prototype" && !m.IsPrivate {
				p.errAt(kpos, "invalid property name")
			}
			fname := m.KeyName
			if m.IsPrivate {
				fname = "#" + m.KeyName
			}
			fn := p.parseFunctionRest(kpos, fname, fkind, isAsync, isGen, true)
			fn.IsExpr = true
			fn.NameIsComputed = m.Computed
			if isCtor {
				fn.Name = name
				cls.Constructor = fn
				continue
			}
			m.Kind = kind
			m.Value = fn
		} else {
			// field
			if kind != PropMethod || isAsync || isGen {
				p.err("expecting '('")
			}
			if !m.Computed && !m.IsPrivate && (m.KeyName == "constructor" || (isStatic && m.KeyName == "prototype")) {
				p.errAt(kpos, "invalid field name")
			}
			m.Kind = PropInit
			// initializer parsed as a function body for `this`
			fn := &FuncNode{NodeBase: NodeBase{kpos}, Kind: FuncClassFieldInit, SimpleParams: true, SrcStart: kpos, Strict: true}
			fn.Line, fn.Col = p.lex.lineCol(kpos)
			fc := p.pushFunc(fn)
			fc.allowSuperProp = true
			fc.allowNewTarget = true
			fc.inClassFieldInit = true
			bc := p.pushBlock(true)
			if p.isPunct("=") {
				p.next()
				init := p.parseAssignExpr()
				if !m.Computed {
					if m.IsPrivate {
						setFuncName(init, "#"+m.KeyName)
					} else {
						setFuncName(init, m.KeyName)
					}
				}
				m.Value = init
				fn.Body = []Node{&ReturnStmt{NodeBase{init.Pos()}, init}}
				fn.ExprBody = true
			}
			fn.EndPos = p.tok.Pos
			fn.SrcEnd = fn.EndPos
			p.popBlock()
			fn.VarNames = fc.varList
			fn.FuncDecls = bc.funcDecls
			fn.UsesArguments = fc.usesArguments
			fn.UsesThis = true
			fn.UsesEval = fc.usesEval
			p.popFunc()
			m.FieldInit = fn
			p.semicolon()
		}
		cls.Members = append(cls.Members, m)
	}
	// check private name references in the class body
	p.classDepth--
	pn := p.privateNames[len(p.privateNames)-1]
	p.privateNames = p.privateNames[:len(p.privateNames)-1]
	for _, ref := range p.pendingPrivateRefs {
		if ref.depth == p.classDepth+1 {
			if !pn[ref.name] {
				if len(p.privateNames) > 0 {
					// defer to outer class
					ref.depth--
					continue
				}
				p.errAt(ref.pos, "undefined private field '%s'", ref.name)
			}
		}
	}
	// drop resolved refs
	var remaining []privateRef
	for _, ref := range p.pendingPrivateRefs {
		if ref.depth <= p.classDepth && ref.depth > 0 {
			remaining = append(remaining, ref)
		}
	}
	p.pendingPrivateRefs = remaining
	endPos := p.tok.Pos + 1
	p.next()
	cls.Source = p.src[pos:endPos]
	p.fc.strict = saveStrict
	return cls
}

type privateRef struct {
	name  string
	pos   int
	depth int
}

func (p *Parser) usePrivateName(name string, pos int) {
	if p.classDepth == 0 {
		p.errAt(pos, "undefined private field '%s'", name)
	}
	p.pendingPrivateRefs = append(p.pendingPrivateRefs, privateRef{name, pos, p.classDepth})
}

// ---------- Modules ----------

func (p *Parser) parseModuleSpecifierString() string {
	if p.tok.Kind != TString {
		p.err("string expected")
	}
	s := p.tok.Val
	p.next()
	return s
}

func (p *Parser) parseImportDeclaration() Node {
	pos := p.tok.Pos
	p.next() // import
	d := &ImportDecl{NodeBase: NodeBase{pos}}
	if p.tok.Kind == TString {
		d.Source = p.parseModuleSpecifierString()
		p.parseImportAttributes()
		p.semicolon()
		return d
	}
	if p.tok.Kind == TIdent && !p.isIdent("from") || (p.isIdent("from") && p.peekIsFrom()) {
		// default import
		npos := p.tok.Pos
		name := p.parseBindingIdentifier()
		p.declareLex(name, npos, true, false, false)
		d.Specs = append(d.Specs, ImportSpec{"default", name})
		if p.isPunct(",") {
			p.next()
		} else {
			p.expectFrom()
			d.Source = p.parseModuleSpecifierString()
			p.parseImportAttributes()
			p.semicolon()
			return d
		}
	}
	if p.isPunct("*") {
		p.next()
		if !p.isIdent("as") {
			p.err("expecting 'as'")
		}
		p.next()
		npos := p.tok.Pos
		name := p.parseBindingIdentifier()
		p.declareLex(name, npos, true, false, false)
		d.Specs = append(d.Specs, ImportSpec{"*", name})
	} else if p.isPunct("{") {
		p.next()
		for !p.isPunct("}") {
			var imported string
			if p.tok.Kind == TString {
				imported = p.tok.Val
				p.next()
			} else if p.tok.Kind == TIdent || p.tok.Kind == TKeyword {
				imported = p.tok.Val
				p.next()
			} else {
				p.err("identifier expected")
			}
			local := imported
			lpos := p.tok.Pos
			if p.isIdent("as") {
				p.next()
				lpos = p.tok.Pos
				local = p.parseBindingIdentifier()
			} else {
				if keywords[local] {
					p.err("invalid import binding")
				}
				p.checkBindingName(local, lpos)
			}
			p.declareLex(local, lpos, true, false, false)
			d.Specs = append(d.Specs, ImportSpec{imported, local})
			if !p.isPunct("}") {
				p.expectPunct(",")
			}
		}
		p.next()
	} else {
		p.err("invalid import")
	}
	p.expectFrom()
	d.Source = p.parseModuleSpecifierString()
	p.parseImportAttributes()
	p.semicolon()
	return d
}

func (p *Parser) parseImportAttributes() {
	if (p.isKw("with") || p.isIdent("assert")) && !p.tok.NLBefore {
		p.next()
		p.expectPunct("{")
		for !p.isPunct("}") {
			if p.tok.Kind == TIdent || p.tok.Kind == TString || p.tok.Kind == TKeyword {
				p.next()
			} else {
				p.err("identifier expected")
			}
			p.expectPunct(":")
			if p.tok.Kind != TString {
				p.err("string expected")
			}
			p.next()
			if !p.isPunct("}") {
				p.expectPunct(",")
			}
		}
		p.next()
	}
}

func (p *Parser) peekIsFrom() bool {
	// current token is identifier 'from'; it's a default import name if followed by 'from'
	st := p.lexState()
	p.next()
	r := p.isIdent("from") || p.isPunct(",")
	p.restoreLexState(st)
	return r
}

func (p *Parser) expectFrom() {
	if !p.isIdent("from") {
		p.err("expecting 'from'")
	}
	p.next()
}

func (p *Parser) parseExportDeclaration() Node {
	pos := p.tok.Pos
	p.next() // export
	d := &ExportDecl{NodeBase: NodeBase{pos}}
	switch {
	case p.isKw("default"):
		p.next()
		d.IsDefault = true
		if p.isKw("function") || (p.isIdent("async") && p.peekIsFunctionNoNL()) {
			isAsync := p.isIdent("async")
			// may be anonymous
			st := p.lexState()
			if isAsync {
				p.next()
			}
			p.next()
			isGen := false
			if p.isPunct("*") {
				isGen = true
				p.next()
			}
			if p.tok.Kind == TIdent {
				p.restoreLexState(st)
				fd := p.parseFunctionDeclaration(isAsync)
				d.Decl = fd
			} else {
				fn := p.parseFunctionRest(pos, "default", FuncNormal, isAsync, isGen, false)
				fn.IsExpr = true
				fn.Name = "default"
				d.Default = fn
			}
		} else if p.isKw("class") {
			st := p.lexState()
			p.next()
			if p.tok.Kind == TIdent && !p.isKw("extends") {
				p.restoreLexState(st)
				d.Decl = p.parseClassDeclaration()
			} else {
				cls := p.parseClassRest(pos, "default", false)
				cls.IsExpr = true
				d.Default = cls
			}
		} else {
			e := p.parseAssignExpr()
			setFuncName(e, "default")
			d.Default = e
			p.semicolon()
		}
		if p.exportedNames == nil {
			p.exportedNames = map[string]bool{}
		}
		if p.exportedNames["default"] {
			p.errAt(pos, "duplicate exported name 'default'")
		}
		p.exportedNames["default"] = true
		return d
	case p.isPunct("*"):
		p.next()
		d.IsStar = true
		if p.isIdent("as") {
			p.next()
			if p.tok.Kind == TIdent || p.tok.Kind == TString || p.tok.Kind == TKeyword {
				d.StarAs = p.tok.Val
				p.addExportedName(d.StarAs, p.tok.Pos)
				p.next()
			} else {
				p.err("identifier expected")
			}
		}
		p.expectFrom()
		d.Source = p.parseModuleSpecifierString()
		p.parseImportAttributes()
		p.semicolon()
		return d
	case p.isPunct("{"):
		p.next()
		for !p.isPunct("}") {
			var local string
			lpos := p.tok.Pos
			if p.tok.Kind == TIdent || p.tok.Kind == TKeyword || p.tok.Kind == TString {
				local = p.tok.Val
				p.next()
			} else {
				p.err("identifier expected")
			}
			exported := local
			epos := lpos
			if p.isIdent("as") {
				p.next()
				if p.tok.Kind == TIdent || p.tok.Kind == TKeyword || p.tok.Kind == TString {
					exported = p.tok.Val
					epos = p.tok.Pos
					p.next()
				} else {
					p.err("identifier expected")
				}
			}
			p.addExportedName(exported, epos)
			d.Specs = append(d.Specs, ExportSpec{local, exported})
			if !p.isPunct("}") {
				p.expectPunct(",")
			}
		}
		p.next()
		if p.isIdent("from") {
			p.next()
			d.Source = p.parseModuleSpecifierString()
			p.parseImportAttributes()
		} else {
			for _, s := range d.Specs {
				if keywords[s.Local] {
					p.errAt(pos, "invalid export")
				}
			}
		}
		p.semicolon()
		return d
	case p.isKw("var") || p.isKw("const") || p.isIdent("let"):
		kind := p.tok.Val
		vpos := p.tok.Pos
		p.next()
		vd := p.parseVarDeclarations(kind, vpos)
		p.semicolon()
		d.Decl = vd
		for _, decl := range vd.Decls {
			collectBoundNamesNode(decl.Target, func(n string, npos int) {
				p.addExportedName(n, npos)
				d.Specs = append(d.Specs, ExportSpec{n, n})
			})
		}
		return d
	case p.isKw("function") || (p.isIdent("async") && p.peekIsFunctionNoNL()):
		fd := p.parseFunctionDeclaration(p.isIdent("async")).(*FuncDecl)
		d.Decl = fd
		p.addExportedName(fd.Func.Name, fd.Pos())
		d.Specs = append(d.Specs, ExportSpec{fd.Func.Name, fd.Func.Name})
		return d
	case p.isKw("class"):
		cd := p.parseClassDeclaration().(*ClassDecl)
		d.Decl = cd
		p.addExportedName(cd.Class.Name, cd.Pos())
		d.Specs = append(d.Specs, ExportSpec{cd.Class.Name, cd.Class.Name})
		return d
	}
	p.err("invalid export syntax")
	return nil
}

func (p *Parser) addExportedName(name string, pos int) {
	if p.exportedNames == nil {
		p.exportedNames = map[string]bool{}
	}
	if p.exportedNames[name] {
		p.errAt(pos, "duplicate exported name '%s'", name)
	}
	p.exportedNames[name] = true
}

// setFuncName sets the inferred name for anonymous function/class expressions
func setFuncName(n Node, name string) {
	switch t := n.(type) {
	case *FuncNode:
		if t.Name == "" && !t.NameIsComputed {
			t.Name = name
			t.InferredName = true
		}
	case *ClassNode:
		if !t.HasName && t.Name == "" {
			t.Name = name
			t.InferredName = true
		}
	case *ParenExpr:
		// (function(){}) does not get a name? Actually it does per spec IsAnonymousFunctionDefinition on parenthesized... it does.
		setFuncName(t.X, name)
	}
}

