package main

// ---------- Expressions ----------

func (p *Parser) parseExpression() Node {
	e := p.parseExpressionNoValidate()
	p.validateExpr(e)
	return e
}

func (p *Parser) parseExpressionNoValidate() Node {
	pos := p.tok.Pos
	e := p.parseAssignExprNoValidate()
	if p.isPunct(",") {
		seq := &SeqExpr{NodeBase{pos}, []Node{e}}
		for p.isPunct(",") {
			p.next()
			seq.Exprs = append(seq.Exprs, p.parseAssignExprNoValidate())
		}
		return seq
	}
	return e
}

// validateExpr checks that no cover-grammar-only constructs remain (e.g. {a=1} object literals)
func (p *Parser) validateExpr(e Node) {
	switch t := e.(type) {
	case *ObjectLit:
		if t.CoverInitPos > 0 {
			p.errAt(t.CoverInitPos, "invalid property name")
		}
		for _, pr := range t.Props {
			if pr.Value != nil {
				p.validateExpr(pr.Value)
			}
			if pr.Computed && pr.Key != nil {
				p.validateExpr(pr.Key)
			}
		}
	case *ArrayLit:
		for _, el := range t.Elems {
			if el != nil {
				p.validateExpr(el)
			}
		}
	case *Spread:
		p.validateExpr(t.Arg)
	case *ParenExpr:
		p.validateExpr(t.X)
	case *SeqExpr:
		for _, x := range t.Exprs {
			p.validateExpr(x)
		}
	case *AssignExpr:
		if t.Op != "=" {
			p.validateExpr(t.Target)
		}
		p.validateExpr(t.Value)
	case *BinaryExpr:
		p.validateExpr(t.L)
		p.validateExpr(t.R)
	case *LogicalExpr:
		p.validateExpr(t.L)
		p.validateExpr(t.R)
	case *CondExpr:
		p.validateExpr(t.Test)
		p.validateExpr(t.Cons)
		p.validateExpr(t.Alt)
	case *UnaryExpr:
		p.validateExpr(t.X)
	case *CallExpr:
		p.validateExpr(t.Callee)
		for _, a := range t.Args {
			p.validateExpr(a)
		}
	case *NewExpr:
		p.validateExpr(t.Callee)
		for _, a := range t.Args {
			p.validateExpr(a)
		}
	case *MemberExpr:
		p.validateExpr(t.Obj)
		if t.Computed {
			p.validateExpr(t.Prop)
		}
	case *OptionalChain:
		p.validateExpr(t.X)
	case *TemplateLit:
		for _, x := range t.Exprs {
			p.validateExpr(x)
		}
	case *TaggedTemplate:
		p.validateExpr(t.Tag)
		p.validateExpr(t.Quasi)
	case *YieldExpr:
		if t.Arg != nil {
			p.validateExpr(t.Arg)
		}
	case *AwaitExpr:
		p.validateExpr(t.Arg)
	case *UpdateExpr:
		p.validateExpr(t.X)
	}
}

func (p *Parser) parseAssignExpr() Node {
	e := p.parseAssignExprNoValidate()
	p.validateExpr(e)
	return e
}

var assignOps = map[string]bool{"=": true, "+=": true, "-=": true, "*=": true, "/=": true, "%=": true, "**=": true, "<<=": true, ">>=": true, ">>>=": true, "&=": true, "|=": true, "^=": true, "&&=": true, "||=": true, "??=": true}

func (p *Parser) parseAssignExprNoValidate() Node {
	pos := p.tok.Pos
	// arrow function / async arrow detection
	if p.tok.Kind == TIdent || p.isKw("yield") || p.isKw("await") {
		if p.isIdent("async") {
			st := p.lexState()
			p.next()
			if !p.tok.NLBefore {
				if p.isKw("function") {
					p.restoreLexState(st)
					return p.parseAssignTail(p.parseConditional(), pos)
				}
				if p.tok.Kind == TIdent && !p.isIdent("of") || (p.tok.Kind == TIdent && p.isIdent("of") && p.peekArrow()) {
					// async x => ...
					ppos := p.tok.Pos
					name := p.tok.Val
					p.next()
					if p.isPunct("=>") && !p.tok.NLBefore {
						p.checkArrowParamName(name, ppos, true)
						p.next()
						fn := p.parseArrowBody(pos, []Node{&Ident{NodeBase{ppos}, name}}, true, true)
						return fn
					}
					p.restoreLexState(st)
				} else if p.isPunct("(") {
					// try async arrow params
					if fn := p.tryArrowParams(pos, true); fn != nil {
						return fn
					}
					p.restoreLexState(st)
				} else {
					p.restoreLexState(st)
				}
			} else {
				p.restoreLexState(st)
			}
		} else if p.isIdent("yield") && (p.fc.isGenerator) {
			return p.parseYield()
		} else if p.isKw("yield") {
			// can't be keyword in our lexer; handled above
		} else {
			// ident => ...
			st := p.lexState()
			name := p.tok.Val
			hasEsc := p.tok.HasEscape
			p.next()
			if p.isPunct("=>") && !p.tok.NLBefore {
				_ = hasEsc
				p.checkArrowParamName(name, pos, false)
				p.next()
				return p.parseArrowBody(pos, []Node{&Ident{NodeBase{pos}, name}}, false, true)
			}
			p.restoreLexState(st)
		}
	} else if p.isPunct("(") {
		if fn := p.tryArrowParams(pos, false); fn != nil {
			return fn
		}
	}
	lhs := p.parseConditional()
	return p.parseAssignTail(lhs, pos)
}

func (p *Parser) peekArrow() bool {
	st := p.lexState()
	p.next()
	r := p.isPunct("=>")
	p.restoreLexState(st)
	return r
}

func (p *Parser) checkArrowParamName(name string, pos int, isAsync bool) {
	if keywords[name] && name != "yield" && name != "await" {
		p.errAt(pos, "unexpected token in expression: '%s'", name)
	}
	if name == "await" && (isAsync || p.fc.isAsync || p.isModule) {
		p.errAt(pos, "await is a reserved identifier")
	}
	if name == "yield" && (p.fc.isGenerator || p.fc.strict) {
		p.errAt(pos, "yield is a reserved identifier")
	}
	if p.fc.strict && (name == "eval" || name == "arguments" || strictReserved[name]) {
		p.errAt(pos, "invalid variable name in strict mode")
	}
}

func (p *Parser) parseAssignTail(lhs Node, pos int) Node {
	if p.tok.Kind == TPunct && assignOps[p.tok.Val] {
		op := p.tok.Val
		opPos := p.tok.Pos
		var target Node
		if op == "=" {
			target = p.toAssignTarget(lhs, false)
		} else {
			target = p.checkSimpleTarget(lhs, opPos)
		}
		p.next()
		rhs := p.parseAssignExpr()
		if id, ok := target.(*Ident); ok && (op == "=" || op == "&&=" || op == "||=" || op == "??=") {
			setFuncName(rhs, id.Name)
		}
		return &AssignExpr{NodeBase{pos}, op, target, rhs}
	}
	return lhs
}

// checkSimpleTarget validates an identifier or member expression as assignment target
func (p *Parser) checkSimpleTarget(e Node, pos int) Node {
	switch t := e.(type) {
	case *Ident:
		if p.fc.strict && (t.Name == "eval" || t.Name == "arguments") {
			p.errAt(t.P, "invalid assignment left-hand side")
		}
		return t
	case *MemberExpr:
		if t.Optional || t.InChain {
			p.errAt(pos, "invalid assignment left-hand side")
		}
		return t
	case *PrivateMemberExpr:
		if t.Optional || t.InChain {
			p.errAt(pos, "invalid assignment left-hand side")
		}
		return t
	case *ParenExpr:
		inner := t.X
		switch inner.(type) {
		case *Ident, *MemberExpr, *PrivateMemberExpr:
			return p.checkSimpleTarget(inner, pos)
		}
	case *OptionalChain:
		p.errAt(pos, "invalid assignment left-hand side")
	case *CallExpr:
		// Annex B: f() = 1 is a runtime ReferenceError in sloppy mode; QuickJS gives syntax error
		p.errAt(pos, "invalid assignment left-hand side")
	}
	p.errAt(pos, "invalid assignment left-hand side")
	return nil
}

// toAssignTarget converts an expression (cover grammar) to an assignment pattern
func (p *Parser) toAssignTarget(e Node, forIn bool) Node {
	switch t := e.(type) {
	case *Ident, *MemberExpr, *PrivateMemberExpr:
		return p.checkSimpleTarget(e, e.Pos())
	case *ParenExpr:
		switch t.X.(type) {
		case *Ident, *MemberExpr, *PrivateMemberExpr:
			return p.checkSimpleTarget(t.X, t.X.Pos())
		}
		p.errAt(t.P, "invalid assignment left-hand side")
	case *ObjectLit:
		op := &ObjectPattern{NodeBase: NodeBase{t.P}}
		for i, pr := range t.Props {
			switch pr.Kind {
			case PropSpread:
				if i != len(t.Props)-1 {
					p.errAt(pr.P, "rest element must be the last one")
				}
				switch pr.Value.(type) {
				case *Ident, *MemberExpr:
					op.Rest = p.toAssignTarget(pr.Value, false)
				default:
					p.errAt(pr.Value.Pos(), "invalid destructuring target")
				}
			case PropInit, PropShorthand:
				pp := &PatternProp{Key: pr.Key, Computed: pr.Computed, KeyName: pr.KeyName}
				pp.Target = p.toAssignTargetWithDefault(pr.Value)
				if pr.Kind == PropShorthand {
					if id, ok := pr.Value.(*Ident); ok {
						p.checkSimpleTarget(id, id.P)
					}
				}
				op.Props = append(op.Props, pp)
			default:
				p.errAt(pr.P, "invalid destructuring target")
			}
		}
		return op
	case *ArrayLit:
		ap := &ArrayPattern{NodeBase: NodeBase{t.P}}
		for i, el := range t.Elems {
			if el == nil {
				ap.Elems = append(ap.Elems, nil)
				continue
			}
			if sp, ok := el.(*Spread); ok {
				if i != len(t.Elems)-1 || t.TrailingCommaAfterSpread {
					p.errAt(sp.P, "rest element must be the last one")
				}
				ap.Elems = append(ap.Elems, &RestElement{NodeBase{sp.P}, p.toAssignTarget(sp.Arg, false)})
				continue
			}
			ap.Elems = append(ap.Elems, p.toAssignTargetWithDefault(el))
		}
		return ap
	case *AssignExpr:
		// only valid nested as default (handled by toAssignTargetWithDefault)
		p.errAt(t.P, "invalid destructuring target")
	}
	p.errAt(e.Pos(), "invalid assignment left-hand side")
	return nil
}

func (p *Parser) toAssignTargetWithDefault(e Node) Node {
	if a, ok := e.(*AssignExpr); ok && a.Op == "=" {
		// already converted target on parse (since Target was converted by toAssignTarget when parsed)
		return &AssignPattern{NodeBase{a.P}, a.Target, a.Value}
	}
	if cv, ok := e.(*CoverInit); ok {
		return &AssignPattern{NodeBase{cv.P}, cv.Target, cv.Default}
	}
	switch e.(type) {
	case *ObjectLit, *ArrayLit, *Ident, *MemberExpr, *ParenExpr, *PrivateMemberExpr:
		return p.toAssignTarget(e, false)
	}
	p.errAt(e.Pos(), "invalid destructuring target")
	return nil
}

// CoverInit represents `a = 1` inside an object literal (only valid as pattern)
type CoverInit struct {
	NodeBase
	Target  Node
	Default Node
}

// tryArrowParams attempts to parse "( params ) =>" ; returns nil (with state restored) if not an arrow
func (p *Parser) tryArrowParams(pos int, isAsync bool) (result *FuncNode) {
	st := p.lexState()
	saveFc := p.fc
	saveFcs := len(p.fcs)
	saveBc := p.bc
	savePending := len(p.pendingPrivateRefs)
	saveTLA := p.hasTLA
	ok := func() (ok bool) {
		defer func() {
			if r := recover(); r != nil {
				if _, isSE := r.(*SyntaxError); isSE {
					ok = false
					return
				}
				panic(r)
			}
		}()
		// scan params quickly: we need to find matching ')' then '=>'
		// Use a lightweight token scan with nesting (regex/template ambiguity is rare in params).
		depth := 0
		for {
			if p.tok.Kind == TEOF {
				return false
			}
			if p.tok.Kind == TPunct {
				switch p.tok.Val {
				case "(", "[", "{":
					depth++
				case ")", "]", "}":
					depth--
				}
			}
			if p.tok.Kind == TTemplate && !p.tok.TplTail {
				// skip template substitutions
				p.skipTemplate()
				continue
			}
			p.next()
			if depth == 0 {
				break
			}
		}
		return p.isPunct("=>") && !p.tok.NLBefore
	}()
	p.restoreLexState(st)
	p.fc = saveFc
	p.fcs = p.fcs[:saveFcs]
	p.bc = saveBc
	p.pendingPrivateRefs = p.pendingPrivateRefs[:savePending]
	p.hasTLA = saveTLA
	if !ok {
		return nil
	}
	// parse as arrow params for real
	fn := &FuncNode{NodeBase: NodeBase{pos}, Kind: FuncArrow, IsArrow: true, IsAsync: isAsync, SrcStart: pos}
	fn.Line, fn.Col = p.lex.lineCol(pos)
	fc := p.pushFunc(fn)
	fc.isAsync = isAsync
	fc.isGenerator = false
	bc := p.pushBlock(true)
	p.expectPunct("(")
	p.parseFormalParams(fn)
	p.expectPunct(")")
	if !p.isPunct("=>") {
		p.err("expecting '=>'")
	}
	if p.tok.NLBefore {
		p.err("line terminator not allowed before '=>'")
	}
	p.next()
	for _, pn := range fn.ParamNames {
		if pn == "await" && (isAsync || saveFc.isAsync || p.isModule) {
			p.errAt(pos, "await is a reserved identifier")
		}
		if pn == "yield" && (saveFc.isGenerator || saveFc.strict) {
			p.errAt(pos, "yield is a reserved identifier")
		}
	}
	if fc.dupParams {
		p.errAt(pos, "duplicate parameter names not allowed in this context")
	}
	if fc.sawAwaitInParams || fc.sawYieldInParams {
		p.errAt(pos, "await/yield not allowed in arrow parameters")
	}
	// body
	if p.isPunct("{") {
		p.next()
		fn.Body = p.parseDirectivesAndBody(func() bool { return p.isPunct("}") }, nil)
		fn.EndPos = p.tok.Pos + 1
		p.next()
	} else {
		fn.ExprBody = true
		saveNoIn := p.noIn
		p.noIn = false
		expr := p.parseAssignExpr()
		p.noIn = saveNoIn
		fn.Body = []Node{&ReturnStmt{NodeBase{expr.Pos()}, expr}}
		fn.EndPos = p.prevTok.Pos + len(p.prevTok.Raw)
	}
	if fc.strict {
		fn.Strict = true
		for _, pn := range fn.ParamNames {
			if pn == "eval" || pn == "arguments" || strictReserved[pn] {
				p.errAt(pos, "invalid variable name in strict mode")
			}
		}
	}
	fn.SrcEnd = fn.EndPos
	fn.Source = p.src[fn.SrcStart:fn.SrcEnd]
	p.popBlock()
	fn.VarNames = fc.varList
	fn.FuncDecls = bc.funcDecls
	fn.LexNames = bc.lex
	fn.UsesArguments = fc.usesArguments
	fn.UsesThis = fc.usesThis
	fn.UsesEval = fc.usesEval
	fn.HasSuperCall = fc.hasSuperCall
	p.popFunc()
	if p.fc != nil {
		if fc.usesArguments {
			p.fc.usesArguments = true
		}
		if fc.usesThis {
			p.fc.usesThis = true
		}
		if fc.usesEval {
			p.fc.usesEval = true
		}
		if fc.hasSuperCall {
			p.fc.hasSuperCall = true
		}
	}
	return fn
}

func (p *Parser) skipTemplate() {
	// current token is a template head; skip through substitutions
	for {
		if p.tok.Kind == TTemplate && p.tok.TplTail {
			p.next()
			return
		}
		if p.tok.Kind == TTemplate {
			p.next()
			depth := 0
			for {
				if p.tok.Kind == TEOF {
					p.err("unexpected end of input")
				}
				if p.isPunct("{") || p.isPunct("(") || p.isPunct("[") {
					depth++
				} else if p.isPunct("}") {
					if depth == 0 {
						p.tok = p.lex.ScanTemplateContinue()
						break
					}
					depth--
				} else if p.isPunct(")") || p.isPunct("]") {
					depth--
				} else if p.tok.Kind == TTemplate && !p.tok.TplTail {
					p.skipTemplate()
					continue
				}
				p.next()
			}
			continue
		}
		return
	}
}

func (p *Parser) parseYield() Node {
	pos := p.tok.Pos
	if p.fc.inParams {
		p.fc.sawYieldInParams = true
		p.err("yield in parameters")
	}
	p.next()
	y := &YieldExpr{NodeBase: NodeBase{pos}}
	if p.tok.NLBefore {
		return y
	}
	if p.isPunct("*") {
		y.Delegate = true
		p.next()
		y.Arg = p.parseAssignExpr()
		return y
	}
	switch {
	case p.isPunct(")"), p.isPunct("]"), p.isPunct("}"), p.isPunct(","), p.isPunct(";"), p.isPunct(":"), p.tok.Kind == TEOF, p.isKw("in") && false:
		return y
	case p.tok.Kind == TTemplate && p.tok.Raw != "" && false:
		return y
	}
	if p.isKw("in") || p.isIdent("of") || p.isPunct("?") {
		return y
	}
	y.Arg = p.parseAssignExpr()
	return y
}

func (p *Parser) parseConditional() Node {
	pos := p.tok.Pos
	test := p.parseBinary(0)
	if p.isPunct("?") {
		p.next()
		saveNoIn := p.noIn
		p.noIn = false
		cons := p.parseAssignExpr()
		p.noIn = saveNoIn
		p.expectPunct(":")
		alt := p.parseAssignExpr()
		return &CondExpr{NodeBase{pos}, test, cons, alt}
	}
	return test
}

var binPrec = map[string]int{
	"??": 1,
	"||": 2, "&&": 3, "|": 4, "^": 5, "&": 6,
	"==": 7, "!=": 7, "===": 7, "!==": 7,
	"<": 8, ">": 8, "<=": 8, ">=": 8, "instanceof": 8, "in": 8,
	"<<": 9, ">>": 9, ">>>": 9,
	"+": 10, "-": 10,
	"*": 11, "/": 11, "%": 11,
	"**": 12,
}

func (p *Parser) binOp() (string, int) {
	if p.tok.Kind == TPunct {
		if prec, ok := binPrec[p.tok.Val]; ok {
			return p.tok.Val, prec
		}
	} else if p.tok.Kind == TKeyword && (p.tok.Val == "instanceof" || (p.tok.Val == "in" && !p.noIn)) {
		return p.tok.Val, 8
	}
	return "", -1
}

func (p *Parser) parseBinary(minPrec int) Node {
	pos := p.tok.Pos
	var left Node
	// private name `#x in obj`
	if p.tok.Kind == TPrivateName {
		name := p.tok.Val
		ppos := p.tok.Pos
		p.next()
		if !p.isKw("in") || p.noIn {
			p.errAt(ppos, "unexpected token in expression: '#%s'", name)
		}
		if minPrec > 8 {
			p.errAt(ppos, "unexpected token in expression: '#%s'", name)
		}
		p.usePrivateName(name, ppos)
		p.next()
		right := p.parseBinary(9)
		left = &PrivateInExpr{NodeBase{pos}, name, right}
	} else {
		left = p.parseUnary()
	}
	for {
		op, prec := p.binOp()
		if prec < 0 || prec < minPrec || (prec == minPrec && op != "**") {
			// equal precedence left-assoc handled by loop in caller level
			if prec >= 0 && prec == minPrec && op == "**" {
				// right assoc handled below
			} else {
				return left
			}
		}
		opPos := p.tok.Pos
		p.next()
		var right Node
		if op == "**" {
			// right associative; unary on the left is a syntax error
			if u, ok := left.(*UnaryExpr); ok && !u.Parenthesized {
				p.errAt(opPos, "unparenthesized unary expression can't appear on the left-hand side of '**'")
			}
			if a, ok := left.(*AwaitExpr); ok && !a.Parenthesized {
				_ = a
			}
			right = p.parseBinary(prec) // right assoc
		} else {
			right = p.parseBinary(prec + 1)
		}
		switch op {
		case "&&", "||", "??":
			// mixing ?? with && / || without parens is an error
			if op == "??" {
				if l, ok := left.(*LogicalExpr); ok && (l.Op == "&&" || l.Op == "||") && !l.Parenthesized {
					p.errAt(opPos, "cannot mix ?? with && or ||")
				}
				if r, ok := right.(*LogicalExpr); ok && (r.Op == "&&" || r.Op == "||") && !r.Parenthesized {
					p.errAt(opPos, "cannot mix ?? with && or ||")
				}
			} else {
				if l, ok := left.(*LogicalExpr); ok && l.Op == "??" && !l.Parenthesized {
					p.errAt(opPos, "cannot mix ?? with && or ||")
				}
				if r, ok := right.(*LogicalExpr); ok && r.Op == "??" && !r.Parenthesized {
					p.errAt(opPos, "cannot mix ?? with && or ||")
				}
			}
			left = &LogicalExpr{NodeBase{pos}, op, left, right, false}
		default:
			left = &BinaryExpr{NodeBase{pos}, op, left, right}
		}
	}
}

func (p *Parser) parseUnary() Node {
	pos := p.tok.Pos
	t := p.tok
	if t.Kind == TPunct {
		switch t.Val {
		case "!", "~", "+", "-":
			p.next()
			x := p.parseUnary()
			return &UnaryExpr{NodeBase{pos}, t.Val, x, false}
		case "++", "--":
			p.next()
			x := p.parseUnary()
			target := p.checkSimpleTargetUpdate(x, x.Pos())
			return &UpdateExpr{NodeBase{pos}, t.Val, true, target}
		}
	} else if t.Kind == TKeyword {
		switch t.Val {
		case "typeof", "void", "delete":
			p.next()
			x := p.parseUnary()
			if t.Val == "delete" && p.fc.strict {
				if _, ok := x.(*Ident); ok {
					p.errAt(pos, "cannot delete a direct reference in strict mode")
				}
				if pe, ok := x.(*ParenExpr); ok {
					if _, ok2 := pe.X.(*Ident); ok2 {
						p.errAt(pos, "cannot delete a direct reference in strict mode")
					}
				}
			}
			if t.Val == "delete" {
				if _, ok := x.(*PrivateMemberExpr); ok {
					p.errAt(pos, "cannot delete a private class field")
				}
			}
			return &UnaryExpr{NodeBase{pos}, t.Val, x, false}
		}
	} else if t.Kind == TIdent && t.Val == "await" && !t.HasEscape && (p.fc.isAsync || (p.fc.isModuleTop && p.isModule)) {
		if p.fc.inParams {
			p.fc.sawAwaitInParams = true
			p.err("await in parameters")
		}
		if p.fc.inClassFieldInit && p.fc.fn != nil && p.fc.fn.Kind == FuncClassFieldInit {
			p.err("await in class field initializer")
		}
		p.next()
		p.markTLA()
		x := p.parseUnary()
		return &AwaitExpr{NodeBase{pos}, x, false}
	}
	return p.parsePostfix()
}

func (p *Parser) checkSimpleTargetUpdate(x Node, pos int) Node {
	switch t := x.(type) {
	case *Ident:
		if p.fc.strict && (t.Name == "eval" || t.Name == "arguments") {
			p.errAt(pos, "invalid increment/decrement operand")
		}
		return t
	case *MemberExpr:
		if t.Optional || t.InChain {
			p.errAt(pos, "invalid increment/decrement operand")
		}
		return t
	case *PrivateMemberExpr:
		if t.Optional || t.InChain {
			p.errAt(pos, "invalid increment/decrement operand")
		}
		return t
	case *ParenExpr:
		switch t.X.(type) {
		case *Ident, *MemberExpr, *PrivateMemberExpr:
			return p.checkSimpleTargetUpdate(t.X, pos)
		}
	}
	p.errAt(pos, "invalid increment/decrement operand")
	return nil
}

func (p *Parser) parsePostfix() Node {
	pos := p.tok.Pos
	x := p.parseLeftHandSideExpr()
	if p.tok.Kind == TPunct && (p.tok.Val == "++" || p.tok.Val == "--") && !p.tok.NLBefore {
		op := p.tok.Val
		target := p.checkSimpleTargetUpdate(x, p.tok.Pos)
		p.next()
		return &UpdateExpr{NodeBase{pos}, op, false, target}
	}
	return x
}

// parseLeftHandSideExpr: new/call/member expressions
func (p *Parser) parseLeftHandSideExpr() Node {
	pos := p.tok.Pos
	var x Node
	if p.isKw("new") {
		x = p.parseNew()
	} else if p.isKw("super") {
		spos := p.tok.Pos
		p.next()
		if p.isPunct("(") {
			if !p.fc.allowSuperCall {
				p.errAt(spos, "unexpected 'super'")
			}
			p.fc.hasSuperCall = true
			p.fc.usesThis = true
			args := p.parseArguments()
			x = &CallExpr{NodeBase: NodeBase{spos}, Callee: &SuperExpr{NodeBase{spos}}, Args: args}
			x.(*CallExpr).P = p.prevTok.Pos
			x.(*CallExpr).P = spos
		} else if p.isPunct(".") || p.isPunct("[") {
			if !p.fc.allowSuperProp {
				p.errAt(spos, "unexpected 'super'")
			}
			p.fc.usesThis = true
			x = &SuperExpr{NodeBase{spos}}
		} else {
			p.errAt(spos, "unexpected 'super'")
		}
	} else if p.isKw("import") {
		ipos := p.tok.Pos
		p.next()
		if p.isPunct(".") {
			p.next()
			if !p.isIdent("meta") {
				p.err("expecting 'meta'")
			}
			if !p.isModule {
				p.errAt(ipos, "import.meta only valid in module code")
			}
			p.next()
			x = &ImportMetaExpr{NodeBase{ipos}}
		} else if p.isPunct("(") {
			p.next()
			saveNoIn := p.noIn
			p.noIn = false
			src := p.parseAssignExpr()
			var opts Node
			if p.isPunct(",") {
				p.next()
				if !p.isPunct(")") {
					opts = p.parseAssignExpr()
					if p.isPunct(",") {
						p.next()
					}
				}
			}
			p.noIn = saveNoIn
			p.expectPunct(")")
			x = &ImportCall{NodeBase{ipos}, src, opts}
		} else {
			p.err("expecting '('")
		}
	} else {
		x = p.parsePrimary()
	}
	return p.parseCallTail(x, pos, true)
}

func (p *Parser) parseNew() Node {
	pos := p.tok.Pos
	p.next() // new
	if p.isPunct(".") {
		p.next()
		if !p.isIdent("target") {
			p.err("expecting 'target'")
		}
		if !p.fc.allowNewTarget {
			p.err("new.target only allowed within functions")
		}
		p.fc.usesThis = true
		p.next()
		return &NewTargetExpr{NodeBase{pos}}
	}
	var callee Node
	if p.isKw("new") {
		callee = p.parseNew()
	} else if p.isKw("import") {
		p.err("invalid use of 'import()'")
	} else if p.isKw("super") {
		spos := p.tok.Pos
		p.next()
		if !p.isPunct(".") && !p.isPunct("[") {
			p.errAt(spos, "unexpected 'super'")
		}
		if !p.fc.allowSuperProp {
			p.errAt(spos, "unexpected 'super'")
		}
		p.fc.usesThis = true
		callee = &SuperExpr{NodeBase{spos}}
	} else {
		callee = p.parsePrimary()
	}
	// member accesses (no calls) bind to callee
	callee = p.parseCallTail(callee, callee.Pos(), false)
	var args []Node
	if p.isPunct("(") {
		args = p.parseArguments()
	}
	return &NewExpr{NodeBase{pos}, callee, args}
}

func (p *Parser) parseArguments() []Node {
	p.expectPunct("(")
	var args []Node
	saveNoIn := p.noIn
	p.noIn = false
	for !p.isPunct(")") {
		if p.isPunct("...") {
			spos := p.tok.Pos
			p.next()
			args = append(args, &Spread{NodeBase{spos}, p.parseAssignExpr()})
		} else {
			args = append(args, p.parseAssignExpr())
		}
		if !p.isPunct(")") {
			p.expectPunct(",")
		}
	}
	p.noIn = saveNoIn
	p.next()
	return args
}

// parseCallTail parses member accesses, calls, optional chains, tagged templates
func (p *Parser) parseCallTail(x Node, pos int, allowCall bool) Node {
	inChain := false
	for {
		switch {
		case p.isPunct("."):
			p.next()
			if p.tok.Kind == TPrivateName {
				name := p.tok.Val
				p.usePrivateName(name, p.tok.Pos)
				p.next()
				x = &PrivateMemberExpr{NodeBase{p.prevTok.Pos}, x, name, false, inChain}
				continue
			}
			if p.tok.Kind != TIdent && p.tok.Kind != TKeyword {
				p.err("expecting field name")
			}
			dotPos := p.prevTok.Pos
			name := p.tok.Val
			p.next()
			x = &MemberExpr{NodeBase: NodeBase{dotPos}, Obj: x, Prop: &StringLit{NodeBase{p.prevTok.Pos}, NewStringFromGo(name)}, Name: name, InChain: inChain}
		case p.isPunct("?."):
			if !allowCall {
				p.err("invalid optional chaining in new expression")
			}
			qpos := p.tok.Pos
			p.next()
			inChain = true
			if p.isPunct("(") {
				args := p.parseArguments()
				x = &CallExpr{NodeBase: NodeBase{qpos}, Callee: x, Args: args, Optional: true, InChain: true}
			} else if p.isPunct("[") {
				p.next()
				saveNoIn := p.noIn
				p.noIn = false
				prop := p.parseExpression()
				p.noIn = saveNoIn
				p.expectPunct("]")
				x = &MemberExpr{NodeBase: NodeBase{qpos}, Obj: x, Prop: prop, Computed: true, Optional: true, InChain: true}
			} else if p.tok.Kind == TPrivateName {
				name := p.tok.Val
				p.usePrivateName(name, p.tok.Pos)
				p.next()
				x = &PrivateMemberExpr{NodeBase{qpos}, x, name, true, true}
			} else if p.tok.Kind == TIdent || p.tok.Kind == TKeyword {
				name := p.tok.Val
				p.next()
				x = &MemberExpr{NodeBase: NodeBase{qpos}, Obj: x, Prop: &StringLit{NodeBase{p.prevTok.Pos}, NewStringFromGo(name)}, Name: name, Optional: true, InChain: true}
			} else if p.tok.Kind == TTemplate {
				p.err("optional chain not allowed with tagged template")
			} else {
				p.err("expecting field name")
			}
		case p.isPunct("["):
			bpos := p.tok.Pos
			p.next()
			saveNoIn := p.noIn
			p.noIn = false
			prop := p.parseExpression()
			p.noIn = saveNoIn
			p.expectPunct("]")
			x = &MemberExpr{NodeBase: NodeBase{bpos}, Obj: x, Prop: prop, Computed: true, InChain: inChain}
		case p.isPunct("(") && allowCall:
			cpos := p.tok.Pos
			args := p.parseArguments()
			ce := &CallExpr{NodeBase: NodeBase{cpos}, Callee: x, Args: args, InChain: inChain}
			if id, ok := x.(*Ident); ok && id.Name == "eval" {
				ce.IsDirectEval = true
				p.fc.usesEval = true
				p.fc.usesArguments = true
				p.fc.usesThis = true
			}
			x = ce
		case p.tok.Kind == TTemplate:
			if inChain {
				p.err("optional chain not allowed with tagged template")
			}
			tpos := p.tok.Pos
			quasi := p.parseTemplateLit(true)
			x = &TaggedTemplate{NodeBase: NodeBase{tpos}, Tag: x, Quasi: quasi}
		default:
			if inChain {
				return &OptionalChain{NodeBase{pos}, x}
			}
			return x
		}
	}
}

func (p *Parser) parseTemplateLit(tagged bool) *TemplateLit {
	pos := p.tok.Pos
	tl := &TemplateLit{NodeBase: NodeBase{pos}}
	for {
		t := p.tok
		if t.Kind != TTemplate {
			p.err("expecting template")
		}
		if t.TplCooked == nil {
			if !tagged {
				p.errAt(t.Pos, "malformed escape sequence in string literal")
			}
			tl.Cooked = append(tl.Cooked, nil)
		} else {
			tl.Cooked = append(tl.Cooked, NewStringFromGo(*t.TplCooked))
		}
		tl.Raws = append(tl.Raws, NewStringFromGo(t.Val))
		if t.TplTail {
			p.next()
			break
		}
		p.next()
		saveNoIn := p.noIn
		p.noIn = false
		e := p.parseExpression()
		p.noIn = saveNoIn
		tl.Exprs = append(tl.Exprs, e)
		if !p.isPunct("}") {
			p.err("expecting '}'")
		}
		p.tok = p.lex.ScanTemplateContinue()
	}
	return tl
}

func (p *Parser) parsePrimary() Node {
	t := p.tok
	pos := t.Pos
	switch t.Kind {
	case TNumber:
		if t.LegacyOctal && p.fc.strict {
			p.err("octal literals are deprecated in strict mode")
		}
		p.next()
		return &NumberLit{NodeBase{pos}, t.Num}
	case TBigInt:
		p.next()
		return &BigIntLit{NodeBase{pos}, t.Big}
	case TString:
		if t.LegacyOctal && p.fc.strict {
			p.err("octal escape sequences are not allowed in strict mode")
		}
		p.next()
		return &StringLit{NodeBase{pos}, NewStringFromGo(t.Val)}
	case TTemplate:
		return p.parseTemplateLit(false)
	case TRegExp:
		p.next()
		return &RegExpLit{NodeBase{pos}, t.Val, t.ReFlags}
	case TPrivateName:
		p.err("unexpected token in expression: '#%s'", t.Val)
	case TIdent:
		name := t.Val
		if !t.HasEscape || true {
			switch name {
			case "async":
				st := p.lexState()
				p.next()
				if p.isKw("function") && !p.tok.NLBefore {
					p.restoreLexState(st)
					return p.parseFunctionExpr()
				}
				p.restoreLexState(st)
			case "arguments":
				if p.fc.inClassFieldInit && p.fc.fn != nil && (p.fc.fn.Kind == FuncClassFieldInit || p.fc.fn.IsStaticBlock) {
					p.err("'arguments' identifier is not allowed in class field initializer")
				}
				p.fc.usesArguments = true
			case "yield":
				if p.fc.isGenerator || p.fc.strict {
					p.err("unexpected token in expression: 'yield'")
				}
			case "await":
				if p.fc.isAsync || p.isModule {
					p.err("unexpected token in expression: 'await'")
				}
				if p.fc.inClassFieldInit && p.fc.fn != nil && p.fc.fn.Kind == FuncClassFieldInit {
					p.err("await in class field initializer")
				}
			case "let":
				if p.fc.strict {
					p.err("invalid variable name in strict mode")
				}
			case "enum":
				p.err("unexpected token in expression: 'enum'")
			default:
				if p.fc.strict && strictReserved[name] {
					p.err("invalid variable name in strict mode")
				}
			}
		}
		if t.HasEscape && keywords[name] {
			p.err("invalid escape in keyword")
		}
		p.next()
		return &Ident{NodeBase{pos}, name}
	case TKeyword:
		switch t.Val {
		case "this":
			p.fc.usesThis = true
			p.next()
			return &ThisExpr{NodeBase{pos}}
		case "null":
			p.next()
			return &NullLit{NodeBase{pos}}
		case "true":
			p.next()
			return &BoolLit{NodeBase{pos}, true}
		case "false":
			p.next()
			return &BoolLit{NodeBase{pos}, false}
		case "function":
			return p.parseFunctionExpr()
		case "class":
			return p.parseClassExpr()
		case "new":
			return p.parseNew()
		case "super", "import":
			return p.parseLeftHandSideExpr()
		}
		p.err("unexpected token in expression: '%s'", t.Val)
	case TPunct:
		switch t.Val {
		case "(":
			p.next()
			saveNoIn := p.noIn
			p.noIn = false
			if p.isPunct(")") {
				p.err("unexpected token in expression: ')'")
			}
			e := p.parseExpressionNoValidate()
			p.noIn = saveNoIn
			p.expectPunct(")")
			pe := &ParenExpr{NodeBase{pos}, e}
			markParenthesized(e)
			return pe
		case "[":
			return p.parseArrayLit()
		case "{":
			return p.parseObjectLit()
		case "/", "/=":
			rt := p.lex.ScanRegExp(t)
			p.tok = rt
			p.next()
			return &RegExpLit{NodeBase{pos}, rt.Val, rt.ReFlags}
		}
	case TEOF:
		p.err("unexpected token in expression: ''")
	}
	p.err("unexpected token in expression: %s", p.tokDesc())
	return nil
}

func markParenthesized(e Node) {
	switch t := e.(type) {
	case *UnaryExpr:
		t.Parenthesized = true
	case *LogicalExpr:
		t.Parenthesized = true
	case *AwaitExpr:
		t.Parenthesized = true
	}
}

func (p *Parser) parseFunctionExpr() Node {
	pos := p.tok.Pos
	isAsync := false
	if p.isIdent("async") {
		isAsync = true
		p.next()
	}
	p.next() // function
	isGen := false
	if p.isPunct("*") {
		isGen = true
		p.next()
	}
	name := ""
	if p.tok.Kind == TIdent {
		name = p.tok.Val
		npos := p.tok.Pos
		// name is evaluated in the function's own context for yield/await
		if name == "yield" && (isGen || p.fc.strict) {
			p.errAt(npos, "yield is a reserved identifier")
		}
		if name == "await" && (isAsync || p.isModule) {
			p.errAt(npos, "await is a reserved identifier")
		}
		if p.fc.strict && (name == "eval" || name == "arguments" || strictReserved[name]) {
			p.errAt(npos, "invalid variable name in strict mode")
		}
		if name == "enum" {
			p.errAt(npos, "unexpected token in expression: 'enum'")
		}
		p.next()
	} else if p.tok.Kind == TKeyword {
		p.err("unexpected token in expression: '%s'", p.tok.Val)
	}
	fn := p.parseFunctionRest(pos, name, FuncNormal, isAsync, isGen, false)
	fn.IsExpr = true
	fn.HasOwnName = name != ""
	return fn
}

func (p *Parser) parseClassExpr() Node {
	pos := p.tok.Pos
	p.next()
	name := ""
	hasName := false
	if p.tok.Kind == TIdent {
		name = p.tok.Val
		hasName = true
		saveStrict := p.fc.strict
		p.fc.strict = true
		p.checkBindingName(name, p.tok.Pos)
		p.fc.strict = saveStrict
		p.next()
	}
	cls := p.parseClassRest(pos, name, hasName)
	cls.IsExpr = true
	return cls
}

func (p *Parser) parseArrayLit() Node {
	pos := p.tok.Pos
	p.next()
	al := &ArrayLit{NodeBase: NodeBase{pos}}
	saveNoIn := p.noIn
	p.noIn = false
	for !p.isPunct("]") {
		if p.isPunct(",") {
			p.next()
			al.Elems = append(al.Elems, nil)
			continue
		}
		var el Node
		if p.isPunct("...") {
			spos := p.tok.Pos
			p.next()
			el = &Spread{NodeBase{spos}, p.parseAssignExprNoValidate()}
		} else {
			el = p.parseAssignExprNoValidate()
		}
		al.Elems = append(al.Elems, el)
		if !p.isPunct("]") {
			p.expectPunct(",")
			if _, ok := el.(*Spread); ok && p.isPunct("]") {
				al.TrailingCommaAfterSpread = true
			}
		}
	}
	p.noIn = saveNoIn
	p.next()
	return al
}

func (p *Parser) parseObjectLit() Node {
	pos := p.tok.Pos
	p.next()
	ol := &ObjectLit{NodeBase: NodeBase{pos}}
	saveNoIn := p.noIn
	p.noIn = false
	hasProto := false
	for !p.isPunct("}") {
		ppos := p.tok.Pos
		pr := &Property{NodeBase: NodeBase{ppos}, Kind: PropInit}
		if p.isPunct("...") {
			p.next()
			pr.Kind = PropSpread
			pr.Value = p.parseAssignExprNoValidate()
			ol.Props = append(ol.Props, pr)
			if !p.isPunct("}") {
				p.expectPunct(",")
			}
			continue
		}
		isAsync := false
		isGen := false
		kind := PropInit
		if p.isIdent("async") {
			st := p.lexState()
			p.next()
			if p.isPunct("(") || p.isPunct(":") || p.isPunct(",") || p.isPunct("}") || p.isPunct("=") || p.tok.NLBefore {
				p.restoreLexState(st)
			} else {
				isAsync = true
			}
		}
		if p.isPunct("*") {
			isGen = true
			p.next()
		}
		if !isAsync && !isGen && (p.isIdent("get") || p.isIdent("set")) {
			st := p.lexState()
			which := p.tok.Val
			p.next()
			if p.isPunct("(") || p.isPunct(":") || p.isPunct(",") || p.isPunct("}") || p.isPunct("=") {
				p.restoreLexState(st)
			} else {
				if which == "get" {
					kind = PropGet
				} else {
					kind = PropSet
				}
			}
		}
		kpos := p.tok.Pos
		isIdentKey := false
		if p.isPunct("[") {
			p.next()
			pr.Key = p.parseAssignExpr()
			pr.Computed = true
			p.expectPunct("]")
		} else {
			keyName, keyNode, isId := p.parsePropertyName()
			pr.Key = keyNode
			pr.KeyName = keyName
			isIdentKey = isId && p.prevTok.Kind == TIdent
			if p.prevTok.Kind == TKeyword && (p.prevTok.Val == "yield" || p.prevTok.Val == "await") {
				isIdentKey = true
			}
		}
		if p.isPunct("(") {
			// method
			fkind := FuncMethod
			if kind == PropGet {
				fkind = FuncGetter
			} else if kind == PropSet {
				fkind = FuncSetter
			}
			fn := p.parseFunctionRest(kpos, pr.KeyName, fkind, isAsync, isGen, true)
			fn.IsExpr = true
			fn.NameIsComputed = pr.Computed
			if kind == PropInit {
				pr.Kind = PropMethod
			} else {
				pr.Kind = kind
			}
			pr.Value = fn
		} else {
			if isAsync || isGen || kind != PropInit {
				p.err("expecting '('")
			}
			if p.isPunct(":") {
				p.next()
				pr.Value = p.parseAssignExprNoValidate()
				if !pr.Computed {
					setFuncName(pr.Value, pr.KeyName)
				}
				if !pr.Computed && pr.KeyName == "__proto__" {
					if hasProto {
						p.errAt(kpos, "duplicate __proto__ property name")
					}
					hasProto = true
					pr.IsProto = true
				}
			} else if isIdentKey {
				// shorthand or cover-init
				name := pr.KeyName
				if keywords[name] && name != "yield" && name != "await" {
					p.errAt(kpos, "unexpected token in expression: '%s'", name)
				}
				if name == "yield" && (p.fc.isGenerator || p.fc.strict) {
					p.errAt(kpos, "unexpected token in expression: 'yield'")
				}
				if name == "await" && (p.fc.isAsync || p.isModule) {
					p.errAt(kpos, "unexpected token in expression: 'await'")
				}
				if p.fc.strict && strictReserved[name] {
					p.errAt(kpos, "invalid variable name in strict mode")
				}
				if name == "arguments" {
					p.fc.usesArguments = true
				}
				if name == "enum" {
					p.errAt(kpos, "unexpected token in expression: 'enum'")
				}
				id := &Ident{NodeBase{kpos}, name}
				if p.isPunct("=") {
					// cover initialized name
					eqPos := p.tok.Pos
					p.next()
					def := p.parseAssignExpr()
					setFuncName(def, name)
					pr.Kind = PropShorthand
					pr.Value = &CoverInit{NodeBase{kpos}, id, def}
					if ol.CoverInitPos == 0 {
						ol.CoverInitPos = eqPos
					}
				} else {
					pr.Kind = PropShorthand
					pr.Value = id
				}
			} else {
				p.err("expecting ':'")
			}
		}
		ol.Props = append(ol.Props, pr)
		if !p.isPunct("}") {
			p.expectPunct(",")
		}
	}
	p.noIn = saveNoIn
	p.next()
	return ol
}
EOF
echo ok"}

