package main

import (
	"math"
	"math/big"
	"strconv"
	"strings"
	"unicode/utf16"
	"unicode/utf8"
)

// Value is one of: undefinedType, nullType, bool, float64, *String, *Symbol, *big.Int, *Object
type Value interface{}

type undefinedType struct{}
type nullType struct{}
type holeType struct{} // array hole marker (never escapes to JS)

var Undefined Value = undefinedType{}
var Null Value = nullType{}
var hole Value = holeType{}

func isUndefined(v Value) bool { _, ok := v.(undefinedType); return ok }
func isNull(v Value) bool      { _, ok := v.(nullType); return ok }
func isNullish(v Value) bool {
	switch v.(type) {
	case undefinedType, nullType:
		return true
	}
	return false
}
func isObject(v Value) bool { _, ok := v.(*Object); return ok }
func isString(v Value) bool { _, ok := v.(*String); return ok }
func isNumber(v Value) bool { _, ok := v.(float64); return ok }
func isSymbol(v Value) bool { _, ok := v.(*Symbol); return ok }
func isBigInt(v Value) bool { _, ok := v.(*big.Int); return ok }
func isBool(v Value) bool   { _, ok := v.(bool); return ok }

// ---------- String ----------

// String is an immutable JS string. ASCII-only strings use s; others use u (UTF-16 code units).
type String struct {
	s string
	u []uint16
	isASCII bool
	key  string // cached key
	hasKey bool
}

var emptyString = &String{s: "", isASCII: true}

func NewStringFromGo(s string) *String {
	for i := 0; i < len(s); i++ {
		if s[i] >= 0x80 {
			return &String{u: decodeWTF8(s)}
		}
	}
	return &String{s: s, isASCII: true}
}

func NewStringFromUTF16(u []uint16) *String {
	for _, c := range u {
		if c >= 0x80 {
			return &String{u: u}
		}
	}
	b := make([]byte, len(u))
	for i, c := range u {
		b[i] = byte(c)
	}
	return &String{s: string(b), isASCII: true}
}

func NewStringFromRunes(rs []rune) *String {
	var sb strings.Builder
	for _, r := range rs {
		sb.WriteRune(r)
	}
	return NewStringFromGo(sb.String())
}

