	if c >= 0xD800 && c <= 0xDBFF && i+1 < s.Len() {
		d := s.At(i + 1)
		if d >= 0xDC00 && d <= 0xDFFF {
			return utf16.DecodeRune(rune(c), rune(d)), 2
		}
	}
	return rune(c), 1
}

type StringBuilder struct {
	ascii   []byte
	u       []uint16
	isASCII bool
}

func NewStringBuilder() *StringBuilder { return &StringBuilder{isASCII: true} }

func (b *StringBuilder) toU() {
	if b.isASCII {
		b.u = make([]uint16, len(b.ascii), len(b.ascii)+16)
		for i, c := range b.ascii {
			b.u[i] = uint16(c)
		}
		b.ascii = nil
		b.isASCII = false
	}
}

func (b *StringBuilder) WriteString(s *String) {
	if s.isASCII {
		if b.isASCII {
			b.ascii = append(b.ascii, s.s...)
		} else {
			for i := 0; i < len(s.s); i++ {
				b.u = append(b.u, uint16(s.s[i]))
			}
		}
	} else {
		b.toU()
		b.u = append(b.u, s.u...)
	}
}

func (b *StringBuilder) WriteGo(s string) {
	for i := 0; i < len(s); i++ {
		if s[i] >= 0x80 {
			b.toU()
			b.u = append(b.u, decodeWTF8(s)...)
			return
		}
	}
	if b.isASCII {
		b.ascii = append(b.ascii, s...)
	} else {
		for i := 0; i < len(s); i++ {
			b.u = append(b.u, uint16(s[i]))
		}
	}
}

func (b *StringBuilder) WriteUnit(c uint16) {
	if c < 0x80 && b.isASCII {
		b.ascii = append(b.ascii, byte(c))
	} else {
		b.toU()
		b.u = append(b.u, c)
	}
}

func (b *StringBuilder) WriteRune(r rune) {
	if r < 0x80 && b.isASCII {
		b.ascii = append(b.ascii, byte(r))
		return
	}
	b.toU()
	if r >= 0x10000 {
		r1, r2 := utf16.EncodeRune(r)
		b.u = append(b.u, uint16(r1), uint16(r2))
	} else {
		b.u = append(b.u, uint16(r))
	}
}

func (b *StringBuilder) Len() int {
	if b.isASCII {
		return len(b.ascii)
	}
	return len(b.u)
}

func (b *StringBuilder) String() *String {
	if b.isASCII {
		return &String{s: string(b.ascii), isASCII: true}
	}
	return NewStringFromUTF16(b.u)
}

