// ---------- Number formatting ----------

func numberToString(f float64) string {
	if f != f {
		return "NaN"
	}
	if f == 0 {
		return "0"
	}
	if math.IsInf(f, 1) {
		return "Infinity"
	}
	if math.IsInf(f, -1) {
		return "-Infinity"
	}
	if f == math.Trunc(f) && math.Abs(f) < 1e21 {
		if math.Abs(f) < 1e15 {
			return strconv.FormatInt(int64(f), 10)
		}
	}
	// shortest repr digits
	neg := f < 0
	if neg {
		f = -f
	}
	digits := strconv.FormatFloat(f, 'e', -1, 64) // d.ddddde±xx
	// parse mantissa digits and exponent
	epos := strings.IndexByte(digits, 'e')
	mant := digits[:epos]
	exp, _ := strconv.Atoi(digits[epos+1:])
	mant = strings.Replace(mant, ".", "", 1)
	k := len(mant)
	n := exp + 1 // decimal point position
	var sb strings.Builder
	if neg {
		sb.WriteByte('-')
	}
	if k <= n && n <= 21 {
		sb.WriteString(mant)
		for i := 0; i < n-k; i++ {
			sb.WriteByte('0')
		}
	} else if 0 < n && n <= 21 {
		sb.WriteString(mant[:n])
		sb.WriteByte('.')
		sb.WriteString(mant[n:])
	} else if -6 < n && n <= 0 {
		sb.WriteString("0.")
		for i := 0; i < -n; i++ {
			sb.WriteByte('0')
		}
		sb.WriteString(mant)
	} else {
		e := n - 1
		sb.WriteByte(mant[0])
		if k > 1 {
			sb.WriteByte('.')
			sb.WriteString(mant[1:])
		}
		sb.WriteByte('e')
		if e >= 0 {
			sb.WriteByte('+')
		}
		sb.WriteString(strconv.Itoa(e))
	}
	return sb.String()
}

// canonical numeric index string check: returns (index, true) if s is an array index (0..2^32-2)
func arrayIndexFromKey(s string) (uint32, bool) {
	n := len(s)
	if n == 0 || n > 10 {
		return 0, false
	}
	if s[0] == '0' {
		return 0, n == 1
	}
	var v uint64
	for i := 0; i < n; i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0, false
		}
		v = v*10 + uint64(c-'0')
	}
	if v >= 4294967295 {
		return 0, false
	}
	return uint32(v), true
}

func isIntegerIndexString(s string) bool {
	_, ok := arrayIndexFromKey(s)
	return ok
}
