	case ClassArguments:
		if k.Sym == nil {
			if idx, ok := arrayIndexFromKey(k.S); ok && int(idx) < len(o.arr) && o.arr[idx] != hole {
				// convert this element to a regular property
				cur := Prop{Value: o.arr[idx], Flags: PropDefault}
				if d.IsAccessor() || (d.HasWritable && !d.Writable) || (d.HasEnumerable && !d.Enumerable) || (d.HasConfigurable && !d.Configurable) {
					o.arr[idx] = hole
					o.props.Set(k, cur)
					return o.defineOrdinary(k, d)
				}
				if d.HasValue {
					o.arr[idx] = d.Value
				}
				return true
			}
		}
	case ClassString:
		if k.Sym == nil {
			s := o.internal.(*String)
			if k.S == "length" {
				return validateImmutable(&Prop{Value: float64(s.Len()), Flags: 0}, d)
			}
			if idx, ok := arrayIndexFromKey(k.S); ok && int(idx) < s.Len() {
				return validateImmutable(&Prop{Value: s.Substring(int(idx), int(idx)+1), Flags: PropEnumerable}, d)
			}
		}
	case ClassTypedArray:
		if k.Sym == nil {
			if num, ok := canonicalNumericIndex(k.S); ok {
				if !typedArrayValidIndex(o, num) {
					return false
				}
				if d.HasConfigurable && !d.Configurable {
					return false
				}
				if d.HasEnumerable && !d.Enumerable {
					return false
				}
				if d.IsAccessor() {
					return false
				}
				if d.HasWritable && !d.Writable {
					return false
				}
				if d.HasValue {
					typedArraySetIndex(o, num, d.Value)
				}
				return true
			}
		}
	case ClassModuleNS:
		return moduleNSDefineOwnProperty(o, k, d)
	}
	return o.defineOrdinary(k, d)
}

func validateImmutable(cur *Prop, d PropDesc) bool {
	if d.HasConfigurable && d.Configurable {
		return false
	}
	if d.HasEnumerable && d.Enumerable != cur.Enumerable() {
		return false
	}
	if d.IsAccessor() {
		return false
	}
	if d.HasWritable && d.Writable {
		return false
	}
	if d.HasValue && !sameValue(d.Value, cur.Value) {
		return false
	}
	return true
}

func (o *Object) defineOrdinary(k PropKey, d PropDesc) bool {
	cur := o.props.Get(k)
	if cur == nil {
		if !o.extensible {
			return false
		}
		var p Prop
		if d.IsAccessor() {
			p.Flags = PropAccessor
			p.Getter = Undefined
			p.Setter = Undefined
			if d.HasGet {
				p.Getter = d.Get
			}
			if d.HasSet {
				p.Setter = d.Set
			}
		} else {
			p.Value = Undefined
			if d.HasValue {
				p.Value = d.Value
			}
			if d.HasWritable && d.Writable {
				p.Flags |= PropWritable
			}
		}
		if d.HasEnumerable && d.Enumerable {
			p.Flags |= PropEnumerable
		}
		if d.HasConfigurable && d.Configurable {
			p.Flags |= PropConfigurable
		}
		o.props.Set(k, p)
		return true
	}
	return applyDescToProp(cur, d)
}

// applyDescToProp validates and applies a descriptor to an existing property
func applyDescToProp(cur *Prop, d PropDesc) bool {
	if !cur.Configurable() {
		if d.HasConfigurable && d.Configurable {
			return false
		}
		if d.HasEnumerable && d.Enumerable != cur.Enumerable() {
			return false
		}
		if !d.IsGeneric() && d.IsAccessor() != cur.IsAccessor() {
			return false
		}
		if cur.IsAccessor() {
			if d.HasGet && !sameValue(d.Get, cur.Getter) {
				return false
			}
			if d.HasSet && !sameValue(d.Set, cur.Setter) {
				return false
			}
		} else if !cur.Writable() {
			if d.HasWritable && d.Writable {
				return false
			}
			if d.HasValue && !sameValue(d.Value, cur.Value) {
				return false
			}
		}
	}
	// apply
	if d.IsAccessor() && !cur.IsAccessor() {
		cur.Flags = (cur.Flags & (PropEnumerable | PropConfigurable)) | PropAccessor
		cur.Value = nil
		cur.Getter = Undefined
		cur.Setter = Undefined
	} else if d.IsData() && cur.IsAccessor() {
		cur.Flags = cur.Flags & (PropEnumerable | PropConfigurable)
		cur.Getter = nil
		cur.Setter = nil
		cur.Value = Undefined
	}
	if d.HasGet {
		cur.Getter = d.Get
	}
	if d.HasSet {
		cur.Setter = d.Set
	}
	if d.HasValue {
		cur.Value = d.Value
	}
	if d.HasWritable {
		if d.Writable {
			cur.Flags |= PropWritable
		} else {
			cur.Flags &^= PropWritable
		}
	}
	if d.HasEnumerable {
		if d.Enumerable {
			cur.Flags |= PropEnumerable
		} else {
			cur.Flags &^= PropEnumerable
		}
	}
	if d.HasConfigurable {
		if d.Configurable {
			cur.Flags |= PropConfigurable
		} else {
			cur.Flags &^= PropConfigurable
		}
	}
	return true
}

// ---------- Array exotic ----------

func newArrayObject(elems []Value) *Object {
	o := newObjectRaw(rt.ArrayPrototype, ClassArray)
	o.arr = elems
	o.internal = &ArrayData{length: uint32(len(elems)), lengthWritable: true}
	return o
}

func arrayLength(o *Object) uint32 {
	ad := o.arrayData()
	if ad.sparse {
		return ad.length
	}
	return uint32(len(o.arr))
}

func arrayMakeSparse(o *Object) {
	ad := o.arrayData()
	if ad.sparse {
		return
	}
	ad.length = uint32(len(o.arr))
	for i, v := range o.arr {
		if v != hole {
			o.props.Set(strKey(uint32ToString(uint32(i))), Prop{Value: v, Flags: PropDefault})
		}
	}
	o.arr = nil
	ad.sparse = true
}

func arraySetLength(o *Object, d PropDesc) bool {
	ad := o.arrayData()
	if d.IsAccessor() {
		return false
	}
	if d.HasConfigurable && d.Configurable {
		return false
	}
	if d.HasEnumerable && d.Enumerable {
		return false
	}
	if !d.HasValue {
		if d.HasWritable {
			if d.Writable && !ad.lengthWritable {
				return false
			}
			if !d.Writable {
				ad.lengthWritable = false
			}
		}
		return true
	}
	newLen, ok := toArrayLengthValue(d.Value)
	if !ok {
		throwRangeError("invalid array length")
	}
	oldLen := arrayLength(o)
	if newLen != oldLen {
		if !ad.lengthWritable {
			return false
		}
	}
	if d.HasWritable && d.Writable && !ad.lengthWritable {
		return false
	}
	if !ad.sparse {
		if newLen < uint32(len(o.arr)) {
			if o.frozenHint || o.sealedHint {
				return false
			}
			for i := newLen; i < uint32(len(o.arr)); i++ {
				o.arr[i] = nil
			}
			o.arr = o.arr[:newLen]
		} else if newLen > uint32(len(o.arr)) {
			if newLen-uint32(len(o.arr)) > 1<<20 {
				arrayMakeSparse(o)
				ad.length = newLen
			} else {
				for uint32(len(o.arr)) < newLen {
					o.arr = append(o.arr, hole)
				}
			}
		}
	} else {
		if newLen < ad.length {
			// delete elements >= newLen (highest first; stop at non-configurable)
			var idxs []uint32
			for i := range o.props.entries {
				k := o.props.entries[i].key
				if k.Sym == nil {
					if idx, ok := arrayIndexFromKey(k.S); ok && idx >= newLen {
						idxs = append(idxs, idx)
					}
				}
			}
			sort.Slice(idxs, func(a, b int) bool { return idxs[a] > idxs[b] })
			for _, idx := range idxs {
				k := strKey(uint32ToString(idx))
				p := o.props.Get(k)
				if !p.Configurable() {
					ad.length = idx + 1
					if d.HasWritable && !d.Writable {
						ad.lengthWritable = false
					}
					return false
				}
				o.props.Delete(k)
			}
		}
		ad.length = newLen
	}
	if d.HasWritable && !d.Writable {
		ad.lengthWritable = false
	}
	return true
}

func toArrayLengthValue(v Value) (uint32, bool) {
	n := toNumber(v)
	u := toUint32(n)
	if float64(u) != n {
		return 0, false
	}
	return u, true
}

func arrayDefineIndex(o *Object, idx uint32, d PropDesc) bool {
	ad := o.arrayData()
	oldLen := arrayLength(o)
	if idx >= oldLen && !ad.lengthWritable {
		return false
	}
	if !ad.sparse {
		simple := !d.IsAccessor() && (!d.HasWritable || d.Writable) && (!d.HasEnumerable || d.Enumerable) && (!d.HasConfigurable || d.Configurable)
		if int(idx) < len(o.arr) {
			if o.arr[idx] != hole {
				if simple {
					if o.frozenHint {
						return d.HasValue && sameValue(d.Value, o.arr[idx]) || !d.HasValue
					}
					if d.HasValue {
						o.arr[idx] = d.Value
					}
					return true
				}
				// convert to sparse to hold a special descriptor
				arrayMakeSparse(o)
			} else {
				if o.frozenHint || o.sealedHint || !o.extensible {
					return false
				}
				if simple {
					// must have all fields to be a full default property
					if d.HasWritable && d.HasEnumerable && d.HasConfigurable || (!d.HasWritable && !d.HasEnumerable && !d.HasConfigurable) {
						if d.HasWritable && d.HasEnumerable && d.HasConfigurable {
							v := d.Value
							if !d.HasValue {
								v = Undefined
							}
							o.arr[idx] = v
							return true
						}
					}
				}
				arrayMakeSparse(o)
			}
		} else {
			if !o.extensible {
				return false
			}
			if simple && d.HasWritable && d.HasEnumerable && d.HasConfigurable && idx <= uint32(len(o.arr))+1024 {
				for uint32(len(o.arr)) < idx {
					o.arr = append(o.arr, hole)
				}
				v := d.Value
				if !d.HasValue {
					v = Undefined
				}
				o.arr = append(o.arr, v)
				return true
			}
			arrayMakeSparse(o)
		}
	}
	// sparse path
	if !o.defineOrdinary(strKey(uint32ToString(idx)), d) {
		return false
	}
	if idx >= ad.length {
		ad.length = idx + 1
	}
	return true
}

// CreateDataProperty semantics (used by literals etc.)
func (o *Object) CreateDataProperty(k PropKey, v Value) bool {
	return o.DefineOwnProperty(k, dataDesc(v, PropDefault))
}

func (o *Object) CreateDataPropertyOrThrow(k PropKey, v Value) {
	if !o.CreateDataProperty(k, v) {
		throwTypeError("cannot define property '%s'", keyToDisplay(k))
	}
}

// fast set of a plain data property, used by builtins setup
func (o *Object) setOwn(name string, v Value, flags uint8) {
	o.props.Set(strKey(name), Prop{Value: v, Flags: flags})
}

func (o *Object) setOwnSym(s *Symbol, v Value, flags uint8) {
	o.props.Set(symKey(s), Prop{Value: v, Flags: flags})
}

func (o *Object) setAccessor(name string, getter, setter *Object, flags uint8) {
	var g, s Value = Undefined, Undefined
	if getter != nil {
		g = getter
	}
	if setter != nil {
		s = setter
	}
	o.props.Set(strKey(name), Prop{Getter: g, Setter: s, Flags: flags | PropAccessor})
}

func keyToDisplay(k PropKey) string {
	if k.Sym != nil {
		return k.Sym.DescriptiveString()
	}
	return k.S
}

// canonicalNumericIndex: for typed arrays / string keys; returns numeric value if string is canonical numeric
func canonicalNumericIndex(s string) (float64, bool) {
	if s == "-0" {
		return math.Copysign(0, -1), true
	}
	if len(s) == 0 {
		return 0, false
	}
	c := s[0]
	if !(c >= '0' && c <= '9') && c != '-' && c != 'I' && c != 'N' {
		return 0, false
	}
	n := stringToNumber(NewStringFromGo(s))
	if numberToString(n) == s {
		return n, true
	}
	return 0, false
}
