cat > /workspace/src/object.go <<'EOF'
package main

import (
	"math"
	"sort"
)

type Class uint8

const (
	ClassObject Class = iota
	ClassArray
	ClassFunction
	ClassError
	ClassBoolean
	ClassNumber
	ClassString
	ClassSymbol
	ClassBigInt
	ClassDate
	ClassRegExp
	ClassMap
	ClassSet
	ClassWeakMap
	ClassWeakSet
	ClassWeakRef
	ClassFinReg
	ClassArrayBuffer
	ClassSharedArrayBuffer
	ClassTypedArray
	ClassDataView
	ClassPromise
	ClassProxy
	ClassGenerator
	ClassAsyncGenerator
	ClassArguments
	ClassModuleNS
	ClassIterator
	ClassAsyncFromSyncIterator
	ClassIteratorHelper
	ClassCallSite
)

const (
	PropWritable     uint8 = 1
	PropEnumerable   uint8 = 2
	PropConfigurable uint8 = 4
	PropAccessor     uint8 = 8
	PropDefault            = PropWritable | PropEnumerable | PropConfigurable
	PropHidden             = PropWritable | PropConfigurable // non-enumerable (builtin methods)
)

type PropKey struct {
	S   string
	Sym *Symbol
}

func strKey(s string) PropKey      { return PropKey{S: s} }
func symKey(s *Symbol) PropKey     { return PropKey{Sym: s} }
func (k PropKey) IsSymbol() bool   { return k.Sym != nil }
func (k PropKey) IsIndex() bool    { _, ok := arrayIndexFromKey(k.S); return k.Sym == nil && ok }

// ToValue converts the key to a JS value (string or symbol)
func (k PropKey) ToValue() Value {
	if k.Sym != nil {
		return k.Sym
	}
	return NewStringFromGo(k.S)
}

type Prop struct {
	Value  Value
	Getter Value // *Object or Undefined
	Setter Value
	Flags  uint8
}

func (p *Prop) IsAccessor() bool { return p.Flags&PropAccessor != 0 }
func (p *Prop) Writable() bool   { return p.Flags&PropWritable != 0 }
func (p *Prop) Enumerable() bool { return p.Flags&PropEnumerable != 0 }
func (p *Prop) Configurable() bool { return p.Flags&PropConfigurable != 0 }

type propEntry struct {
	key  PropKey
	prop Prop
}

type PropMap struct {
	entries []propEntry
	index   map[PropKey]int
}

const propIndexThreshold = 8

func (m *PropMap) find(k PropKey) int {
	if m.index != nil {
		if i, ok := m.index[k]; ok {
			return i
		}
		return -1
	}
	for i := range m.entries {
		if m.entries[i].key == k {
			return i
		}
	}
	return -1
}

func (m *PropMap) Get(k PropKey) *Prop {
	i := m.find(k)
	if i < 0 {
		return nil
	}
	return &m.entries[i].prop
}

func (m *PropMap) Set(k PropKey, p Prop) {
	i := m.find(k)
	if i >= 0 {
		m.entries[i].prop = p
		return
	}
	m.entries = append(m.entries, propEntry{k, p})
	if m.index != nil {
		m.index[k] = len(m.entries) - 1
	} else if len(m.entries) > propIndexThreshold {
		m.index = make(map[PropKey]int, len(m.entries)*2)
		for i := range m.entries {
			m.index[m.entries[i].key] = i
		}
	}
}

func (m *PropMap) Delete(k PropKey) bool {
	i := m.find(k)
	if i < 0 {
		return false
	}
	copy(m.entries[i:], m.entries[i+1:])
	m.entries[len(m.entries)-1] = propEntry{}
	m.entries = m.entries[:len(m.entries)-1]
	if m.index != nil {
		delete(m.index, k)
		for j := i; j < len(m.entries); j++ {
			m.index[m.entries[j].key] = j
		}
	}
	return true
}

func (m *PropMap) Len() int { return len(m.entries) }

type Object struct {
	proto      *Object
	class      Class
	extensible bool
	props      PropMap
	arr        []Value // dense elements for arrays / arguments
	internal   interface{}
	callable   bool
	ctor       bool
	frozenHint bool
	sealedHint bool
	isHTMLDDA  bool
	id         int // for inspect / weak maps
	classProtoName string
}

var objectIDCounter int

func newObjectRaw(proto *Object, class Class) *Object {
	objectIDCounter++
	return &Object{proto: proto, class: class, extensible: true, id: objectIDCounter}
}

// ---------- Descriptors ----------

type PropDesc struct {
	Value           Value
	Get, Set        Value
	HasValue        bool
	HasGet, HasSet  bool
	Writable        bool
	HasWritable     bool
	Enumerable      bool
	HasEnumerable   bool
	Configurable    bool
	HasConfigurable bool
}

func (d *PropDesc) IsAccessor() bool { return d.HasGet || d.HasSet }
func (d *PropDesc) IsData() bool     { return d.HasValue || d.HasWritable }
func (d *PropDesc) IsGeneric() bool  { return !d.IsAccessor() && !d.IsData() }

func propToDesc(p *Prop) PropDesc {
	d := PropDesc{Enumerable: p.Enumerable(), HasEnumerable: true, Configurable: p.Configurable(), HasConfigurable: true}
	if p.IsAccessor() {
		d.Get = p.Getter
		d.Set = p.Setter
		d.HasGet = true
		d.HasSet = true
	} else {
		d.Value = p.Value
		d.HasValue = true
		d.Writable = p.Writable()
		d.HasWritable = true
	}
	return d
}

func dataDesc(v Value, flags uint8) PropDesc {
	return PropDesc{Value: v, HasValue: true, Writable: flags&PropWritable != 0, HasWritable: true,
		Enumerable: flags&PropEnumerable != 0, HasEnumerable: true, Configurable: flags&PropConfigurable != 0, HasConfigurable: true}
}

// ---------- Array helpers ----------

type ArrayData struct {
	length uint32
	sparse bool // elements stored in props
	lengthWritable bool
}

func (o *Object) arrayData() *ArrayData {
	return o.internal.(*ArrayData)
}

// ---------- Internal methods ----------

// GetOwnProperty returns the own property or nil
func (o *Object) GetOwnProperty(k PropKey) *Prop {
	switch o.class {
	case ClassArray:
		if k.Sym == nil {
			if k.S == "length" {
				ad := o.arrayData()
				fl := PropWritable
				if !ad.lengthWritable {
					fl = 0
				}
				return &Prop{Value: float64(ad.length), Flags: fl}
			}
			if !ad_sparse(o) {
				if idx, ok := arrayIndexFromKey(k.S); ok {
					if int(idx) < len(o.arr) && o.arr[idx] != hole {
						fl := PropDefault
						if o.frozenHint {
							fl = PropEnumerable
						} else if o.sealedHint {
							fl = PropEnumerable | PropWritable
						}
						return &Prop{Value: o.arr[idx], Flags: fl}
					}
					return nil
				}
			}
		}
	case ClassArguments:
		if k.Sym == nil {
			if idx, ok := arrayIndexFromKey(k.S); ok && int(idx) < len(o.arr) && o.arr[idx] != hole {
				fl := PropDefault
				return &Prop{Value: o.arr[idx], Flags: fl}
			}
		}
	case ClassString:
		if k.Sym == nil {
			s := o.internal.(*String)
			if k.S == "length" {
				return &Prop{Value: float64(s.Len()), Flags: 0}
			}
			if idx, ok := arrayIndexFromKey(k.S); ok && int(idx) < s.Len() {
				return &Prop{Value: s.Substring(int(idx), int(idx)+1), Flags: PropEnumerable}
			}
		}
	case ClassTypedArray:
		if k.Sym == nil {
			if num, ok := canonicalNumericIndex(k.S); ok {
				v := typedArrayGetIndex(o, num)
				if v == nil {
					return nil
				}
				return &Prop{Value: v, Flags: PropDefault}
			}
		}
	case ClassProxy:
		return proxyGetOwnProperty(o, k)
	case ClassModuleNS:
		return moduleNSGetOwnProperty(o, k)
	}
	return o.props.Get(k)
}

func ad_sparse(o *Object) bool {
	return o.internal.(*ArrayData).sparse
}

func (o *Object) HasOwnProperty(k PropKey) bool {
	return o.GetOwnProperty(k) != nil
}

func (o *Object) GetPrototypeOf() *Object {
	if o.class == ClassProxy {
		return proxyGetPrototypeOf(o)
	}
	return o.proto
}

func (o *Object) SetPrototypeOf(p *Object) bool {
	if o.class == ClassProxy {
		return proxySetPrototypeOf(o, p)
	}
	if o.proto == p {
		return true
	}
	if !o.extensible {
		return false
	}
	if o.isImmutableProto() {
		return false
	}
	// cycle check
	for q := p; q != nil; q = q.proto {
		if q == o {
			return false
		}
		if q.class == ClassProxy {
			break
		}
	}
	o.proto = p
	return true
}

func (o *Object) isImmutableProto() bool {
	return o == rt.ObjectPrototype
}

func (o *Object) IsExtensible() bool {
	if o.class == ClassProxy {
		return proxyIsExtensible(o)
	}
	return o.extensible
}

func (o *Object) PreventExtensions() bool {
	if o.class == ClassProxy {
		return proxyPreventExtensions(o)
	}
	if o.class == ClassTypedArray {
		ta := o.internal.(*TypedArray)
		if ta.lengthTracking || !ta.buffer.internal.(*ArrayBufferData).isFixedLength() {
			return false
		}
	}
	o.extensible = false
	return true
}

func (o *Object) HasProperty(k PropKey) bool {
	for obj := o; obj != nil; {
		if obj.class == ClassProxy {
			return proxyHas(obj, k)
		}
		if obj.class == ClassTypedArray && k.Sym == nil {
			if num, ok := canonicalNumericIndex(k.S); ok {
				return typedArrayValidIndex(obj, num)
			}
		}
		if obj.GetOwnProperty(k) != nil {
			return true
		}
		obj = obj.proto
	}
	return false
}

// Get implements [[Get]] with receiver
func (o *Object) Get(k PropKey, receiver Value) Value {
	obj := o
	for obj != nil {
		if obj.class == ClassProxy {
			return proxyGet(obj, k, receiver)
		}
		if obj.class == ClassTypedArray && k.Sym == nil {
			if num, ok := canonicalNumericIndex(k.S); ok {
				v := typedArrayGetIndex(obj, num)
				if v == nil {
					return Undefined
				}
				return v
			}
		}
		p := obj.GetOwnProperty(k)
		if p != nil {
			if p.IsAccessor() {
				if g, ok := p.Getter.(*Object); ok {
					return callFunction(g, receiver, nil)
				}
				return Undefined
			}
			return p.Value
		}
		obj = obj.proto
	}
	return Undefined
}

func (o *Object) GetStr(name string) Value {
	return o.Get(strKey(name), o)
}

func (o *Object) GetSym(s *Symbol) Value {
	return o.Get(symKey(s), o)
}

// Set implements [[Set]]; returns false on failure
func (o *Object) Set(k PropKey, v Value, receiver Value) bool {
	obj := o
	for obj != nil {
		if obj.class == ClassProxy {
			return proxySet(obj, k, v, receiver)
		}
		if obj.class == ClassTypedArray && k.Sym == nil {
			if num, ok := canonicalNumericIndex(k.S); ok {
				if ro, ok2 := receiver.(*Object); ok2 && ro == obj {
					typedArraySetIndex(obj, num, v)
					return true
				}
				if !typedArrayValidIndex(obj, num) {
					return true
				}
			}
		}
		// fast path for arrays
		if obj.class == ClassArray && k.Sym == nil && !ad_sparse(obj) {
			if idx, ok := arrayIndexFromKey(k.S); ok {
				if int(idx) < len(obj.arr) && obj.arr[idx] != hole {
					if ro, ok2 := receiver.(*Object); ok2 && ro == obj {
						if obj.frozenHint {
							return false
						}
						obj.arr[idx] = v
						return true
					}
					break
				}
			}
		}
		p := obj.GetOwnProperty(k)
		if p != nil {
			if p.IsAccessor() {
				if s, ok := p.Setter.(*Object); ok {
					callFunction(s, receiver, []Value{v})
					return true
				}
				return false
			}
			if !p.Writable() {
				return false
			}
			break
		}
		obj = obj.proto
	}
	// receiver must be an object
	recv, ok := receiver.(*Object)
	if !ok {
		return false
	}
	existing := recv.GetOwnProperty(k)
	if existing != nil {
		if existing.IsAccessor() {
			return false
		}
		if !existing.Writable() {
			return false
		}
		return recv.DefineOwnProperty(k, PropDesc{Value: v, HasValue: true})
	}
	return recv.DefineOwnProperty(k, dataDesc(v, PropDefault))
}

func (o *Object) SetStr(name string, v Value) bool {
	return o.Set(strKey(name), v, o)
}

func (o *Object) Delete(k PropKey) bool {
	switch o.class {
	case ClassProxy:
		return proxyDelete(o, k)
	case ClassArray:
		if k.Sym == nil {
			if k.S == "length" {
				return false
			}
			if !ad_sparse(o) {
				if idx, ok := arrayIndexFromKey(k.S); ok {
					if int(idx) < len(o.arr) {
						if o.frozenHint || o.sealedHint {
							return o.arr[idx] == hole
						}
						if int(idx) == len(o.arr)-1 && false {
							o.arr = o.arr[:idx]
						} else {
							o.arr[idx] = hole
						}
					}
					return true
				}
			}
		}
	case ClassArguments:
		if k.Sym == nil {
			if idx, ok := arrayIndexFromKey(k.S); ok && int(idx) < len(o.arr) {
				if o.arr[idx] != hole {
					// move to props? simply mark hole; mapped arguments not supported
					o.arr[idx] = hole
				}
				return true
			}
		}
	case ClassString:
		if k.Sym == nil {
			s := o.internal.(*String)
			if k.S == "length" {
				return false
			}
			if idx, ok := arrayIndexFromKey(k.S); ok && int(idx) < s.Len() {
				return false
			}
		}
	case ClassTypedArray:
		if k.Sym == nil {
			if num, ok := canonicalNumericIndex(k.S); ok {
				return !typedArrayValidIndex(o, num)
			}
		}
	case ClassModuleNS:
		return moduleNSDelete(o, k)
	}
	p := o.props.Get(k)
	if p == nil {
		return true
	}
	if !p.Configurable() {
		return false
	}
	o.props.Delete(k)
	return true
}

// OwnKeys returns own property keys in spec order
func (o *Object) OwnKeys() []PropKey {
	if o.class == ClassProxy {
		return proxyOwnKeys(o)
	}
	if o.class == ClassModuleNS {
		return moduleNSOwnKeys(o)
	}
	var keys []PropKey
	var intKeys []uint32
	switch o.class {
	case ClassArray, ClassArguments:
		if o.class == ClassArguments || !ad_sparse(o) {
			for i, v := range o.arr {
				if v != hole {
					keys = append(keys, strKey(uint32ToString(uint32(i))))
				}
			}
		}
	case ClassString:
		n := o.internal.(*String).Len()
		for i := 0; i < n; i++ {
			keys = append(keys, strKey(uint32ToString(uint32(i))))
		}
	case ClassTypedArray:
		n := typedArrayLength(o)
		for i := 0; i < n; i++ {
			keys = append(keys, strKey(uint32ToString(uint32(i))))
		}
	}
	// integer keys from props (sorted)
	hasInt := false
	for i := range o.props.entries {
		k := o.props.entries[i].key
		if k.Sym == nil {
			if idx, ok := arrayIndexFromKey(k.S); ok {
				intKeys = append(intKeys, idx)
				hasInt = true
			}
		}
	}
	if hasInt {
		sort.Slice(intKeys, func(a, b int) bool { return intKeys[a] < intKeys[b] })
		for _, idx := range intKeys {
			keys = append(keys, strKey(uint32ToString(idx)))
		}
	}
	if o.class == ClassArray {
		keys = append(keys, strKey("length"))
	} else if o.class == ClassString {
		keys = append(keys, strKey("length"))
	}
	for i := range o.props.entries {
		k := o.props.entries[i].key
		if k.Sym == nil {
			if _, ok := arrayIndexFromKey(k.S); ok {
				continue
			}
			keys = append(keys, k)
		}
	}
	for i := range o.props.entries {
		k := o.props.entries[i].key
		if k.Sym != nil {
			keys = append(keys, k)
		}
	}
	return keys
}

func uint32ToString(i uint32) string {
	if i < 10 {
		return string(rune('0' + i))
	}
	var buf [10]byte
	p := len(buf)
	for i > 0 {
		p--
		buf[p] = byte('0' + i%10)
		i /= 10
	}
	return string(buf[p:])
}

// DefineOwnProperty implements ValidateAndApplyPropertyDescriptor
func (o *Object) DefineOwnProperty(k PropKey, d PropDesc) bool {
	switch o.class {
	case ClassProxy:
		return proxyDefineOwnProperty(o, k, d)
	case ClassArray:
		if k.Sym == nil {
			if k.S == "length" {
				return arraySetLength(o, d)
			}
			if idx, ok := arrayIndexFromKey(k.S); ok {
				return arrayDefineIndex(o, idx, d)
			}
		}
	case ClassArguments:
		if k.Sym == nil {
			if idx, ok := arrayIndexFromKey(k.S); ok && int(idx) < len(o.arr) && o.arr[idx] != hole {
				// convert this element to a regular property
				cur := Prop{Value: o.arr[idx], Flags: PropDefault}
				if d.IsAccessor() || (d.HasWritable && !d.Writable) || (d.HasEnumerable && !d.Enumerable) || (d.HasConfigurable && !d.Configurable) {
					o.arr[idx] = hole
					o.props.Set(k, cur)
					return o.defineOrdinary(k, d)
				}
				if d.HasValue {
					o.arr[idx] = d.Value
				}
				return true
			}
		}
	case ClassString:
		if k.Sym == nil {
			s := o.internal.(*String)
			if k.S == "length" {
				return validateImmutable(&Prop{Value: float64(s.Len()), Flags: 0}, d)
			}
			if idx, ok := arrayIndexFromKey(k.S); ok && int(idx) < s.Len() {
				return validateImmutable(&Prop{Value: s.Substring(int(idx), int(idx)+1), Flags: PropEnumerable}, d)
			}
		}
	case ClassTypedArray:
		if k.Sym == nil {
			if num, ok := canonicalNumericIndex(k.S); ok {
				if !typedArrayValidIndex(o, num) {
					return false
				}
				if d.HasConfigurable && !d.Configurable {
					return false
				}
				if d.HasEnumerable && !d.Enumerable {
					return false
				}
				if d.IsAccessor() {
					return false
				}
				if d.HasWritable && !d.Writable {
					return false
				}
				if d.HasValue {
					typedArraySetIndex(o, num, d.Value)
				}
				return true
			}
		}
	case ClassModuleNS:
		return moduleNSDefineOwnProperty(o, k, d)
	}
	return o.defineOrdinary(k, d)
}

func validateImmutable(cur *Prop, d PropDesc) bool {
	if d.HasConfigurable && d.Configurable {
		return false
	}
	if d.HasEnumerable && d.Enumerable != cur.Enumerable() {
		return false
	}
	if d.IsAccessor() {
		return false
	}
	if d.HasWritable && d.Writable {
		return false
	}
	if d.HasValue && !sameValue(d.Value, cur.Value) {
		return false
	}
	return true
}

func (o *Object) defineOrdinary(k PropKey, d PropDesc) bool {
	cur := o.props.Get(k)
	if cur == nil {
		if !o.extensible {
			return false
		}
		var p Prop
		if d.IsAccessor() {
			p.Flags = PropAccessor
			p.Getter = Undefined
			p.Setter = Undefined
			if d.HasGet {
				p.Getter = d.Get
			}
			if d.HasSet {
				p.Setter = d.Set
			}
		} else {
			p.Value = Undefined
			if d.HasValue {
				p.Value = d.Value
			}
			if d.HasWritable && d.Writable {
				p.Flags |= PropWritable
			}
		}
		if d.HasEnumerable && d.Enumerable {
			p.Flags |= PropEnumerable
		}
		if d.HasConfigurable && d.Configurable {
			p.Flags |= PropConfigurable
		}
		o.props.Set(k, p)
		return true
	}
	return applyDescToProp(cur, d)
}

// applyDescToProp validates and applies a descriptor to an existing property
func applyDescToProp(cur *Prop, d PropDesc) bool {
	if !cur.Configurable() {
		if d.HasConfigurable && d.Configurable {
			return false
		}
		if d.HasEnumerable && d.Enumerable != cur.Enumerable() {
			return false
		}
		if !d.IsGeneric() && d.IsAccessor() != cur.IsAccessor() {
			return false
		}
		if cur.IsAccessor() {
			if d.HasGet && !sameValue(d.Get, cur.Getter) {
				return false
			}
			if d.HasSet && !sameValue(d.Set, cur.Setter) {
				return false
			}
		} else if !cur.Writable() {
			if d.HasWritable && d.Writable {
				return false
			}
			if d.HasValue && !sameValue(d.Value, cur.Value) {
				return false
			}
		}
	}
	// apply
	if d.IsAccessor() && !cur.IsAccessor() {
		cur.Flags = (cur.Flags & (PropEnumerable | PropConfigurable)) | PropAccessor
		cur.Value = nil
		cur.Getter = Undefined
		cur.Setter = Undefined
	} else if d.IsData() && cur.IsAccessor() {
		cur.Flags = cur.Flags & (PropEnumerable | PropConfigurable)
		cur.Getter = nil
		cur.Setter = nil
		cur.Value = Undefined
	}
	if d.HasGet {
		cur.Getter = d.Get
	}
	if d.HasSet {
		cur.Setter = d.Set
	}
	if d.HasValue {
		cur.Value = d.Value
	}
	if d.HasWritable {
		if d.Writable {
			cur.Flags |= PropWritable
		} else {
			cur.Flags &^= PropWritable
		}
	}
	if d.HasEnumerable {
		if d.Enumerable {
			cur.Flags |= PropEnumerable
		} else {
			cur.Flags &^= PropEnumerable
		}
	}
	if d.HasConfigurable {
		if d.Configurable {
			cur.Flags |= PropConfigurable
		} else {
			cur.Flags &^= PropConfigurable
		}
	}
	return true
}

// ---------- Array exotic ----------

func newArrayObject(elems []Value) *Object {
	o := newObjectRaw(rt.ArrayPrototype, ClassArray)
	o.arr = elems
	o.internal = &ArrayData{length: uint32(len(elems)), lengthWritable: true}
	return o
}

func arrayLength(o *Object) uint32 {
	ad := o.arrayData()
	if ad.sparse {
		return ad.length
	}
	return uint32(len(o.arr))
}

func arrayMakeSparse(o *Object) {
	ad := o.arrayData()
	if ad.sparse {
		return
	}
	ad.length = uint32(len(o.arr))
	for i, v := range o.arr {
		if v != hole {
			o.props.Set(strKey(uint32ToString(uint32(i))), Prop{Value: v, Flags: PropDefault})
		}
	}
	o.arr = nil
	ad.sparse = true
}

func arraySetLength(o *Object, d PropDesc) bool {
	ad := o.arrayData()
	if d.IsAccessor() {
		return false
	}
	if d.HasConfigurable && d.Configurable {
		return false
	}
	if d.HasEnumerable && d.Enumerable {
		return false
	}
	if !d.HasValue {
		if d.HasWritable {
			if d.Writable && !ad.lengthWritable {
				return false
			}
			if !d.Writable {
				ad.lengthWritable = false
			}
		}
		return true
	}
	newLen, ok := toArrayLengthValue(d.Value)
	if !ok {
		throwRangeError("invalid array length")
	}
	oldLen := arrayLength(o)
	if newLen != oldLen {
		if !ad.lengthWritable {
			return false
		}
	}
	if d.HasWritable && d.Writable && !ad.lengthWritable {
		return false
	}
	if !ad.sparse {
		if newLen < uint32(len(o.arr)) {
			if o.frozenHint || o.sealedHint {
				return false
			}
			for i := newLen; i < uint32(len(o.arr)); i++ {
				o.arr[i] = nil
			}
			o.arr = o.arr[:newLen]
		} else if newLen > uint32(len(o.arr)) {
			if newLen-uint32(len(o.arr)) > 1<<20 {
				arrayMakeSparse(o)
				ad.length = newLen
			} else {
				for uint32(len(o.arr)) < newLen {
					o.arr = append(o.arr, hole)
				}
			}
		}
	} else {
		if newLen < ad.length {
			// delete elements >= newLen (highest first; stop at non-configurable)
			var idxs []uint32
			for i := range o.props.entries {
				k := o.props.entries[i].key
				if k.Sym == nil {
					if idx, ok := arrayIndexFromKey(k.S); ok && idx >= newLen {
						idxs = append(idxs, idx)
					}
				}
			}
			sort.Slice(idxs, func(a, b int) bool { return idxs[a] > idxs[b] })
			for _, idx := range idxs {
				k := strKey(uint32ToString(idx))
				p := o.props.Get(k)
				if !p.Configurable() {
					ad.length = idx + 1
					if d.HasWritable && !d.Writable {
						ad.lengthWritable = false
					}
					return false
				}
				o.props.Delete(k)
			}
		}
		ad.length = newLen
	}
	if d.HasWritable && !d.Writable {
		ad.lengthWritable = false
	}
	return true
}

func toArrayLengthValue(v Value) (uint32, bool) {
	n := toNumber(v)
	u := toUint32(n)
	if float64(u) != n {
		return 0, false
	}
	return u, true
}

func arrayDefineIndex(o *Object, idx uint32, d PropDesc) bool {
	ad := o.arrayData()
	oldLen := arrayLength(o)
	if idx >= oldLen && !ad.lengthWritable {
		return false
	}
	if !ad.sparse {
		simple := !d.IsAccessor() && (!d.HasWritable || d.Writable) && (!d.HasEnumerable || d.Enumerable) && (!d.HasConfigurable || d.Configurable)
		if int(idx) < len(o.arr) {
			if o.arr[idx] != hole {
				if simple {
					if o.frozenHint {
						return d.HasValue && sameValue(d.Value, o.arr[idx]) || !d.HasValue
					}
					if d.HasValue {
						o.arr[idx] = d.Value
					}
					return true
				}
				// convert to sparse to hold a special descriptor
				arrayMakeSparse(o)
			} else {
				if o.frozenHint || o.sealedHint || !o.extensible {
					return false
				}
				if simple {
					// must have all fields to be a full default property
					if d.HasWritable && d.HasEnumerable && d.HasConfigurable || (!d.HasWritable && !d.HasEnumerable && !d.HasConfigurable) {
						if d.HasWritable && d.HasEnumerable && d.HasConfigurable {
							v := d.Value
							if !d.HasValue {
								v = Undefined
							}
							o.arr[idx] = v
							return true
						}
					}
				}
				arrayMakeSparse(o)
			}
		} else {
			if !o.extensible {
				return false
			}
			if simple && d.HasWritable && d.HasEnumerable && d.HasConfigurable && idx <= uint32(len(o.arr))+1024 {
				for uint32(len(o.arr)) < idx {
					o.arr = append(o.arr, hole)
				}
				v := d.Value
				if !d.HasValue {
					v = Undefined
				}
				o.arr = append(o.arr, v)
				return true
			}
			arrayMakeSparse(o)
		}
	}
	// sparse path
	if !o.defineOrdinary(strKey(uint32ToString(idx)), d) {
		return false
	}
	if idx >= ad.length {
		ad.length = idx + 1
	}
	return true
}

// CreateDataProperty semantics (used by literals etc.)
func (o *Object) CreateDataProperty(k PropKey, v Value) bool {
	return o.DefineOwnProperty(k, dataDesc(v, PropDefault))
}

func (o *Object) CreateDataPropertyOrThrow(k PropKey, v Value) {
	if !o.CreateDataProperty(k, v) {
		throwTypeError("cannot define property '%s'", keyToDisplay(k))
	}
}

// fast set of a plain data property, used by builtins setup
func (o *Object) setOwn(name string, v Value, flags uint8) {
	o.props.Set(strKey(name), Prop{Value: v, Flags: flags})
}

func (o *Object) setOwnSym(s *Symbol, v Value, flags uint8) {
	o.props.Set(symKey(s), Prop{Value: v, Flags: flags})
}

func (o *Object) setAccessor(name string, getter, setter *Object, flags uint8) {
	var g, s Value = Undefined, Undefined
	if getter != nil {
		g = getter
	}
	if setter != nil {
		s = setter
	}
	o.props.Set(strKey(name), Prop{Getter: g, Setter: s, Flags: flags | PropAccessor})
}

func keyToDisplay(k PropKey) string {
	if k.Sym != nil {
		return k.Sym.DescriptiveString()
	}
	return k.S
}

// canonicalNumericIndex: for typed arrays / string keys; returns numeric value if string is canonical numeric
func canonicalNumericIndex(s string) (float64, bool) {
	if s == "-0" {
		return math.Copysign(0, -1), true
	}
	if len(s) == 0 {
		return 0, false
	}
	c := s[0]
	if !(c >= '0' && c <= '9') && c != '-' && c != 'I' && c != 'N' {
		return 0, false
	}
	n := stringToNumber(NewStringFromGo(s))
	if numberToString(n) == s {
		return n, true
	}
	return 0, false
}
