type Source struct {
	name      string
	text      string
	lineStarts []int
}

func NewSource(name, text string) *Source {
	s := &Source{name: name, text: text}
	s.lineStarts = append(s.lineStarts, 0)
	for i := 0; i < len(text); i++ {
		if text[i] == '\n' {
			s.lineStarts = append(s.lineStarts, i+1)
		}
	}
	return s
}

func (s *Source) LineCol(pos int) (int, int) {
	// binary search
	lo, hi := 0, len(s.lineStarts)-1
	for lo < hi {
		mid := (lo + hi + 1) / 2
		if s.lineStarts[mid] <= pos {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	ls := s.lineStarts[lo]
	if pos > len(s.text) {
		pos = len(s.text)
	}
	col := 0
	for i := ls; i < pos; i++ {
		if s.text[i]&0xC0 != 0x80 {
			col++
		}
	}
	return lo + 1, col + 1
}

