var maxStackDepth = 1000

// ---------- Type conversion ----------

func typeOf(v Value) string {
	switch x := v.(type) {
	case undefinedType:
		return "undefined"
	case nullType:
		return "object"
	case bool:
		return "boolean"
	case float64:
		return "number"
	case *String:
		return "string"
	case *Symbol:
		return "symbol"
	case *big.Int:
		return "bigint"
	case *Object:
		if x.isHTMLDDA {
			return "undefined"
		}
		if x.callable {
			return "function"
		}
		return "object"
	}
	return "undefined"
}

func toBoolean(v Value) bool {
	switch x := v.(type) {
	case undefinedType, nullType:
		return false
	case bool:
		return x
	case float64:
		return !(x == 0 || x != x)
	case *String:
		return x.Len() > 0
	case *Symbol:
		return true
	case *big.Int:
		return x.Sign() != 0
	case *Object:
		return !x.isHTMLDDA
	}
	return false
}

func toPrimitive(v Value, hint string) Value {
	o, ok := v.(*Object)
	if !ok {
		return v
	}
	ex := o.Get(symKey(SymToPrimitive), o)
	if !isNullish(ex) {
		if !isCallable(ex) {
			throwTypeError("Symbol.toPrimitive is not a function")
		}
		if hint == "" {
			hint = "default"
		}
		r := callFunction(ex.(*Object), o, []Value{NewStringFromGo(hint)})
		if _, isObj := r.(*Object); isObj {
			throwTypeError("toPrimitive")
		}
		return r
	}
	if hint == "" || hint == "default" {
		hint = "number"
	}
	return ordinaryToPrimitive(o, hint)
}

func ordinaryToPrimitive(o *Object, hint string) Value {
	var methods [2]string
	if hint == "string" {
		methods = [2]string{"toString", "valueOf"}
	} else {
		methods = [2]string{"valueOf", "toString"}
	}
	for _, m := range methods {
		f := o.Get(strKey(m), o)
		if isCallable(f) {
			r := callFunction(f.(*Object), o, nil)
			if _, isObj := r.(*Object); !isObj {
				return r
			}
		}
	}
	throwTypeError("toPrimitive")
	return nil
}

func toNumber(v Value) float64 {
	switch x := v.(type) {
	case float64:
		return x
	case undefinedType:
		return math.NaN()
	case nullType:
		return 0
	case bool:
		if x {
			return 1
		}
		return 0
	case *String:
		return stringToNumber(x)
	case *Symbol:
		throwTypeError("cannot convert symbol to number")
	case *big.Int:
		throwTypeError("cannot convert bigint to number")
	case *Object:
		return toNumber(toPrimitive(v, "number"))
	}
	return math.NaN()
}

// toNumeric returns float64 or *big.Int
func toNumeric(v Value) Value {
	p := toPrimitive(v, "number")
	if b, ok := p.(*big.Int); ok {
		return b
	}
	return toNumber(p)
}

func isStrWhitespace(c uint16) bool {
	switch c {
	case 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x20, 0xA0, 0x1680, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000, 0xFEFF:
		return true
	}
	if c >= 0x2000 && c <= 0x200A {
		return true
	}
	return false
}

func trimJSSpace(s *String) *String {
	n := s.Len()
	i, j := 0, n
	for i < j && isStrWhitespace(s.At(i)) {
		i++
	}
	for j > i && isStrWhitespace(s.At(j-1)) {
		j--
	}
	return s.Substring(i, j)
}

func stringToNumber(s *String) float64 {
	t := trimJSSpace(s)
	if t.Len() == 0 {
		return 0
	}
	str := t.String()
	if !t.isASCII {
		return math.NaN()
	}
	if len(str) > 2 && str[0] == '0' {
		switch str[1] {
		case 'x', 'X':
			return parseRadixOrNaN(str[2:], 16)
		case 'o', 'O':
			return parseRadixOrNaN(str[2:], 8)
		case 'b', 'B':
			return parseRadixOrNaN(str[2:], 2)
		}
	}
	switch str {
	case "Infinity", "+Infinity":
		return math.Inf(1)
	case "-Infinity":
		return math.Inf(-1)
	}
	// validate StrDecimalLiteral: digits, optional '.', digits, optional exponent
	i := 0
	if str[i] == '+' || str[i] == '-' {
		i++
	}
	digits := 0
	for i < len(str) && str[i] >= '0' && str[i] <= '9' {
		i++
		digits++
	}
	if i < len(str) && str[i] == '.' {
		i++
		for i < len(str) && str[i] >= '0' && str[i] <= '9' {
			i++
			digits++
		}
	}
	if digits == 0 {
		return math.NaN()
	}
	if i < len(str) && (str[i] == 'e' || str[i] == 'E') {
		i++
		if i < len(str) && (str[i] == '+' || str[i] == '-') {
			i++
		}
		ed := 0
		for i < len(str) && str[i] >= '0' && str[i] <= '9' {
			i++
			ed++
		}
		if ed == 0 {
			return math.NaN()
		}
	}
	if i != len(str) {
		return math.NaN()
	}
	f, err := strconv.ParseFloat(str, 64)
	if err != nil {
		if ne, ok := err.(*strconv.NumError); ok && ne.Err == strconv.ErrRange {
			return f
		}
		return math.NaN()
	}
	return f
}

func parseRadixOrNaN(s string, radix int) float64 {
	if len(s) == 0 {
		return math.NaN()
	}
	for i := 0; i < len(s); i++ {
		d := hexVal(s[i])
		if d < 0 || d >= radix {
			return math.NaN()
		}
	}
	return parseIntRadix(s, radix)
}

func toIntegerOrInfinity(v Value) float64 {
	n := toNumber(v)
	if n != n {
		return 0
	}
	if math.IsInf(n, 0) {
		return n
	}
	return math.Trunc(n)
}

func toInt32(n float64) int32 {
	if n != n || math.IsInf(n, 0) {
		return 0
	}
	if n >= -2147483648 && n <= 2147483647 {
		return int32(n)
	}
	n = math.Trunc(n)
	n = math.Mod(n, 4294967296)
	if n < 0 {
		n += 4294967296
	}
	return int32(uint32(n))
}

func toUint32(n float64) uint32 {
	return uint32(toInt32(n))
}

func toInt32V(v Value) int32   { return toInt32(toNumber(v)) }
func toUint32V(v Value) uint32 { return toUint32(toNumber(v)) }

func toLength(v Value) int64 {
	n := toIntegerOrInfinity(v)
	if n <= 0 {
		return 0
	}
	if n > 9007199254740991 {
		return 9007199254740991
	}
	return int64(n)
}

func toIndex(v Value) int64 {
	if isUndefined(v) {
		return 0
	}
	n := toIntegerOrInfinity(v)
	if n < 0 || n > 9007199254740991 {
		throwRangeError("invalid array index")
	}
	return int64(n)
}

func toString(v Value) *String {
	switch x := v.(type) {
	case *String:
		return x
	case undefinedType:
		return strUndefined
	case nullType:
		return strNull
	case bool:
		if x {
			return strTrue
		}
		return strFalse
	case float64:
		return NewStringFromGo(numberToString(x))
	case *Symbol:
		throwTypeError("cannot convert symbol to string")
	case *big.Int:
		return NewStringFromGo(x.String())
	case *Object:
		return toString(toPrimitive(v, "string"))
	}
	return emptyString
}

var (
	strUndefined = NewStringFromGo("undefined")
	strNull      = NewStringFromGo("null")
	strTrue      = NewStringFromGo("true")
	strFalse     = NewStringFromGo("false")
)

func toGoString(v Value) string { return toString(v).String() }

func toObject(v Value) *Object {
	switch x := v.(type) {
	case *Object:
		return x
	case undefinedType:
		throwTypeError("cannot convert to object")
	case nullType:
		throwTypeError("cannot convert to object")
	case bool:
		o := newObjectRaw(rt.BooleanPrototype, ClassBoolean)
		o.internal = x
		return o
	case float64:
		o := newObjectRaw(rt.NumberPrototype, ClassNumber)
		o.internal = x
		return o
	case *String:
		o := newObjectRaw(rt.StringPrototype, ClassString)
		o.internal = x
		return o
	case *Symbol:
		o := newObjectRaw(rt.SymbolPrototype, ClassSymbol)
		o.internal = x
		return o
	case *big.Int:
		o := newObjectRaw(rt.BigIntPrototype, ClassBigInt)
		o.internal = x
		return o
	}
	throwTypeError("cannot convert to object")
	return nil
}

func toPropertyKey(v Value) PropKey {
	switch x := v.(type) {
	case *String:
		return PropKey{S: x.Key()}
	case *Symbol:
		return PropKey{Sym: x}
	case float64:
		if x >= 0 && x < 4294967295 && x == math.Trunc(x) {
			return PropKey{S: uint32ToString(uint32(x))}
		}
		return PropKey{S: numberToString(x)}
	case *Object:
		p := toPrimitive(v, "string")
		return toPropertyKey(p)
	}
	return PropKey{S: toString(v).Key()}
}

func isCallable(v Value) bool {
	o, ok := v.(*Object)
	return ok && o.callable
}

func isConstructor(v Value) bool {
	o, ok := v.(*Object)
	return ok && o.ctor
}

func isArray(v Value) bool {
	o, ok := v.(*Object)
	if !ok {
		return false
	}
	if o.class == ClassArray {
		return true
	}
	if o.class == ClassProxy {
		pd := o.internal.(*ProxyData)
		if pd.target == nil {
			throwTypeError("revoked proxy")
		}
		return isArray(pd.target)
	}
	return false
}

// ---------- Equality ----------

func sameValue(a, b Value) bool {
	switch x := a.(type) {
	case float64:
		y, ok := b.(float64)
		if !ok {
			return false
		}
		if x != x && y != y {
			return true
		}
		if x == 0 && y == 0 {
			return math.Signbit(x) == math.Signbit(y)
		}
		return x == y
	}
	return strictEquals(a, b)
}

func sameValueZero(a, b Value) bool {
	if x, ok := a.(float64); ok {
		y, ok := b.(float64)
		if !ok {
			return false
		}
		if x != x && y != y {
			return true
		}
		return x == y
	}
	return strictEquals(a, b)
}

func strictEquals(a, b Value) bool {
	switch x := a.(type) {
	case undefinedType:
		_, ok := b.(undefinedType)
		return ok
	case nullType:
		_, ok := b.(nullType)
		return ok
	case bool:
		y, ok := b.(bool)
		return ok && x == y
	case float64:
		y, ok := b.(float64)
		return ok && x == y
	case *String:
		y, ok := b.(*String)
		return ok && x.Equals(y)
	case *Symbol:
		y, ok := b.(*Symbol)
		return ok && x == y
	case *big.Int:
		y, ok := b.(*big.Int)
		return ok && x.Cmp(y) == 0
	case *Object:
		y, ok := b.(*Object)
		return ok && x == y
	}
	return false
}

func looseEquals(a, b Value) bool {
	switch x := a.(type) {
	case undefinedType, nullType:
		if isNullish(b) {
			return true
		}
		if o, ok := b.(*Object); ok && o.isHTMLDDA {
			return true
		}
		return false
	case bool:
		switch b.(type) {
		case bool:
			return strictEquals(a, b)
		}
		return looseEquals(boolToNum(x), b)
	case float64:
		switch y := b.(type) {
		case float64:
			return x == y
		case *String:
			return x == stringToNumber(y)
		case *big.Int:
			return bigEqualsNum(y, x)
		case bool:
			return looseEquals(a, boolToNum(y))
		case *Object:
			return looseEquals(a, toPrimitive(b, ""))
		}
		return false
	case *String:
		switch y := b.(type) {
		case *String:
			return x.Equals(y)
		case float64:
			return stringToNumber(x) == y
		case *big.Int:
			n, ok := stringToBigInt(x)
			return ok && n.Cmp(y) == 0
		case bool:
			return looseEquals(a, boolToNum(y))
		case *Object:
			return looseEquals(a, toPrimitive(b, ""))
		}
		return false
	case *Symbol:
		switch b.(type) {
		case *Symbol:
			return a == b
		case *Object:
			return looseEquals(a, toPrimitive(b, ""))
		}
		return false
	case *big.Int:
		switch y := b.(type) {
		case *big.Int:
			return x.Cmp(y) == 0
		case float64:
			return bigEqualsNum(x, y)
		case *String:
			n, ok := stringToBigInt(y)
			return ok && n.Cmp(x) == 0
		case bool:
			return looseEquals(a, boolToNum(y))
		case *Object:
			return looseEquals(a, toPrimitive(b, ""))
		}
		return false
	case *Object:
		switch b.(type) {
		case *Object:
			return a == b
		case undefinedType, nullType:
			return x.isHTMLDDA
		default:
			return looseEquals(toPrimitive(a, ""), b)
		}
	}
	return false
}

func boolToNum(b bool) float64 {
	if b {
		return 1
	}
	return 0
}

func bigEqualsNum(b *big.Int, f float64) bool {
	if f != f || math.IsInf(f, 0) {
		return false
	}
	if f != math.Trunc(f) {
		return false
	}
	bf := new(big.Float).SetInt(b)
	return bf.Cmp(big.NewFloat(f)) == 0
}

func stringToBigInt(s *String) (*big.Int, bool) {
	t := trimJSSpace(s).String()
	if t == "" {
		return new(big.Int), true
	}
	radix := 10
	if len(t) > 2 && t[0] == '0' {
		switch t[1] {
		case 'x', 'X':
			radix = 16
			t = t[2:]
		case 'o', 'O':
			radix = 8
			t = t[2:]
		case 'b', 'B':
			radix = 2
			t = t[2:]
		}
	}
	if radix != 10 && len(t) == 0 {
		return nil, false
	}
	if radix == 10 {
		if t[0] == '+' || t[0] == '-' {
			// allowed? StringToBigInt allows sign for decimal
		}
	}
	for i, c := range t {
		if radix == 10 && i == 0 && (c == '-' || c == '+') {
			if len(t) == 1 {
				return nil, false
			}
			continue
		}
		d := hexVal(byte(c))
		if c >= 128 || d < 0 || d >= radix {
			return nil, false
		}
	}
	b := new(big.Int)
	if _, ok := b.SetString(t, radix); !ok {
		return nil, false
	}
	return b, true
}

func toBigInt(v Value) *big.Int {
	p := toPrimitive(v, "number")
	switch x := p.(type) {
	case *big.Int:
		return x
	case bool:
		if x {
			return big.NewInt(1)
		}
		return big.NewInt(0)
	case *String:
		b, ok := stringToBigInt(x)
		if !ok {
			throwSyntaxError("invalid bigint literal")
		}
		return b
	case undefinedType:
		throwTypeError("cannot convert undefined to bigint")
	case nullType:
		throwTypeError("cannot convert null to bigint")
	case float64:
		throwTypeError("cannot convert number to bigint")
	case *Symbol:
		throwTypeError("cannot convert symbol to bigint")
	}
	throwTypeError("cannot convert to bigint")
	return nil
}

// ---------- Operators ----------

func jsAdd(a, b Value) Value {
	// fast paths
	if x, ok := a.(float64); ok {
		if y, ok := b.(float64); ok {
			return x + y
		}
	}
	if x, ok := a.(*String); ok {
		if y, ok := b.(*String); ok {
			return x.Concat(y)
		}
	}
	pa := toPrimitive(a, "")
	pb := toPrimitive(b, "")
	if sa, ok := pa.(*String); ok {
		return sa.Concat(toString(pb))
	}
	if sb, ok := pb.(*String); ok {
		return toString(pa).Concat(sb)
	}
	na := toNumeric(pa)
	nb := toNumeric(pb)
	if ba, ok := na.(*big.Int); ok {
		if bb, ok := nb.(*big.Int); ok {
			return new(big.Int).Add(ba, bb)
		}
		throwTypeError("both operands must be BigInt")
	}
	if _, ok := nb.(*big.Int); ok {
		throwTypeError("both operands must be BigInt")
	}
	return na.(float64) + nb.(float64)
}

func jsArith(op string, a, b Value) Value {
	if x, ok := a.(float64); ok {
		if y, ok := b.(float64); ok {
			return numArith(op, x, y)
		}
	}
	na := toNumeric(a)
	nb := toNumeric(b)
	ba, aBig := na.(*big.Int)
	bb, bBig := nb.(*big.Int)
	if aBig || bBig {
		if !(aBig && bBig) {
			throwTypeError("both operands must be BigInt")
		}
		return bigArith(op, ba, bb)
	}
	return numArith(op, na.(float64), nb.(float64))
}

func numArith(op string, x, y float64) float64 {
	switch op {
	case "-":
		return x - y
	case "*":
		return x * y
	case "/":
		return x / y
	case "%":
		if y == 0 || x != x || y != y || math.IsInf(x, 0) {
			return math.NaN()
		}
		if math.IsInf(y, 0) {
			return x
		}
		if x == 0 {
			return x
		}
		r := math.Mod(x, y)
		if r == 0 {
			return math.Copysign(0, x)
		}
		return r
	case "**":
		return jsPow(x, y)
	case "&":
		return float64(toInt32(x) & toInt32(y))
	case "|":
		return float64(toInt32(x) | toInt32(y))
	case "^":
		return float64(toInt32(x) ^ toInt32(y))
	case "<<":
		return float64(toInt32(x) << (toUint32(y) & 31))
	case ">>":
		return float64(toInt32(x) >> (toUint32(y) & 31))
	case ">>>":
		return float64(toUint32(x) >> (toUint32(y) & 31))
	}
	return math.NaN()
}

func jsPow(x, y float64) float64 {
	if y != y {
		return math.NaN()
	}
	if y == 0 {
		return 1
	}
	if (x == 1 || x == -1) && math.IsInf(y, 0) {
		return math.NaN()
	}
	return math.Pow(x, y)
}

func bigArith(op string, x, y *big.Int) Value {
	switch op {
	case "-":
		return new(big.Int).Sub(x, y)
	case "*":
		return new(big.Int).Mul(x, y)
	case "/":
		if y.Sign() == 0 {
			throwRangeError("division by zero")
		}
		return new(big.Int).Quo(x, y)
	case "%":
		if y.Sign() == 0 {
			throwRangeError("division by zero")
		}
		return new(big.Int).Rem(x, y)
	case "**":
		if y.Sign() < 0 {
			throwRangeError("negative exponent")
		}
		if y.BitLen() > 32 {
			if x.Sign() == 0 || x.CmpAbs(big.NewInt(1)) == 0 {
				// fine
			} else {
				throwRangeError("bigint exponent too large")
			}
		}
		return new(big.Int).Exp(x, y, nil)
	case "&":
		return new(big.Int).And(x, y)
	case "|":
		return new(big.Int).Or(x, y)
	case "^":
		return new(big.Int).Xor(x, y)
	case "<<":
		if y.BitLen() > 31 {
			if y.Sign() < 0 {
				if x.Sign() < 0 {
					return big.NewInt(-1)
				}
				return new(big.Int)
			}
			throwRangeError("bigint shift too large")
		}
		n := y.Int64()
		if n >= 0 {
			return new(big.Int).Lsh(x, uint(n))
		}
		return new(big.Int).Rsh(x, uint(-n))
	case ">>":
		if y.BitLen() > 31 {
			if y.Sign() > 0 {
				if x.Sign() < 0 {
					return big.NewInt(-1)
				}
				return new(big.Int)
			}
			throwRangeError("bigint shift too large")
		}
		n := y.Int64()
		if n >= 0 {
			return new(big.Int).Rsh(x, uint(n))
		}
		return new(big.Int).Lsh(x, uint(-n))
	case ">>>":
		throwTypeError("BigInts have no unsigned right shift, use >> instead")
	}
	return nil
}

// jsCompare returns: -1 less, 0 equal, 1 greater, 2 undefined (NaN)
func jsLess(a, b Value, leftFirst bool) (result bool, undefined bool) {
	var pa, pb Value
	if leftFirst {
		pa = toPrimitive(a, "number")
		pb = toPrimitive(b, "number")
	} else {
		pb = toPrimitive(b, "number")
		pa = toPrimitive(a, "number")
	}
	if sa, ok := pa.(*String); ok {
		if sb, ok := pb.(*String); ok {
			return sa.Compare(sb) < 0, false
		}
		if bb, ok := pb.(*big.Int); ok {
			na, ok := stringToBigInt(sa)
			if !ok {
				return false, true
			}
			return na.Cmp(bb) < 0, false
		}
	}
	if ba, ok := pa.(*big.Int); ok {
		if sb, ok := pb.(*String); ok {
			nb, ok := stringToBigInt(sb)
			if !ok {
				return false, true
			}
			return ba.Cmp(nb) < 0, false
		}
	}
	na := toNumeric(pa)
	nb := toNumeric(pb)
	switch x := na.(type) {
	case float64:
		switch y := nb.(type) {
		case float64:
			if x != x || y != y {
				return false, true
			}
			return x < y, false
		case *big.Int:
			if x != x {
				return false, true
			}
			if math.IsInf(x, 1) {
				return false, false
			}
			if math.IsInf(x, -1) {
				return true, false
			}
			return big.NewFloat(x).Cmp(new(big.Float).SetInt(y)) < 0, false
		}
	case *big.Int:
		switch y := nb.(type) {
		case *big.Int:
			return x.Cmp(y) < 0, false
		case float64:
			if y != y {
				return false, true
			}
			if math.IsInf(y, 1) {
				return true, false
			}
			if math.IsInf(y, -1) {
				return false, false
			}
			return new(big.Float).SetInt(x).Cmp(big.NewFloat(y)) < 0, false
		}
	}
	return false, true
}

func jsInstanceOf(v Value, target Value) bool {
	t, ok := target.(*Object)
	if !ok {
		throwTypeError("invalid 'instanceof' right operand")
	}
	h := t.Get(symKey(SymHasInstance), t)
	if !isNullish(h) {
		if !isCallable(h) {
			throwTypeError("Symbol.hasInstance is not a function")
		}
		return toBoolean(callFunction(h.(*Object), t, []Value{v}))
	}
	if !t.callable {
		throwTypeError("invalid 'instanceof' right operand")
	}
	return ordinaryHasInstance(t, v)
}

func ordinaryHasInstance(c *Object, v Value) bool {
	if !c.callable {
		return false
	}
	if fd, ok := c.internal.(*Function); ok && fd.boundTarget != nil {
		return jsInstanceOf(v, fd.boundTarget)
	}
	o, ok := v.(*Object)
	if !ok {
		return false
	}
	pv := c.Get(strKey("prototype"), c)
	proto, ok := pv.(*Object)
	if !ok {
		throwTypeError("operand 'prototype' property is not an object")
	}
	for {
		o = o.GetPrototypeOf()
		if o == nil {
			return false
		}
		if o == proto {
			return true
		}
	}
}

func jsIn(key Value, obj Value) bool {
	o, ok := obj.(*Object)
	if !ok {
		throwTypeError("invalid 'in' operand")
	}
	return o.HasProperty(toPropertyKey(key))
}

// ---------- Calls ----------

func callFunction(f *Object, this Value, args []Value) Value {
	if !f.callable {
		throwTypeError("not a function")
	}
	switch fd := f.internal.(type) {
	case *Function:
		return fd.call(f, this, args, nil)
	}
	throwTypeError("not a function")
	return nil
}

func callValue(fv Value, this Value, args []Value) Value {
	f, ok := fv.(*Object)
	if !ok || !f.callable {
		throwTypeError("not a function")
	}
	return callFunction(f, this, args)
}

func construct(f *Object, args []Value, newTarget *Object) Value {
	if !f.ctor {
		throwTypeError("not a constructor")
	}
	if newTarget == nil {
		newTarget = f
	}
	fd := f.internal.(*Function)
	return fd.construct(f, args, newTarget)
}

// getPrototypeFromConstructor: newTarget.prototype or fallback
func getPrototypeFromCtor(newTarget *Object, fallback *Object) *Object {
	if newTarget == nil {
		return fallback
	}
	pv := newTarget.Get(strKey("prototype"), newTarget)
	if p, ok := pv.(*Object); ok {
		return p
	}
	return fallback
}

func speciesConstructor(o *Object, defaultCtor *Object) *Object {
	c := o.Get(strKey("constructor"), o)
	if isUndefined(c) {
		return defaultCtor
	}
	co, ok := c.(*Object)
	if !ok {
		throwTypeError("not a constructor")
	}
	s := co.Get(symKey(SymSpecies), co)
	if isNullish(s) {
		return defaultCtor
	}
	if !isConstructor(s) {
		throwTypeError("not a constructor")
	}
	return s.(*Object)
}

func getMethod(v Value, k PropKey) *Object {
	var f Value
	if o, ok := v.(*Object); ok {
		f = o.Get(k, o)
	} else {
		f = toObject(v).Get(k, v)
	}
	if isNullish(f) {
		return nil
	}
	if !isCallable(f) {
		throwTypeError("not a function")
	}
	return f.(*Object)
}

// getV: property get on any value (primitives use their prototype)
func getV(v Value, k PropKey) Value {
	switch x := v.(type) {
	case *Object:
		return x.Get(k, x)
	case *String:
		if k.Sym == nil {
			if k.S == "length" {
				return float64(x.Len())
			}
			if idx, ok := arrayIndexFromKey(k.S); ok {
				if int(idx) < x.Len() {
					return x.Substring(int(idx), int(idx)+1)
				}
				return Undefined
			}
		}
		return rt.StringPrototype.Get(k, v)
	case float64:
		return rt.NumberPrototype.Get(k, v)
	case bool:
		return rt.BooleanPrototype.Get(k, v)
	case *Symbol:
		return rt.SymbolPrototype.Get(k, v)
	case *big.Int:
		return rt.BigIntPrototype.Get(k, v)
	case undefinedType:
		throwTypeError("cannot read property '%s' of undefined", keyToDisplay(k))
	case nullType:
		throwTypeError("cannot read property '%s' of null", keyToDisplay(k))
	}
	return Undefined
}

func lengthOfArrayLike(o *Object) int64 {
	if o.class == ClassArray {
		return int64(arrayLength(o))
	}
	return toLength(o.Get(strKey("length"), o))
}

func createListFromArrayLike(v Value) []Value {
	o, ok := v.(*Object)
	if !ok {
		throwTypeError("not an object")
	}
	if o.class == ClassArray && !ad_sparse(o) {
		out := make([]Value, len(o.arr))
		for i, e := range o.arr {
			if e == hole {
				out[i] = Undefined
			} else {
				out[i] = e
			}
		}
		return out
	}
	n := lengthOfArrayLike(o)
	out := make([]Value, n)
	for i := int64(0); i < n; i++ {
		out[i] = o.Get(strKey(strconv.FormatInt(i, 10)), o)
	}
	return out
}

func idxKey(i int64) PropKey {
	if i >= 0 && i < 4294967295 {
		return strKey(uint32ToString(uint32(i)))
	}
	return strKey(numberToString(float64(i)))
}

func arg(args []Value, i int) Value {
	if i < len(args) {
		return args[i]
