// getVar reads a variable
func (in *Interp) getVar(name string, pos int) Value {
	sc, idx := lookupBinding(in.scope, name)
	if sc != nil {
		if idx == -2 {
			return sc.withObj.Get(strKey(name), sc.withObj)
		}
		fl := sc.flags[idx]
		if fl&bTDZ != 0 {
			in.frame.pos = pos
			throwReferenceError("lexical variable '%s' is not initialized... wait", name)
		}
		if fl&bImport != 0 {
			return resolveImportBinding(sc, idx, name)
		}
		return sc.vals[idx]
	}
	// global lexical
	if g := rt.GlobalLex; g != nil {
		if i := g.find(name); i >= 0 {
			if g.flags[i]&bTDZ != 0 {
				in.frame.pos = pos
				throwReferenceError("lexical variable '%s' is not initialized", name)
			}
			return g.vals[i]
		}
	}
	k := strKey(name)
	gl := rt.Global
	p := gl.GetOwnProperty(k)
	if p != nil {
		if p.IsAccessor() {
			if g, ok := p.Getter.(*Object); ok {
				return callFunction(g, gl, nil)
			}
			return Undefined
		}
		return p.Value
	}
	if gl.proto != nil && gl.proto.HasProperty(k) {
		return gl.proto.Get(k, gl)
	}
	in.frame.pos = pos
	throwReferenceError("'%s' is not defined", name)
	return nil
}

// typeofVar: like getVar but returns undefined for unresolvable
func (in *Interp) getVarOrUndefined(name string, pos int) (Value, bool) {
	sc, idx := lookupBinding(in.scope, name)
	if sc != nil {
		if idx == -2 {
			return sc.withObj.Get(strKey(name), sc.withObj), true
		}
		if sc.flags[idx]&bTDZ != 0 {
			in.frame.pos = pos
			throwReferenceError("lexical variable '%s' is not initialized", name)
		}
		if sc.flags[idx]&bImport != 0 {
			return resolveImportBinding(sc, idx, name), true
		}
		return sc.vals[idx], true
	}
	if g := rt.GlobalLex; g != nil {
		if i := g.find(name); i >= 0 {
			if g.flags[i]&bTDZ != 0 {
				in.frame.pos = pos
				throwReferenceError("lexical variable '%s' is not initialized", name)
			}
			return g.vals[i], true
		}
	}
	k := strKey(name)
	if rt.Global.HasProperty(k) {
		return rt.Global.Get(k, rt.Global), true
	}
	return Undefined, false
}

func (in *Interp) setVar(name string, v Value, pos int) {
	sc, idx := lookupBinding(in.scope, name)
	if sc != nil {
		if idx == -2 {
			sc.withObj.Set(strKey(name), v, sc.withObj)
			return
		}
		fl := sc.flags[idx]
		if fl&bTDZ != 0 {
			in.frame.pos = pos
			throwReferenceError("lexical variable '%s' is not initialized", name)
		}
		if fl&bConst != 0 {
			if fl&bFuncName != 0 {
				if in.strict {
					in.frame.pos = pos
					throwTypeError("'%s' is read-only", name)
				}
				return
			}
			in.frame.pos = pos
			throwTypeError("'%s' is read-only", name)
		}
		if fl&bImport != 0 {
			in.frame.pos = pos
			throwTypeError("'%s' is read-only", name)
		}
		sc.vals[idx] = v
		return
	}
	if g := rt.GlobalLex; g != nil {
		if i := g.find(name); i >= 0 {
			if g.flags[i]&bTDZ != 0 {
				in.frame.pos = pos
				throwReferenceError("lexical variable '%s' is not initialized", name)
			}
			if g.flags[i]&bConst != 0 {
				in.frame.pos = pos
				throwTypeError("'%s' is read-only", name)
			}
			g.vals[i] = v
			return
		}
	}
	k := strKey(name)
	gl := rt.Global
	if in.strict && !gl.HasProperty(k) {
		in.frame.pos = pos
		throwReferenceError("'%s' is not defined", name)
	}
	if !gl.Set(k, v, gl) {
		if in.strict {
			in.frame.pos = pos
			throwTypeError("'%s' is read-only", name)
		}
	}
}

// initBinding initializes a lexical binding (clears TDZ) in the nearest scope that declares it
func (in *Interp) initBinding(name string, v Value) {
	for s := in.scope; s != nil; s = s.parent {
		if s.withObj != nil {
			continue
		}
		for i := len(s.names) - 1; i >= 0; i-- {
			if s.names[i] == name {
				s.vals[i] = v
				s.flags[i] &^= bTDZ
				return
			}
		}
	}
	if g := rt.GlobalLex; g != nil {
		if i := g.find(name); i >= 0 {
			g.vals[i] = v
			g.flags[i] &^= bTDZ
			return
		}
	}
	// var in global: set on global object
	rt.Global.Set(strKey(name), v, rt.Global)
}

// ---------- Functions ----------

func (fn *Function) call(fobj *Object, this Value, args []Value, newTarget *Object) Value {
	if fn.boundTarget != nil {
		all := make([]Value, 0, len(fn.boundArgs)+len(args))
		all = append(all, fn.boundArgs...)
		all = append(all, args...)
		return callFunction(fn.boundTarget, fn.boundThis, all)
	}
	if fn.native != nil {
		frame := &Frame{fnName: fn.name, fnObj: fobj, isNative: true}
		pushFrame(frame)
		r := fn.native(this, args)
		popFrame()
		return r
	}
	if fn.isClassCtor && newTarget == nil {
		throwTypeError("class constructors must be invoked with 'new'")
	}
	return fn.callJS(fobj, this, args, newTarget)
}

func (fn *Function) construct(fobj *Object, args []Value, newTarget *Object) Value {
	if fn.boundTarget != nil {
		all := make([]Value, 0, len(fn.boundArgs)+len(args))
		all = append(all, fn.boundArgs...)
		all = append(all, args...)
		nt := newTarget
		if nt == fobj {
			nt = fn.boundTarget
		}
		return construct(fn.boundTarget, all, nt)
	}
	if fn.nativeCtor != nil {
		frame := &Frame{fnName: fn.name, fnObj: fobj, isNative: true}
		pushFrame(frame)
		r := fn.nativeCtor(args, newTarget)
		popFrame()
		return r
	}
	if fn.native != nil {
		throwTypeError("not a constructor")
	}
	if fn.isDerived {
		// this is uninitialized until super()
		r := fn.callJS(fobj, nil, args, newTarget)
		return r
	}
	proto := getPrototypeFromCtor(newTarget, rt.ObjectPrototype)
	obj := newObjectRaw(proto, ClassObject)
	r := fn.callJS(fobj, obj, args, newTarget)
	if ro, ok := r.(*Object); ok {
		return ro
	}
	return obj
}

func (fn *Function) callJS(fobj *Object, this Value, args []Value, newTarget *Object) Value {
	node := fn.node
	act := &Activation{fnObj: fobj, fn: fn, args: args, module: fn.module, src: fn.src, strict: node.Strict, privEnv: fn.privEnv}
	if newTarget != nil {
		act.newTarget = newTarget
	} else {
		act.newTarget = Undefined
	}
	act.homeObject = fn.homeObject
	if node.IsArrow || node.Kind == FuncClassFieldInit && fn.lexAct != nil && false {
		act = fn.lexAct
	}
	frame := &Frame{fnName: fn.name, fnObj: fobj, src: fn.src, pos: node.P}
	if node.IsArrow {
		// arrow: share lexical activation but own frame
		la := fn.lexAct
		act = &Activation{this: la.this, thisInit: la.thisInit, fnObj: la.fnObj, fn: la.fn, newTarget: la.newTarget, homeObject: la.homeObject, args: la.args, argumentsObj: la.argumentsObj, module: fn.module, src: fn.src, strict: node.Strict, privEnv: fn.privEnv, gen: nil}
		act.lexParent = la
		act.isArrowAct = true
	} else {
		if this == nil {
			act.thisInit = false
			act.this = Undefined
		} else {
			act.thisInit = true
			if node.Strict {
				act.this = this
			} else {
				switch this.(type) {
				case undefinedType, nullType:
					act.this = rt.Global
				case *Object:
					act.this = this
				default:
					act.this = toObject(this)
				}
			}
		}
	}
	act.frame = frame
	scope := newScope(fn.scope, act)
	scope.funcScope = true
	in := &Interp{scope: scope, act: act, src: fn.src, frame: frame, strict: node.Strict, module: fn.module}
	if node.IsGenerator || node.IsAsync {
		return in.startCoroutine(fn, fobj, args, act)
	}
	pushFrame(frame)
	defer popFrame()
	in.bindParamsAndHoist(fn, args)
	var result Value = Undefined
	if node.ExprBody {
		result = in.evalExpr(node.Body[0].(*ReturnStmt).Arg)
	} else {
		c := in.execStatements(node.Body)
		if c.t == cReturn {
			result = c.v
		}
	}
	if fn.isDerived && newTarget != nil {
		// derived constructor: return this
		if ro, ok := result.(*Object); ok {
			return ro
		}
		if !isUndefined(result) {
			throwTypeError("derived class constructor must return an object or undefined")
		}
		if !act.thisInit {
			throwReferenceError("this is not initialized")
		}
		return act.this
	}
	return result
}

func (in *Interp) bindParamsAndHoist(fn *Function, args []Value) {
	node := fn.node
	scope := in.scope
	act := in.act
	// arguments object
	needArgs := node.UsesArguments && !node.IsArrow
	if needArgs {
		ao := createArgumentsObject(act, args, node.Strict || !node.SimpleParams)
		act.argumentsObj = ao
		hasParamArguments := false
		for _, pn := range node.ParamNames {
			if pn == "arguments" {
				hasParamArguments = true
			}
		}
		if !hasParamArguments {
			scope.declare("arguments", ao, 0)
		}
	}
	// params
	if node.SimpleParams {
		for i, p := range node.Params {
			id := p.(*Ident)
			var v Value = Undefined
			if i < len(args) {
				v = args[i]
			}
			// duplicate names: last wins
			if j := scope.find(id.Name); j >= 0 && j >= 0 && scope.names[j] == id.Name && i > 0 && hasDup(node.ParamNames, id.Name) {
				scope.vals[j] = v
			} else {
				scope.declare(id.Name, v, 0)
			}
		}
	} else {
		// declare all param names first (TDZ)
		for _, pn := range node.ParamNames {
			scope.declare(pn, Undefined, bTDZ)
		}
		for i, p := range node.Params {
			if r, ok := p.(*RestElement); ok {
				rest := []Value{}
				if i < len(args) {
					rest = append(rest, args[i:]...)
				}
				in.bindPattern(r.Target, newArrayObject(rest), true)
				break
			}
			var v Value = Undefined
			if i < len(args) {
				v = args[i]
			}
			in.bindPattern(p, v, true)
		}
	}
	// var names
	for _, vn := range node.VarNames {
		if scope.find(vn) < 0 {
			scope.declare(vn, Undefined, bVar)
		}
	}
	// lexical names (TDZ)
	for _, ln := range node.LexNames {
		if ln.IsFunc {
			continue
		}
		fl := bTDZ
		if ln.IsConst {
			fl |= bConst
		}
		if i := scope.find(ln.Name); i >= 0 && !node.SimpleParams {
			// lexical shadowing param name is not allowed by parser; ignore
			continue
		}
		scope.declare(ln.Name, Undefined, fl)
	}
	// function declarations
	for _, fd := range node.FuncDecls {
		fo := in.makeFunction(fd)
		if i := scope.find(fd.Name); i >= 0 {
			scope.vals[i] = fo
			scope.flags[i] &^= bTDZ
		} else {
			scope.declare(fd.Name, fo, bVar)
		}
	}
}

func hasDup(names []string, n string) bool {
	c := 0
	for _, x := range names {
		if x == n {
			c++
		}
	}
	return c > 1
}

func createArgumentsObject(act *Activation, args []Value, unmapped bool) *Object {
	o := newObjectRaw(rt.ObjectPrototype, ClassArguments)
	o.arr = make([]Value, len(args))
	copy(o.arr, args)
	o.setOwn("length", float64(len(args)), PropHidden)
	o.setOwnSym(SymIterator, rt.ArrayProtoValues, PropHidden)
	if unmapped {
		o.props.Set(strKey("callee"), Prop{Getter: rt.ThrowTypeError, Setter: rt.ThrowTypeError, Flags: PropAccessor})
	} else {
		o.setOwn("callee", act.fnObj, PropHidden)
	}
	return o
}

// makeFunction creates a function object (closure) for a FuncNode in the current scope
func (in *Interp) makeFunction(node *FuncNode) *Object {
	return makeFunctionObject(node, in.scope, in.act, in.src, in.module, nil)
}

func makeFunctionObject(node *FuncNode, scope *Scope, act *Activation, src *Source, module *Module, homeObject *Object) *Object {
	fn := &Function{node: node, scope: scope, name: node.Name, src: src, module: module, strict: node.Strict, homeObject: homeObject}
	fn.isAsync = node.IsAsync
	fn.isGenerator = node.IsGenerator
	if act != nil {
		fn.privEnv = act.privEnv
	}
	var proto *Object
	switch {
	case node.IsAsync && node.IsGenerator:
		proto = rt.AsyncGeneratorFunctionPrototype
	case node.IsAsync:
		proto = rt.AsyncFunctionPrototype
	case node.IsGenerator:
		proto = rt.GeneratorFunctionPrototype
	default:
		proto = rt.FunctionPrototype
	}
	fobj := newObjectRaw(proto, ClassFunction)
	fobj.internal = fn
	fobj.callable = true
	if node.IsArrow {
		fn.lexAct = act
	}
	isCtor := node.Kind == FuncNormal && !node.IsAsync && !node.IsGenerator && !node.IsArrow
	if node.Kind == FuncClassConstructor || node.Kind == FuncDerivedConstructor {
		isCtor = true
		fn.isClassCtor = true
		fn.isDerived = node.Kind == FuncDerivedConstructor
	}
	fobj.ctor = isCtor
	// function expression with own name: bind name in an intermediate scope
	if node.IsExpr && node.HasOwnName && node.Name != "" && node.Kind == FuncNormal {
		ns := newScope(scope, nil)
		ns.declare(node.Name, fobj, bConst|bFuncName)
		fn.scope = ns
	}
	// length
	nparams := 0
	for _, p := range node.Params {
		if _, ok := p.(*RestElement); ok {
			break
		}
		if _, ok := p.(*AssignPattern); ok {
			break
		}
		nparams++
	}
	fobj.setOwn("length", float64(nparams), PropConfigurable)
	name := node.Name
	if node.Kind == FuncGetter {
		name = "get " + name
	} else if node.Kind == FuncSetter {
		name = "set " + name
	}
	fobj.setOwn("name", NewStringFromGo(name), PropConfigurable)
	fn.name = node.Name
	// prototype property
	if node.IsGenerator {
		var gp *Object
		if node.IsAsync {
			gp = newObjectRaw(rt.AsyncGeneratorPrototype, ClassObject)
		} else {
			gp = newObjectRaw(rt.GeneratorPrototype, ClassObject)
		}
		fobj.setOwn("prototype", gp, PropWritable)
	} else if isCtor && !fn.isClassCtor {
		po := newObjectRaw(rt.ObjectPrototype, ClassObject)
		po.setOwn("constructor", fobj, PropHidden)
		fobj.setOwn("prototype", po, PropWritable)
	}
	return fobj
}

// ---------- Native function helpers ----------

func newNativeFunction(name string, length int, f NativeFn) *Object {
	fn := &Function{native: f, name: name}
	o := newObjectRaw(rt.FunctionPrototype, ClassFunction)
	o.internal = fn
	o.callable = true
	o.setOwn("length", float64(length), PropConfigurable)
	o.setOwn("name", NewStringFromGo(name), PropConfigurable)
	return o
}

func newNativeConstructor(name string, length int, call NativeFn, ctor NativeCtor, proto *Object) *Object {
	fn := &Function{native: call, nativeCtor: ctor, name: name}
	o := newObjectRaw(rt.FunctionPrototype, ClassFunction)
	o.internal = fn
	o.callable = true
	o.ctor = true
	o.setOwn("length", float64(length), PropConfigurable)
	o.setOwn("name", NewStringFromGo(name), PropConfigurable)
	if proto != nil {
		o.setOwn("prototype", proto, 0)
		proto.setOwn("constructor", o, PropHidden)
	}
	return o
}

func (o *Object) defineMethod(name string, length int, f NativeFn) *Object {
	m := newNativeFunction(name, length, f)
	o.setOwn(name, m, PropHidden)
	return m
}

func (o *Object) defineMethodSym(sym *Symbol, name string, length int, f NativeFn) *Object {
	m := newNativeFunction(name, length, f)
	o.setOwnSym(sym, m, PropHidden)
	return m
}

func (o *Object) defineGetter(name string, f NativeFn) {
	g := newNativeFunction("get "+name, 0, f)
	o.setAccessor(name, g, nil, PropConfigurable)
}

func (o *Object) defineGetterSym(sym *Symbol, name string, f NativeFn) {
	g := newNativeFunction("get "+name, 0, f)
	o.props.Set(symKey(sym), Prop{Getter: g, Setter: Undefined, Flags: PropAccessor | PropConfigurable})
}

func (o *Object) defineAccessor(name string, g NativeFn, s NativeFn) {
	var go_, so *Object
	if g != nil {
		go_ = newNativeFunction("get "+name, 0, g)
	}
	if s != nil {
		so = newNativeFunction("set "+name, 1, s)
	}
	o.setAccessor(name, go_, so, PropConfigurable)
}

// ---------- misc ----------

func thisNumberValue(v Value, method string) float64 {
	switch x := v.(type) {
	case float64:
		return x
	case *Object:
		if x.class == ClassNumber {
			return x.internal.(float64)
		}
	}
	throwTypeError("not a number")
	return math.NaN()
}

func thisBigIntValue(v Value) *big.Int {
	switch x := v.(type) {
	case *big.Int:
		return x
	case *Object:
		if x.class == ClassBigInt {
			return x.internal.(*big.Int)
		}
	}
	throwTypeError("not a bigint")
