{"command":"cat > /workspace/src/interp_stmt.go <<'EOF'
package main

// execStatements runs a statement list in the current scope
func (in *Interp) execStatements(body []Node) completion {
	for _, s := range body {
		c := in.execStmt(s)
		if c.t != cNormal {
			return c
		}
	}
	return normalCompletion
}

// enterBlock creates a scope for lexical declarations if needed, returns restore func
func (in *Interp) pushBlockScope(lex []LexName, funcDecls []*FuncNode) *Scope {
	if len(lex) == 0 && len(funcDecls) == 0 {
		return nil
	}
	saved := in.scope
	sc := newScope(in.scope, nil)
	in.scope = sc
	for _, ln := range lex {
		if ln.IsFunc {
			continue
		}
		fl := bTDZ
		if ln.IsConst {
			fl |= bConst
		}
		sc.declare(ln.Name, Undefined, fl)
	}
	for _, fd := range funcDecls {
		fo := in.makeFunction(fd)
		if i := sc.find(fd.Name); i >= 0 {
			sc.vals[i] = fo
			sc.flags[i] &^= bTDZ
		} else {
			sc.declare(fd.Name, fo, 0)
		}
		if fd.AnnexB && !in.strict {
			// also assign to the var-scoped binding when the declaration is evaluated (we do it at block entry)
			in.setVarScoped(fd.Name, fo, saved)
		}
	}
	return saved
}

func (in *Interp) setVarScoped(name string, v Value, from *Scope) {
	for s := from; s != nil; s = s.parent {
		if s.withObj != nil {
			continue
		}
		if i := s.find(name); i >= 0 {
			s.vals[i] = v
			return
		}
		if s.funcScope {
			break
		}
	}
	if from == nil || in.act == nil {
		rt.Global.Set(strKey(name), v, rt.Global)
	}
}

func (in *Interp) execBlock(b *BlockStmt) completion {
	saved := in.pushBlockScope(b.Lex, b.FuncDecls)
	c := in.execStatements(b.Body)
	if saved != nil {
		in.scope = saved
	}
	return c
}

func (in *Interp) execStmt(s Node) completion {
	switch st := s.(type) {
	case *ExprStmt:
		in.evalExpr(st.X)
		return normalCompletion
	case *VarDecl:
		in.execVarDecl(st)
		return normalCompletion
	case *FuncDecl:
		// hoisted; nothing at runtime (Annex B handled at block entry)
		return normalCompletion
	case *ClassDecl:
		cls := in.evalClass(st.Class)
		in.initBinding(st.Class.Name, cls)
		return normalCompletion
	case *ReturnStmt:
		var v Value = Undefined
		if st.Arg != nil {
			v = in.evalExpr(st.Arg)
		}
		return completion{t: cReturn, v: v}
	case *IfStmt:
		if toBoolean(in.evalExpr(st.Test)) {
			return in.execStmt(st.Cons)
		} else if st.Alt != nil {
			return in.execStmt(st.Alt)
		}
		return normalCompletion
	case *BlockStmt:
		return in.execBlock(st)
	case *ForStmt:
		return in.execFor(st, "")
	case *ForInStmt:
		if st.Of {
			return in.execForOf(st, "")
		}
		return in.execForIn(st, "")
	case *WhileStmt:
		return in.execWhile(st, "")
	case *DoWhileStmt:
		return in.execDoWhile(st, "")
	case *BreakStmt:
		return completion{t: cBreak, label: st.Label}
	case *ContinueStmt:
		return completion{t: cContinue, label: st.Label}
	case *ThrowStmt:
		v := in.evalExpr(st.Arg)
		in.frame.pos = st.P
		panic(&Throw{Val: v})
	case *TryStmt:
		return in.execTry(st)
	case *SwitchStmt:
		return in.execSwitch(st, "")
	case *LabeledStmt:
		return in.execLabeled(st)
	case *EmptyStmt:
		return normalCompletion
	case *WithStmt:
		obj := toObject(in.evalExpr(st.Obj))
		saved := in.scope
		sc := newScope(in.scope, nil)
		sc.withObj = obj
		in.scope = sc
		c := in.execStmt(st.Body)
		in.scope = saved
		return c
	case *DebuggerStmt:
		return normalCompletion
	case *ImportDecl:
		return normalCompletion
	case *ExportDecl:
		return in.execExport(st)
	}
	throwInternalError("unknown statement type %T", s)
	return normalCompletion
}

func (in *Interp) execVarDecl(d *VarDecl) {
	for _, decl := range d.Decls {
		if decl.Init == nil {
			if d.Kind == "var" {
				continue
			}
			// let x;  -> initialize to undefined
			if id, ok := decl.Target.(*Ident); ok {
				in.initBinding(id.Name, Undefined)
			}
			continue
		}
		v := in.evalExpr(decl.Init)
		if d.Kind == "var" {
			if id, ok := decl.Target.(*Ident); ok {
				in.setVar(id.Name, v, decl.P)
			} else {
				in.bindPattern(decl.Target, v, false)
			}
		} else {
			in.bindPattern(decl.Target, v, true)
		}
	}
}

// loopContinues checks a completion from a loop body: returns (continueLoop, completionToReturn, shouldReturn)
func loopBodyResult(c completion, label string) (bool, completion) {
	switch c.t {
	case cBreak:
		if c.label == "" || c.label == label {
			return false, normalCompletion
		}
		return false, c
	case cContinue:
		if c.label == "" || c.label == label {
			return true, normalCompletion
		}
		return false, c
	case cReturn:
		return false, c
	}
	return true, normalCompletion
}

func (in *Interp) execLabeled(st *LabeledStmt) completion {
	var c completion
	switch body := st.Body.(type) {
	case *ForStmt:
		c = in.execFor(body, st.Label)
	case *ForInStmt:
		if body.Of {
			c = in.execForOf(body, st.Label)
		} else {
			c = in.execForIn(body, st.Label)
		}
	case *WhileStmt:
		c = in.execWhile(body, st.Label)
	case *DoWhileStmt:
		c = in.execDoWhile(body, st.Label)
	case *SwitchStmt:
		c = in.execSwitch(body, st.Label)
	default:
		c = in.execStmt(st.Body)
	}
	if c.t == cBreak && c.label == st.Label {
		return normalCompletion
	}
	return c
}

func (in *Interp) execWhile(st *WhileStmt, label string) completion {
	for toBoolean(in.evalExpr(st.Test)) {
		c := in.execStmt(st.Body)
		if c.t != cNormal {
			cont, r := loopBodyResult(c, label)
			if !cont {
				return r
			}
		}
	}
	return normalCompletion
}

func (in *Interp) execDoWhile(st *DoWhileStmt, label string) completion {
	for {
		c := in.execStmt(st.Body)
		if c.t != cNormal {
			cont, r := loopBodyResult(c, label)
			if !cont {
				return r
			}
		}
		if !toBoolean(in.evalExpr(st.Test)) {
			break
		}
	}
	return normalCompletion
}

func (in *Interp) execFor(st *ForStmt, label string) completion {
	saved := in.scope
	defer func() { in.scope = saved }()
	perIteration := false
	if len(st.Lex) > 0 {
		sc := newScope(in.scope, nil)
		in.scope = sc
		for _, ln := range st.Lex {
			fl := bTDZ
			if ln.IsConst {
				fl |= bConst
			}
			sc.declare(ln.Name, Undefined, fl)
			if !ln.IsConst {
				perIteration = true
			}
		}
		if vd, ok := st.Init.(*VarDecl); ok {
			in.execVarDecl(vd)
		}
	} else if st.Init != nil {
		if vd, ok := st.Init.(*VarDecl); ok {
			in.execVarDecl(vd)
		} else {
			in.evalExpr(st.Init)
		}
	}
	if perIteration {
		in.copyIterationScope()
	}
	for {
		if st.Test != nil && !toBoolean(in.evalExpr(st.Test)) {
			break
		}
		c := in.execStmt(st.Body)
		if c.t != cNormal {
			cont, r := loopBodyResult(c, label)
			if !cont {
				return r
			}
		}
		if perIteration {
			in.copyIterationScope()
		}
		if st.Update != nil {
			in.evalExpr(st.Update)
		}
	}
	return normalCompletion
}

// copyIterationScope replaces the current (loop) scope with a copy so closures capture per-iteration bindings
func (in *Interp) copyIterationScope() {
	old := in.scope
	sc := &Scope{parent: old.parent, act: old.act}
	sc.names = old.names // names shared (immutable after creation here)
	sc.vals = make([]Value, len(old.vals))
	copy(sc.vals, old.vals)
	sc.flags = make([]uint8, len(old.flags))
	copy(sc.flags, old.flags)
	in.scope = sc
}

func (in *Interp) forBindingScope(st *ForInStmt) (func(), func(v Value)) {
	// returns enter-iteration and bind functions
	vd, isDecl := st.Left.(*VarDecl)
	if isDecl && vd.Kind != "var" {
		decl := vd.Decls[0]
		return func() {
				sc := newScope(in.scope, nil)
				for _, ln := range st.Lex {
					fl := bTDZ
					if ln.IsConst {
						fl |= bConst
					}
					sc.declare(ln.Name, Undefined, fl)
				}
				in.scope = sc
			}, func(v Value) {
				in.bindPattern(decl.Target, v, true)
			}
	}
	if isDecl {
		decl := vd.Decls[0]
		return func() {}, func(v Value) {
			if id, ok := decl.Target.(*Ident); ok {
				in.setVar(id.Name, v, decl.P)
			} else {
				in.bindPattern(decl.Target, v, false)
			}
		}
	}
	return func() {}, func(v Value) {
		in.assignToTarget(st.Left, v)
	}
}

func (in *Interp) execForIn(st *ForInStmt, label string) completion {
	saved := in.scope
	defer func() { in.scope = saved }()
	// Annex B: for (var x = init in obj)
	if vd, ok := st.Left.(*VarDecl); ok && vd.Decls[0].Init != nil {
		in.execVarDecl(vd)
	}
	// TDZ scope for evaluating the right side when using let/const
	if len(st.Lex) > 0 {
		sc := newScope(in.scope, nil)
		for _, ln := range st.Lex {
			sc.declare(ln.Name, Undefined, bTDZ)
		}
		in.scope = sc
	}
	objv := in.evalExpr(st.Right)
	in.scope = saved
	if isNullish(objv) {
		return normalCompletion
	}
	obj := toObject(objv)
	enter, bind := in.forBindingScope(st)
	visited := map[PropKey]bool{}
	for o := obj; o != nil; o = o.GetPrototypeOf() {
		keys := o.OwnKeys()
		for _, k := range keys {
			if k.Sym != nil {
				continue
			}
			if visited[k] {
				continue
			}
			visited[k] = true
			p := o.GetOwnProperty(k)
			if p == nil || !p.Enumerable() {
				continue
			}
			in.scope = saved
			enter()
			bind(NewStringFromGo(k.S))
			c := in.execStmt(st.Body)
			in.scope = saved
			if c.t != cNormal {
				cont, r := loopBodyResult(c, label)
				if !cont {
					return r
				}
			}
		}
	}
	return normalCompletion
}

func (in *Interp) execForOf(st *ForInStmt, label string) completion {
	saved := in.scope
	defer func() { in.scope = saved }()
	if len(st.Lex) > 0 {
		sc := newScope(in.scope, nil)
		for _, ln := range st.Lex {
			sc.declare(ln.Name, Undefined, bTDZ)
		}
		in.scope = sc
	}
	iterable := in.evalExpr(st.Right)
	in.scope = saved
	enter, bind := in.forBindingScope(st)
	var iter *Iterator
	if st.Await {
		iter = getAsyncIterator(iterable)
	} else {
		iter = getIterator(iterable)
	}
	result := normalCompletion
	func() {
		defer func() {
			if r := recover(); r != nil {
				// close iterator on abrupt completion (throw)
				if _, ok := r.(*Throw); ok {
					if st.Await {
						in.asyncIteratorCloseSwallow(iter)
					} else {
						iteratorCloseSwallow(iter)
					}
				}
				panic(r)
			}
		}()
		for {
			var v Value
			var done bool
			if st.Await {
				res := iter.nextRaw(nil)
				res = in.await(res)
				ro, ok := res.(*Object)
				if !ok {
					throwTypeError("iterator result is not an object")
				}
				done = toBoolean(ro.Get(strKey("done"), ro))
				if done {
					break
				}
				v = ro.Get(strKey("value"), ro)
			} else {
				var ok bool
				v, ok = iter.step()
				if !ok {
					break
				}
			}
			in.scope = saved
			enter()
			var c completion
			func() {
				defer func() {
					if r := recover(); r != nil {
						if _, ok := r.(*Throw); ok {
							iter.done = true
							if st.Await {
								in.asyncIteratorCloseSwallow(iter)
							} else {
								iteratorCloseSwallow(iter)
							}
							// mark closed so outer recover does not close again
							iter.closed = true
						}
						panic(r)
					}
				}()
				bind(v)
				c = in.execStmt(st.Body)
			}()
			in.scope = saved
			if c.t != cNormal {
				cont, r := loopBodyResult(c, label)
				if !cont {
					if st.Await {
						in.asyncIteratorClose(iter)
					} else {
						iteratorClose(iter)
					}
					result = r
					return
				}
			}
		}
	}()
	return result
}

func (in *Interp) execTry(st *TryStmt) completion {
	var result completion
	var thrown *Throw
	var pending interface{} // non-Throw panic to re-raise after finally
	func() {
		defer func() {
			if r := recover(); r != nil {
				if t, ok := r.(*Throw); ok {
					thrown = t
				} else {
					pending = r
				}
			}
		}()
		result = in.execBlock(st.Block)
	}()
	if thrown != nil && st.Handler != nil {
		t := thrown
		thrown = nil
		func() {
			defer func() {
				if r := recover(); r != nil {
					if t2, ok := r.(*Throw); ok {
						thrown = t2
					} else {
						pending = r
					}
				}
			}()
			saved := in.scope
			sc := newScope(in.scope, nil)
			in.scope = sc
			if st.Param != nil {
				collectBoundNamesNode(st.Param, func(n string, _ int) {
					sc.declare(n, Undefined, bTDZ)
				})
				in.bindPattern(st.Param, t.Val, true)
			}
			result = in.execBlock(st.Handler)
			in.scope = saved
		}()
	}
	if st.Finalizer != nil {
		fc := in.execBlock(st.Finalizer)
		if fc.t != cNormal {
			return fc
		}
	}
	if pending != nil {
		panic(pending)
	}
	if thrown != nil {
		panic(thrown)
	}
	return result
}

func (in *Interp) execSwitch(st *SwitchStmt, label string) completion {
	disc := in.evalExpr(st.Disc)
	saved := in.pushBlockScope(st.Lex, st.FuncDecls)
	defer func() {
		if saved != nil {
			in.scope = saved
		}
	}()
	matched := -1
	for i, c := range st.Cases {
		if c.Test == nil {
			continue
		}
		v := in.evalExpr(c.Test)
		if strictEquals(disc, v) {
			matched = i
			break
		}
	}
	if matched < 0 {
		for i, c := range st.Cases {
			if c.Test == nil {
				matched = i
				break
			}
		}
	}
	if matched < 0 {
		return normalCompletion
	}
	for i := matched; i < len(st.Cases); i++ {
		c := in.execStatements(st.Cases[i].Body)
		if c.t != cNormal {
			if c.t == cBreak && (c.label == "" || c.label == label) {
				return normalCompletion
			}
			return c
		}
	}
	return normalCompletion
}
EOF
echo ok"}

