func (in *Interp) evalExpr(n Node) Value {
	switch e := n.(type) {
	case *NumberLit:
		return e.Val
	case *StringLit:
		return e.Val
	case *BoolLit:
		return e.Val
	case *NullLit:
		return Null
	case *BigIntLit:
		return e.Val
	case *Ident:
		return in.getVar(e.Name, e.P)
	case *ThisExpr:
		return in.getThis(e.P)
	case *TemplateLit:
		return in.evalTemplate(e)
	case *BinaryExpr:
		return in.evalBinary(e)
	case *LogicalExpr:
		l := in.evalExpr(e.L)
		switch e.Op {
		case "&&":
			if !toBoolean(l) {
				return l
			}
		case "||":
			if toBoolean(l) {
				return l
			}
		case "??":
			if !isNullish(l) {
				return l
			}
		}
		return in.evalExpr(e.R)
	case *UnaryExpr:
		return in.evalUnary(e)
	case *UpdateExpr:
		return in.evalUpdate(e)
	case *AssignExpr:
		return in.evalAssign(e)
	case *CondExpr:
		if toBoolean(in.evalExpr(e.Test)) {
			return in.evalExpr(e.Cons)
		}
		return in.evalExpr(e.Alt)
	case *SeqExpr:
		var v Value = Undefined
		for _, x := range e.Exprs {
			v = in.evalExpr(x)
		}
		return v
	case *MemberExpr:
		obj := in.evalExpr(e.Obj)
		if e.Optional && isNullish(obj) {
			panic(optionalShortCircuit{})
		}
		return in.getMember(obj, e)
	case *PrivateMemberExpr:
		obj := in.evalExpr(e.Obj)
		if e.Optional && isNullish(obj) {
			panic(optionalShortCircuit{})
		}
		in.frame.pos = e.P
		return in.privateGet(obj, e.Name)
	case *OptionalChain:
		return in.evalOptionalChain(e)
	case *CallExpr:
		return in.evalCall(e)
	case *NewExpr:
		return in.evalNew(e)
	case *ArrayLit:
		return in.evalArrayLit(e)
	case *ObjectLit:
		return in.evalObjectLit(e)
	case *FuncNode:
		return in.evalFuncExpr(e)
	case *ClassNode:
		return in.evalClass(e)
	case *ParenExpr:
		return in.evalExpr(e.X)
	case *RegExpLit:
		in.frame.pos = e.P
		return newRegExpObject(e.Pattern, e.Flags)
	case *TaggedTemplate:
		return in.evalTaggedTemplate(e)
	case *Spread:
		throwSyntaxError("unexpected spread")
	case *YieldExpr:
		return in.evalYield(e)
	case *AwaitExpr:
		v := in.evalExpr(e.Arg)
		in.frame.pos = e.P
		return in.await(v)
	case *NewTargetExpr:
		if in.act == nil {
			return Undefined
		}
		return in.act.newTarget
	case *ImportMetaExpr:
		return in.importMeta()
	case *ImportCall:
		spec := in.evalExpr(e.Src)
		if e.Opts != nil {
			in.evalExpr(e.Opts)
		}
		in.frame.pos = e.P
		return in.dynamicImport(spec)
	case *SuperExpr:
		throwSyntaxError("unexpected 'super'")
	case *PrivateInExpr:
		r := in.evalExpr(e.R)
		ro, ok := r.(*Object)
		if !ok {
			in.frame.pos = e.P
			throwTypeError("invalid 'in' operand")
		}
		pn := in.resolvePrivateName(e.Name)
		return privateHas(ro, pn)
	case *CoverInit:
		throwSyntaxError("invalid property name")
	}
	throwInternalError("unknown expression type %T", n)
	return nil
}

type optionalShortCircuit struct{}

func (in *Interp) evalOptionalChain(e *OptionalChain) (result Value) {
	defer func() {
		if r := recover(); r != nil {
			if _, ok := r.(optionalShortCircuit); ok {
				result = Undefined
				return
			}
			panic(r)
		}
	}()
	return in.evalExpr(e.X)
}

func (in *Interp) getThis(pos int) Value {
	act := in.act
	if act == nil {
		if in.module != nil {
			return Undefined
		}
		return rt.Global
	}
	if !act.thisInit {
		in.frame.pos = pos
		throwReferenceError("this is not initialized")
	}
	return act.this
}

func (in *Interp) evalTemplate(e *TemplateLit) Value {
	sb := NewStringBuilder()
	for i, q := range e.Cooked {
		sb.WriteString(q)
		if i < len(e.Exprs) {
			v := in.evalExpr(e.Exprs[i])
			if _, isSym := v.(*Symbol); isSym {
				in.frame.pos = e.Exprs[i].Pos()
				throwTypeError("cannot convert symbol to string")
			}
			sb.WriteString(toString(v))
		}
	}
	return sb.String()
}

func (in *Interp) evalTaggedTemplate(e *TaggedTemplate) Value {
	var this Value = Undefined
	var fn Value
	switch c := e.Tag.(type) {
	case *MemberExpr:
		obj := in.evalExpr(c.Obj)
		this = obj
		fn = in.getMember(obj, c)
	default:
		fn = in.evalExpr(e.Tag)
	}
	// template object (cached per site)
	tobj := e.cache
	if tobj == nil {
		cooked := make([]Value, len(e.Quasi.Cooked))
		raws := make([]Value, len(e.Quasi.Raws))
		for i, c := range e.Quasi.Cooked {
			if c == nil {
				cooked[i] = Undefined
			} else {
				cooked[i] = c
			}
			raws[i] = e.Quasi.Raws[i]
		}
		rawArr := newArrayObject(raws)
		freezeObject(rawArr)
		tobj = newArrayObject(cooked)
		tobj.setOwn("raw", rawArr, 0)
		freezeObject(tobj)
		e.cache = tobj
	}
	args := make([]Value, 0, len(e.Quasi.Exprs)+1)
	args = append(args, tobj)
	for _, x := range e.Quasi.Exprs {
		args = append(args, in.evalExpr(x))
	}
	in.frame.pos = e.P
	if !isCallable(fn) {
		throwTypeError("not a function")
	}
	return callFunction(fn.(*Object), this, args)
}

func freezeObject(o *Object) {
	if o.class == ClassArray && !ad_sparse(o) {
		o.frozenHint = true
		o.arrayData().lengthWritable = false
	}
	for _, k := range o.OwnKeys() {
		p := o.GetOwnProperty(k)
		if p == nil {
			continue
		}
		d := PropDesc{Configurable: false, HasConfigurable: true}
		if !p.IsAccessor() {
			d.Writable = false
			d.HasWritable = true
		}
		o.DefineOwnProperty(k, d)
	}
	o.PreventExtensions()
}

// ---------- member access ----------

func (in *Interp) memberKey(e *MemberExpr) PropKey {
	if !e.Computed {
		return PropKey{S: e.Name}
	}
	kv := in.evalExpr(e.Prop)
	return toPropertyKey(kv)
}

func (in *Interp) getMember(obj Value, e *MemberExpr) Value {
	if _, ok := e.Obj.(*SuperExpr); ok {
		return in.superGet(e)
	}
	if !e.Computed {
		k := PropKey{S: e.Name}
		switch o := obj.(type) {
		case *Object:
			return o.Get(k, o)
		case undefinedType:
			in.frame.pos = e.P
			throwTypeError("cannot read property '%s' of undefined", e.Name)
		case nullType:
			in.frame.pos = e.P
			throwTypeError("cannot read property '%s' of null", e.Name)
		}
		return getV(obj, k)
	}
	kv := in.evalExpr(e.Prop)
	// fast path: array index
	if o, ok := obj.(*Object); ok {
		if f, ok := kv.(float64); ok && o.class == ClassArray && !ad_sparse(o) {
			if f >= 0 && f < float64(len(o.arr)) && f == math.Trunc(f) {
				v := o.arr[int(f)]
				if v != hole {
					return v
				}
			}
		}
		if o.class == ClassTypedArray {
			if f, ok := kv.(float64); ok {
				if v := typedArrayGetIndex(o, f); v != nil {
					return v
				}
				if f == math.Trunc(f) {
					return Undefined
				}
			}
		}
		k := toPropertyKey(kv)
		return o.Get(k, o)
	}
	if isNullish(obj) {
		in.frame.pos = e.P
		k := toPropertyKey(kv)
		if isUndefined(obj) {
			throwTypeError("cannot read property '%s' of undefined", keyToDisplay(k))
		}
		throwTypeError("cannot read property '%s' of null", keyToDisplay(k))
	}
	if s, ok := obj.(*String); ok {
		if f, ok := kv.(float64); ok && f >= 0 && f < float64(s.Len()) && f == math.Trunc(f) {
			return s.Substring(int(f), int(f)+1)
		}
	}
	return getV(obj, toPropertyKey(kv))
}

func (in *Interp) setMember(obj Value, k PropKey, v Value, pos int) {
	switch o := obj.(type) {
	case *Object:
		if !o.Set(k, v, o) {
			if in.strict {
				in.frame.pos = pos
				throwTypeError("'%s' is read-only", keyToDisplay(k))
			}
		}
	case undefinedType:
		in.frame.pos = pos
		throwTypeError("cannot set property '%s' of undefined", keyToDisplay(k))
	case nullType:
		in.frame.pos = pos
		throwTypeError("cannot set property '%s' of null", keyToDisplay(k))
	default:
		// primitive: set via prototype (setters) with receiver = primitive
		proto := toObject(obj).proto
		ok := proto.Set(k, v, obj)
		if !ok && in.strict {
			in.frame.pos = pos
			throwTypeError("'%s' is read-only", keyToDisplay(k))
		}
	}
}

func (in *Interp) superGet(e *MemberExpr) Value {
	home := in.act.homeObject
	if home == nil {
		in.frame.pos = e.P
		throwSyntaxError("'super' is only valid in a method")
	}
	k := in.memberKey(e)
	this := in.getThis(e.P)
	proto := home.GetPrototypeOf()
	if proto == nil {
		in.frame.pos = e.P
		throwTypeError("cannot read property '%s' of null", keyToDisplay(k))
	}
	return proto.Get(k, this)
}

func (in *Interp) superSet(e *MemberExpr, v Value) {
	home := in.act.homeObject
	if home == nil {
		throwSyntaxError("'super' is only valid in a method")
	}
	k := in.memberKey(e)
	this := in.getThis(e.P)
	proto := home.GetPrototypeOf()
	if proto == nil {
		throwTypeError("cannot set property of null")
	}
	if !proto.Set(k, v, this) && in.strict {
		throwTypeError("'%s' is read-only", keyToDisplay(k))
	}
}

// ---------- calls ----------

func (in *Interp) evalArgs(args []Node) []Value {
	if len(args) == 0 {
		return nil
	}
	out := make([]Value, 0, len(args))
	for _, a := range args {
		if sp, ok := a.(*Spread); ok {
			v := in.evalExpr(sp.Arg)
			iterateToSlice(v, func(x Value) { out = append(out, x) })
			continue
		}
		out = append(out, in.evalExpr(a))
	}
	return out
}

func (in *Interp) evalCall(e *CallExpr) Value {
	var this Value = Undefined
	var fn Value
	switch c := e.Callee.(type) {
	case *SuperExpr:
		return in.evalSuperCall(e)
	case *MemberExpr:
		if _, isSuper := c.Obj.(*SuperExpr); isSuper {
			this = in.getThis(c.P)
			fn = in.superGet(c)
		} else {
			obj := in.evalExpr(c.Obj)
			if c.Optional && isNullish(obj) {
				panic(optionalShortCircuit{})
			}
			this = obj
			fn = in.getMember(obj, c)
		}
	case *PrivateMemberExpr:
		obj := in.evalExpr(c.Obj)
		if c.Optional && isNullish(obj) {
			panic(optionalShortCircuit{})
		}
		this = obj
		in.frame.pos = c.P
		fn = in.privateGet(obj, c.Name)
	case *Ident:
		if e.IsDirectEval {
			fn = in.getVar(c.Name, c.P)
			if fo, ok := fn.(*Object); ok && fo == rt.evalFunction {
				args := in.evalArgs(e.Args)
				in.frame.pos = e.P
				return in.directEval(args)
			}
		} else {
			// with-object this binding
			sc, idx := lookupBinding(in.scope, c.Name)
			if sc != nil && idx == -2 {
				this = sc.withObj
				fn = sc.withObj.Get(strKey(c.Name), sc.withObj)
			} else {
				fn = in.getVar(c.Name, c.P)
			}
		}
	case *ParenExpr:
		// (a.b)() keeps this
		if m, ok := c.X.(*MemberExpr); ok {
			obj := in.evalExpr(m.Obj)
			this = obj
			fn = in.getMember(obj, m)
		} else {
			fn = in.evalExpr(c.X)
		}
	default:
		fn = in.evalExpr(e.Callee)
	}
	if e.Optional && isNullish(fn) {
		panic(optionalShortCircuit{})
	}
	args := in.evalArgs(e.Args)
	in.frame.pos = e.P
	fo, ok := fn.(*Object)
	if !ok || !fo.callable {
		throwTypeError("%s", notFunctionMsg(e.Callee, fn))
	}
	return callFunction(fo, this, args)
}

func notFunctionMsg(callee Node, v Value) string {
	return "not a function"
}

func (in *Interp) evalNew(e *NewExpr) Value {
	ctor := in.evalExpr(e.Callee)
	args := in.evalArgs(e.Args)
	in.frame.pos = e.P
	co, ok := ctor.(*Object)
	if !ok || !co.ctor {
		throwTypeError("not a constructor")
	}
	return construct(co, args, co)
}

func (in *Interp) evalSuperCall(e *CallExpr) Value {
	act := in.act
	if act == nil || act.fn == nil {
		throwSyntaxError("'super' is only valid in a derived class constructor")
	}
	// find the constructor function's activation (arrows share act)
	fnObj := act.fnObj
	parent := fnObj.GetPrototypeOf()
	args := in.evalArgs(e.Args)
	in.frame.pos = e.P
	if parent == nil || !parent.ctor {
		throwTypeError("not a constructor")
	}
	if act.thisInit {
		throwReferenceError("super() already called")
	}
	nt, _ := act.newTarget.(*Object)
	result := construct(parent, args, nt)
	ro, _ := result.(*Object)
	if act.thisInit {
		throwReferenceError("super() already called")
	}
	act.this = ro
	act.thisInit = true
	// initialize fields
	in.initializeInstanceElements(ro, fnObj)
	return result
}

// ---------- unary / binary ----------

func (in *Interp) evalUnary(e *UnaryExpr) Value {
	switch e.Op {
	case "typeof":
		if id, ok := e.X.(*Ident); ok {
			v, _ := in.getVarOrUndefined(id.Name, id.P)
			return NewStringFromGo(typeOf(v))
		}
		return NewStringFromGo(typeOf(in.evalExpr(e.X)))
	case "delete":
		return in.evalDelete(e)
	case "void":
		in.evalExpr(e.X)
		return Undefined
	case "!":
		return !toBoolean(in.evalExpr(e.X))
	case "-":
		v := in.evalExpr(e.X)
		if f, ok := v.(float64); ok {
			return -f
		}
		n := toNumeric(v)
		if b, ok := n.(*big.Int); ok {
			return new(big.Int).Neg(b)
		}
		return -n.(float64)
	case "+":
		v := in.evalExpr(e.X)
		if f, ok := v.(float64); ok {
			return f
		}
		in.frame.pos = e.P
		return toNumber(v)
	case "~":
		v := in.evalExpr(e.X)
		n := toNumeric(v)
		if b, ok := n.(*big.Int); ok {
			return new(big.Int).Not(b)
		}
		return float64(^toInt32(n.(float64)))
	}
	throwInternalError("bad unary op")
	return nil
}

func (in *Interp) evalDelete(e *UnaryExpr) Value {
	switch t := e.X.(type) {
	case *MemberExpr:
		if _, isSuper := t.Obj.(*SuperExpr); isSuper {
			in.getThis(t.P)
			throwReferenceError("unsupported reference to 'super'")
		}
		obj := in.evalExpr(t.Obj)
		k := in.memberKey(t)
		in.frame.pos = e.P
		o := toObject(obj)
		ok := o.Delete(k)
		if !ok && in.strict {
			throwTypeError("could not delete property '%s'", keyToDisplay(k))
		}
		return ok
	case *OptionalChain:
		var res Value = true
		func() {
			defer func() {
				if r := recover(); r != nil {
					if _, ok := r.(optionalShortCircuit); ok {
						res = true
						return
					}
					panic(r)
				}
			}()
			if m, ok := t.X.(*MemberExpr); ok {
				obj := in.evalExpr(m.Obj)
				if m.Optional && isNullish(obj) {
					res = true
					return
				}
				k := in.memberKey(m)
				o := toObject(obj)
				ok := o.Delete(k)
				if !ok && in.strict {
					throwTypeError("could not delete property '%s'", keyToDisplay(k))
				}
				res = ok
				return
			}
			in.evalExpr(t.X)
			res = true
		}()
		return res
	case *Ident:
		sc, idx := lookupBinding(in.scope, t.Name)
		if sc != nil {
			if idx == -2 {
				return sc.withObj.Delete(strKey(t.Name))
			}
			return false
		}
		if rt.GlobalLex.find(t.Name) >= 0 {
			return false
		}
		return rt.Global.Delete(strKey(t.Name))
	case *ParenExpr:
		return in.evalDelete(&UnaryExpr{NodeBase: e.NodeBase, Op: "delete", X: t.X})
	default:
		in.evalExpr(e.X)
		return true
	}
}

func (in *Interp) evalBinary(e *BinaryExpr) Value {
	l := in.evalExpr(e.L)
	r := in.evalExpr(e.R)
	in.frame.pos = e.P
	return binaryOp(e.Op, l, r)
}

func binaryOp(op string, l, r Value) Value {
	switch op {
	case "+":
		return jsAdd(l, r)
	case "-", "*", "/", "%", "**", "&", "|", "^", "<<", ">>", ">>>":
		return jsArith(op, l, r)
	case "==":
		return looseEquals(l, r)
	case "!=":
		return !looseEquals(l, r)
	case "===":
		return strictEquals(l, r)
	case "!==":
		return !strictEquals(l, r)
	case "<":
		if a, ok := l.(float64); ok {
			if b, ok := r.(float64); ok {
				return a < b
			}
		}
		res, undef := jsLess(l, r, true)
		return res && !undef
	case ">":
		if a, ok := l.(float64); ok {
			if b, ok := r.(float64); ok {
				return a > b
			}
		}
		res, undef := jsLess(r, l, false)
		return res && !undef
	case "<=":
		if a, ok := l.(float64); ok {
			if b, ok := r.(float64); ok {
				return a <= b
			}
		}
		res, undef := jsLess(r, l, false)
		return !res && !undef
	case ">=":
		if a, ok := l.(float64); ok {
			if b, ok := r.(float64); ok {
				return a >= b
			}
		}
		res, undef := jsLess(l, r, true)
		return !res && !undef
	case "instanceof":
		return jsInstanceOf(l, r)
	case "in":
		return jsIn(l, r)
	}
	throwInternalError("bad binary op %s", op)
	return nil
}

// ---------- assignment ----------

func (in *Interp) evalAssign(e *AssignExpr) Value {
	if e.Op == "=" {
		switch t := e.Target.(type) {
		case *Ident:
			v := in.evalExpr(e.Value)
			in.setVar(t.Name, v, e.P)
			return v
		case *MemberExpr:
			if _, isSuper := t.Obj.(*SuperExpr); isSuper {
				v := in.evalExpr(e.Value)
				in.superSet(t, v)
				return v
			}
			obj := in.evalExpr(t.Obj)
			var k PropKey
			var kv Value
			if t.Computed {
				kv = in.evalExpr(t.Prop)
			} else {
				k = PropKey{S: t.Name}
			}
			v := in.evalExpr(e.Value)
			if t.Computed {
				// fast path array index store
				if o, ok := obj.(*Object); ok {
					if f, ok := kv.(float64); ok && o.class == ClassArray && !ad_sparse(o) && !o.frozenHint {
						if f >= 0 && f < float64(len(o.arr)) && f == math.Trunc(f) {
							if o.arr[int(f)] != hole {
								o.arr[int(f)] = v
								return v
							}
						} else if f == float64(len(o.arr)) && o.extensible && o.arrayData().lengthWritable && !o.sealedHint {
							o.arr = append(o.arr, v)
							return v
						}
					}
					if o.class == ClassTypedArray {
						if f, ok := kv.(float64); ok {
							typedArraySetIndex(o, f, v)
							return v
						}
					}
				}
				if isNullish(obj) {
					in.frame.pos = t.P
					if isUndefined(obj) {
						throwTypeError("cannot set property '%s' of undefined", keyToDisplay(toPropertyKey(kv)))
					}
					throwTypeError("cannot set property '%s' of null", keyToDisplay(toPropertyKey(kv)))
				}
				k = toPropertyKey(kv)
			}
			in.setMember(obj, k, v, t.P)
			return v
		case *PrivateMemberExpr:
			obj := in.evalExpr(t.Obj)
			v := in.evalExpr(e.Value)
			in.frame.pos = t.P
			in.privateSet(obj, t.Name, v)
			return v
		default:
			v := in.evalExpr(e.Value)
			in.assignToTarget(e.Target, v)
			return v
		}
	}
	// compound / logical assignment
	switch t := e.Target.(type) {
	case *Ident:
		cur := in.getVar(t.Name, t.P)
		var v Value
		switch e.Op {
		case "&&=":
			if !toBoolean(cur) {
				return cur
			}
			v = in.evalExpr(e.Value)
		case "||=":
			if toBoolean(cur) {
				return cur
			}
			v = in.evalExpr(e.Value)
		case "??=":
			if !isNullish(cur) {
				return cur
			}
			v = in.evalExpr(e.Value)
		default:
			r := in.evalExpr(e.Value)
			in.frame.pos = e.P
			v = binaryOp(e.Op[:len(e.Op)-1], cur, r)
		}
		in.setVar(t.Name, v, e.P)
		return v
	case *MemberExpr:
		if _, isSuper := t.Obj.(*SuperExpr); isSuper {
			cur := in.superGet(t)
			v := in.compoundValue(e, cur)
			if v == nil {
				return cur
			}
			in.superSet(t, v)
			return v
		}
		obj := in.evalExpr(t.Obj)
		k := in.memberKey(t)
		in.frame.pos = t.P
		cur := getV(obj, k)
		v := in.compoundValue(e, cur)
		if v == nil {
			return cur
		}
		in.setMember(obj, k, v, t.P)
		return v
	case *PrivateMemberExpr:
		obj := in.evalExpr(t.Obj)
		in.frame.pos = t.P
		cur := in.privateGet(obj, t.Name)
		v := in.compoundValue(e, cur)
		if v == nil {
			return cur
		}
		in.privateSet(obj, t.Name, v)
		return v
	}
	throwSyntaxError("invalid assignment target")
	return nil
}

// compoundValue computes the new value for compound assignment; returns nil for short-circuit
func (in *Interp) compoundValue(e *AssignExpr, cur Value) Value {
	switch e.Op {
	case "&&=":
		if !toBoolean(cur) {
			return nil
		}
		return in.evalExpr(e.Value)
	case "||=":
		if toBoolean(cur) {
			return nil
		}
		return in.evalExpr(e.Value)
	case "??=":
		if !isNullish(cur) {
			return nil
		}
		return in.evalExpr(e.Value)
	}
	r := in.evalExpr(e.Value)
	in.frame.pos = e.P
	return binaryOp(e.Op[:len(e.Op)-1], cur, r)
}

func (in *Interp) evalUpdate(e *UpdateExpr) Value {
	var cur Value
	var set func(Value)
	switch t := e.X.(type) {
	case *Ident:
		cur = in.getVar(t.Name, t.P)
		set = func(v Value) { in.setVar(t.Name, v, e.P) }
	case *MemberExpr:
		if _, isSuper := t.Obj.(*SuperExpr); isSuper {
			cur = in.superGet(t)
			set = func(v Value) { in.superSet(t, v) }
		} else {
			obj := in.evalExpr(t.Obj)
			k := in.memberKey(t)
			in.frame.pos = t.P
			cur = getV(obj, k)
			set = func(v Value) { in.setMember(obj, k, v, t.P) }
		}
	case *PrivateMemberExpr:
		obj := in.evalExpr(t.Obj)
		in.frame.pos = t.P
		cur = in.privateGet(obj, t.Name)
		set = func(v Value) { in.privateSet(obj, t.Name, v) }
	default:
		throwSyntaxError("invalid increment/decrement operand")
	}
	var old Value
	var nv Value
	if f, ok := cur.(float64); ok {
		old = f
		if e.Op == "++" {
			nv = f + 1
		} else {
			nv = f - 1
		}
	} else {
		in.frame.pos = e.P
		n := toNumeric(cur)
		old = n
		if b, ok := n.(*big.Int); ok {
			if e.Op == "++" {
				nv = new(big.Int).Add(b, big.NewInt(1))
			} else {
				nv = new(big.Int).Sub(b, big.NewInt(1))
			}
		} else {
			f := n.(float64)
			if e.Op == "++" {
				nv = f + 1
			} else {
				nv = f - 1
			}
		}
	}
	set(nv)
	if e.Prefix {
		return nv
	}
	return old
}

// assignToTarget assigns to an expression target or pattern (assignment context, not declaration)
func (in *Interp) assignToTarget(target Node, v Value) {
	switch t := target.(type) {
	case *Ident:
		in.setVar(t.Name, v, t.P)
	case *MemberExpr:
		if _, isSuper := t.Obj.(*SuperExpr); isSuper {
			in.superSet(t, v)
			return
		}
		obj := in.evalExpr(t.Obj)
		k := in.memberKey(t)
		in.setMember(obj, k, v, t.P)
	case *PrivateMemberExpr:
		obj := in.evalExpr(t.Obj)
		in.frame.pos = t.P
		in.privateSet(obj, t.Name, v)
	case *ParenExpr:
		in.assignToTarget(t.X, v)
	case *ObjectPattern, *ArrayPattern, *AssignPattern:
		in.bindPattern(target, v, false)
	default:
		throwSyntaxError("invalid assignment target")
	}
}

// bindPattern binds a destructuring pattern. If decl is true, identifiers are initialized (lexical/param), else assigned.
func (in *Interp) bindPattern(pat Node, v Value, decl bool) {
	switch p := pat.(type) {
	case *Ident:
		if decl {
			in.initBinding(p.Name, v)
		} else {
			in.setVar(p.Name, v, p.P)
		}
	case *AssignPattern:
		if isUndefined(v) {
			v = in.evalExpr(p.Default)
		}
		in.bindPattern(p.Target, v, decl)
	case *ObjectPattern:
		if isNullish(v) {
			in.frame.pos = p.P
			throwTypeError("cannot destructure '%s'", toGoString(v))
		}
		obj := toObject(v)
		var used []PropKey
		for _, pp := range p.Props {
			var k PropKey
			if pp.Computed {
				k = toPropertyKey(in.evalExpr(pp.Key))
			} else {
				k = PropKey{S: pp.KeyName}
			}
			used = append(used, k)
			var val Value
			if _, isObj := v.(*Object); isObj {
				val = obj.Get(k, obj)
			} else {
				val = getV(v, k)
			}
			in.bindPattern(pp.Target, val, decl)
		}
		if p.Rest != nil {
			rest := newObjectRaw(rt.ObjectPrototype, ClassObject)
			for _, k := range obj.OwnKeys() {
				skip := false
				for _, u := range used {
					if u == k {
						skip = true
						break
					}
				}
				if skip {
					continue
				}
				pr := obj.GetOwnProperty(k)
				if pr == nil || !pr.Enumerable() {
					continue
				}
				rest.CreateDataProperty(k, obj.Get(k, obj))
			}
			in.bindPattern(p.Rest, rest, decl)
		}
	case *ArrayPattern:
		in.frame.pos = p.P
		iter := getIterator(v)
		func() {
			defer func() {
				if r := recover(); r != nil {
					if _, ok := r.(*Throw); ok && !iter.done {
						iteratorCloseSwallow(iter)
					}
					panic(r)
				}
			}()
			for _, el := range p.Elems {
				if el == nil {
					iter.step()
					continue
				}
				if r, ok := el.(*RestElement); ok {
					var rest []Value
					for {
						x, ok := iter.step()
						if !ok {
							break
						}
						rest = append(rest, x)
					}
					in.bindPattern(r.Target, newArrayObject(rest), decl)
					break
				}
				var val Value = Undefined
				if !iter.done {
					x, ok := iter.step()
					if ok {
						val = x
					}
				}
				in.bindPattern(el, val, decl)
			}
		}()
		if !iter.done {
			iteratorClose(iter)
		}
	case *MemberExpr, *PrivateMemberExpr, *ParenExpr:
		in.assignToTarget(pat, v)
	case *RestElement:
		in.bindPattern(p.Target, v, decl)
	default:
		throwSyntaxError("invalid destructuring target")
	}
}

// ---------- literals ----------

func (in *Interp) evalArrayLit(e *ArrayLit) Value {
	elems := make([]Value, 0, len(e.Elems))
	for _, el := range e.Elems {
		if el == nil {
			elems = append(elems, hole)
			continue
		}
		if sp, ok := el.(*Spread); ok {
			v := in.evalExpr(sp.Arg)
			in.frame.pos = sp.P
			iterateToSlice(v, func(x Value) { elems = append(elems, x) })
			continue
		}
		elems = append(elems, in.evalExpr(el))
	}
	return newArrayObject(elems)
}

func (in *Interp) evalObjectLit(e *ObjectLit) Value {
	obj := newObjectRaw(rt.ObjectPrototype, ClassObject)
	for _, pr := range e.Props {
		switch pr.Kind {
		case PropSpread:
			src := in.evalExpr(pr.Value)
			copyDataProperties(obj, src, nil)
			continue
		}
		var k PropKey
		if pr.Computed {
			k = toPropertyKey(in.evalExpr(pr.Key))
		} else {
			k = PropKey{S: pr.KeyName}
		}
		switch pr.Kind {
		case PropInit, PropShorthand:
			if pr.IsProto {
				v := in.evalExpr(pr.Value)
				if po, ok := v.(*Object); ok {
					obj.proto = po
				} else if isNull(v) {
					obj.proto = nil
				}
				continue
			}
			var v Value
			if fnode, ok := pr.Value.(*FuncNode); ok && fnode.IsExpr && !fnode.HasOwnName && pr.Computed && fnode.Name == "" {
				fo := in.evalFuncExpr(fnode)
				setFunctionName(fo, k, "")
				v = fo
			} else if cn, ok := pr.Value.(*ClassNode); ok && !cn.HasName && pr.Computed {
				co := in.evalClassNamed(cn, k)
				v = co
			} else {
				v = in.evalExpr(pr.Value)
			}
			obj.props.Set(k, Prop{Value: v, Flags: PropDefault})
			// handle index keys for ordering: props map handles ordering at OwnKeys time
		case PropMethod:
			fnode := pr.Value.(*FuncNode)
			fo := makeFunctionObject(fnode, in.scope, in.act, in.src, in.module, obj)
			if pr.Computed {
				setFunctionName(fo, k, "")
			}
			obj.props.Set(k, Prop{Value: fo, Flags: PropDefault})
		case PropGet, PropSet:
			fnode := pr.Value.(*FuncNode)
			fo := makeFunctionObject(fnode, in.scope, in.act, in.src, in.module, obj)
			if pr.Computed {
				if pr.Kind == PropGet {
					setFunctionName(fo, k, "get")
				} else {
					setFunctionName(fo, k, "set")
				}
			}
			existing := obj.props.Get(k)
			var g, s Value = Undefined, Undefined
			if existing != nil && existing.IsAccessor() {
				g, s = existing.Getter, existing.Setter
			}
			if pr.Kind == PropGet {
				g = fo
			} else {
				s = fo
			}
			obj.props.Set(k, Prop{Getter: g, Setter: s, Flags: PropAccessor | PropEnumerable | PropConfigurable})
		}
	}
	return obj
}

func setFunctionName(fo *Object, k PropKey, prefix string) {
	var name string
	if k.Sym != nil {
		if k.Sym.hasDesc {
			name = "[" + k.Sym.desc.String() + "]"
		} else {
			name = ""
		}
	} else {
		name = k.S
	}
	if prefix != "" {
		name = prefix + " " + name
	}
	fo.setOwn("name", NewStringFromGo(name), PropConfigurable)
	if fn, ok := fo.internal.(*Function); ok {
		fn.name = name
	}
}

func copyDataProperties(target *Object, src Value, excluded []PropKey) {
	if isNullish(src) {
		return
	}
	from := toObject(src)
	for _, k := range from.OwnKeys() {
		skip := false
		for _, ex := range excluded {
			if ex == k {
				skip = true
				break
			}
		}
		if skip {
			continue
		}
		p := from.GetOwnProperty(k)
		if p == nil || !p.Enumerable() {
			continue
		}
		target.CreateDataProperty(k, from.Get(k, from))
	}
}

func (in *Interp) evalFuncExpr(e *FuncNode) Value {
	return in.makeFunction(e)
}

// ---------- iteration ----------

type Iterator struct {
	obj    *Object
	next   Value
	done   bool
	closed bool
	// fast array path
	fastArr *Object
	idx     int
	isAsync bool
}

func getIterator(v Value) *Iterator {
	if o, ok := v.(*Object); ok && o.class == ClassArray && !ad_sparse(o) {
		if m := o.Get(symKey(SymIterator), o); m == rt.ArrayProtoValues && rt.arrayIterNextIntact() {
			return &Iterator{fastArr: o}
		}
	}
	m := getMethod(v, symKey(SymIterator))
	if m == nil {
		throwTypeError("%s is not iterable", describeForError(v))
	}
	return getIteratorFromMethod(v, m)
}

func describeForError(v Value) string {
	switch x := v.(type) {
	case undefinedType:
		return "undefined"
	case nullType:
		return "null"
	case *Object:
		if x.callable {
			return "function"
		}
		return "object"
	case *String:
		return "string"
	case float64:
		return "number"
	case bool:
		return "boolean"
	case *Symbol:
		return "symbol"
	case *big.Int:
		return "bigint"
	}
	return "value"
}

func getIteratorFromMethod(v Value, m *Object) *Iterator {
	it := callFunction(m, v, nil)
	io, ok := it.(*Object)
	if !ok {
		throwTypeError("iterator is not an object")
	}
	next := io.Get(strKey("next"), io)
	return &Iterator{obj: io, next: next}
}

func getAsyncIterator(v Value) *Iterator {
	m := getMethod(v, symKey(SymAsyncIterator))
	if m == nil {
		sm := getMethod(v, symKey(SymIterator))
		if sm == nil {
			throwTypeError("%s is not async iterable", describeForError(v))
		}
		syncIter := getIteratorFromMethod(v, sm)
		return createAsyncFromSyncIterator(syncIter)
	}
	it := getIteratorFromMethod(v, m)
	it.isAsync = true
	return it
}

// nextRaw calls next and returns the raw result (for async)
func (it *Iterator) nextRaw(arg []Value) Value {
	if !isCallable(it.next) {
		throwTypeError("iterator next is not a function")
	}
	return callFunction(it.next.(*Object), it.obj, arg)
}

// step returns (value, ok); ok=false when done
func (it *Iterator) step() (Value, bool) {
	if it.fastArr != nil {
		arr := it.fastArr
		if it.idx >= len(arr.arr) || ad_sparse(arr) {
			if ad_sparse(arr) && uint32(it.idx) < arrayLength(arr) {
				v := arr.Get(idxKey(int64(it.idx)), arr)
				it.idx++
				return v, true
			}
			it.done = true
			return nil, false
		}
		v := arr.arr[it.idx]
		it.idx++
		if v == hole {
			v = Undefined
		}
		return v, true
	}
	if it.done {
		return nil, false
	}
	res := it.nextRaw(nil)
	ro, ok := res.(*Object)
	if !ok {
		it.done = true
		throwTypeError("iterator result is not an object")
	}
	if toBoolean(ro.Get(strKey("done"), ro)) {
		it.done = true
		return nil, false
	}
	return ro.Get(strKey("value"), ro), true
}

func iteratorClose(it *Iterator) {
	if it.fastArr != nil || it.closed {
		return
	}
	it.closed = true
	it.done = true
	ret := it.obj.Get(strKey("return"), it.obj)
	if isNullish(ret) {
		return
	}
	if !isCallable(ret) {
		throwTypeError("iterator return is not a function")
	}
	r := callFunction(ret.(*Object), it.obj, nil)
	if _, ok := r.(*Object); !ok {
		throwTypeError("iterator result is not an object")
	}
}

// iteratorCloseSwallow closes the iterator ignoring errors from return()
func iteratorCloseSwallow(it *Iterator) {
	if it.fastArr != nil || it.closed {
		return
	}
	it.closed = true
	it.done = true
	defer func() { recover() }()
	ret := it.obj.Get(strKey("return"), it.obj)
	if isNullish(ret) {
		return
	}
	if !isCallable(ret) {
		return
	}
	callFunction(ret.(*Object), it.obj, nil)
}

func (in *Interp) asyncIteratorClose(it *Iterator) {
	if it.closed {
		return
	}
	it.closed = true
	it.done = true
	ret := it.obj.Get(strKey("return"), it.obj)
	if isNullish(ret) {
		return
	}
	if !isCallable(ret) {
		throwTypeError("iterator return is not a function")
	}
	r := callFunction(ret.(*Object), it.obj, nil)
	r = in.await(r)
	if _, ok := r.(*Object); !ok {
		throwTypeError("iterator result is not an object")
	}
}

func (in *Interp) asyncIteratorCloseSwallow(it *Iterator) {
	if it.closed {
		return
	}
	it.closed = true
	it.done = true
	defer func() { recover() }()
	ret := it.obj.Get(strKey("return"), it.obj)
	if isNullish(ret) || !isCallable(ret) {
		return
	}
	r := callFunction(ret.(*Object), it.obj, nil)
	in.await(r)
}

func iterateToSlice(v Value, f func(Value)) {
	it := getIterator(v)
	for {
		x, ok := it.step()
		if !ok {
			break
		}
		f(x)
	}
}

func iterableToList(v Value) []Value {
	var out []Value
	iterateToSlice(v, func(x Value) { out = append(out, x) })
	return out
}

func createIterResult(v Value, done bool) *Object {
	o := newObjectRaw(rt.ObjectPrototype, ClassObject)
	o.props.Set(strKey("value"), Prop{Value: v, Flags: PropDefault})
	o.props.Set(strKey("done"), Prop{Value: done, Flags: PropDefault})
	return o
}
EOF
echo ok"}

