	var classAct *Activation
	if in.act != nil {
		a := *in.act
		a.privEnv = pe
		classAct = &a
	} else {
		classAct = &Activation{this: Undefined, privEnv: pe, newTarget: Undefined, module: in.module, src: in.src, strict: true}
		if in.module == nil {
			classAct.this = rt.Global
			classAct.thisInit = true
		}
