	var ctorParent *Object = rt.FunctionPrototype
	if c.SuperClass != nil {
		sv := in.evalExpr(c.SuperClass)
		in.frame.pos = c.SuperClass.Pos()
		if isNull(sv) {
			protoParent = nil
		} else {
			so, ok := sv.(*Object)
			if !ok || !so.ctor {
				throwTypeError("parent class must be constructor")
			}
			pp := so.Get(strKey("prototype"), so)
			if ppo, ok := pp.(*Object); ok {
				protoParent = ppo
			} else if isNull(pp) {
				protoParent = nil
			} else {
				throwTypeError("parent prototype must be an object or null")
			}
			ctorParent = so
		}
	}
	proto := newObjectRaw(protoParent, ClassObject)
	// constructor
	ctorNode := c.Constructor
	if ctorNode == nil {
		ctorNode = defaultConstructorNode(c)
	}
	F := makeFunctionObject(ctorNode, in.scope, classAct, in.src, in.module, proto)
	F.proto = ctorParent
	fn := F.internal.(*Function)
	fn.isClassCtor = true
	fn.isDerived = c.SuperClass != nil
	fn.privEnv = pe
	fn.classSrc = c.Source
	F.ctor = true
	F.setOwn("prototype", proto, 0)
	proto.setOwn("constructor", F, PropHidden)
	className := c.Name
	if nameKey.Sym != nil || c.Name == "" {
		setFunctionName(F, nameKey, "")
		className = toGoString(F.Get(strKey("name"), F))
	} else {
		F.setOwn("name", NewStringFromGo(className), PropConfigurable)
		fn.name = className
	}
	if c.Name == "" && nameKey.S == "" && nameKey.Sym == nil {
		F.setOwn("name", emptyString, PropConfigurable)
	}
	// members
	var instanceFields []classFieldDef
	var staticElems []func()
	for _, m := range c.Members {
		if m.IsStaticBlock {
			blk := m.Block
			staticElems = append(staticElems, func() {
				bo := makeFunctionObject(blk, in.scope, classAct, in.src, in.module, F)
				bo.internal.(*Function).isStaticInit = true
				callFunction(bo, F, nil)
			})
			continue
		}
		target := proto
		if m.Static {
			target = F
		}
		var key PropKey
		var pn *PrivateName
		if m.IsPrivate {
			pn = pe.names[m.KeyName]
		} else if m.Computed {
			kv := in.evalExpr(m.Key)
			key = toPropertyKey(kv)
		} else {
			key = PropKey{S: m.KeyName}
		}
		switch m.Kind {
		case PropMethod, PropGet, PropSet:
			fnode := m.Value.(*FuncNode)
			fo := makeFunctionObject(fnode, in.scope, classAct, in.src, in.module, target)
			fo.internal.(*Function).privEnv = pe
			if m.IsPrivate {
				switch m.Kind {
				case PropMethod:
					pn.method = fo
					setFunctionName(fo, PropKey{S: "#" + m.KeyName}, "")
				case PropGet:
					pn.getter = fo
					setFunctionName(fo, PropKey{S: "#" + m.KeyName}, "get")
				case PropSet:
					pn.setter = fo
					setFunctionName(fo, PropKey{S: "#" + m.KeyName}, "set")
				}
				if m.Static {
					// install on F now
					if F.findPriv(pn) < 0 {
						F.privFields = append(F.privFields, privField{pn, Undefined})
					}
				} else {
					fn.privMethods = appendUniquePN(fn.privMethods, pn)
				}
				continue
			}
			if m.Computed {
				switch m.Kind {
				case PropGet:
					setFunctionName(fo, key, "get")
				case PropSet:
					setFunctionName(fo, key, "set")
				default:
					setFunctionName(fo, key, "")
				}
			}
			switch m.Kind {
			case PropMethod:
				target.DefineOwnProperty(key, dataDesc(fo, PropHidden))
			case PropGet, PropSet:
				existing := target.GetOwnProperty(key)
				var g, s Value = Undefined, Undefined
				if existing != nil && existing.IsAccessor() {
					g, s = existing.Getter, existing.Setter
				}
				if m.Kind == PropGet {
					g = fo
				} else {
					s = fo
				}
				target.props.Set(key, Prop{Getter: g, Setter: s, Flags: PropAccessor | PropConfigurable})
			}
		case PropInit:
			fd := classFieldDef{key: key, priv: pn, isStatic: m.Static}
			if m.FieldInit != nil && m.Value != nil {
				fo := makeFunctionObject(m.FieldInit, in.scope, classAct, in.src, in.module, target)
				fo.internal.(*Function).privEnv = pe
				fo.internal.(*Function).isFieldInit = true
				fd.initFn = fo
				// anonymous function/class field values get the field name
				if m.Computed {
					fd.isAnonFn = isAnonymousFunctionDef(m.Value)
				}
			}
			if m.Static {
				fdc := fd
				staticElems = append(staticElems, func() {
					defineField(F, fdc)
				})
			} else {
				instanceFields = append(instanceFields, fd)
			}
		}
	}
	fn.fields = instanceFields
	// initialize class name binding
	if bindName != "" && (c.HasName || !c.IsExpr) {
		if i := sc.find(bindName); i >= 0 {
			sc.vals[i] = F
			sc.flags[i] &^= bTDZ
		}
	}
	// static elements in order
	for _, se := range staticElems {
		se()
	}
	return F
}

func isAnonymousFunctionDef(n Node) bool {
	switch t := n.(type) {
	case *FuncNode:
		return !t.HasOwnName && (t.Name == "" || t.InferredName)
	case *ClassNode:
		return !t.HasName
	case *ParenExpr:
		return isAnonymousFunctionDef(t.X)
	}
	return false
}

func appendUniquePN(list []*PrivateName, pn *PrivateName) []*PrivateName {
	for _, x := range list {
		if x == pn {
			return list
		}
	}
	return append(list, pn)
}

func defineField(obj *Object, fd classFieldDef) {
	var v Value = Undefined
	if fd.initFn != nil {
		v = callFunction(fd.initFn, obj, nil)
		if fd.isAnonFn {
			if fo, ok := v.(*Object); ok && fo.callable {
				if fd.priv != nil {
					setFunctionName(fo, PropKey{S: "#" + fd.priv.name}, "")
				} else {
					setFunctionName(fo, fd.key, "")
				}
			}
		}
	}
	if fd.priv != nil {
		privateAdd(obj, fd.priv, v)
		return
	}
	if !obj.DefineOwnProperty(fd.key, dataDesc(v, PropDefault)) {
		throwTypeError("cannot define field '%s'", keyToDisplay(fd.key))
	}
}

// initializeInstanceElements installs private methods and fields of constructor F on obj
func (in *Interp) initializeInstanceElements(obj *Object, F *Object) {
	fn, ok := F.internal.(*Function)
	if !ok {
		return
	}
	for _, pn := range fn.privMethods {
		if obj.findPriv(pn) >= 0 {
			throwTypeError("private method #%s already installed", pn.name)
		}
		obj.privFields = append(obj.privFields, privField{pn, Undefined})
	}
	for _, fd := range fn.fields {
		defineField(obj, fd)
	}
}

func defaultConstructorNode(c *ClassNode) *FuncNode {
	fn := &FuncNode{NodeBase: NodeBase{c.P}, Name: c.Name, Strict: true, SimpleParams: true, IsExpr: true}
	fn.Source = c.Source
	if c.SuperClass != nil {
		fn.Kind = FuncDerivedConstructor
		fn.SimpleParams = false
		fn.ParamNames = []string{"args"}
		fn.Params = []Node{&RestElement{NodeBase{c.P}, &Ident{NodeBase{c.P}, "args"}}}
		fn.Body = []Node{&ExprStmt{NodeBase{c.P}, &CallExpr{NodeBase: NodeBase{c.P}, Callee: &SuperExpr{NodeBase{c.P}}, Args: []Node{&Spread{NodeBase{c.P}, &Ident{NodeBase{c.P}, "args"}}}}}}
		fn.HasSuperCall = true
		fn.UsesThis = true
	} else {
		fn.Kind = FuncClassConstructor
	}
	fn.IsDefaultCtor = true
	return fn
}
