// spawn starts the goroutine running the body
func (g *Generator) spawn(bindParams bool) {
	g.started = true
	in := g.in
	go func() {
		first := <-g.resume
		var result coMsg
		func() {
			defer func() {
				if r := recover(); r != nil {
					switch t := r.(type) {
					case *Throw:
						result = coMsg{kind: coThrow, val: t.Val}
					case *genReturnSignal:
						result = coMsg{kind: coReturn, val: t.val}
					default:
						result = coMsg{kind: coPanic, raw: r}
					}
				}
			}()
			if first.kind == coThrow {
				panic(&Throw{Val: first.val})
			}
			if first.kind == coReturn {
				panic(&genReturnSignal{first.val})
			}
			if bindParams {
				in.bindParamsAndHoist(g.fn, g.args)
			}
			var v Value = Undefined
			node := g.fn.node
			if node.ExprBody {
				v = in.evalExpr(node.Body[0].(*ReturnStmt).Arg)
			} else {
				c := in.execStatements(node.Body)
				if c.t == cReturn {
					v = c.v
				}
			}
			result = coMsg{kind: coReturn, val: v}
		}()
		g.state = genCompleted
		g.yield <- result
	}()
}

// resumeWith hands control to the coroutine and waits for its next message
func (g *Generator) resumeWith(msg coMsg) coMsg {
	savedFrame := rt.frame
	savedDepth := rt.frameDepth
	g.frame.parent = rt.frame
	rt.frame = g.frame
	rt.frameDepth++
	if rt.frameDepth > maxStackDepth {
		rt.frame = savedFrame
		rt.frameDepth = savedDepth
		throwInternalError("stack overflow")
	}
	g.state = genExecuting
	g.resume <- msg
	out := <-g.yield
	rt.frame = savedFrame
	rt.frameDepth = savedDepth
	if out.kind == coPanic {
		panic(out.raw)
	}
	return out
}

// yieldOut is called from within the coroutine
func (g *Generator) yieldOut(msg coMsg) coMsg {
	g.yield <- msg
	return <-g.resume
}

// ---------- yield / await inside bodies ----------

func (in *Interp) currentGen() *Generator {
	if in.act != nil && in.act.gen != nil {
		return in.act.gen
	}
	return nil
}

func (in *Interp) evalYield(e *YieldExpr) Value {
	g := in.currentGen()
	if g == nil {
		throwSyntaxError("yield outside generator")
	}
	if e.Delegate {
		return in.evalYieldStar(e, g)
	}
	var v Value = Undefined
	if e.Arg != nil {
		v = in.evalExpr(e.Arg)
	}
	if g.isAsync {
		v = in.await(v)
	}
	g.state = genSuspendedYield
	msg := g.yieldOut(coMsg{kind: coYield, val: v})
	g.state = genExecuting
	switch msg.kind {
	case coThrow:
		in.frame.pos = e.P
		panic(&Throw{Val: msg.val})
	case coReturn:
		rv := msg.val
		if g.isAsync {
			rv = in.await(rv)
		}
		panic(&genReturnSignal{rv})
	}
	return msg.val
}

func (in *Interp) evalYieldStar(e *YieldExpr, g *Generator) Value {
	iterable := in.evalExpr(e.Arg)
	in.frame.pos = e.P
	var iter *Iterator
	if g.isAsync {
		iter = getAsyncIterator(iterable)
	} else {
		iter = getIterator(iterable)
		if iter.fastArr != nil {
			// use generic path
			m := getMethod(iterable, symKey(SymIterator))
			iter = getIteratorFromMethod(iterable, m)
		}
	}
	received := coMsg{kind: coNext, val: Undefined}
	for {
		var res Value
		switch received.kind {
		case coNext:
			res = iter.nextRaw([]Value{received.val})
		case coThrow:
			th := iter.obj.Get(strKey("throw"), iter.obj)
			if isNullish(th) {
				// close iterator then throw TypeError
				if g.isAsync {
					in.asyncIteratorClose(iter)
				} else {
					iteratorClose(iter)
				}
				throwTypeError("iterator does not have a throw method")
			}
			res = callValue(th, iter.obj, []Value{received.val})
		case coReturn:
			ret := iter.obj.Get(strKey("return"), iter.obj)
			if isNullish(ret) {
				rv := received.val
				if g.isAsync {
					rv = in.await(rv)
				}
				panic(&genReturnSignal{rv})
			}
			res = callValue(ret, iter.obj, []Value{received.val})
		}
		if g.isAsync {
			res = in.await(res)
		}
		ro, ok := res.(*Object)
		if !ok {
			throwTypeError("iterator result is not an object")
		}
