			v := ro.Get(strKey("value"), ro)
			received = g.yieldOut(coMsg{kind: coYield, val: v})
		} else {
			received = g.yieldOut(coMsg{kind: coYieldRaw, val: ro})
		}
		g.state = genExecuting
	}
