		first := <-g.resume
		var result coMsg
		func() {
			defer func() {
				if r := recover(); r != nil {
					switch t := r.(type) {
					case *Throw:
						result = coMsg{kind: coThrow, val: t.Val}
					case *genReturnSignal:
						result = coMsg{kind: coReturn, val: t.val}
					default:
						result = coMsg{kind: coPanic, raw: r}
					}
				}
			}()
			if first.kind == coThrow {
				panic(&Throw{Val: first.val})
			}
			if first.kind == coReturn {
				panic(&genReturnSignal{first.val})
			}
			if bindParams {
				in.bindParamsAndHoist(g.fn, g.args)
			}
			var v Value = Undefined
			node := g.fn.node
			if node.ExprBody {
				v = in.evalExpr(node.Body[0].(*ReturnStmt).Arg)
			} else {
				c := in.execStatements(node.Body)
				if c.t == cReturn {
					v = c.v
				}
			}
			result = coMsg{kind: coReturn, val: v}
		}()
		g.state = genCompleted
		g.yield <- result
	}()
}

// resumeWith hands control to the coroutine and waits for its next message
func (g *Generator) resumeWith(msg coMsg) coMsg {
	savedFrame := rt.frame
	savedDepth := rt.frameDepth
	g.frame.parent = rt.frame
	rt.frame = g.frame
	rt.frameDepth++
	if rt.frameDepth > maxStackDepth {
		rt.frame = savedFrame
		rt.frameDepth = savedDepth
		throwInternalError("stack overflow")
	}
	g.state = genExecuting
	g.resume <- msg
	out := <-g.yield
	rt.frame = savedFrame
	rt.frameDepth = savedDepth
	if out.kind == coPanic {
		panic(out.raw)
	}
	return out
}

// yieldOut is called from within the coroutine
func (g *Generator) yieldOut(msg coMsg) coMsg {
	g.yield <- msg
	return <-g.resume
}

// ---------- yield / await inside bodies ----------

func (in *Interp) currentGen() *Generator {
	if in.act != nil && in.act.gen != nil {
		return in.act.gen
	}
	return nil
}

func (in *Interp) evalYield(e *YieldExpr) Value {
	g := in.currentGen()
	if g == nil {
		throwSyntaxError("yield outside generator")
	}
	if e.Delegate {
		return in.evalYieldStar(e, g)
	}
	var v Value = Undefined
	if e.Arg != nil {
		v = in.evalExpr(e.Arg)
	}
	if g.isAsync {
		v = in.await(v)
	}
	g.state = genSuspendedYield
	msg := g.yieldOut(coMsg{kind: coYield, val: v})
	g.state = genExecuting
	switch msg.kind {
	case coThrow:
		in.frame.pos = e.P
		panic(&Throw{Val: msg.val})
	case coReturn:
		rv := msg.val
		if g.isAsync {
			rv = in.await(rv)
		}
		panic(&genReturnSignal{rv})
	}
	return msg.val
}

func (in *Interp) evalYieldStar(e *YieldExpr, g *Generator) Value {
	iterable := in.evalExpr(e.Arg)
	in.frame.pos = e.P
	var iter *Iterator
	if g.isAsync {
		iter = getAsyncIterator(iterable)
	} else {
		iter = getIterator(iterable)
		if iter.fastArr != nil {
			// use generic path
			m := getMethod(iterable, symKey(SymIterator))
			iter = getIteratorFromMethod(iterable, m)
		}
	}
	received := coMsg{kind: coNext, val: Undefined}
	for {
		var res Value
		switch received.kind {
		case coNext:
			res = iter.nextRaw([]Value{received.val})
		case coThrow:
			th := iter.obj.Get(strKey("throw"), iter.obj)
			if isNullish(th) {
				// close iterator then throw TypeError
				if g.isAsync {
					in.asyncIteratorClose(iter)
				} else {
					iteratorClose(iter)
				}
				throwTypeError("iterator does not have a throw method")
			}
			res = callValue(th, iter.obj, []Value{received.val})
		case coReturn:
			ret := iter.obj.Get(strKey("return"), iter.obj)
			if isNullish(ret) {
				rv := received.val
				if g.isAsync {
					rv = in.await(rv)
				}
				panic(&genReturnSignal{rv})
			}
			res = callValue(ret, iter.obj, []Value{received.val})
		}
		if g.isAsync {
			res = in.await(res)
		}
		ro, ok := res.(*Object)
		if !ok {
			throwTypeError("iterator result is not an object")
		}
		done := toBoolean(ro.Get(strKey("done"), ro))
		if done {
			v := ro.Get(strKey("value"), ro)
			if received.kind == coReturn {
				panic(&genReturnSignal{v})
			}
			return v
		}
		g.state = genSuspendedYield
		if g.isAsync {
			v := ro.Get(strKey("value"), ro)
			received = g.yieldOut(coMsg{kind: coYield, val: v})
		} else {
			received = g.yieldOut(coMsg{kind: coYieldRaw, val: ro})
		}
		g.state = genExecuting
	}
}

// await suspends the current async coroutine until the promise settles
func (in *Interp) await(v Value) Value {
	g := in.currentGen()
	if g == nil || !g.isAsync {
		// top-level await in module or misuse: run the event loop until settled
		return awaitSync(v)
	}
	msg := g.yieldOut(coMsg{kind: coAwait, val: v})
	if msg.kind == coThrow {
		panic(&Throw{Val: msg.val})
	}
	return msg.val
}

// awaitSync: used for top-level await; drives the job queue until the promise settles
func awaitSync(v Value) Value {
	p := promiseResolve(rt.PromiseCtor, v)
	pd := p.internal.(*PromiseData)
	for pd.state == promisePending {
		if !runOneJobOrTimer() {
			break
		}
	}
	if pd.state == promisePending {
		throwInternalError("top-level await: promise never settled")
	}
	pd.handled = true
	if pd.state == promiseRejected {
		panic(&Throw{Val: pd.value})
	}
	return pd.value
}

// ---------- async function driver ----------

func (g *Generator) asyncStep(msg coMsg) {
	out := g.resumeWith(msg)
	switch out.kind {
	case coAwait:
		g.awaitThen(out.val, func(v Value) { g.asyncStep(coMsg{kind: coNext, val: v}) }, func(e Value) { g.asyncStep(coMsg{kind: coThrow, val: e}) })
	case coReturn:
		callFunction(g.resolveFn, Undefined, []Value{out.val})
	case coThrow:
		callFunction(g.rejectFn, Undefined, []Value{out.val})
	default:
		throwInternalError("unexpected coroutine message in async function")
	}
}

// awaitThen subscribes to the promise for value v
func (g *Generator) awaitThen(v Value, onFul func(Value), onRej func(Value)) {
	var p *Object
	func() {
		defer func() {
			if r := recover(); r != nil {
				if t, ok := r.(*Throw); ok {
					// error during PromiseResolve (e.g. getter throws) -> reject path
					p = nil
					enqueueJob(func() { onRej(t.Val) })
					return
				}
				panic(r)
			}
		}()
		p = promiseResolve(rt.PromiseCtor, v)
	}()
	if p == nil {
		return
	}
	performPromiseThenNative(p, onFul, onRej)
}

// ---------- sync generator protocol ----------

func generatorResume(gobj Value, kind int, val Value) Value {
	o, ok := gobj.(*Object)
	if !ok || o.class != ClassGenerator {
		throwTypeError("not a generator")
	}
	g := o.internal.(*Generator)
	switch g.state {
	case genExecuting:
		throwTypeError("generator is already running")
	case genCompleted:
		switch kind {
		case coNext:
			return createIterResult(Undefined, true)
		case coReturn:
			return createIterResult(val, true)
		default:
			panic(&Throw{Val: val})
		}
	case genSuspendedStart:
		if kind == coReturn {
			g.state = genCompleted
			return createIterResult(val, true)
		}
		if kind == coThrow {
			g.state = genCompleted
			panic(&Throw{Val: val})
		}
		if !g.started {
			g.spawn(false)
		}
	}
	out := g.resumeWith(coMsg{kind: kind, val: val})
	switch out.kind {
	case coYield:
		g.state = genSuspendedYield
		return createIterResult(out.val, false)
	case coYieldRaw:
		g.state = genSuspendedYield
		return out.val
	case coReturn:
		g.state = genCompleted
		return createIterResult(out.val, true)
	case coThrow:
		g.state = genCompleted
		panic(&Throw{Val: out.val})
	}
	throwInternalError("unexpected generator message")
	return nil
}

// ---------- async generator protocol ----------

func asyncGeneratorEnqueue(gobj Value, kind int, val Value) Value {
	p, res, rej := newPromiseCapability(rt.PromiseCtor)
	o, ok := gobj.(*Object)
	if !ok || o.class != ClassAsyncGenerator {
		callFunction(rej, Undefined, []Value{makeError("TypeError", "not an AsyncGenerator object")})
		return p
	}
	g := o.internal.(*Generator)
	req := &asyncGenRequest{kind: kind, val: val, promise: p, resolve: res, reject: rej}
	g.queue = append(g.queue, req)
	if g.state != genExecuting && g.state != genAwaitingReturn {
		asyncGenResumeNext(g)
	}
	return p
}

func asyncGenResumeNext(g *Generator) {
	for len(g.queue) > 0 {
		if g.state == genExecuting || g.state == genAwaitingReturn {
			return
		}
		req := g.queue[0]
		if g.state == genCompleted {
			switch req.kind {
			case coNext:
				g.queue = g.queue[1:]
				callFunction(req.resolve, Undefined, []Value{createIterResult(Undefined, true)})
				continue
			case coThrow:
				g.queue = g.queue[1:]
				callFunction(req.reject, Undefined, []Value{req.val})
				continue
			case coReturn:
				// await the value then resolve
				g.state = genAwaitingReturn
				g.awaitThen(req.val, func(v Value) {
					g.state = genCompleted
					g.queue = g.queue[1:]
					callFunction(req.resolve, Undefined, []Value{createIterResult(v, true)})
					asyncGenResumeNext(g)
				}, func(e Value) {
					g.state = genCompleted
					g.queue = g.queue[1:]
					callFunction(req.reject, Undefined, []Value{e})
					asyncGenResumeNext(g)
				})
				return
			}
		}
		if g.state == genSuspendedStart {
			if req.kind == coReturn {
				g.state = genCompleted
				continue // handled by completed branch on next loop iteration
			}
			if req.kind == coThrow {
				g.state = genCompleted
				continue
			}
			if !g.started {
				g.spawn(false)
			}
		}
		// resume the body
		g.asyncGenStep(coMsg{kind: req.kind, val: req.val})
		return
	}
}

func (g *Generator) asyncGenStep(msg coMsg) {
	out := g.resumeWith(msg)
	switch out.kind {
	case coAwait:
		g.state = genExecuting
		g.awaitThen(out.val, func(v Value) { g.asyncGenStep(coMsg{kind: coNext, val: v}) }, func(e Value) { g.asyncGenStep(coMsg{kind: coThrow, val: e}) })
	case coYield:
		g.state = genSuspendedYield
		req := g.queue[0]
		g.queue = g.queue[1:]
		callFunction(req.resolve, Undefined, []Value{createIterResult(out.val, false)})
		asyncGenResumeNext(g)
	case coReturn:
		g.state = genCompleted
		req := g.queue[0]
		g.queue = g.queue[1:]
		callFunction(req.resolve, Undefined, []Value{createIterResult(out.val, true)})
		asyncGenResumeNext(g)
	case coThrow:
		g.state = genCompleted
		req := g.queue[0]
		g.queue = g.queue[1:]
		callFunction(req.reject, Undefined, []Value{out.val})
		asyncGenResumeNext(g)
	}
}
