// newPromiseCapability creates a promise using constructor C
func newPromiseCapability(C *Object) (*Object, *Object, *Object) {
	if C == rt.PromiseCtor {
		p := newPromiseObject(nil)
		res, rej := createResolvingFunctions(p)
		return p, res, rej
	}
	if !C.ctor {
		throwTypeError("not a constructor")
	}
	var resolve, reject Value = Undefined, Undefined
	executor := newNativeFunction("", 2, func(this Value, args []Value) Value {
		if !isUndefined(resolve) || !isUndefined(reject) {
			throwTypeError("promise capability executor already called")
		}
		resolve = arg(args, 0)
		reject = arg(args, 1)
		return Undefined
	})
	pv := construct(C, []Value{executor}, C)
	if !isCallable(resolve) || !isCallable(reject) {
		throwTypeError("promise capability functions are not callable")
	}
	return pv.(*Object), resolve.(*Object), reject.(*Object)
}

// promiseResolve implements PromiseResolve(C, x)
func promiseResolve(C *Object, x Value) *Object {
	if xo, ok := x.(*Object); ok && xo.class == ClassPromise {
		c := xo.Get(strKey("constructor"), xo)
		if c == Value(C) {
			return xo
		}
	}
	p, res, _ := newPromiseCapability(C)
	callFunction(res, Undefined, []Value{x})
	return p
}

// performPromiseThen with JS handlers and an optional result capability
func performPromiseThen(p *Object, onFulfilled, onRejected Value, resultPromise *Object, resolve, reject Value) {
	pd := p.internal.(*PromiseData)
	if !isCallable(onFulfilled) {
		onFulfilled = Undefined
	}
	if !isCallable(onRejected) {
		onRejected = Undefined
	}
	fr := &promiseReaction{kind: 0, handler: onFulfilled, promise: resultPromise, resolve: resolve, reject: reject}
	rr := &promiseReaction{kind: 1, handler: onRejected, promise: resultPromise, resolve: resolve, reject: reject}
	switch pd.state {
	case promisePending:
		pd.fulfillReactions = append(pd.fulfillReactions, fr)
		pd.rejectReactions = append(pd.rejectReactions, rr)
	case promiseFulfilled:
		triggerReaction(fr, pd.value)
	case promiseRejected:
		if !pd.handled {
			// remove from tracker
			removeFromRejectionTracker(p)
		}
		triggerReaction(rr, pd.value)
	}
	pd.handled = true
}

func performPromiseThenNative(p *Object, onFul func(Value), onRej func(Value)) {
	pd := p.internal.(*PromiseData)
	fr := &promiseReaction{kind: 0, nativeHandler: onFul}
	rr := &promiseReaction{kind: 1, nativeHandler: onRej}
	switch pd.state {
	case promisePending:
		pd.fulfillReactions = append(pd.fulfillReactions, fr)
		pd.rejectReactions = append(pd.rejectReactions, rr)
	case promiseFulfilled:
		triggerReaction(fr, pd.value)
	case promiseRejected:
		if !pd.handled {
			removeFromRejectionTracker(p)
		}
		triggerReaction(rr, pd.value)
	}
	pd.handled = true
}

func removeFromRejectionTracker(p *Object) {
	for i, q := range rt.rejectionTracker {
		if q == p {
			rt.rejectionTracker = append(rt.rejectionTracker[:i], rt.rejectionTracker[i+1:]...)
			return
		}
	}
}

// promiseThen: the JS-visible then operation; returns the derived promise
func promiseThen(p *Object, onFulfilled, onRejected Value) Value {
	C := speciesConstructor(p, rt.PromiseCtor)
	rp, res, rej := newPromiseCapability(C)
	performPromiseThen(p, onFulfilled, onRejected, rp, res, rej)
	return rp
}
