actions.command:
cat > /workspace/src/modules.go <<'EOF'
package main

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type Module struct {
	name      string // resolved path / display name
	src       *Source
	prog      *Program
	scope     *Scope
	ns        *Object
	meta      *Object
	status    int // 0 unlinked, 1 linking, 2 linked, 3 evaluating, 4 evaluated, 5 errored
	evalError *Throw
	exports   map[string]exportEntry // exported name -> entry
	starExports []*Module
	requested []*Module
	builtin   bool
	builtinNS *Object // for std/os: an object whose props are the exports
	evalPromise *Object
	isAsync   bool
	in        *Interp
	hasTLA    bool
	act       *Activation
}

type exportEntry struct {
	local  string  // local binding name (if module != nil and indirect, this is the import name)
	module *Module // nil => local binding in this module; else re-export from module
	isNS   bool    // export * as ns
}

func (m *Module) resolveExport(name string, visited map[*Module]bool) (*Module, string, bool) {
	if m.builtin {
		if m.builtinNS.GetOwnProperty(strKey(name)) != nil {
			return m, name, true
		}
		return nil, "", false
	}
	if visited[m] {
		return nil, "", false
	}
	visited[m] = true
	if e, ok := m.exports[name]; ok {
		if e.module == nil {
			return m, e.local, true
		}
		if e.isNS {
			return e.module, "*", true
		}
		return e.module.resolveExport(e.local, visited)
	}
	if name == "default" {
		return nil, "", false
	}
	var found *Module
	var foundName string
	for _, sm := range m.starExports {
		rm, rn, ok := sm.resolveExport(name, visited)
		if ok {
			if found != nil && (found != rm || foundName != rn) {
				return nil, "", false // ambiguous
			}
			found = rm
			foundName = rn
		}
	}
	if found != nil {
		return found, foundName, true
	}
	return nil, "", false
}

func (m *Module) exportedNames(visited map[*Module]bool) []string {
	if m.builtin {
		var names []string
		for _, k := range m.builtinNS.OwnKeys() {
			if k.Sym == nil {
				names = append(names, k.S)
			}
		}
		return names
	}
	if visited[m] {
		return nil
	}
	visited[m] = true
	var names []string
	for n := range m.exports {
		names = append(names, n)
	}
	for _, sm := range m.starExports {
		for _, n := range sm.exportedNames(visited) {
			if n == "default" {
				continue
			}
			dup := false
			for _, x := range names {
				if x == n {
					dup = true
					break
				}
			}
			if !dup {
				names = append(names, n)
			}
		}
	}
	return names
}

// getBindingValue reads the current value of an exported binding
func (m *Module) getBindingValue(local string) Value {
	if m.builtin {
		return m.builtinNS.Get(strKey(local), m.builtinNS)
	}
	if local == "*" {
		return m.getNamespace()
	}
	sc := m.scope
	i := sc.find(local)
	if i < 0 {
		throwReferenceError("'%s' is not defined", local)
	}
	if sc.flags[i]&bTDZ != 0 {
		throwReferenceError("lexical variable '%s' is not initialized", local)
	}
	if sc.flags[i]&bImport != 0 {
		return resolveImportBinding(sc, i, local)
	}
	return sc.vals[i]
}

func resolveImportBinding(sc *Scope, idx int, name string) Value {
	ib := sc.imports[name]
	if ib == nil {
		throwReferenceError("'%s' is not defined", name)
	}
	if ib.name == "*" {
		return ib.module.getNamespace()
	}
	rm, rn, ok := ib.module.resolveExport(ib.name, map[*Module]bool{})
	if !ok {
		throwSyntaxError("Could not find export '%s' in module '%s'", ib.name, ib.module.name)
	}
	return rm.getBindingValue(rn)
}

func (m *Module) getNamespace() *Object {
	if m.ns != nil {
		return m.ns
	}
	ns := newObjectRaw(nil, ClassModuleNS)
	ns.internal = m
	ns.extensible = false
	ns.props.Set(symKey(SymToStringTag), Prop{Value: NewStringFromGo("Module"), Flags: 0})
	m.ns = ns
	return ns
}

func moduleNSNames(o *Object) []string {
	m := o.internal.(*Module)
	names := m.exportedNames(map[*Module]bool{})
	// only resolvable names
	var out []string
	for _, n := range names {
		if _, _, ok := m.resolveExport(n, map[*Module]bool{}); ok {
			out = append(out, n)
		}
	}
	sort.Strings(out)
	return out
}

func moduleNSGetOwnProperty(o *Object, k PropKey) *Prop {
	if k.Sym != nil {
		return o.props.Get(k)
	}
	m := o.internal.(*Module)
	rm, rn, ok := m.resolveExport(k.S, map[*Module]bool{})
	if !ok {
		return nil
	}
	v := rm.getBindingValue(rn)
	return &Prop{Value: v, Flags: PropWritable | PropEnumerable}
}

func moduleNSOwnKeys(o *Object) []PropKey {
	var keys []PropKey
	for _, n := range moduleNSNames(o) {
		keys = append(keys, strKey(n))
	}
	for i := range o.props.entries {
		keys = append(keys, o.props.entries[i].key)
	}
	return keys
}

func moduleNSDelete(o *Object, k PropKey) bool {
	if k.Sym != nil {
		return o.props.Get(k) == nil
	}
	return moduleNSGetOwnProperty(o, k) == nil
}

func moduleNSDefineOwnProperty(o *Object, k PropKey, d PropDesc) bool {
	if k.Sym != nil {
		return o.defineOrdinary(k, d)
	}
	cur := moduleNSGetOwnProperty(o, k)
	if cur == nil {
		return false
	}
	if d.HasConfigurable && d.Configurable {
		return false
	}
	if d.HasEnumerable && !d.Enumerable {
		return false
	}
	if d.IsAccessor() {
		return false
	}
	if d.HasWritable && !d.Writable {
		return false
	}
	if d.HasValue {
		return sameValue(d.Value, cur.Value)
	}
	return true
}

// ---------- loading ----------

func resolveModuleName(base string, spec string) string {
	if spec == "std" || spec == "os" || spec == "bjson" {
		return spec
	}
	if strings.HasPrefix(spec, "./") || strings.HasPrefix(spec, "../") {
		dir := "."
		if base != "" && base != "<cmdline>" && base != "<input>" {
			dir = filepath.Dir(base)
		}
		return filepath.Clean(filepath.Join(dir, spec))
	}
	return spec
}

func loadModule(name string, pos int) *Module {
	if m, ok := rt.modules[name]; ok {
		return m
	}
	if name == "std" {
		m := &Module{name: name, builtin: true, builtinNS: getStdModule(), status: 4}
		rt.modules[name] = m
		return m
	}
	if name == "os" {
		m := &Module{name: name, builtin: true, builtinNS: getOsModule(), status: 4}
		rt.modules[name] = m
		return m
	}
	data, err := os.ReadFile(name)
	if err != nil {
		throwReferenceError("could not load module filename '%s'", name)
	}
	text := string(data)
	m := parseModule(name, text)
	return m
}

func parseModule(name, text string) *Module {
	p := NewParser(text, name, true)
	prog, err := p.ParseProgram()
	if err != nil {
		se := err.(*SyntaxError)
		e := makeError("SyntaxError", se.Msg)
		e.setOwn("stack", NewStringFromGo(formatSyntaxStack(name, se)), PropHidden)
		panic(&Throw{Val: e})
	}
	m := &Module{name: name, prog: prog, src: NewSource(name, text), exports: map[string]exportEntry{}}
	rt.modules[name] = m
	// requested modules
	for _, imp := range prog.Imports {
		rn := resolveModuleName(name, imp.Source)
		dep := loadModule(rn, imp.P)
		m.requested = append(m.requested, dep)
	}
	for _, exp := range prog.Exports {
		if exp.Source != "" {
			rn := resolveModuleName(name, exp.Source)
			dep := loadModule(rn, exp.P)
			m.requested = append(m.requested, dep)
			if exp.IsStar {
				if exp.StarAs != "" {
					m.exports[exp.StarAs] = exportEntry{module: dep, isNS: true}
				} else {
					m.starExports = append(m.starExports, dep)
				}
			} else {
				for _, s := range exp.Specs {
					m.exports[s.Exported] = exportEntry{local: s.Local, module: dep}
				}
			}
		} else if exp.IsDefault {
			if exp.Decl != nil {
				switch d := exp.Decl.(type) {
				case *FuncDecl:
					m.exports["default"] = exportEntry{local: d.Func.Name}
				case *ClassDecl:
					m.exports["default"] = exportEntry{local: d.Class.Name}
				}
			} else {
				m.exports["default"] = exportEntry{local: "*default*"}
			}
		} else {
			for _, s := range exp.Specs {
				m.exports[s.Exported] = exportEntry{local: s.Local}
			}
		}
	}
	return m
}

func formatSyntaxStack(name string, se *SyntaxError) string {
	return "    at " + name + ":" + itoa(se.Line) + ":" + itoa(se.Col) + "\n"
}

func itoa(i int) string {
	return uint32ToString(uint32(i))
}

// linkModule creates the module scope and resolves imports
func linkModule(m *Module) {
	if m.builtin || m.status >= 1 {
		return
	}
	m.status = 1
	for _, dep := range m.requested {
		linkModule(dep)
	}
	sc := newScope(nil, nil)
	sc.funcScope = true
	sc.module = m
	sc.imports = map[string]*importBinding{}
	m.scope = sc
	act := &Activation{this: Undefined, thisInit: true, newTarget: Undefined, module: m, src: m.src, strict: true}
	m.act = act
	sc.act = act
	prog := m.prog
	// imports
	for _, imp := range prog.Imports {
		rn := resolveModuleName(m.name, imp.Source)
		dep := rt.modules[rn]
		for _, s := range imp.Specs {
			if s.Imported != "*" {
				// validate export exists
				if _, _, ok := dep.resolveExport(s.Imported, map[*Module]bool{}); !ok {
					e := makeError("SyntaxError", "Could not find export '"+s.Imported+"' in module '"+dep.name+"'")
					e.setOwn("stack", NewStringFromGo(""), PropHidden)
					panic(&Throw{Val: e})
				}
			}
			sc.imports[s.Local] = &importBinding{module: dep, name: s.Imported}
			sc.declare(s.Local, Undefined, bImport|bConst)
		}
	}
	// var names
	for _, vn := range prog.VarNames {
		if sc.find(vn) < 0 {
			sc.declare(vn, Undefined, bVar)
		}
	}
	for _, ln := range prog.Lex {
		if ln.IsFunc {
			continue
		}
		fl := bTDZ
		if ln.IsConst {
			fl |= bConst
		}
		sc.declare(ln.Name, Undefined, fl)
	}
	if _, ok := m.exports["default"]; ok && m.exports["default"].local == "*default*" {
		sc.declare("*default*", Undefined, bTDZ|bConst)
	}
	in := &Interp{scope: sc, act: act, src: m.src, strict: true, module: m}
	in.frame = &Frame{fnName: "<anonymous>", src: m.src, pos: 0, isModuleTop: true}
	m.in = in
	// function declarations
	for _, fd := range prog.FuncDecls {
		fo := in.makeFunction(fd)
		if i := sc.find(fd.Name); i >= 0 {
			sc.vals[i] = fo
			sc.flags[i] &^= bTDZ
		} else {
			sc.declare(fd.Name, fo, bVar)
		}
	}
	m.status = 2
}

// evaluateModule runs the module body (and dependencies first)
func evaluateModule(m *Module) {
	if m.builtin || m.status >= 3 {
		if m.status == 5 && m.evalError != nil {
			panic(m.evalError)
		}
		return
	}
	m.status = 3
	for _, dep := range m.requested {
		evaluateModule(dep)
	}
	in := m.in
	pushFrame(in.frame)
	defer popFrame()
	func() {
		defer func() {
			if r := recover(); r != nil {
				if t, ok := r.(*Throw); ok {
					m.status = 5
					m.evalError = t
				}
				panic(r)
			}
		}()
		if m.prog.HasTLA {
			runModuleAsync(m)
		} else {
			in.execStatements(m.prog.Body)
		}
	}()
	if m.status != 5 {
		m.status = 4
	}
}

func runModuleAsync(m *Module) {
	in := m.in
	// Build a pseudo async function for the body
	node := &FuncNode{Body: m.prog.Body, IsAsync: true, Strict: true, SimpleParams: true, Name: "<anonymous>"}
	fn := &Function{node: node, scope: in.scope, name: "<anonymous>", src: m.src, module: m, strict: true}
	fobj := newObjectRaw(rt.AsyncFunctionPrototype, ClassFunction)
	fobj.internal = fn
	fobj.callable = true
	g := &Generator{resume: make(chan coMsg), yield: make(chan coMsg), frame: in.frame, in: in, fn: fn, fobj: fobj, act: m.act, isAsync: true}
	m.act.gen = g
	p, res, rej := newPromiseCapability(rt.PromiseCtor)
	g.promise = p
	g.resolveFn = res
	g.rejectFn = rej
	g.spawn(false)
	g.asyncStep(coMsg{kind: coNext, val: Undefined})
	m.evalPromise = p
	// drive until settled
	pd := p.internal.(*PromiseData)
	for pd.state == promisePending {
		if !runOneJobOrTimer() {
			break
		}
	}
	pd.handled = true
	if pd.state == promiseRejected {
		panic(&Throw{Val: pd.value})
	}
}

func (in *Interp) execExport(st *ExportDecl) completion {
	if st.Decl != nil {
		return in.execStmt(st.Decl)
	}
	if st.IsDefault && st.Default != nil {
		var v Value
		switch d := st.Default.(type) {
		case *FuncNode:
			v = in.makeFunction(d)
		case *ClassNode:
			v = in.evalClass(d)
		default:
			v = in.evalExpr(st.Default)
		}
		in.initBinding("*default*", v)
	}
	return normalCompletion
}

func (in *Interp) importMeta() Value {
	m := in.module
	if m == nil {
		throwSyntaxError("import.meta not in module")
	}
	if m.meta == nil {
		meta := newObjectRaw(nil, ClassObject)
		url := m.name
		if !strings.HasPrefix(url, "file://") {
			abs, err := filepath.Abs(url)
			if err == nil {
				url = abs
			}
			url = "file://" + url
		}
		meta.setOwn("url", NewStringFromGo(url), PropDefault)
		meta.setOwn("main", rt.mainModule == m, PropDefault)
		m.meta = meta
	}
	return m.meta
}

func (in *Interp) dynamicImport(specv Value) Value {
	p, res, rej := newPromiseCapability(rt.PromiseCtor)
	var base string
	if in.module != nil {
		base = in.module.name
	} else if in.src != nil {
		base = in.src.name
	}
	func() {
		defer func() {
			if r := recover(); r != nil {
				if t, ok := r.(*Throw); ok {
					callFunction(rej, Undefined, []Value{t.Val})
					return
				}
				panic(r)
			}
		}()
		spec := toGoString(specv)
		name := resolveModuleName(base, spec)
		m := loadModule(name, 0)
		linkModule(m)
		evaluateModule(m)
		ns := m.getNamespace()
		callFunction(res, Undefined, []Value{ns})
	}()
	return p
}

// ---------- scripts & eval ----------

// runScript evaluates a parsed script program in the global scope
func runScript(src *Source, prog *Program, frameName string) Value {
	act := &Activation{this: rt.Global, thisInit: true, newTarget: Undefined, src: src, strict: prog.Strict}
	in := &Interp{scope: rt.GlobalLex, act: act, src: src, strict: prog.Strict}
	// use a scope chained to nothing: global lookups go through GlobalLex then global object
	in.scope = nil
	in.frame = &Frame{fnName: frameName, src: src, pos: 0, isEval: true}
	pushFrame(in.frame)
	defer popFrame()
	globalDeclarationInstantiation(in, prog)
	var last Value = Undefined
	for _, s := range prog.Body {
		if es, ok := s.(*ExprStmt); ok {
			last = in.evalExpr(es.X)
			continue
		}
		c := in.execStmt(s)
		if c.t == cReturn {
			return c.v
		}
		if c.t != cNormal {
			break
		}
	}
	return last
}

func globalDeclarationInstantiation(in *Interp, prog *Program) {
	g := rt.Global
	gl := rt.GlobalLex
	for _, ln := range prog.Lex {
		if ln.IsFunc {
			continue
		}
		if gl.find(ln.Name) >= 0 {
			throwSyntaxError("redeclaration of '%s'", ln.Name)
		}
		if p := g.GetOwnProperty(strKey(ln.Name)); p != nil && !p.Configurable() {
			throwSyntaxError("redeclaration of '%s'", ln.Name)
		}
	}
	for _, vn := range prog.VarNames {
		if gl.find(vn) >= 0 {
			throwSyntaxError("redeclaration of '%s'", vn)
		}
	}
	for _, ln := range prog.Lex {
		if ln.IsFunc {
			continue
		}
		fl := bTDZ
		if ln.IsConst {
			fl |= bConst
		}
		gl.declare(ln.Name, Undefined, fl)
	}
	for _, vn := range prog.VarNames {
		if g.GetOwnProperty(strKey(vn)) == nil {
			g.DefineOwnProperty(strKey(vn), dataDesc(Undefined, PropWritable|PropEnumerable))
		}
	}
	for _, fd := range prog.FuncDecls {
		fo := in.makeFunction(fd)
		k := strKey(fd.Name)
		existing := g.GetOwnProperty(k)
		if existing == nil || existing.Configurable() {
			g.DefineOwnProperty(k, dataDesc(fo, PropWritable|PropEnumerable))
		} else {
			g.Set(k, fo, g)
		}
	}
}

// directEval evaluates code in the current scope
func (in *Interp) directEval(args []Value) Value {
	if len(args) == 0 {
		return Undefined
	}
	codev, ok := args[0].(*String)
	if !ok {
		return args[0]
	}
	code := codev.String()
	p := NewParser(code, "<input>", false)
	p.evalMode = true
	// inherit strictness and function context
	var fcInit func(fc *funcCtx)
	strict := in.strict
	act := in.act
	fcInit = func(fc *funcCtx) {
		fc.strict = strict
		if act != nil && act.fn != nil {
			fc.allowNewTarget = true
			fc.allowSuperProp = act.homeObject != nil
			fc.allowSuperCall = act.fn.isDerived && !act.thisInit
		}
		if act != nil && act.privEnv != nil {
			p.evalPrivEnv = act.privEnv
		}
	}
	p.topInit = fcInit
	prog, err := p.ParseProgram()
	if err != nil {
		se := err.(*SyntaxError)
		e := makeError("SyntaxError", se.Msg)
		e.setOwn("stack", NewStringFromGo(formatSyntaxStack("<input>", se)), PropHidden)
		panic(&Throw{Val: e})
	}
	src := NewSource("<input>", code)
	strictEval := prog.Strict
	// scope setup
	var sc *Scope
	varScope := in.scope
	if strictEval {
		sc = newScope(in.scope, nil)
		sc.funcScope = true
		varScope = sc
	} else {
		sc = newScope(in.scope, nil)
		// find nearest function scope for vars
		for s := in.scope; s != nil; s = s.parent {
			if s.funcScope {
				varScope = s
				break
			}
			varScope = s.parent
		}
	}
	ein := &Interp{scope: sc, act: in.act, src: src, strict: strictEval, module: in.module, privEnv: in.privEnv}
	ein.frame = &Frame{fnName: "<eval>", src: src, pos: 0, isEval: true}
	pushFrame(ein.frame)
	defer popFrame()
	// lexical declarations
	for _, ln := range prog.Lex {
		if ln.IsFunc {
			continue
		}
		fl := bTDZ
		if ln.IsConst {
			fl |= bConst
		}
		sc.declare(ln.Name, Undefined, fl)
	}
	// var declarations
	for _, vn := range prog.VarNames {
		if varScope == nil {
			if rt.Global.GetOwnProperty(strKey(vn)) == nil {
				rt.Global.DefineOwnProperty(strKey(vn), dataDesc(Undefined, PropDefault))
			}
		} else if varScope.find(vn) < 0 {
			varScope.declare(vn, Undefined, bVar)
		}
	}
	for _, fd := range prog.FuncDecls {
		fo := ein.makeFunction(fd)
		if varScope == nil {
			rt.Global.DefineOwnProperty(strKey(fd.Name), dataDesc(fo, PropDefault))
		} else if i := varScope.find(fd.Name); i >= 0 {
			varScope.vals[i] = fo
		} else {
			varScope.declare(fd.Name, fo, bVar)
		}
	}
	var last Value = Undefined
	for _, s := range prog.Body {
		if es, ok := s.(*ExprStmt); ok {
			last = ein.evalExpr(es.X)
			continue
		}
		c := ein.execStmt(s)
		if c.t != cNormal {
			break
		}
	}
	return last
}

// indirectEval evaluates in the global scope
func indirectEval(code *String) Value {
	text := code.String()
	p := NewParser(text, "<input>", false)
	p.evalMode = true
	prog, err := p.ParseProgram()
	if err != nil {
		se := err.(*SyntaxError)
		e := makeError("SyntaxError", se.Msg)
		e.setOwn("stack", NewStringFromGo(formatSyntaxStack("<input>", se)), PropHidden)
		panic(&Throw{Val: e})
	}
	src := NewSource("<input>", text)
	act := &Activation{this: rt.Global, thisInit: true, newTarget: Undefined, src: src, strict: prog.Strict}
	in := &Interp{scope: nil, act: act, src: src, strict: prog.Strict}
	in.frame = &Frame{fnName: "<eval>", src: src, pos: 0, isEval: true}
	pushFrame(in.frame)
	defer popFrame()
	var sc *Scope
	if prog.Strict {
		sc = newScope(nil, nil)
		sc.funcScope = true
		in.scope = sc
		for _, ln := range prog.Lex {
			if ln.IsFunc {
				continue
			}
			fl := bTDZ
			if ln.IsConst {
				fl |= bConst
			}
			sc.declare(ln.Name, Undefined, fl)
		}
		for _, vn := range prog.VarNames {
			sc.declare(vn, Undefined, bVar)
		}
		for _, fd := range prog.FuncDecls {
			fo := in.makeFunction(fd)
			if i := sc.find(fd.Name); i >= 0 {
				sc.vals[i] = fo
			} else {
				sc.declare(fd.Name, fo, bVar)
			}
		}
	} else {
		// lexical declarations of sloppy indirect eval live in a new scope too (not global lex)
		sc = newScope(nil, nil)
		in.scope = sc
		for _, ln := range prog.Lex {
			if ln.IsFunc {
				continue
			}
			fl := bTDZ
			if ln.IsConst {
				fl |= bConst
			}
			sc.declare(ln.Name, Undefined, fl)
		}
		g := rt.Global
		for _, vn := range prog.VarNames {
			if g.GetOwnProperty(strKey(vn)) == nil {
				g.DefineOwnProperty(strKey(vn), dataDesc(Undefined, PropDefault))
			}
		}
		for _, fd := range prog.FuncDecls {
			fo := in.makeFunction(fd)
			g.DefineOwnProperty(strKey(fd.Name), dataDesc(fo, PropDefault))
		}
	}
	var last Value = Undefined
	for _, s := range prog.Body {
		if es, ok := s.(*ExprStmt); ok {
			last = in.evalExpr(es.X)
			continue
		}
		c := in.execStmt(s)
		if c.t != cNormal {
			break
		}
	}
	return last
}
