func objectToString(this Value) string {
	switch this.(type) {
	case undefinedType:
		return "[object Undefined]"
	case nullType:
		return "[object Null]"
	}
	o := toObject(this)
	var tag string
	switch o.class {
	case ClassArray:
		tag = "Array"
	case ClassArguments:
		tag = "Arguments"
	case ClassFunction:
		tag = "Function"
	case ClassError:
		tag = "Error"
	case ClassBoolean:
		tag = "Boolean"
	case ClassNumber:
		tag = "Number"
	case ClassString:
		tag = "String"
	case ClassDate:
		tag = "Date"
	case ClassRegExp:
		tag = "RegExp"
	case ClassProxy:
		if isArray(o) {
			tag = "Array"
		} else if o.callable {
			tag = "Function"
		} else {
			tag = "Object"
		}
	default:
		if o.callable {
			tag = "Function"
		} else {
			tag = "Object"
		}
	}
	t := o.Get(symKey(SymToStringTag), o)
	if ts, ok := t.(*String); ok {
		tag = ts.String()
	}
	return "[object " + tag + "]"
}

func enumerableOwn(o *Object, kind int) []Value {
	var out []Value
	for _, k := range o.OwnKeys() {
		if k.Sym != nil {
			continue
		}
		p := o.GetOwnProperty(k)
		if p == nil || !p.Enumerable() {
			continue
		}
		switch kind {
		case 0:
			out = append(out, NewStringFromGo(k.S))
		case 1:
			out = append(out, o.Get(k, o))
		case 2:
			v := o.Get(k, o)
			out = append(out, newArrayObject([]Value{NewStringFromGo(k.S), v}))
		}
	}
	return out
}

func toPropertyDescriptor(v Value) PropDesc {
	o, ok := v.(*Object)
	if !ok {
		throwTypeError("property descriptor must be an object")
	}
	var d PropDesc
	if o.HasProperty(strKey("enumerable")) {
		d.HasEnumerable = true
		d.Enumerable = toBoolean(o.Get(strKey("enumerable"), o))
	}
	if o.HasProperty(strKey("configurable")) {
		d.HasConfigurable = true
		d.Configurable = toBoolean(o.Get(strKey("configurable"), o))
	}
	if o.HasProperty(strKey("value")) {
		d.HasValue = true
		d.Value = o.Get(strKey("value"), o)
	}
	if o.HasProperty(strKey("writable")) {
		d.HasWritable = true
		d.Writable = toBoolean(o.Get(strKey("writable"), o))
	}
	if o.HasProperty(strKey("get")) {
		g := o.Get(strKey("get"), o)
		if !isUndefined(g) && !isCallable(g) {
			throwTypeError("invalid getter")
		}
		d.HasGet = true
		d.Get = g
	}
	if o.HasProperty(strKey("set")) {
		s := o.Get(strKey("set"), o)
		if !isUndefined(s) && !isCallable(s) {
			throwTypeError("invalid setter")
		}
		d.HasSet = true
		d.Set = s
	}
	if (d.HasGet || d.HasSet) && (d.HasValue || d.HasWritable) {
		throwTypeError("cannot have both accessor and value properties in descriptor")
	}
	return d
}

func fromPropertyDescriptor(p *Prop) Value {
	o := newObjectRaw(rt.ObjectPrototype, ClassObject)
	if p.IsAccessor() {
		o.setOwn("get", p.Getter, PropDefault)
		o.setOwn("set", p.Setter, PropDefault)
	} else {
		o.setOwn("value", p.Value, PropDefault)
		o.setOwn("writable", p.Writable(), PropDefault)
	}
	o.setOwn("enumerable", p.Enumerable(), PropDefault)
	o.setOwn("configurable", p.Configurable(), PropDefault)
	return o
}

func objectDefineProperties(o *Object, propsv Value) {
	props := toObject(propsv)
	type kd struct {
		k PropKey
		d PropDesc
	}
	var list []kd
	for _, k := range props.OwnKeys() {
		p := props.GetOwnProperty(k)
		if p == nil || !p.Enumerable() {
			continue
		}
		list = append(list, kd{k, toPropertyDescriptor(props.Get(k, props))})
	}
	for _, e := range list {
		if !o.DefineOwnProperty(e.k, e.d) {
			throwTypeError("cannot define property '%s'", keyToDisplay(e.k))
		}
	}
}

func setIntegrityLevel(o *Object, frozen bool) bool {
	if !o.PreventExtensions() {
		return false
	}
	if o.class == ClassArray && !ad_sparse(o) {
		if frozen {
			o.frozenHint = true
			o.arrayData().lengthWritable = false
		} else {
			o.sealedHint = true
		}
	}
	if o.class == ClassTypedArray && frozen && typedArrayLength(o) > 0 {
		throwTypeError("cannot freeze typed array with elements")
	}
	for _, k := range o.OwnKeys() {
		if o.class == ClassArray && k.Sym == nil && k.IsIndex() && !ad_sparse(o) {
			continue
		}
		d := PropDesc{Configurable: false, HasConfigurable: true}
		if frozen {
			p := o.GetOwnProperty(k)
			if p != nil && !p.IsAccessor() {
				d.Writable = false
				d.HasWritable = true
			}
		}
		o.DefineOwnProperty(k, d)
	}
	return true
}

func testIntegrityLevel(o *Object, frozen bool) bool {
	if o.IsExtensible() {
		return false
	}
	for _, k := range o.OwnKeys() {
		p := o.GetOwnProperty(k)
		if p == nil {
			continue
		}
		if p.Configurable() {
			return false
		}
		if frozen && !p.IsAccessor() && p.Writable() {
			return false
		}
	}
	return true
}

type groupEntry struct {
	key   Value
	items []Value
}

func groupBy(items Value, cb Value, propertyKeys bool) []*groupEntry {
	if isNullish(items) {
		throwTypeError("items is not iterable")
	}
	if !isCallable(cb) {
		throwTypeError("not a function")
	}
	var groups []*groupEntry
	it := getIterator(items)
	k := 0
	for {
		v, ok := it.step()
		if !ok {
			break
		}
		var key Value
		func() {
			defer func() {
				if r := recover(); r != nil {
					iteratorCloseSwallow(it)
					panic(r)
				}
			}()
			key = callValue(cb, Undefined, []Value{v, float64(k)})
			if propertyKeys {
				pk := toPropertyKey(key)
				key = pk.ToValue()
			} else {
				if f, ok := key.(float64); ok && f == 0 {
					key = float64(0)
				}
			}
		}()
		found := false
		for _, g := range groups {
			if sameValue(g.key, key) {
				g.items = append(g.items, v)
				found = true
				break
			}
		}
		if !found {
			groups = append(groups, &groupEntry{key: key, items: []Value{v}})
		}
		k++
	}
	return groups
}

// ---------- Function ----------

func setupFunction() {
	proto := rt.FunctionPrototype
	proto.setOwn("length", float64(0), PropConfigurable)
	proto.setOwn("name", emptyString, PropConfigurable)
	ctor := newNativeConstructor("Function", 1, func(this Value, args []Value) Value {
		return createDynamicFunction(args, "function", nil)
	}, func(args []Value, nt *Object) Value {
		return createDynamicFunction(args, "function", nt)
	}, proto)
	rt.FunctionCtor = ctor
	rt.Global.setOwn("Function", ctor, PropHidden)

	proto.defineMethod("call", 1, func(this Value, args []Value) Value {
		f, ok := this.(*Object)
		if !ok || !f.callable {
			throwTypeError("not a function")
		}
		var rest []Value
		if len(args) > 1 {
			rest = args[1:]
		}
		return callFunction(f, arg(args, 0), rest)
	})
	proto.defineMethod("apply", 2, func(this Value, args []Value) Value {
		f, ok := this.(*Object)
		if !ok || !f.callable {
			throwTypeError("not a function")
		}
		var list []Value
		if a := arg(args, 1); !isNullish(a) {
			list = createListFromArrayLike(a)
		}
		return callFunction(f, arg(args, 0), list)
	})
	proto.defineMethod("bind", 1, func(this Value, args []Value) Value {
		f, ok := this.(*Object)
		if !ok || !f.callable {
			throwTypeError("not a function")
		}
		var bargs []Value
		if len(args) > 1 {
			bargs = append(bargs, args[1:]...)
		}
		bf := &Function{boundTarget: f, boundThis: arg(args, 0), boundArgs: bargs}
		bo := newObjectRaw(f.GetPrototypeOf(), ClassFunction)
		bo.internal = bf
		bo.callable = true
		bo.ctor = f.ctor
		// length
		l := 0.0
		if f.HasOwnProperty(strKey("length")) {
			lv := f.Get(strKey("length"), f)
			if lf, ok := lv.(float64); ok {
				if math.IsInf(lf, 1) {
					l = lf
				} else if math.IsInf(lf, -1) {
					l = 0
				} else {
					l = math.Max(0, math.Trunc(lf)-float64(len(bargs)))
				}
			}
		}
		bo.setOwn("length", l, PropConfigurable)
		nv := f.Get(strKey("name"), f)
		name := ""
		if ns, ok := nv.(*String); ok {
			name = ns.String()
		}
		bo.setOwn("name", NewStringFromGo("bound "+name), PropConfigurable)
		bf.name = "bound " + name
		return bo
	})
	proto.defineMethod("toString", 0, func(this Value, args []Value) Value {
		f, ok := this.(*Object)
		if !ok || !f.callable {
			throwTypeError("not a function")
		}
		return NewStringFromGo(functionToString(f))
	})
	proto.defineMethodSym(SymHasInstance, "[Symbol.hasInstance]", 1, func(this Value, args []Value) Value {
		f, ok := this.(*Object)
		if !ok {
			return false
		}
		return ordinaryHasInstance(f, arg(args, 0))
	})
	proto.props.Get(symKey(SymHasInstance)).Flags = 0
	// ThrowTypeError
	rt.ThrowTypeError = newNativeFunction("", 0, func(this Value, args []Value) Value {
		throwTypeError("'caller', 'callee', and 'arguments' properties may not be accessed")
		return nil
	})
	rt.ThrowTypeError.extensible = false
	proto.props.Set(strKey("caller"), Prop{Getter: rt.ThrowTypeError, Setter: rt.ThrowTypeError, Flags: PropAccessor | PropConfigurable})
	proto.props.Set(strKey("arguments"), Prop{Getter: rt.ThrowTypeError, Setter: rt.ThrowTypeError, Flags: PropAccessor | PropConfigurable})
}

func functionToString(f *Object) string {
	fn, ok := f.internal.(*Function)
	if !ok {
		return "function () {\n    [native code]\n}"
	}
	if fn.node != nil {
		if fn.classSrc != "" {
			return fn.classSrc
		}
		if fn.node.Source != "" {
			return fn.node.Source
		}
	}
	if fn.boundTarget != nil {
		return "function () {\n    [native code]\n}"
	}
	return "function " + fn.name + "() {\n    [native code]\n}"
}

func createDynamicFunction(args []Value, kind string, nt *Object) Value {
	var params []string
	body := ""
	if len(args) > 0 {
		for _, a := range args[:len(args)-1] {
			params = append(params, toGoString(a))
		}
		body = toGoString(args[len(args)-1])
	}
	prefix := "function"
	switch kind {
	case "async":
		prefix = "async function"
	case "generator":
		prefix = "function*"
	case "asyncGenerator":
		prefix = "async function*"
	}
	src := "(" + prefix + " anonymous(" + strings.Join(params, ",") + "\n) {\n" + body + "\n})"
	p := NewParser(src, "<input>", false)
	prog, err := p.ParseProgram()
	if err != nil {
		se := err.(*SyntaxError)
		e := makeError("SyntaxError", se.Msg)
		e.setOwn("stack", NewStringFromGo(formatSyntaxStack("<input>", se)), PropHidden)
		panic(&Throw{Val: e})
	}
	if len(prog.Body) != 1 {
		throwSyntaxError("invalid function body")
	}
	es, ok := prog.Body[0].(*ExprStmt)
	if !ok {
		throwSyntaxError("invalid function body")
	}
	var fnode *FuncNode
	switch x := es.X.(type) {
	case *ParenExpr:
		fnode, ok = x.X.(*FuncNode)
	case *FuncNode:
		fnode = x
		ok = true
	}
	if !ok || fnode == nil {
		throwSyntaxError("invalid function body")
	}
	fnode.HasOwnName = false
	fnode.Source = src[1 : len(src)-1]
	source := NewSource("<input>", src)
	act := &Activation{this: rt.Global, thisInit: true, newTarget: Undefined, src: source}
	fo := makeFunctionObject(fnode, nil, act, source, nil, nil)
	if nt != nil {
		var fallback *Object
		switch kind {
		case "async":
			fallback = rt.AsyncFunctionPrototype
		case "generator":
			fallback = rt.GeneratorFunctionPrototype
		case "asyncGenerator":
			fallback = rt.AsyncGeneratorFunctionPrototype
		default:
			fallback = rt.FunctionPrototype
		}
		fo.proto = getPrototypeFromCtor(nt, fallback)
	}
	return fo
}
