			rt.ErrorProtos[n] = proto
		}
		length := 1
		if n == "AggregateError" {
			length = 2
		}
		mk := func(args []Value, nt *Object) Value {
			p := getPrototypeFromCtor(nt, rt.ErrorProtos[n])
			e := newObjectRaw(p, ClassError)
			msgIdx := 0
			if n == "AggregateError" {
				msgIdx = 1
			}
			msg := arg(args, msgIdx)
			if !isUndefined(msg) {
				e.setOwn("message", toString(msg), PropHidden)
			}
			opts := arg(args, msgIdx+1)
			if oo, ok := opts.(*Object); ok && oo.HasProperty(strKey("cause")) {
				e.setOwn("cause", oo.Get(strKey("cause"), oo), PropHidden)
			}
			if n == "AggregateError" {
				errs := iterableToList(arg(args, 0))
				e.setOwn("errors", newArrayObject(errs), PropHidden)
			}
			e.setOwn("stack", NewStringFromGo(buildStackTrace(1)), PropHidden)
			return e
		}
		ctor := newNativeConstructor(n, length, func(this Value, args []Value) Value {
			return mk(args, nil)
		}, mk, proto)
		if n == "Error" {
			baseCtor = ctor
		} else {
			ctor.proto = baseCtor
		}
		proto.setOwn("name", NewStringFromGo(n), PropHidden)
		proto.setOwn("message", emptyString, PropHidden)
		rt.ErrorCtors[n] = ctor
		rt.Global.setOwn(n, ctor, PropHidden)
	}
	baseProto.defineMethod("toString", 0, func(this Value, args []Value) Value {
		o, ok := this.(*Object)
		if !ok {
			throwTypeError("not an object")
		}
		nv := o.Get(strKey("name"), o)
		name := "Error"
		if !isUndefined(nv) {
			name = toGoString(nv)
		}
		mv := o.Get(strKey("message"), o)
		msg := ""
		if !isUndefined(mv) {
			msg = toGoString(mv)
		}
		if name == "" {
			return NewStringFromGo(msg)
		}
		if msg == "" {
			return NewStringFromGo(name)
		}
		return NewStringFromGo(name + ": " + msg)
	})
	// Error.prepareStackTrace / captureStackTrace are absent in this build
	_ = strings.TrimSpace
}

func errorToDisplayString(v Value) string {
	// used for uncaught errors: "Name: message" plus stack
	return toGoString(v)
}
