func toFixed(n float64, digits int) string {
	// use big arithmetic for exact decimal rounding (round half up on exact binary value)
	neg := n < 0 || (n == 0 && math.Signbit(n))
	if neg {
		n = -n
	}
	bf := new(big.Float).SetPrec(2000).SetFloat64(n)
	scale := new(big.Float).SetPrec(2000).SetInt(new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(digits)), nil))
	bf.Mul(bf, scale)
	// round half up
	half := new(big.Float).SetPrec(2000).SetFloat64(0.5)
	bf.Add(bf, half)
	bi, _ := bf.Int(nil)
	s := bi.String()
	if digits > 0 {
		for len(s) <= digits {
			s = "0" + s
		}
		s = s[:len(s)-digits] + "." + s[len(s)-digits:]
	}
	if neg && n != 0 {
		s = "-" + s
	} else if neg && n == 0 {
		s = "-" + s
	}
	return s
}

func toPrecision(n float64, p int) string {
	if n == 0 {
		s := "0"
		if p > 1 {
			s += "." + strings.Repeat("0", p-1)
		}
		if math.Signbit(n) {
			return "-" + s
		}
		return s
	}
	neg := n < 0
	if neg {
		n = -n
	}
	// get p significant digits with correct rounding
	s := strconv.FormatFloat(n, 'e', p-1, 64) // d.ddde±xx
	epos := strings.IndexByte(s, 'e')
	mant := strings.Replace(s[:epos], ".", "", 1)
	e, _ := strconv.Atoi(s[epos+1:])
	var out string
	if e < -6 || e >= p {
		out = mant[:1]
		if p > 1 {
			out += "." + mant[1:]
		}
		if e >= 0 {
			out += "e+" + strconv.Itoa(e)
		} else {
			out += "e-" + strconv.Itoa(-e)
		}
	} else if e == p-1 {
		out = mant
	} else if e >= 0 {
		out = mant[:e+1] + "." + mant[e+1:]
	} else {
		out = "0." + strings.Repeat("0", -e-1) + mant
	}
	if neg {
		out = "-" + out
	}
	return out
}

func toExponential(n float64, f int) string {
	neg := n < 0
	if neg {
		n = -n
	}
	var s string
	if f < 0 {
		s = strconv.FormatFloat(n, 'e', -1, 64)
	} else {
		s = strconv.FormatFloat(n, 'e', f, 64)
	}
	epos := strings.IndexByte(s, 'e')
	mant := s[:epos]
	e, _ := strconv.Atoi(s[epos+1:])
	out := mant
	if e >= 0 {
		out += "e+" + strconv.Itoa(e)
	} else {
		out += "e-" + strconv.Itoa(-e)
	}
	if neg {
		out = "-" + out
	}
	return out
}

const digitChars = "0123456789abcdefghijklmnopqrstuvwxyz"

func numberToStringRadix(n float64, radix int) string {
	if n != n {
		return "NaN"
	}
	if math.IsInf(n, 1) {
		return "Infinity"
	}
	if math.IsInf(n, -1) {
		return "-Infinity"
	}
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	ip := math.Floor(n)
	fp := n - ip
	var sb strings.Builder
	// integer part
	if ip == 0 {
		sb.WriteByte('0')
	} else if ip < 1e21 {
		// exact via big int
		bi, _ := new(big.Float).SetFloat64(ip).Int(nil)
		sb.WriteString(bi.Text(radix))
	} else {
		bi, _ := new(big.Float).SetFloat64(ip).Int(nil)
		sb.WriteString(bi.Text(radix))
	}
	if fp > 0 {
		sb.WriteByte('.')
		// generate digits until the fraction is uniquely identified (like V8/QuickJS: use delta approach)
		delta := 0.5 * (math.Nextafter(n, math.Inf(1)) - n)
		delta = math.Max(math.Nextafter(0, 1), delta)
		if delta > 0 {
			for {
				fp *= float64(radix)
				delta *= float64(radix)
				d := int(fp)
				fp -= float64(d)
				if fp > 0.5 || (fp == 0.5 && (d&1) == 1) {
					if fp+delta > 1 {
						// round up and propagate
						for {
							d++
							if d < radix {
								break
							}
							// carry: need to fix previous digit; rare -- fall back
							d = radix - 1
							break
						}
						sb.WriteByte(digitChars[d])
						break
					}
				}
				sb.WriteByte(digitChars[d])
				if fp < delta {
					break
				}
			}
		}
	}
	s := sb.String()
	if neg {
		return "-" + s
	}
	return s
}

