		if len(args) == 0 {
			return float64(0)
		}
		nums := make([]float64, len(args))
		for i, a := range args {
			nums[i] = toNumber(a)
		}
		inf := false
		nan := false
		for _, n := range nums {
			if math.IsInf(n, 0) {
				inf = true
			}
			if n != n {
				nan = true
			}
		}
		if inf {
			return math.Inf(1)
		}
		if nan {
			return math.NaN()
		}
		sum := 0.0
		for _, n := range nums {
			sum += n * n
		}
		return math.Sqrt(sum)
	})
	m.defineMethod("random", 0, func(this Value, args []Value) Value {
		return randFloat()
	})
	m.defineMethod("sumPrecise", 1, func(this Value, args []Value) Value {
		// Kahan-ish via big.Float
		sum := new(big.Float).SetPrec(2000)
		it := getIterator(arg(args, 0))
		anyInf := 0
		nan := false
		for {
			v, ok := it.step()
			if !ok {
				break
			}
			f, isNum := v.(float64)
			if !isNum {
				iteratorCloseSwallow(it)
				throwTypeError("not a number")
			}
			if f != f {
				nan = true
				continue
			}
			if math.IsInf(f, 1) {
				if anyInf < 0 {
					nan = true
				}
				anyInf = 1
				continue
			}
			if math.IsInf(f, -1) {
				if anyInf > 0 {
					nan = true
				}
				anyInf = -1
				continue
			}
			sum.Add(sum, new(big.Float).SetFloat64(f))
		}
		if nan {
			return math.NaN()
		}
		if anyInf != 0 {
			return math.Inf(anyInf)
		}
		r, _ := sum.Float64()
		if r == 0 && sum.Sign() == 0 {
			return math.Copysign(0, -1)
		}
		return r
	})
