func parseIntJS(s *String, radixV Value) Value {
	str := trimJSSpace(s)
	i := 0
	n := str.Len()
	sign := 1.0
	if i < n && (str.At(i) == '+' || str.At(i) == '-') {
		if str.At(i) == '-' {
			sign = -1
		}
		i++
	}
	radix := int(toInt32V(radixV))
	stripPrefix := true
	if radix != 0 {
		if radix < 2 || radix > 36 {
			return math.NaN()
		}
		if radix != 16 {
			stripPrefix = false
		}
	} else {
		radix = 10
	}
	if stripPrefix && i+1 < n && str.At(i) == '0' && (str.At(i+1) == 'x' || str.At(i+1) == 'X') {
		i += 2
		radix = 16
	}
	start := i
	for i < n {
		c := str.At(i)
		d := -1
		if c < 128 {
			d = hexVal(byte(c))
			if d < 0 && c >= 'g' && c <= 'z' {
				d = int(c-'a') + 10
			} else if d < 0 && c >= 'G' && c <= 'Z' {
				d = int(c-'A') + 10
			}
		}
		if d < 0 || d >= radix {
			break
		}
		i++
	}
	if i == start {
		return math.NaN()
	}
	digits := str.Substring(start, i).String()
	var v float64
	if radix == 10 {
		v, _ = strconv.ParseFloat(digits, 64)
	} else {
		v = parseIntRadix(digits, radix)
	}
	return sign * v
}

func parseFloatJS(s *String) Value {
	str := trimJSSpace(s).String()
	// find longest prefix that is a StrDecimalLiteral
	i := 0
	n := len(str)
	if i < n && (str[i] == '+' || str[i] == '-') {
		i++
	}
	if strings.HasPrefix(str[i:], "Infinity") {
		if str[0] == '-' {
			return math.Inf(-1)
		}
		return math.Inf(1)
	}
	digits := 0
	for i < n && str[i] >= '0' && str[i] <= '9' {
		i++
		digits++
	}
	if i < n && str[i] == '.' {
		j := i + 1
		fd := 0
		for j < n && str[j] >= '0' && str[j] <= '9' {
			j++
			fd++
		}
		if fd > 0 || digits > 0 {
			i = j
			digits += fd
		}
	}
	if digits == 0 {
		return math.NaN()
	}
	if i < n && (str[i] == 'e' || str[i] == 'E') {
		j := i + 1
		if j < n && (str[j] == '+' || str[j] == '-') {
			j++
		}
		ed := 0
		for j < n && str[j] >= '0' && str[j] <= '9' {
			j++
			ed++
		}
		if ed > 0 {
			i = j
		}
	}
	f, err := strconv.ParseFloat(str[:i], 64)
	if err != nil {
		if ne, ok := err.(*strconv.NumError); ok && ne.Err == strconv.ErrRange {
			return f
		}
		return math.NaN()
	}
	return f
}

func float16Round(x float64) float64 {
	if x != x || math.IsInf(x, 0) || x == 0 {
		return x
	}
	bits := float64ToFloat16(x)
	return float16ToFloat64(bits)
}

func float64ToFloat16(f float64) uint16 {
	// round-to-nearest-even conversion
	sign := uint16(0)
	if f < 0 || (f == 0 && math.Signbit(f)) {
		sign = 0x8000
		f = -f
	}
	if f != f {
		return 0x7e00
	}
	if math.IsInf(f, 0) {
		return sign | 0x7c00
	}
	if f == 0 {
		return sign
	}
	// scale
	e := math.Floor(math.Log2(f))
	if e < -14 {
		// subnormal: value = m * 2^-24
		m := f / math.Pow(2, -24)
		mr := roundHalfEven(m)
		if mr >= 1024 {
			return sign | 0x0400
		}
		return sign | uint16(mr)
	}
	if e > 15 {
		return sign | 0x7c00
	}
	m := f/math.Pow(2, e) - 1 // in [0,1)
	mr := roundHalfEven(m * 1024)
	if mr >= 1024 {
		e++
		mr = 0
		if e > 15 {
			return sign | 0x7c00
		}
	}
	return sign | uint16((int(e)+15)<<10) | uint16(mr)
}

func roundHalfEven(x float64) float64 {
	return math.RoundToEven(x)
}

func float16ToFloat64(h uint16) float64 {
	sign := 1.0
	if h&0x8000 != 0 {
		sign = -1
	}
	e := int((h >> 10) & 0x1f)
	m := float64(h & 0x3ff)
	if e == 0 {
		return sign * m * math.Pow(2, -24)
	}
	if e == 31 {
		if m == 0 {
			return sign * math.Inf(1)
		}
		return math.NaN()
	}
	return sign * (1 + m/1024) * math.Pow(2, float64(e-15))
}
