func uriEncode(s *String, unescaped string) Value {
	var sb strings.Builder
	n := s.Len()
	for i := 0; i < n; i++ {
		c := s.At(i)
		if c < 128 && strings.IndexByte(unescaped, byte(c)) >= 0 {
			sb.WriteByte(byte(c))
			continue
		}
		var cp rune
		if c >= 0xDC00 && c <= 0xDFFF {
			throwError("URIError", "malformed URI sequence")
		}
		if c >= 0xD800 && c <= 0xDBFF {
			i++
			if i >= n {
				throwError("URIError", "malformed URI sequence")
			}
			d := s.At(i)
			if d < 0xDC00 || d > 0xDFFF {
				throwError("URIError", "malformed URI sequence")
			}
			cp = utf16.DecodeRune(rune(c), rune(d))
		} else {
			cp = rune(c)
		}
		var buf [4]byte
		nb := encodeRuneUTF8(buf[:], cp)
		for j := 0; j < nb; j++ {
			sb.WriteString("%" + hex2(int(buf[j])))
		}
	}
	return NewStringFromGo(sb.String())
}

func encodeRuneUTF8(buf []byte, r rune) int {
	switch {
	case r < 0x80:
		buf[0] = byte(r)
		return 1
	case r < 0x800:
		buf[0] = byte(0xC0 | r>>6)
		buf[1] = byte(0x80 | r&0x3F)
		return 2
	case r < 0x10000:
		buf[0] = byte(0xE0 | r>>12)
		buf[1] = byte(0x80 | (r>>6)&0x3F)
		buf[2] = byte(0x80 | r&0x3F)
		return 3
	default:
		buf[0] = byte(0xF0 | r>>18)
		buf[1] = byte(0x80 | (r>>12)&0x3F)
		buf[2] = byte(0x80 | (r>>6)&0x3F)
		buf[3] = byte(0x80 | r&0x3F)
		return 4
	}
}

func uriDecode(s *String, reserved string) Value {
	var out []uint16
	n := s.Len()
	for i := 0; i < n; i++ {
		c := s.At(i)
		if c != '%' {
			out = append(out, c)
			continue
		}
		start := i
		if i+2 >= n {
			throwError("URIError", "malformed URI sequence")
		}
		b, ok := hexByte(s, i+1)
		if !ok {
			throwError("URIError", "malformed URI sequence")
		}
		i += 2
		if b < 0x80 {
			if strings.IndexByte(reserved, byte(b)) >= 0 {
				for j := start; j <= i; j++ {
					out = append(out, s.At(j))
				}
			} else {
				out = append(out, uint16(b))
			}
			continue
		}
		var nbytes int
		switch {
		case b&0xE0 == 0xC0:
			nbytes = 2
		case b&0xF0 == 0xE0:
			nbytes = 3
		case b&0xF8 == 0xF0:
			nbytes = 4
		default:
			throwError("URIError", "malformed URI sequence")
		}
		if i+3*(nbytes-1) >= n {
			throwError("URIError", "malformed URI sequence")
		}
		cp := rune(b) & (0x7F >> uint(nbytes))
		for k := 1; k < nbytes; k++ {
			if s.At(i+1) != '%' {
				throwError("URIError", "malformed URI sequence")
			}
			bb, ok := hexByte(s, i+2)
			if !ok || bb&0xC0 != 0x80 {
				throwError("URIError", "malformed URI sequence")
			}
			cp = cp<<6 | rune(bb&0x3F)
			i += 3
		}
		if cp < 0x80 || (nbytes == 3 && cp < 0x800) || (nbytes == 4 && cp < 0x10000) || cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF) {
			throwError("URIError", "malformed URI sequence")
		}
		if cp >= 0x10000 {
			r1, r2 := utf16.EncodeRune(cp)
			out = append(out, uint16(r1), uint16(r2))
		} else {
			out = append(out, uint16(cp))
		}
	}
	return NewStringFromUTF16(out)
}

func hexByte(s *String, i int) (int, bool) {
	if i+1 >= s.Len() {
		return 0, false
	}
	a, b := s.At(i), s.At(i+1)
	if a >= 128 || b >= 128 {
		return 0, false
	}
	d1, d2 := hexVal(byte(a)), hexVal(byte(b))
	if d1 < 0 || d2 < 0 {
		return 0, false
	}
	return d1*16 + d2, true
}
