}

func hex2(v int) string {
	const h = "0123456789ABCDEF"
	return string([]byte{h[(v>>4)&0xf], h[v&0xf]})
}

func uriEncode(s *String, unescaped string) Value {
	var sb strings.Builder
	n := s.Len()
	for i := 0; i < n; i++ {
		c := s.At(i)
		if c < 128 && strings.IndexByte(unescaped, byte(c)) >= 0 {
			sb.WriteByte(byte(c))
			continue
		}
		var cp rune
		if c >= 0xDC00 && c <= 0xDFFF {
			throwError("URIError", "malformed URI sequence")
		}
		if c >= 0xD800 && c <= 0xDBFF {
			i++
			if i >= n {
