type arrayIterState struct {
	obj  *Object
	idx  int64
	kind int
	done bool
}

func (ai *arrayIterState) next() Value {
	if ai.done {
		return createIterResult(Undefined, true)
	}
	o := ai.obj
	var n int64
	if o.class == ClassTypedArray {
		if typedArrayIsOutOfBounds(o) {
			throwTypeError("typed array is detached or out of bounds")
		}
		n = int64(typedArrayLength(o))
	} else {
		n = lengthOfArrayLike(o)
	}
	if ai.idx >= n {
		ai.done = true
		return createIterResult(Undefined, true)
	}
	i := ai.idx
	ai.idx++
	switch ai.kind {
	case 0:
		return createIterResult(float64(i), false)
	case 1:
		return createIterResult(o.Get(idxKey(i), o), false)
	default:
		return createIterResult(newArrayObject([]Value{float64(i), o.Get(idxKey(i), o)}), false)
	}
}

func newArrayIterator(o *Object, kind int) *Object {
	it := newObjectRaw(rt.ArrayIteratorPrototype, ClassIterator)
	it.internal = &arrayIterState{obj: o, kind: kind}
	return it
}

func (r *Realm) arrayIterNextIntact() bool {
	p := r.ArrayIteratorPrototype.props.Get(strKey("next"))
	return p != nil && p.Value == Value(r.arrayIterNext)
}

func relIndex(v Value, n int64, def int64) int64 {
	if isUndefined(v) {
		return def
	}
	f := toIntegerOrInfinity(v)
	if f < 0 {
		r := float64(n) + f
		if r < 0 {
			return 0
		}
		return int64(r)
	}
	if f > float64(n) {
		return n
	}
	return int64(f)
}

func arrayJoin(o *Object, sep *String) Value {
	n := lengthOfArrayLike(o)
	if rt.joinDepth > 0 {
		for _, x := range rt.joinStack {
			if x == o {
				return emptyString
			}
		}
	}
	rt.joinStack = append(rt.joinStack, o)
	rt.joinDepth++
	defer func() {
		rt.joinDepth--
		rt.joinStack = rt.joinStack[:len(rt.joinStack)-1]
	}()
	sb := NewStringBuilder()
	for k := int64(0); k < n; k++ {
		if k > 0 {
			sb.WriteString(sep)
		}
		v := o.Get(idxKey(k), o)
		if !isNullish(v) {
			sb.WriteString(toString(v))
		}
	}
	return sb.String()
}

func collectForSort(o *Object, n int64) ([]Value, int64) {
	var items []Value
	holes := int64(0)
	for k := int64(0); k < n; k++ {
		pk := idxKey(k)
		if o.HasProperty(pk) {
			items = append(items, o.Get(pk, o))
		} else {
			holes++
		}
	}
	return items, holes
}

func sortValues(items []Value, cmp Value) {
	// undefined values sort to the end
	var defined []Value
	undef := 0
	for _, v := range items {
		if isUndefined(v) {
			undef++
		} else {
			defined = append(defined, v)
		}
	}
	less := func(a, b Value) bool {
		if !isUndefined(cmp) {
			r := toNumber(callValue(cmp, Undefined, []Value{a, b}))
			return r < 0
		}
		sa, sb := toString(a), toString(b)
		return sa.Compare(sb) < 0
	}
	sort.SliceStable(defined, func(i, j int) bool { return less(defined[i], defined[j]) })
	copy(items, defined)
	for i := len(defined); i < len(items); i++ {
		items[i] = Undefined
	}
}

func flattenInto(target *Object, src *Object, n int64, idx *int64, depth float64, mapper *Object, thisArg Value) {
	for k := int64(0); k < n; k++ {
		pk := idxKey(k)
		if !src.HasProperty(pk) {
			continue
		}
		el := src.Get(pk, src)
		if mapper != nil {
			el = callFunction(mapper, thisArg, []Value{el, float64(k), src})
		}
		if depth > 0 && isArray(el) {
			eo := el.(*Object)
			flattenInto(target, eo, lengthOfArrayLike(eo), idx, depth-1, nil, Undefined)
		} else {
			target.CreateDataPropertyOrThrow(idxKey(*idx), el)
			*idx++
		}
	}
}

func arrayFromAsync(this Value, args []Value) Value {
	p, res, rej := newPromiseCapability(rt.PromiseCtor)
	// implement via an async-like coroutine using native awaiting
	items := arg(args, 0)
	mapFn := arg(args, 1)
	thisArg := arg(args, 2)
	func() {
		defer func() {
			if r := recover(); r != nil {
				if t, ok := r.(*Throw); ok {
					callFunction(rej, Undefined, []Value{t.Val})
					return
				}
				panic(r)
			}
		}()
		if !isUndefined(mapFn) && !isCallable(mapFn) {
			throwTypeError("not a function")
		}
		var a *Object
		if isConstructor(this) && this != Value(rt.ArrayCtor) {
			a = construct(this.(*Object), nil, nil).(*Object)
		} else {
			a = newArrayObject(nil)
		}
		var iter *Iterator
		usingAsync := getMethod(items, symKey(SymAsyncIterator))
		if usingAsync != nil {
			iter = getIteratorFromMethod(items, usingAsync)
			iter.isAsync = true
		} else if m := getMethod(items, symKey(SymIterator)); m != nil {
			iter = createAsyncFromSyncIterator(getIteratorFromMethod(items, m))
		}
		k := int64(0)
		var step func()
		finish := func() {
			a.Set(strKey("length"), float64(k), a)
			callFunction(res, Undefined, []Value{a})
		}
		if iter == nil {
			// array-like
			src := toObject(items)
			n := lengthOfArrayLike(src)
			var loop func()
			loop = func() {
				if k >= n {
					finish()
					return
				}
				v := src.Get(idxKey(k), src)
				onVal := func(v Value) {
					defer catchToReject(rej)
					if !isUndefined(mapFn) {
						mv := callValue(mapFn, thisArg, []Value{v, float64(k)})
						pr := promiseResolve(rt.PromiseCtor, mv)
						performPromiseThenNative(pr, func(mv Value) {
							defer catchToReject(rej)
							a.CreateDataPropertyOrThrow(idxKey(k), mv)
							k++
							loop()
						}, func(e Value) { callFunction(rej, Undefined, []Value{e}) })
						return
					}
					a.CreateDataPropertyOrThrow(idxKey(k), v)
					k++
					loop()
				}
				pr := promiseResolve(rt.PromiseCtor, v)
				performPromiseThenNative(pr, onVal, func(e Value) { callFunction(rej, Undefined, []Value{e}) })
			}
			loop()
			return
		}
		step = func() {
			defer catchToReject(rej)
			r := iter.nextRaw(nil)
			pr := promiseResolve(rt.PromiseCtor, r)
			performPromiseThenNative(pr, func(result Value) {
				defer catchToReject(rej)
				ro, ok := result.(*Object)
				if !ok {
					throwTypeError("iterator result is not an object")
				}
				if toBoolean(ro.Get(strKey("done"), ro)) {
					finish()
					return
				}
				v := ro.Get(strKey("value"), ro)
				if !isUndefined(mapFn) {
					mv := callValue(mapFn, thisArg, []Value{v, float64(k)})
					pr2 := promiseResolve(rt.PromiseCtor, mv)
					performPromiseThenNative(pr2, func(mv Value) {
						defer catchToReject(rej)
						a.CreateDataPropertyOrThrow(idxKey(k), mv)
						k++
						step()
					}, func(e Value) { callFunction(rej, Undefined, []Value{e}) })
					return
				}
				a.CreateDataPropertyOrThrow(idxKey(k), v)
				k++
				step()
			}, func(e Value) { callFunction(rej, Undefined, []Value{e}) })
		}
		step()
	}()
	return p
}

func catchToReject(rej *Object) {
	if r := recover(); r != nil {
		if t, ok := r.(*Throw); ok {
