			return NewStringFromGo(s.DescriptiveString())
		}
		return toString(args[0])
	}, func(args []Value, nt *Object) Value {
		var s *String = emptyString
		if len(args) > 0 {
			s = toString(args[0])
		}
		o := newObjectRaw(getPrototypeFromCtor(nt, rt.StringPrototype), ClassString)
		o.internal = s
		return o
	}, proto)
