	})
	ctor.defineMethod("fromCodePoint", 1, func(this Value, args []Value) Value {
		var u []uint16
		for _, a := range args {
			n := toNumber(a)
			if n != math.Trunc(n) || n < 0 || n > 0x10FFFF {
				throwRangeError("invalid code point")
			}
			cp := rune(n)
			if cp >= 0x10000 {
				r1, r2 := utf16.EncodeRune(cp)
				u = append(u, uint16(r1), uint16(r2))
			} else {
				u = append(u, uint16(cp))
			}
