	proto.defineMethod("split", 2, func(this Value, args []Value) Value {
		if isNullish(this) {
			throwTypeError("cannot convert to object")
		}
		sep := arg(args, 0)
		if !isNullish(sep) {
			if m := getMethod(sep, symKey(SymSplit)); m != nil {
				return callFunction(m, sep, []Value{this, arg(args, 1)})
			}
		}
		s := toString(this)
		lim := uint32(0xFFFFFFFF)
		if !isUndefined(arg(args, 1)) {
			lim = toUint32V(arg(args, 1))
		}
		sepS := toString(sep)
		if lim == 0 {
			return newArrayObject(nil)
		}
		if isUndefined(sep) {
			return newArrayObject([]Value{s})
		}
		var out []Value
		if sepS.Len() == 0 {
			for i := 0; i < s.Len() && uint32(len(out)) < lim; i++ {
				out = append(out, s.Substring(i, i+1))
			}
			return newArrayObject(out)
		}
		p := 0
		for {
			q := s.IndexOf(sepS, p)
			if q < 0 {
				break
			}
			out = append(out, s.Substring(p, q))
			if uint32(len(out)) >= lim {
				return newArrayObject(out)
			}
			p = q + sepS.Len()
		}
		out = append(out, s.Substring(p, s.Len()))
		return newArrayObject(out)
	})
