type stringIterState struct {
	s   *String
	pos int
}

func clampIndex(f float64, n int) float64 {
	if f < 0 {
		return 0
	}
	if f > float64(n) {
		return float64(n)
	}
	return f
}

func stringPad(s *String, maxLenV Value, fillV Value, start bool) Value {
	maxLen := toLength(maxLenV)
	if maxLen <= int64(s.Len()) {
		return s
	}
	fill := NewStringFromGo(" ")
	if !isUndefined(fillV) {
		fill = toString(fillV)
	}
	if fill.Len() == 0 {
		return s
	}
	fillLen := int(maxLen) - s.Len()
	if maxLen > 1<<30 {
		throwRangeError("invalid string length")
	}
	sb := NewStringBuilder()
	for sb.Len() < fillLen {
		sb.WriteString(fill)
	}
	padding := sb.String().Substring(0, fillLen)
	if start {
		return padding.Concat(s)
	}
	return s.Concat(padding)
}

var specialUpper = map[rune]string{
	0x00DF: "SS", 0x0149: "\u02BCN", 0x01F0: "J\u030C", 0x0390: "\u0399\u0308\u0301", 0x03B0: "\u03A5\u0308\u0301",
	0x0587: "\u0535\u0552", 0x1E96: "H\u0331", 0x1E97: "T\u0308", 0x1E98: "W\u030A", 0x1E99: "Y\u030A", 0x1E9A: "A\u02BE",
	0xFB00: "FF", 0xFB01: "FI", 0xFB02: "FL", 0xFB03: "FFI", 0xFB04: "FFL", 0xFB05: "ST", 0xFB06: "ST",
	0x1E9E: "\u1E9E",
}

func stringToUpper(s *String) *String {
	if s.isASCII {
		return NewStringFromGo(strings.ToUpper(s.s))
	}
	sb := NewStringBuilder()
	for i := 0; i < s.Len(); {
		cp, n := s.CodePointAt(i)
		i += n
		if sp, ok := specialUpper[cp]; ok {
			sb.WriteGo(sp)
			continue
		}
		sb.WriteRune(unicode.ToUpper(cp))
	}
	return sb.String()
}

func stringToLower(s *String) *String {
	if s.isASCII {
		return NewStringFromGo(strings.ToLower(s.s))
	}
	sb := NewStringBuilder()
	for i := 0; i < s.Len(); {
		cp, n := s.CodePointAt(i)
		i += n
		if cp == 0x0130 {
			sb.WriteGo("i\u0307")
			continue
		}
		if cp == 0x03A3 {
			// final sigma handling
			if isFinalSigma(s, i-n) {
				sb.WriteRune(0x03C2)
			} else {
				sb.WriteRune(0x03C3)
			}
			continue
		}
		sb.WriteRune(unicode.ToLower(cp))
	}
	return sb.String()
}

func isFinalSigma(s *String, pos int) bool {
	// preceded by a cased letter and not followed by one
	before := false
	for i := pos - 1; i >= 0; i-- {
		c := rune(s.At(i))
		if unicode.IsLetter(c) {
			before = true
			break
		}
		if unicode.Is(unicode.Mn, c) {
			continue
		}
		break
	}
	if !before {
		return false
	}
	for i := pos + 1; i < s.Len(); i++ {
		c := rune(s.At(i))
		if unicode.IsLetter(c) {
			return false
		}
		if unicode.Is(unicode.Mn, c) {
			continue
		}
		break
	}
	return true
}

// getSubstitution implements the $-replacement patterns
func getSubstitution(matched *String, str *String, position int, captures []Value, namedCaptures Value, replacement *String) *String {
	sb := NewStringBuilder()
	n := replacement.Len()
	m := len(captures)
	tailPos := position + matched.Len()
	for i := 0; i < n; i++ {
		c := replacement.At(i)
		if c != '$' || i+1 >= n {
			sb.WriteUnit(c)
			continue
		}
		d := replacement.At(i + 1)
		switch {
		case d == '$':
			sb.WriteUnit('$')
			i++
		case d == '&':
			sb.WriteString(matched)
			i++
		case d == '`':
			sb.WriteString(str.Substring(0, position))
			i++
		case d == '\'':
			if tailPos < str.Len() {
				sb.WriteString(str.Substring(tailPos, str.Len()))
			}
			i++
		case d >= '0' && d <= '9':
			idx := int(d - '0')
			consumed := 1
			if i+2 < n {
				d2 := replacement.At(i + 2)
				if d2 >= '0' && d2 <= '9' {
					idx2 := idx*10 + int(d2-'0')
					if idx2 >= 1 && idx2 <= m {
						idx = idx2
						consumed = 2
					}
				}
			}
			if idx >= 1 && idx <= m {
				cv := captures[idx-1]
				if !isUndefined(cv) {
					sb.WriteString(toString(cv))
				}
				i += consumed
			} else {
				sb.WriteUnit('$')
			}
		case d == '<':
			if isUndefined(namedCaptures) {
				sb.WriteUnit('$')
				continue
			}
			// find '>'
			end := -1
			for j := i + 2; j < n; j++ {
				if replacement.At(j) == '>' {
					end = j
					break
				}
			}
			if end < 0 {
				sb.WriteUnit('$')
				continue
			}
			groupName := replacement.Substring(i+2, end)
			nc := toObject(namedCaptures)
			cv := nc.Get(PropKey{S: groupName.Key()}, nc)
			if !isUndefined(cv) {
				sb.WriteString(toString(cv))
			}
			i = end
		default:
			sb.WriteUnit('$')
		}
	}
	return sb.String()
}
