type jsonParser struct {
	s   []uint16
	src *String
	pos int
}

func (p *jsonParser) fail(msg string) {
	// QuickJS reports position as line:col in stack; message is generic
	throwSyntaxErrorAt(msg, p.lineCol())
}

func (p *jsonParser) lineCol() (int, int) {
	line, col := 1, 1
	for i := 0; i < p.pos && i < len(p.s); i++ {
		if p.s[i] == '\n' {
			line++
			col = 1
		} else {
			col++
		}
	}
	return line, col
}

func throwSyntaxErrorAt(msg string, line, col int) {
	e := makeError("SyntaxError", msg)
	stack := "    at <input>:" + itoa(line) + ":" + itoa(col) + "\n" + buildStackTrace(0)
	e.setOwn("stack", NewStringFromGo(stack), PropHidden)
	panic(&Throw{Val: e})
}

func (p *jsonParser) skipWS() {
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.pos++
		} else {
			break
		}
	}
}

func (p *jsonParser) peek() int {
	if p.pos >= len(p.s) {
		return -1
	}
	return int(p.s[p.pos])
}

func (p *jsonParser) parseValue() Value {
	c := p.peek()
	switch {
	case c == '{':
		p.pos++
		obj := newObjectRaw(rt.ObjectPrototype, ClassObject)
		p.skipWS()
		if p.peek() == '}' {
			p.pos++
			return obj
		}
		for {
			p.skipWS()
			if p.peek() != '"' {
				p.fail("unexpected token in JSON")
			}
			key := p.parseString()
			p.skipWS()
			if p.peek() != ':' {
				p.fail("expecting ':'")
			}
			p.pos++
			p.skipWS()
			v := p.parseValue()
			obj.CreateDataProperty(PropKey{S: key.Key()}, v)
			p.skipWS()
			if p.peek() == ',' {
				p.pos++
				continue
			}
			if p.peek() == '}' {
				p.pos++
				return obj
			}
			p.fail("expecting ',' or '}'")
		}
	case c == '[':
		p.pos++
		var elems []Value
		p.skipWS()
		if p.peek() == ']' {
			p.pos++
			return newArrayObject(elems)
		}
		for {
			p.skipWS()
			elems = append(elems, p.parseValue())
			p.skipWS()
			if p.peek() == ',' {
				p.pos++
				continue
			}
			if p.peek() == ']' {
				p.pos++
				return newArrayObject(elems)
			}
			p.fail("expecting ',' or ']'")
		}
	case c == '"':
		return p.parseString()
	case c == 't':
		if p.matchWord("true") {
			return true
		}
	case c == 'f':
		if p.matchWord("false") {
			return false
		}
	case c == 'n':
		if p.matchWord("null") {
			return Null
		}
	case c == '-' || (c >= '0' && c <= '9'):
		return p.parseNumber()
	case c == -1:
		p.fail("unexpected end of input")
	}
	p.fail("unexpected token in JSON")
	return nil
}

func (p *jsonParser) matchWord(w string) bool {
	if p.pos+len(w) > len(p.s) {
		return false
	}
	for i := 0; i < len(w); i++ {
		if p.s[p.pos+i] != uint16(w[i]) {
			return false
		}
	}
	p.pos += len(w)
	return true
}

func (p *jsonParser) parseNumber() Value {
	start := p.pos
	if p.peek() == '-' {
		p.pos++
	}
	if p.peek() == '0' {
		p.pos++
	} else if c := p.peek(); c >= '1' && c <= '9' {
		for c := p.peek(); c >= '0' && c <= '9'; c = p.peek() {
			p.pos++
		}
	} else {
		p.fail("unexpected token in JSON")
	}
	if p.peek() == '.' {
		p.pos++
		if c := p.peek(); !(c >= '0' && c <= '9') {
			p.fail("unexpected token in JSON")
		}
		for c := p.peek(); c >= '0' && c <= '9'; c = p.peek() {
			p.pos++
		}
	}
	if c := p.peek(); c == 'e' || c == 'E' {
		p.pos++
		if c := p.peek(); c == '+' || c == '-' {
			p.pos++
		}
		if c := p.peek(); !(c >= '0' && c <= '9') {
			p.fail("unexpected token in JSON")
		}
		for c := p.peek(); c >= '0' && c <= '9'; c = p.peek() {
			p.pos++
		}
	}
	str := string(utf16.Decode(p.s[start:p.pos]))
	f, err := strconv.ParseFloat(str, 64)
	if err != nil {
		if ne, ok := err.(*strconv.NumError); ok && ne.Err == strconv.ErrRange {
			return f
		}
		p.fail("invalid number")
	}
	return f
}

func (p *jsonParser) parseString() *String {
	p.pos++ // opening quote
	var out []uint16
	for {
		if p.pos >= len(p.s) {
			p.fail("unexpected end of string")
		}
		c := p.s[p.pos]
		if c == '"' {
			p.pos++
			break
		}
		if c < 0x20 {
			p.fail("invalid character in string")
		}
		if c == '\\' {
			p.pos++
			if p.pos >= len(p.s) {
				p.fail("unexpected end of string")
			}
			e := p.s[p.pos]
			p.pos++
			switch e {
			case '"':
				out = append(out, '"')
			case '\\':
				out = append(out, '\\')
			case '/':
				out = append(out, '/')
			case 'b':
				out = append(out, '\b')
			case 'f':
				out = append(out, '\f')
			case 'n':
				out = append(out, '\n')
			case 'r':
				out = append(out, '\r')
			case 't':
				out = append(out, '\t')
			case 'u':
				if p.pos+4 > len(p.s) {
					p.fail("invalid escape")
				}
				v := 0
				for i := 0; i < 4; i++ {
					h := p.s[p.pos+i]
					d := -1
					if h < 128 {
						d = hexVal(byte(h))
					}
					if d < 0 {
						p.fail("invalid escape")
					}
					v = v*16 + d
				}
				p.pos += 4
				out = append(out, uint16(v))
			default:
				p.fail("invalid escape")
			}
			continue
		}
		out = append(out, c)
		p.pos++
	}
	return NewStringFromUTF16(out)
}

func internalizeJSON(holder *Object, k PropKey, reviver *Object) Value {
	val := holder.Get(k, holder)
	if vo, ok := val.(*Object); ok {
		if isArray(vo) {
			n := lengthOfArrayLike(vo)
			for i := int64(0); i < n; i++ {
				ik := idxKey(i)
				nv := internalizeJSON(vo, ik, reviver)
				if isUndefined(nv) {
					vo.Delete(ik)
				} else {
					vo.CreateDataProperty(ik, nv)
				}
			}
		} else {
			for _, pk := range vo.OwnKeys() {
				if pk.Sym != nil {
					continue
				}
				p := vo.GetOwnProperty(pk)
				if p == nil || !p.Enumerable() {
					continue
				}
				nv := internalizeJSON(vo, pk, reviver)
				if isUndefined(nv) {
					vo.Delete(pk)
				} else {
					vo.CreateDataProperty(pk, nv)
				}
			}
		}
	}
	return callFunction(reviver, holder, []Value{k.ToValue(), val})
}

type jsonStringifier struct {
	replacerFn   *Object
	propertyList []PropKey
	hasPropList  bool
	gap          string
	indent       string
	stack        []*Object
}

func jsonStringify(value, replacer, space Value) Value {
	st := &jsonStringifier{}
	if ro, ok := replacer.(*Object); ok {
		if ro.callable {
			st.replacerFn = ro
		} else if isArray(ro) {
			st.hasPropList = true
			n := lengthOfArrayLike(ro)
			seen := map[PropKey]bool{}
			for i := int64(0); i < n; i++ {
				v := ro.Get(idxKey(i), ro)
				var item PropKey
				ok := false
				switch x := v.(type) {
				case *String:
					item = PropKey{S: x.Key()}
					ok = true
				case float64:
					item = toPropertyKey(x)
					ok = true
				case *Object:
					if x.class == ClassString || x.class == ClassNumber {
						item = PropKey{S: toString(x).Key()}
						ok = true
					}
				}
				if ok && !seen[item] {
					seen[item] = true
					st.propertyList = append(st.propertyList, item)
				}
			}
		}
	}
	if so, ok := space.(*Object); ok {
		if so.class == ClassNumber {
			space = toNumber(so)
		} else if so.class == ClassString {
			space = toString(so)
		}
	}
	switch sp := space.(type) {
	case float64:
		n := int(math.Min(10, math.Trunc(sp)))
		if n >= 1 {
			st.gap = strings.Repeat(" ", n)
		}
	case *String:
		s := sp.String()
		if len(s) > 10 {
			// first 10 code units
			s = sp.Substring(0, 10).String()
		}
		st.gap = s
	}
	wrapper := newObjectRaw(rt.ObjectPrototype, ClassObject)
	wrapper.CreateDataProperty(strKey(""), value)
	sb := NewStringBuilder()
	ok := st.serializeProperty(sb, strKey(""), wrapper)
	if !ok {
		return Undefined
	}
	return sb.String()
}

func (st *jsonStringifier) serializeProperty(sb *StringBuilder, key PropKey, holder *Object) bool {
	value := holder.Get(key, holder)
	if vo, ok := value.(*Object); ok || isBigInt(value) {
		toJSON := getV(value, strKey("toJSON"))
		if isCallable(toJSON) {
			value = callValue(toJSON, value, []Value{key.ToValue()})
		}
		_ = vo
	}
	if st.replacerFn != nil {
		value = callFunction(st.replacerFn, holder, []Value{key.ToValue(), value})
	}
	if vo, ok := value.(*Object); ok {
		switch vo.class {
		case ClassNumber:
			value = toNumber(vo)
		case ClassString:
			value = toString(vo)
		case ClassBoolean:
			value = vo.internal.(bool)
		case ClassBigInt:
			value = vo.internal.(*big.Int)
		}
		if vo.isRawJSON {
			sb.WriteString(toString(vo.Get(strKey("rawJSON"), vo)))
			return true
		}
	}
	switch v := value.(type) {
	case nullType:
		sb.WriteGo("null")
		return true
	case bool:
		if v {
			sb.WriteGo("true")
		} else {
			sb.WriteGo("false")
		}
		return true
	case *String:
		jsonQuote(sb, v)
		return true
	case float64:
		if math.IsInf(v, 0) || v != v {
			sb.WriteGo("null")
		} else {
			sb.WriteGo(numberToString(v))
		}
		return true
	case *big.Int:
		throwTypeError("BigInt value can't be serialized in JSON")
	case *Object:
		if v.callable {
			return false
		}
		if isArray(v) {
			st.serializeArray(sb, v)
		} else {
			st.serializeObject(sb, v)
		}
		return true
	}
	return false
}

func (st *jsonStringifier) checkCycle(o *Object) {
	for _, s := range st.stack {
		if s == o {
			throwTypeError("circular reference")
		}
	}
}

func (st *jsonStringifier) serializeObject(sb *StringBuilder, o *Object) {
	st.checkCycle(o)
	st.stack = append(st.stack, o)
	stepback := st.indent
	st.indent += st.gap
	var keys []PropKey
	if st.hasPropList {
		keys = st.propertyList
	} else {
		for _, k := range o.OwnKeys() {
			if k.Sym != nil {
				continue
			}
			p := o.GetOwnProperty(k)
			if p != nil && p.Enumerable() {
				keys = append(keys, k)
			}
		}
	}
	sb.WriteGo("{")
	first := true
	for _, k := range keys {
		mark := sb.Len()
		if !first {
			sb.WriteGo(",")
		}
		if st.gap != "" {
			sb.WriteGo("\n")
			sb.WriteGo(st.indent)
		}
		jsonQuote(sb, NewStringFromGo(k.S))
		sb.WriteGo(":")
		if st.gap != "" {
			sb.WriteGo(" ")
		}
		if !st.serializeProperty(sb, k, o) {
			// rollback
			sb.truncate(mark)
			continue
		}
		first = false
	}
	if !first && st.gap != "" {
		sb.WriteGo("\n")
		sb.WriteGo(stepback)
	}
	sb.WriteGo("}")
	st.stack = st.stack[:len(st.stack)-1]
	st.indent = stepback
}

func (st *jsonStringifier) serializeArray(sb *StringBuilder, o *Object) {
	st.checkCycle(o)
	st.stack = append(st.stack, o)
	stepback := st.indent
	st.indent += st.gap
	n := lengthOfArrayLike(o)
	sb.WriteGo("[")
	for i := int64(0); i < n; i++ {
		if i > 0 {
			sb.WriteGo(",")
		}
		if st.gap != "" {
			sb.WriteGo("\n")
			sb.WriteGo(st.indent)
		}
		if !st.serializeProperty(sb, idxKey(i), o) {
			sb.WriteGo("null")
		}
	}
	if n > 0 && st.gap != "" {
		sb.WriteGo("\n")
		sb.WriteGo(stepback)
	}
	sb.WriteGo("]")
	st.stack = st.stack[:len(st.stack)-1]
	st.indent = stepback
}

func (b *StringBuilder) truncate(n int) {
	if b.isASCII {
		b.ascii = b.ascii[:n]
	} else {
		b.u = b.u[:n]
	}
}

func jsonQuote(sb *StringBuilder, s *String) {
	sb.WriteUnit('"')
	n := s.Len()
	for i := 0; i < n; i++ {
		c := s.At(i)
		switch c {
		case '"':
			sb.WriteGo("\\\"")
		case '\\':
			sb.WriteGo("\\\\")
		case '\b':
			sb.WriteGo("\\b")
		case '\f':
			sb.WriteGo("\\f")
		case '\n':
			sb.WriteGo("\\n")
		case '\r':
			sb.WriteGo("\\r")
		case '\t':
			sb.WriteGo("\\t")
		default:
			if c < 0x20 {
				sb.WriteGo("\\u" + hex4(int(c)))
			} else if c >= 0xD800 && c <= 0xDFFF {
				// lone surrogate -> escape; valid pair -> keep
				if c <= 0xDBFF && i+1 < n && s.At(i+1) >= 0xDC00 && s.At(i+1) <= 0xDFFF {
					sb.WriteUnit(c)
					sb.WriteUnit(s.At(i + 1))
					i++
				} else {
					sb.WriteGo("\\u" + hex4(int(c)))
				}
			} else {
				sb.WriteUnit(c)
			}
		}
	}
	sb.WriteUnit('"')
}

func hex4(v int) string {
	const h = "0123456789abcdef"
	return string([]byte{h[(v>>12)&0xf], h[(v>>8)&0xf], h[(v>>4)&0xf], h[v&0xf]})
}
