func (c *charClass) matches(r rune, ignoreCase bool, unicodeMode bool) bool {
	m := c.contains(r)
	if !m && ignoreCase {
		// try case variants
		for _, v := range caseVariants(r, unicodeMode) {
			if c.contains(v) {
				m = true
				break
			}
		}
	}
	if c.negate {
		return !m
	}
	return m
}

func (c *charClass) contains(r rune) bool {
	// ranges sorted; binary search
	rs := c.ranges
	lo, hi := 0, len(rs)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		if r < rs[mid].lo {
			hi = mid - 1
		} else if r > rs[mid].hi {
			lo = mid + 1
		} else {
			return true
		}
	}
	return false
}

func (c *charClass) addRange(lo, hi rune) {
	c.ranges = append(c.ranges, classRange{lo, hi})
}

func (c *charClass) addClass(o *charClass) {
	if o.negate {
		// add complement of o
		inv := o.inverted()
		c.ranges = append(c.ranges, inv.ranges...)
		return
	}
	c.ranges = append(c.ranges, o.ranges...)
}

func (c *charClass) normalize() {
	rs := c.ranges
	if len(rs) == 0 {
		return
	}
	sort.Slice(rs, func(i, j int) bool { return rs[i].lo < rs[j].lo })
	out := rs[:1]
	for _, r := range rs[1:] {
		last := &out[len(out)-1]
		if r.lo <= last.hi+1 {
			if r.hi > last.hi {
				last.hi = r.hi
			}
		} else {
			out = append(out, r)
		}
	}
	c.ranges = out
}

func (c *charClass) inverted() *charClass {
	c.normalize()
	inv := &charClass{}
	prev := rune(0)
	for _, r := range c.ranges {
		if r.lo > prev {
			inv.ranges = append(inv.ranges, classRange{prev, r.lo - 1})
		}
		prev = r.hi + 1
	}
	if prev <= 0x10FFFF {
		inv.ranges = append(inv.ranges, classRange{prev, 0x10FFFF})
	}
	return inv
}

func caseVariants(r rune, unicodeMode bool) []rune {
	var out []rune
	u := unicode.ToUpper(r)
	l := unicode.ToLower(r)
	if u != r {
		out = append(out, u)
	}
	if l != r {
		out = append(out, l)
	}
	// simple fold orbit
	f := unicode.SimpleFold(r)
	for f != r {
		dup := false
		for _, x := range out {
			if x == f {
				dup = true
			}
		}
		if !dup {
			out = append(out, f)
		}
		f = unicode.SimpleFold(f)
	}
	return out
