		}
	}
	p := &reParser{src: src, names: map[string]int{}, unicodeM: c.unicodeM || c.vMode, vMode: c.vMode, ignoreCase: c.ignoreCase, dotAll: c.dotAll, multiline: c.multiline}
	// pre-scan for named groups (so \k is parsed as backreference)
	for i := 0; i+2 < len(src); i++ {
		if src[i] == '\\' {
			i++
			continue
		}
		if src[i] == '(' && src[i+1] == '?' && src[i+2] == '<' && i+3 < len(src) && src[i+3] != '=' && src[i+3] != '!' {
			p.hasNamed = true
		}
	}
	p.groupNames = append(p.groupNames, "")
	root := p.parseDisjunction()
	if p.pos < len(p.src) {
		if p.peek() == ')' {
			p.fail("unmatched ')'")
		}
		p.fail("invalid regular expression")
	}
	for _, n := range p.backrefNames {
		if _, ok := p.names[n]; !ok {
			p.fail("invalid group name")
		}
	}
	c.root = root
	c.ncap = p.ncap
	c.names = p.names
	c.groupNames = p.groupNames
	return c
}

func (p *reParser) parseDisjunction() *reNode {
	alts := []*reNode{p.parseAlternative()}
	for p.eat('|') {
		alts = append(alts, p.parseAlternative())
	}
	if len(alts) == 1 {
		return alts[0]
	}
	return &reNode{kind: reAlt, children: alts}
}

func (p *reParser) parseAlternative() *reNode {
	var items []*reNode
	for p.pos < len(p.src) && p.peek() != '|' && p.peek() != ')' {
		items = append(items, p.parseTerm())
	}
	if len(items) == 1 {
		return items[0]
	}
	if len(items) == 0 {
		return &reNode{kind: reEmpty}
	}
	return &reNode{kind: reSeq, children: items}
}

func (p *reParser) parseTerm() *reNode {
	c := p.peek()
	capBefore := p.ncap
	var atom *reNode
	switch c {
	case '^':
		p.pos++
		return &reNode{kind: reBOL}
	case '$':
		p.pos++
		return &reNode{kind: reEOL}
	case '\\':
		if p.pos+1 < len(p.src) {
			n := p.src[p.pos+1]
			if n == 'b' {
				p.pos += 2
				return &reNode{kind: reWordB}
			}
			if n == 'B' {
				p.pos += 2
				return &reNode{kind: reNotWordB}
			}
		}
		atom = p.parseAtomEscape()
	case '(':
		p.pos++
		if p.eat('?') {
			switch p.peek() {
			case ':':
				p.pos++
				d := p.parseDisjunction()
				p.expectClose()
				atom = &reNode{kind: reNCGroup, children: []*reNode{d}}
			case '=', '!':
				neg := p.peek() == '!'
				p.pos++
				d := p.parseDisjunction()
				p.expectClose()
				k := reLookahead
				if neg {
					k = reNegLookahead
				}
				atom = &reNode{kind: k, children: []*reNode{d}}
				if !p.unicodeM {
					// lookaheads can be quantified in annex B
					break
				}
				return atom
			case '<':
				p.pos++
				if p.peek() == '=' || p.peek() == '!' {
					neg := p.peek() == '!'
					p.pos++
					d := p.parseDisjunction()
					p.expectClose()
					k := reLookbehind
					if neg {
						k = reNegLookbehind
					}
					return &reNode{kind: k, children: []*reNode{d}}
				}
				name := p.parseGroupName()
				if _, dup := p.names[name]; dup {
					p.fail("duplicate group name")
				}
				p.ncap++
				idx := p.ncap
				p.names[name] = idx
				p.groupNames = append(p.groupNames, name)
				d := p.parseDisjunction()
				p.expectClose()
				atom = &reNode{kind: reGroup, group: idx, name: name, children: []*reNode{d}}
			default:
				p.fail("invalid group")
			}
		} else {
			p.ncap++
			idx := p.ncap
			p.groupNames = append(p.groupNames, "")
			d := p.parseDisjunction()
			p.expectClose()
			atom = &reNode{kind: reGroup, group: idx, children: []*reNode{d}}
		}
	case '.':
		p.pos++
		atom = &reNode{kind: reAny}
	case '[':
		atom = p.parseClass()
	case '*', '+', '?':
		p.fail("nothing to repeat")
	case '{':
		if p.unicodeM {
			p.fail("nothing to repeat")
		}
		// annex B: literal '{' if not a valid quantifier
		if p.isQuantifierAt(p.pos) {
			p.fail("nothing to repeat")
		}
		p.pos++
		atom = &reNode{kind: reChar, ch: '{'}
	case ')':
		p.fail("unmatched ')'")
	case ']', '}':
		if p.unicodeM {
			p.fail("lone quantifier brackets")
		}
		p.pos++
		atom = &reNode{kind: reChar, ch: c}
	default:
		p.pos++
		atom = &reNode{kind: reChar, ch: c}
	}
	// quantifier
	return p.parseQuantifier(atom, capBefore)
}

func (p *reParser) isQuantifierAt(pos int) bool {
	if pos >= len(p.src) || p.src[pos] != '{' {
		return false
	}
	i := pos + 1
	digits := 0
	for i < len(p.src) && p.src[i] >= '0' && p.src[i] <= '9' {
		i++
		digits++
	}
	if digits == 0 {
		return false
	}
	if i < len(p.src) && p.src[i] == ',' {
		i++
		for i < len(p.src) && p.src[i] >= '0' && p.src[i] <= '9' {
			i++
		}
	}
	return i < len(p.src) && p.src[i] == '}'
}

func (p *reParser) parseQuantifier(atom *reNode, capBefore int) *reNode {
	min, max := -1, -1
	switch p.peek() {
	case '*':
		p.pos++
		min, max = 0, -1
	case '+':
		p.pos++
		min, max = 1, -1
	case '?':
		p.pos++
		min, max = 0, 1
	case '{':
		if p.isQuantifierAt(p.pos) {
			p.pos++
			min = p.parseInt()
			max = min
			if p.eat(',') {
				if p.peek() == '}' {
					max = -1
				} else {
					max = p.parseInt()
				}
			}
			p.pos++ // }
			if max != -1 && max < min {
				p.fail("numbers out of order in {} quantifier")
			}
		} else {
			if p.unicodeM {
				p.fail("incomplete quantifier")
			}
			return atom
		}
	default:
		return atom
	}
	greedy := true
	if p.eat('?') {
		greedy = false
	}
	if atom.kind == reLookahead || atom.kind == reNegLookahead {
		if p.unicodeM {
			p.fail("nothing to repeat")
		}
	}
	if atom.kind == reBOL || atom.kind == reEOL || atom.kind == reWordB || atom.kind == reNotWordB || atom.kind == reLookbehind || atom.kind == reNegLookbehind {
		p.fail("nothing to repeat")
	}
	return &reNode{kind: reStar, children: []*reNode{atom}, min: min, max: max, greedy: greedy, capStart: capBefore + 1, capEnd: p.ncap}
}

func (p *reParser) parseInt() int {
	start := p.pos
	for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
		p.pos++
	}
	v, err := strconv.Atoi(string(p.src[start:p.pos]))
	if err != nil {
		return 1 << 30
	}
	return v
}

func (p *reParser) expectClose() {
	if !p.eat(')') {
		p.fail("expecting ')'")
	}
}

func (p *reParser) parseGroupName() string {
	var sb strings.Builder
	first := true
	for {
		c := p.peek()
		if c == -1 {
			p.fail("invalid group name")
		}
		if c == '>' {
			p.pos++
			break
		}
		if c == '\\' {
			p.pos++
			if !p.eat('u') {
				p.fail("invalid group name")
			}
			cp := p.parseUnicodeEscapeInName()
			c = cp
		} else {
			p.pos++
			// surrogate pair in non-unicode mode
			if c >= 0xD800 && c <= 0xDBFF && p.peek() >= 0xDC00 && p.peek() <= 0xDFFF {
				c = utf16.DecodeRune(c, p.peek())
				p.pos++
			}
		}
		if first && !isIDStart(c) || !first && !isIDPart(c) {
			p.fail("invalid group name")
		}
		sb.WriteRune(c)
		first = false
	}
	if sb.Len() == 0 {
		p.fail("invalid group name")
	}
	return sb.String()
}

func (p *reParser) parseUnicodeEscapeInName() rune {
	if p.eat('{') {
		v := rune(0)
		n := 0
		for p.peek() != '}' {
			d := hexValRune(p.peek())
			if d < 0 {
				p.fail("invalid group name")
			}
			v = v*16 + rune(d)
			p.pos++
			n++
			if v > 0x10FFFF {
				p.fail("invalid group name")
			}
		}
		p.pos++
		if n == 0 {
			p.fail("invalid group name")
		}
		return v
	}
	v := rune(0)
	for i := 0; i < 4; i++ {
		d := hexValRune(p.peek())
		if d < 0 {
			p.fail("invalid group name")
		}
		v = v*16 + rune(d)
		p.pos++
	}
	if v >= 0xD800 && v <= 0xDBFF && p.peek() == '\\' && p.pos+1 < len(p.src) && p.src[p.pos+1] == 'u' {
		save := p.pos
		p.pos += 2
		lo := rune(0)
		ok := true
		for i := 0; i < 4; i++ {
			d := hexValRune(p.peek())
			if d < 0 {
				ok = false
				break
			}
			lo = lo*16 + rune(d)
			p.pos++
		}
		if ok && lo >= 0xDC00 && lo <= 0xDFFF {
			return utf16.DecodeRune(v, lo)
		}
		p.pos = save
	}
	return v
}

func hexValRune(r rune) int {
	if r < 0 || r > 127 {
		return -1
	}
	return hexVal(byte(r))
}

func (p *reParser) parseAtomEscape() *reNode {
	p.pos++ // backslash
	c := p.peek()
	if c == -1 {
		p.fail("\\ at end of pattern")
	}
	switch {
	case c >= '1' && c <= '9':
		// backreference or legacy octal
		start := p.pos
		n := p.parseInt()
		if n <= p.ncap || p.unicodeM || p.countGroups() >= n {
			return &reNode{kind: reBackref, group: n}
		}
		// annex B: octal escape or identity
		p.pos = start
		if c >= '8' {
			p.pos++
			return &reNode{kind: reChar, ch: c}
		}
		v := p.parseLegacyOctal()
		return &reNode{kind: reChar, ch: v}
	case c == '0':
		p.pos++
		if p.peek() >= '0' && p.peek() <= '9' {
			if p.unicodeM {
				p.fail("invalid decimal escape")
			}
			p.pos--
			v := p.parseLegacyOctal()
			return &reNode{kind: reChar, ch: v}
		}
		return &reNode{kind: reChar, ch: 0}
	case c == 'k':
		p.pos++
		if p.peek() == '<' && (p.hasNamed || p.unicodeM) {
			p.pos++
			name := p.parseGroupName()
			p.backrefNames = append(p.backrefNames, name)
			return &reNode{kind: reNamedBackref, name: name}
		}
		if p.unicodeM || p.hasNamed {
			p.fail("invalid named reference")
		}
		return &reNode{kind: reChar, ch: 'k'}
	case c == 'd' || c == 'D' || c == 'w' || c == 'W' || c == 's' || c == 'S':
		p.pos++
		return &reNode{kind: reClass, cls: builtinClass(c, p.ignoreCase, p.unicodeM)}
	case c == 'p' || c == 'P':
		if p.unicodeM {
			p.pos++
			cls := p.parsePropertyEscape(c == 'P')
			return &reNode{kind: reClass, cls: cls}
		}
		p.pos++
		return &reNode{kind: reChar, ch: c}
	}
	r := p.parseCharEscape(false)
	return &reNode{kind: reChar, ch: r}
}

func (p *reParser) countGroups() int {
	n := 0
	inClass := false
	for i := 0; i < len(p.src); i++ {
		c := p.src[i]
		if c == '\\' {
			i++
			continue
		}
		if c == '[' {
			inClass = true
		} else if c == ']' {
			inClass = false
		} else if c == '(' && !inClass {
			if i+1 < len(p.src) && p.src[i+1] == '?' {
				if i+2 < len(p.src) && p.src[i+2] == '<' && i+3 < len(p.src) && p.src[i+3] != '=' && p.src[i+3] != '!' {
					n++
				}
				continue
			}
			n++
		}
	}
	return n
}

func (p *reParser) parseLegacyOctal() rune {
	v := rune(0)
	n := 0
	for n < 3 && p.peek() >= '0' && p.peek() <= '7' {
		nv := v*8 + (p.peek() - '0')
		if nv > 0377 {
			break
		}
		v = nv
		p.pos++
		n++
	}
	return v
}

// parseCharEscape parses the escape after backslash (pos at the escape char)
func (p *reParser) parseCharEscape(inClass bool) rune {
	c := p.peek()
	p.pos++
	switch c {
	case 'n':
		return '\n'
	case 't':
		return '\t'
	case 'r':
		return '\r'
	case 'f':
		return '\f'
	case 'v':
		return '\v'
	case 'b':
		if inClass {
			return '\b'
		}
	case '-':
		if inClass {
			return '-'
		}
		if p.unicodeM {
			p.fail("invalid escape")
		}
		return '-'
	case 'c':
		n := p.peek()
		if (n >= 'a' && n <= 'z') || (n >= 'A' && n <= 'Z') {
			p.pos++
			return n % 32
		}
		if inClass && !p.unicodeM && ((n >= '0' && n <= '9') || n == '_') {
			p.pos++
			return n % 32
		}
		if p.unicodeM {
			p.fail("invalid escape")
		}
		p.pos--
		return '\\'
	case 'x':
		if p.pos+2 <= len(p.src) {
			d1, d2 := hexValRune(p.src[p.pos]), hexValRune(p.src[p.pos+1])
			if d1 >= 0 && d2 >= 0 {
				p.pos += 2
				return rune(d1*16 + d2)
			}
		}
		if p.unicodeM {
			p.fail("invalid escape")
		}
		return 'x'
	case 'u':
		if p.eat('{') {
			if !p.unicodeM {
				p.pos--
				return 'u'
			}
			v := rune(0)
			n := 0
			for p.peek() != '}' {
				d := hexValRune(p.peek())
				if d < 0 {
					p.fail("invalid unicode escape")
				}
				v = v*16 + rune(d)
				if v > 0x10FFFF {
					p.fail("invalid unicode escape")
				}
				p.pos++
				n++
			}
			p.pos++
			if n == 0 {
				p.fail("invalid unicode escape")
			}
			return v
		}
		if p.pos+4 <= len(p.src) {
			v := rune(0)
			ok := true
			for i := 0; i < 4; i++ {
				d := hexValRune(p.src[p.pos+i])
				if d < 0 {
					ok = false
					break
				}
				v = v*16 + rune(d)
			}
			if ok {
				p.pos += 4
				if p.unicodeM && v >= 0xD800 && v <= 0xDBFF && p.peek() == '\\' && p.pos+5 < len(p.src) && p.src[p.pos+1] == 'u' {
					lo := rune(0)
					ok2 := true
					for i := 0; i < 4; i++ {
						d := hexValRune(p.src[p.pos+2+i])
						if d < 0 {
							ok2 = false
							break
						}
						lo = lo*16 + rune(d)
					}
					if ok2 && lo >= 0xDC00 && lo <= 0xDFFF {
						p.pos += 6
						return utf16.DecodeRune(v, lo)
					}
				}
				return v
			}
		}
		if p.unicodeM {
			p.fail("invalid unicode escape")
		}
		return 'u'
	case '0':
		if p.peek() >= '0' && p.peek() <= '9' {
			if p.unicodeM {
				p.fail("invalid escape")
			}
			p.pos--
			return p.parseLegacyOctal()
		}
		return 0
	}
	if c >= '1' && c <= '9' {
		if inClass {
			if p.unicodeM {
				p.fail("invalid class escape")
			}
			if c >= '8' {
				return c
			}
			p.pos--
			return p.parseLegacyOctal()
		}
	}
	if p.unicodeM {
		// only syntax characters may be identity-escaped
		if strings.ContainsRune("^$\\.*+?()[]{}|/", c) {
			return c
		}
		p.fail("invalid escape")
	}
	if c == -1 {
		p.fail("\\ at end of pattern")
	}
	return c
}

func builtinClass(c rune, ignoreCase bool, unicodeM bool) *charClass {
	cls := &charClass{}
	switch c {
	case 'd', 'D':
		cls.addRange('0', '9')
		cls.negate = c == 'D'
	case 'w', 'W':
		cls.addRange('a', 'z')
		cls.addRange('A', 'Z')
		cls.addRange('0', '9')
		cls.addRange('_', '_')
		if ignoreCase && unicodeM {
			cls.addRange(0x017F, 0x017F)
			cls.addRange(0x212A, 0x212A)
		}
		cls.negate = c == 'W'
	case 's', 'S':
		for _, r := range []rune{0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x20, 0xA0, 0x1680, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000, 0xFEFF} {
			cls.addRange(r, r)
		}
		cls.addRange(0x2000, 0x200A)
		cls.negate = c == 'S'
	}
	cls.normalize()
	return cls
}

func (p *reParser) parsePropertyEscape(negate bool) *charClass {
	if !p.eat('{') {
		p.fail("invalid property name")
	}
	start := p.pos
	for p.peek() != '}' {
		if p.peek() == -1 {
			p.fail("invalid property name")
		}
		p.pos++
	}
	body := string(p.src[start:p.pos])
	p.pos++
	cls := unicodePropertyClass(body)
	if cls == nil {
		p.fail("invalid property name")
	}
	cls.negate = negate
	return cls
}

func tableToClass(t *unicode.RangeTable) *charClass {
	cls := &charClass{}
	for _, r := range t.R16 {
		if r.Stride == 1 {
			cls.addRange(rune(r.Lo), rune(r.Hi))
		} else {
			for c := rune(r.Lo); c <= rune(r.Hi); c += rune(r.Stride) {
				cls.addRange(c, c)
			}
		}
	}
	for _, r := range t.R32 {
		if r.Stride == 1 {
			cls.addRange(rune(r.Lo), rune(r.Hi))
		} else {
			for c := rune(r.Lo); c <= rune(r.Hi); c += rune(r.Stride) {
				cls.addRange(c, c)
			}
		}
	}
	cls.normalize()
	return cls
}

var gcAliases = map[string]string{
	"Letter": "L", "Cased_Letter": "LC", "Uppercase_Letter": "Lu", "Lowercase_Letter": "Ll", "Titlecase_Letter": "Lt", "Modifier_Letter": "Lm", "Other_Letter": "Lo",
	"Mark": "M", "Combining_Mark": "M", "Nonspacing_Mark": "Mn", "Spacing_Mark": "Mc", "Enclosing_Mark": "Me",
	"Number": "N", "Decimal_Number": "Nd", "digit": "Nd", "Letter_Number": "Nl", "Other_Number": "No",
	"Punctuation": "P", "punct": "P", "Connector_Punctuation": "Pc", "Dash_Punctuation": "Pd", "Open_Punctuation": "Ps", "Close_Punctuation": "Pe", "Initial_Punctuation": "Pi", "Final_Punctuation": "Pf", "Other_Punctuation": "Po",
	"Symbol": "S", "Math_Symbol": "Sm", "Currency_Symbol": "Sc", "Modifier_Symbol": "Sk", "Other_Symbol": "So",
	"Separator": "Z", "Space_Separator": "Zs", "Line_Separator": "Zl", "Paragraph_Separator": "Zp",
	"Other": "C", "Control": "Cc", "cntrl": "Cc", "Format": "Cf", "Surrogate": "Cs", "Private_Use": "Co", "Unassigned": "Cn",
}

func unicodePropertyClass(body string) *charClass {
	name := body
	value := ""
	if i := strings.IndexByte(body, '='); i >= 0 {
		name = body[:i]
		value = body[i+1:]
	}
	if value != "" {
		switch name {
		case "General_Category", "gc":
			return gcClass(value)
		case "Script", "sc", "Script_Extensions", "scx":
			if t, ok := unicode.Scripts[value]; ok {
				return tableToClass(t)
			}
			if full, ok := scriptAliases[value]; ok {
				if t, ok := unicode.Scripts[full]; ok {
					return tableToClass(t)
				}
			}
			return nil
		}
		return nil
	}
	if c := gcClass(name); c != nil {
		return c
	}
	switch name {
	case "Any":
		c := &charClass{}
		c.addRange(0, 0x10FFFF)
		return c
	case "ASCII":
		c := &charClass{}
		c.addRange(0, 0x7F)
		return c
	case "Assigned":
		c := tableToClass(unicode.Categories["Cn"])
		if c == nil {
			return nil
		}
		return c.inverted()
	case "Alphabetic", "Alpha":
		c := &charClass{}
		c.addClass(tableToClass(unicode.Letter))
		c.addClass(tableToClass(unicode.Nl))
		c.addClass(tableToClass(unicode.Other_Alphabetic))
		c.normalize()
		return c
	case "Uppercase", "Upper":
		c := &charClass{}
		c.addClass(tableToClass(unicode.Lu))
		c.addClass(tableToClass(unicode.Other_Uppercase))
		c.normalize()
		return c
	case "Lowercase", "Lower":
		c := &charClass{}
		c.addClass(tableToClass(unicode.Ll))
		c.addClass(tableToClass(unicode.Other_Lowercase))
		c.normalize()
		return c
	case "White_Space", "space":
		return tableToClass(unicode.White_Space)
	case "Emoji", "Emoji_Presentation", "Extended_Pictographic":
		c := &charClass{}
		c.addRange(0x1F300, 0x1FAFF)
		c.addRange(0x2600, 0x27BF)
		c.addRange(0x1F000, 0x1F2FF)
		if name == "Emoji" {
			c.addRange('#', '#')
			c.addRange('*', '*')
			c.addRange('0', '9')
			c.addRange(0xA9, 0xA9)
			c.addRange(0xAE, 0xAE)
		}
		c.normalize()
		return c
	}
	if t, ok := unicode.Properties[name]; ok {
		return tableToClass(t)
	}
	return nil
}

var scriptAliases = map[string]string{"Latn": "Latin", "Grek": "Greek", "Cyrl": "Cyrillic", "Hani": "Han", "Arab": "Arabic", "Hebr": "Hebrew", "Hira": "Hiragana", "Kana": "Katakana", "Hang": "Hangul", "Thai": "Thai", "Deva": "Devanagari", "Zyyy": "Common", "Zinh": "Inherited"}

func gcClass(v string) *charClass {
	if a, ok := gcAliases[v]; ok {
		v = a
	}
	if v == "LC" {
		c := &charClass{}
		c.addClass(tableToClass(unicode.Lu))
		c.addClass(tableToClass(unicode.Ll))
		c.addClass(tableToClass(unicode.Lt))
		c.normalize()
		return c
	}
	if t, ok := unicode.Categories[v]; ok {
		return tableToClass(t)
	}
	return nil
}

func (p *reParser) parseClass() *reNode {
	p.pos++ // [
	cls := &charClass{}
	if p.eat('^') {
		cls.negate = true
	}
	for {
		c := p.peek()
		if c == -1 {
			p.fail("unterminated character class")
		}
		if c == ']' {
			p.pos++
			break
		}
		lo, loCls := p.parseClassAtom()
		if p.peek() == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] != ']' {
			p.pos++
			hi, hiCls := p.parseClassAtom()
			if loCls != nil || hiCls != nil {
				if p.unicodeM {
					p.fail("invalid class range")
				}
				if loCls != nil {
					cls.addClass(loCls)
				} else {
					cls.addRange(lo, lo)
				}
				cls.addRange('-', '-')
				if hiCls != nil {
					cls.addClass(hiCls)
				} else {
					cls.addRange(hi, hi)
				}
				continue
			}
			if lo > hi {
				p.fail("invalid class range")
			}
			cls.addRange(lo, hi)
			continue
		}
		if loCls != nil {
			cls.addClass(loCls)
		} else {
			cls.addRange(lo, lo)
		}
	}
	cls.normalize()
	return &reNode{kind: reClass, cls: cls}
}

// parseClassAtom returns a single char or a class (for \d etc.)
func (p *reParser) parseClassAtom() (rune, *charClass) {
	c := p.peek()
	if c == '\\' {
		p.pos++
		e := p.peek()
		switch e {
		case 'd', 'D', 'w', 'W', 's', 'S':
			p.pos++
			return 0, builtinClass(e, p.ignoreCase, p.unicodeM)
		case 'p', 'P':
			if p.unicodeM {
				p.pos++
				return 0, p.parsePropertyEscape(e == 'P')
			}
		case -1:
			p.fail("\\ at end of pattern")
		}
		return p.parseCharEscape(true), nil
	}
	p.pos++
	return c, nil
}

// ---------- Matcher ----------

type reMatcher struct {
	re        *reCompiled
	input     []uint16
	caps      []int // 2*(ncap+1)
	steps     int
}

func (m *reMatcher) at(pos int) (rune, int) {
	if pos >= len(m.input) {
		return -1, 0
	}
	c := m.input[pos]
	if m.re.unicodeM && c >= 0xD800 && c <= 0xDBFF && pos+1 < len(m.input) {
		d := m.input[pos+1]
		if d >= 0xDC00 && d <= 0xDFFF {
			return utf16.DecodeRune(rune(c), rune(d)), 2
		}
	}
	return rune(c), 1
}

func (m *reMatcher) before(pos int) (rune, int) {
	if pos <= 0 {
		return -1, 0
	}
	c := m.input[pos-1]
	if m.re.unicodeM && c >= 0xDC00 && c <= 0xDFFF && pos-2 >= 0 {
		d := m.input[pos-2]
		if d >= 0xD800 && d <= 0xDBFF {
			return utf16.DecodeRune(rune(d), rune(c)), 2
		}
	}
	return rune(c), 1
}

func isWordChar(r rune) bool {
	return r == '_' || (r >= '0' && r <= '9') || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
}

func (m *reMatcher) isWordAt(pos int) bool {
	if pos < 0 || pos >= len(m.input) {
		return false
	}
	r := rune(m.input[pos])
	if isWordChar(r) {
		return true
	}
	if m.re.ignoreCase && m.re.unicodeM && (r == 0x017F || r == 0x212A) {
		return true
	}
	return false
}

func isLineTerminatorRune(r rune) bool {
	return r == '\n' || r == '\r' || r == 0x2028 || r == 0x2029
}

// match node at pos with continuation; direction: +1 forward, -1 backward (lookbehind)
func (m *reMatcher) match(n *reNode, pos int, dir int, k func(int) bool) bool {
	m.steps++
	if m.steps > 50000000 {
		throwInternalError("regexp backtracking limit exceeded")
	}
	switch n.kind {
	case reEmpty:
		return k(pos)
	case reChar:
		var r rune
		var sz int
		if dir > 0 {
			r, sz = m.at(pos)
		} else {
			r, sz = m.before(pos)
		}
		if sz == 0 {
			return false
		}
		if r == n.ch || (m.re.ignoreCase && canonicalize(r, m.re.unicodeM) == canonicalize(n.ch, m.re.unicodeM)) {
			return k(pos + dir*sz)
		}
		return false
	case reAny:
		var r rune
		var sz int
		if dir > 0 {
			r, sz = m.at(pos)
		} else {
			r, sz = m.before(pos)
		}
		if sz == 0 {
			return false
		}
		if !m.re.dotAll && isLineTerminatorRune(r) {
			return false
		}
		return k(pos + dir*sz)
	case reClass:
		var r rune
		var sz int
		if dir > 0 {
			r, sz = m.at(pos)
		} else {
			r, sz = m.before(pos)
		}
		if sz == 0 {
			return false
		}
		if n.cls.matches(r, m.re.ignoreCase, m.re.unicodeM) {
			return k(pos + dir*sz)
		}
		return false
	case reSeq:
		if dir > 0 {
			return m.matchSeq(n.children, 0, pos, dir, k)
		}
		return m.matchSeqRev(n.children, len(n.children)-1, pos, dir, k)
	case reAlt:
		for _, c := range n.children {
			if m.match(c, pos, dir, k) {
				return true
			}
		}
		return false
	case reGroup:
		idx := n.group
		oldS, oldE := m.caps[2*idx], m.caps[2*idx+1]
		ok := m.match(n.children[0], pos, dir, func(e int) bool {
			ps, pe := m.caps[2*idx], m.caps[2*idx+1]
			if dir > 0 {
				m.caps[2*idx] = pos
				m.caps[2*idx+1] = e
			} else {
				m.caps[2*idx] = e
				m.caps[2*idx+1] = pos
			}
			if k(e) {
				return true
			}
			m.caps[2*idx] = ps
			m.caps[2*idx+1] = pe
			return false
		})
		if !ok {
			m.caps[2*idx] = oldS
			m.caps[2*idx+1] = oldE
		}
		return ok
	case reNCGroup:
		return m.match(n.children[0], pos, dir, k)
	case reBOL:
		if pos == 0 || (m.re.multiline && isLineTerminatorRune(rune(m.input[pos-1]))) {
			return k(pos)
		}
		return false
	case reEOL:
		if pos == len(m.input) || (m.re.multiline && isLineTerminatorRune(rune(m.input[pos]))) {
			return k(pos)
		}
		return false
	case reWordB, reNotWordB:
		a := m.isWordAt(pos - 1)
		b := m.isWordAt(pos)
		isB := a != b
		if (n.kind == reWordB) == isB {
			return k(pos)
		}
		return false
	case reBackref, reNamedBackref:
		idx := n.group
		if n.kind == reNamedBackref {
			idx = m.re.names[n.name]
		}
		s, e := m.caps[2*idx], m.caps[2*idx+1]
		if s < 0 || e < 0 {
			return k(pos)
		}
		l := e - s
		if dir > 0 {
			if pos+l > len(m.input) {
				return false
			}
			for i := 0; i < l; i++ {
				a, b := rune(m.input[s+i]), rune(m.input[pos+i])
				if a != b && !(m.re.ignoreCase && canonicalize(a, m.re.unicodeM) == canonicalize(b, m.re.unicodeM)) {
					return false
				}
			}
			return k(pos + l)
		}
		if pos-l < 0 {
			return false
		}
		for i := 0; i < l; i++ {
			a, b := rune(m.input[s+i]), rune(m.input[pos-l+i])
			if a != b && !(m.re.ignoreCase && canonicalize(a, m.re.unicodeM) == canonicalize(b, m.re.unicodeM)) {
				return false
			}
		}
		return k(pos - l)
	case reLookahead, reNegLookahead:
		saved := make([]int, len(m.caps))
		copy(saved, m.caps)
		ok := m.match(n.children[0], pos, 1, func(int) bool { return true })
		if n.kind == reLookahead {
			if !ok {
				copy(m.caps, saved)
				return false
			}
			if k(pos) {
				return true
			}
			copy(m.caps, saved)
			return false
		}
		copy(m.caps, saved)
		if ok {
			return false
		}
		return k(pos)
	case reLookbehind, reNegLookbehind:
		saved := make([]int, len(m.caps))
		copy(saved, m.caps)
		ok := m.match(n.children[0], pos, -1, func(int) bool { return true })
		if n.kind == reLookbehind {
			if !ok {
				copy(m.caps, saved)
				return false
			}
			if k(pos) {
				return true
			}
			copy(m.caps, saved)
			return false
		}
		copy(m.caps, saved)
		if ok {
			return false
		}
		return k(pos)
	case reStar:
		return m.matchRepeat(n, pos, dir, 0, -1, k)
	}
	return false
}

func (m *reMatcher) matchSeq(items []*reNode, i int, pos int, dir int, k func(int) bool) bool {
	if i == len(items) {
		return k(pos)
	}
	return m.match(items[i], pos, dir, func(p int) bool {
		return m.matchSeq(items, i+1, p, dir, k)
	})
}

func (m *reMatcher) matchSeqRev(items []*reNode, i int, pos int, dir int, k func(int) bool) bool {
	if i < 0 {
		return k(pos)
	}
	return m.match(items[i], pos, dir, func(p int) bool {
		return m.matchSeqRev(items, i-1, p, dir, k)
	})
}

func (m *reMatcher) resetCaps(n *reNode) {
	for i := n.capStart; i <= n.capEnd; i++ {
		m.caps[2*i] = -1
		m.caps[2*i+1] = -1
	}
}

func (m *reMatcher) matchRepeat(n *reNode, pos int, dir int, count int, lastPos int, k func(int) bool) bool {
	child := n.children[0]
	// try another iteration
	tryMore := func() bool {
		if n.max != -1 && count >= n.max {
			return false
		}
		saved := make([]int, 0)
		if n.capEnd >= n.capStart {
			saved = make([]int, 2*(n.capEnd-n.capStart+1))
			copy(saved, m.caps[2*n.capStart:2*(n.capEnd+1)])
			m.resetCaps(n)
		}
		ok := m.match(child, pos, dir, func(p int) bool {
			if p == pos && count >= n.min {
				// empty iteration: stop to avoid infinite loop
				return false
			}
			return m.matchRepeat(n, p, dir, count+1, pos, k)
		})
		if !ok && len(saved) > 0 {
			copy(m.caps[2*n.capStart:2*(n.capEnd+1)], saved)
		}
		return ok
	}
	if count < n.min {
		return tryMore()
	}
	if n.greedy {
		if tryMore() {
			return true
		}
		return k(pos)
	}
	if k(pos) {
		return true
	}
	return tryMore()
}

// exec runs the regexp at the given start index; returns capture positions or nil
func (re *reCompiled) exec(input []uint16, start int) []int {
	m := &reMatcher{re: re, input: input}
	m.caps = make([]int, 2*(re.ncap+1))
	for i := start; i <= len(input); i++ {
		for j := range m.caps {
			m.caps[j] = -1
		}
		var end int
		ok := m.match(re.root, i, 1, func(e int) bool { end = e; return true })
		if ok {
			m.caps[0] = i
			m.caps[1] = end
			return m.caps
		}
		if re.sticky {
			return nil
		}
		// in unicode mode, advance by code point
		if re.unicodeM && i < len(input) {
			c := input[i]
			if c >= 0xD800 && c <= 0xDBFF && i+1 < len(input) && input[i+1] >= 0xDC00 && input[i+1] <= 0xDFFF {
				i++
			}
		}
	}
	return nil
}
