package main

import (
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf16"
)

// ---------- AST ----------

type reNodeKind int

const (
	reChar reNodeKind = iota // single code unit/point
	reAny                    // .
	reClass                  // [..]
	reSeq
	reAlt
	reGroup   // capturing
	reNCGroup // non-capturing
	reStar    // quantifier
	reBOL
	reEOL
	reWordB
	reNotWordB
	reBackref
	reNamedBackref
	reLookahead
	reNegLookahead
	reLookbehind
	reNegLookbehind
	reEmpty
)

type reNode struct {
	kind     reNodeKind
	ch       rune
	cls      *charClass
	children []*reNode
	min, max int // quantifier; max=-1 => inf
	greedy   bool
	group    int // capture index
	name     string
	// for quantified group: range of capture indices to reset
	capStart, capEnd int
}

type classRange struct{ lo, hi rune }

type charClass struct {
	ranges  []classRange
	negate  bool
	// for v-flag string alternatives (not supported fully)
}

func (c *charClass) matches(r rune, ignoreCase bool, unicodeMode bool) bool {
	m := c.contains(r)
	if !m && ignoreCase {
		// try case variants
		for _, v := range caseVariants(r, unicodeMode) {
			if c.contains(v) {
				m = true
				break
			}
		}
	}
	if c.negate {
		return !m
	}
	return m
}

func (c *charClass) contains(r rune) bool {
	// ranges sorted; binary search
	rs := c.ranges
	lo, hi := 0, len(rs)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		if r < rs[mid].lo {
			hi = mid - 1
		} else if r > rs[mid].hi {
			lo = mid + 1
		} else {
			return true
		}
	}
	return false
}

func (c *charClass) addRange(lo, hi rune) {
	c.ranges = append(c.ranges, classRange{lo, hi})
}

func (c *charClass) addClass(o *charClass) {
	if o.negate {
		// add complement of o
		inv := o.inverted()
		c.ranges = append(c.ranges, inv.ranges...)
		return
	}
	c.ranges = append(c.ranges, o.ranges...)
}

func (c *charClass) normalize() {
	rs := c.ranges
	if len(rs) == 0 {
		return
	}
	sort.Slice(rs, func(i, j int) bool { return rs[i].lo < rs[j].lo })
	out := rs[:1]
	for _, r := range rs[1:] {
		last := &out[len(out)-1]
		if r.lo <= last.hi+1 {
			if r.hi > last.hi {
				last.hi = r.hi
			}
		} else {
			out = append(out, r)
		}
	}
	c.ranges = out
}

func (c *charClass) inverted() *charClass {
	c.normalize()
	inv := &charClass{}
	prev := rune(0)
	for _, r := range c.ranges {
		if r.lo > prev {
			inv.ranges = append(inv.ranges, classRange{prev, r.lo - 1})
		}
		prev = r.hi + 1
	}
	if prev <= 0x10FFFF {
		inv.ranges = append(inv.ranges, classRange{prev, 0x10FFFF})
	}
	return inv
}

func caseVariants(r rune, unicodeMode bool) []rune {
	var out []rune
	u := unicode.ToUpper(r)
	l := unicode.ToLower(r)
	if u != r {
		out = append(out, u)
	}
	if l != r {
		out = append(out, l)
	}
	// simple fold orbit
	f := unicode.SimpleFold(r)
	for f != r {
		dup := false
		for _, x := range out {
			if x == f {
				dup = true
			}
		}
		if !dup {
			out = append(out, f)
		}
		f = unicode.SimpleFold(f)
	}
	return out
}

func canonicalize(r rune, unicodeMode bool) rune {
	if unicodeMode {
		// simple case folding
		f := r
		m := unicode.SimpleFold(r)
		for m != r {
			if m < f {
				f = m
			}
			m = unicode.SimpleFold(m)
		}
		return f
	}
	if r < 128 {
		if r >= 'a' && r <= 'z' {
			return r - 32
		}
		return r
	}
	u := unicode.ToUpper(r)
	if u < 128 && r >= 128 {
		return r
	}
	// map via upper of single char
	return u
}

// ---------- Parser ----------

type reParser struct {
	src        []rune
	pos        int
	ncap       int
	names      map[string]int
	groupNames []string // index -> name
	unicodeM   bool
	vMode      bool
	ignoreCase bool
	hasNamed   bool
	backrefNames []string
	dotAll     bool
	multiline  bool
}

type reCompiled struct {
	root       *reNode
	ncap       int
	names      map[string]int
	groupNames []string
	ignoreCase bool
	multiline  bool
	dotAll     bool
	unicodeM   bool
	sticky     bool
	global     bool
	hasIndices bool
	vMode      bool
}

func (p *reParser) fail(msg string) {
	throwSyntaxError("%s", msg)
}

func (p *reParser) peek() rune {
	if p.pos >= len(p.src) {
		return -1
	}
	return p.src[p.pos]
}

func (p *reParser) eat(r rune) bool {
	if p.peek() == r {
		p.pos++
		return true
	}
	return false
}

func compileRegExp(pattern string, flags string) *reCompiled {
	c := &reCompiled{}
	for _, f := range flags {
		switch f {
		case 'g':
			if c.global {
				throwSyntaxError("invalid regular expression flags")
			}
			c.global = true
		case 'i':
			if c.ignoreCase {
				throwSyntaxError("invalid regular expression flags")
			}
			c.ignoreCase = true
		case 'm':
			if c.multiline {
				throwSyntaxError("invalid regular expression flags")
			}
			c.multiline = true
		case 's':
			if c.dotAll {
				throwSyntaxError("invalid regular expression flags")
			}
			c.dotAll = true
		case 'u':
			if c.unicodeM {
				throwSyntaxError("invalid regular expression flags")
			}
			c.unicodeM = true
		case 'v':
			if c.vMode {
				throwSyntaxError("invalid regular expression flags")
			}
			c.vMode = true
		case 'y':
			if c.sticky {
				throwSyntaxError("invalid regular expression flags")
			}
			c.sticky = true
		case 'd':
			if c.hasIndices {
				throwSyntaxError("invalid regular expression flags")
			}
			c.hasIndices = true
		default:
			throwSyntaxError("invalid regular expression flags")
		}
	}
	if c.unicodeM && c.vMode {
		throwSyntaxError("invalid regular expression flags")
	}
	// pattern as code points (in non-unicode mode, surrogates stay as separate units)
	var src []rune
	s := NewStringFromGo(pattern)
	u := s.UTF16()
	if c.unicodeM || c.vMode {
		for i := 0; i < len(u); i++ {
			cu := u[i]
			if cu >= 0xD800 && cu <= 0xDBFF && i+1 < len(u) && u[i+1] >= 0xDC00 && u[i+1] <= 0xDFFF {
				src = append(src, utf16.DecodeRune(rune(cu), rune(u[i+1])))
				i++
			} else {
				src = append(src, rune(cu))
			}
		}
	} else {
		for _, cu := range u {
			src = append(src, rune(cu))
		}
	}
	p := &reParser{src: src, names: map[string]int{}, unicodeM: c.unicodeM || c.vMode, vMode: c.vMode, ignoreCase: c.ignoreCase, dotAll: c.dotAll, multiline: c.multiline}
	// pre-scan for named groups (so \k is parsed as backreference)
	for i := 0; i+2 < len(src); i++ {
		if src[i] == '\\' {
			i++
			continue
		}
		if src[i] == '(' && src[i+1] == '?' && src[i+2] == '<' && i+3 < len(src) && src[i+3] != '=' && src[i+3] != '!' {
			p.hasNamed = true
		}
	}
	p.groupNames = append(p.groupNames, "")
	root := p.parseDisjunction()
	if p.pos < len(p.src) {
		if p.peek() == ')' {
			p.fail("unmatched ')'")
		}
		p.fail("invalid regular expression")
	}
	for _, n := range p.backrefNames {
		if _, ok := p.names[n]; !ok {
			p.fail("invalid group name")
		}
	}
	c.root = root
	c.ncap = p.ncap
	c.names = p.names
	c.groupNames = p.groupNames
	return c
}

func (p *reParser) parseDisjunction() *reNode {
	alts := []*reNode{p.parseAlternative()}
	for p.eat('|') {
		alts = append(alts, p.parseAlternative())
	}
	if len(alts) == 1 {
		return alts[0]
	}
	return &reNode{kind: reAlt, children: alts}
}

func (p *reParser) parseAlternative() *reNode {
	var items []*reNode
	for p.pos < len(p.src) && p.peek() != '|' && p.peek() != ')' {
		items = append(items, p.parseTerm())
	}
	if len(items) == 1 {
		return items[0]
	}
	if len(items) == 0 {
		return &reNode{kind: reEmpty}
	}
	return &reNode{kind: reSeq, children: items}
}

func (p *reParser) parseTerm() *reNode {
	c := p.peek()
	capBefore := p.ncap
	var atom *reNode
	switch c {
	case '^':
		p.pos++
		return &reNode{kind: reBOL}
	case '$':
		p.pos++
		return &reNode{kind: reEOL}
	case '\\':
		if p.pos+1 < len(p.src) {
			n := p.src[p.pos+1]
			if n == 'b' {
				p.pos += 2
				return &reNode{kind: reWordB}
			}
			if n == 'B' {
				p.pos += 2
				return &reNode{kind: reNotWordB}
			}
		}
		atom = p.parseAtomEscape()
	case '(':
		p.pos++
		if p.eat('?') {
			switch p.peek() {
			case ':':
				p.pos++
				d := p.parseDisjunction()
				p.expectClose()
				atom = &reNode{kind: reNCGroup, children: []*reNode{d}}
			case '=', '!':
				neg := p.peek() == '!'
				p.pos++
				d := p.parseDisjunction()
				p.expectClose()
				k := reLookahead
				if neg {
					k = reNegLookahead
				}
				atom = &reNode{kind: k, children: []*reNode{d}}
				if !p.unicodeM {
					// lookaheads can be quantified in annex B
					break
				}
				return atom
			case '<':
				p.pos++
				if p.peek() == '=' || p.peek() == '!' {
					neg := p.peek() == '!'
					p.pos++
					d := p.parseDisjunction()
					p.expectClose()
					k := reLookbehind
					if neg {
						k = reNegLookbehind
					}
					return &reNode{kind: k, children: []*reNode{d}}
				}
				name := p.parseGroupName()
				if _, dup := p.names[name]; dup {
					p.fail("duplicate group name")
				}
				p.ncap++
				idx := p.ncap
				p.names[name] = idx
				p.groupNames = append(p.groupNames, name)
				d := p.parseDisjunction()
				p.expectClose()
				atom = &reNode{kind: reGroup, group: idx, name: name, children: []*reNode{d}}
			default:
				p.fail("invalid group")
			}
		} else {
			p.ncap++
			idx := p.ncap
			p.groupNames = append(p.groupNames, "")
			d := p.parseDisjunction()
			p.expectClose()
			atom = &reNode{kind: reGroup, group: idx, children: []*reNode{d}}
		}
	case '.':
		p.pos++
		atom = &reNode{kind: reAny}
	case '[':
		atom = p.parseClass()
	case '*', '+', '?':
		p.fail("nothing to repeat")
	case '{':
		if p.unicodeM {
			p.fail("nothing to repeat")
		}
		// annex B: literal '{' if not a valid quantifier
		if p.isQuantifierAt(p.pos) {
			p.fail("nothing to repeat")
		}
		p.pos++
		atom = &reNode{kind: reChar, ch: '{'}
	case ')':
		p.fail("unmatched ')'")
	case ']', '}':
		if p.unicodeM {
			p.fail("lone quantifier brackets")
		}
		p.pos++
		atom = &reNode{kind: reChar, ch: c}
	default:
		p.pos++
		atom = &reNode{kind: reChar, ch: c}
	}
	// quantifier
	return p.parseQuantifier(atom, capBefore)
}

func (p *reParser) isQuantifierAt(pos int) bool {
	if pos >= len(p.src) || p.src[pos] != '{' {
		return false
	}
	i := pos + 1
	digits := 0
	for i < len(p.src) && p.src[i] >= '0' && p.src[i] <= '9' {
		i++
		digits++
	}
	if digits == 0 {
		return false
	}
	if i < len(p.src) && p.src[i] == ',' {
		i++
		for i < len(p.src) && p.src[i] >= '0' && p.src[i] <= '9' {
			i++
		}
	}
	return i < len(p.src) && p.src[i] == '}'
}

func (p *reParser) parseQuantifier(atom *reNode, capBefore int) *reNode {
	min, max := -1, -1
	switch p.peek() {
	case '*':
		p.pos++
		min, max = 0, -1
	case '+':
		p.pos++
		min, max = 1, -1
	case '?':
		p.pos++
		min, max = 0, 1
	case '{':
		if p.isQuantifierAt(p.pos) {
			p.pos++
			min = p.parseInt()
			max = min
			if p.eat(',') {
				if p.peek() == '}' {
					max = -1
				} else {
					max = p.parseInt()
				}
			}
			p.pos++ // }
			if max != -1 && max < min {
				p.fail("numbers out of order in {} quantifier")
			}
		} else {
			if p.unicodeM {
				p.fail("incomplete quantifier")
			}
			return atom
		}
	default:
		return atom
	}
	greedy := true
	if p.eat('?') {
		greedy = false
	}
	if atom.kind == reLookahead || atom.kind == reNegLookahead {
		if p.unicodeM {
			p.fail("nothing to repeat")
		}
	}
	if atom.kind == reBOL || atom.kind == reEOL || atom.kind == reWordB || atom.kind == reNotWordB || atom.kind == reLookbehind || atom.kind == reNegLookbehind {
		p.fail("nothing to repeat")
	}
	return &reNode{kind: reStar, children: []*reNode{atom}, min: min, max: max, greedy: greedy, capStart: capBefore + 1, capEnd: p.ncap}
}

func (p *reParser) parseInt() int {
	start := p.pos
	for p.pos < len(p.src) && p.src[p.pos] >= '0' && p.src[p.pos] <= '9' {
		p.pos++
	}
	v, err := strconv.Atoi(string(p.src[start:p.pos]))
	if err != nil {
		return 1 << 30
	}
	return v
}

func (p *reParser) expectClose() {
	if !p.eat(')') {
		p.fail("expecting ')'")
	}
}

func (p *reParser) parseGroupName() string {
	var sb strings.Builder
	first := true
	for {
		c := p.peek()
		if c == -1 {
			p.fail("invalid group name")
		}
		if c == '>' {
			p.pos++
			break
		}
		if c == '\\' {
			p.pos++
			if !p.eat('u') {
				p.fail("invalid group name")
			}
			cp := p.parseUnicodeEscapeInName()
			c = cp
		} else {
			p.pos++
			// surrogate pair in non-unicode mode
			if c >= 0xD800 && c <= 0xDBFF && p.peek() >= 0xDC00 && p.peek() <= 0xDFFF {
				c = utf16.DecodeRune(c, p.peek())
				p.pos++
			}
		}
		if first && !isIDStart(c) || !first && !isIDPart(c) {
			p.fail("invalid group name")
		}
		sb.WriteRune(c)
		first = false
	}
	if sb.Len() == 0 {
		p.fail("invalid group name")
	}
	return sb.String()
}

func (p *reParser) parseUnicodeEscapeInName() rune {
	if p.eat('{') {
		v := rune(0)
		n := 0
		for p.peek() != '}' {
			d := hexValRune(p.peek())
			if d < 0 {
				p.fail("invalid group name")
			}
			v = v*16 + rune(d)
			p.pos++
			n++
			if v > 0x10FFFF {
				p.fail("invalid group name")
			}
		}
		p.pos++
		if n == 0 {
			p.fail("invalid group name")
		}
		return v
	}
	v := rune(0)
	for i := 0; i < 4; i++ {
		d := hexValRune(p.peek())
		if d < 0 {
			p.fail("invalid group name")
		}
		v = v*16 + rune(d)
		p.pos++
	}
	if v >= 0xD800 && v <= 0xDBFF && p.peek() == '\\' && p.pos+1 < len(p.src) && p.src[p.pos+1] == 'u' {
		save := p.pos
		p.pos += 2
		lo := rune(0)
		ok := true
		for i := 0; i < 4; i++ {
			d := hexValRune(p.peek())
			if d < 0 {
				ok = false
				break
			}
			lo = lo*16 + rune(d)
			p.pos++
		}
		if ok && lo >= 0xDC00 && lo <= 0xDFFF {
			return utf16.DecodeRune(v, lo)
		}
		p.pos = save
	}
	return v
}

func hexValRune(r rune) int {
	if r < 0 || r > 127 {
		return -1
	}
	return hexVal(byte(r))
}

func (p *reParser) parseAtomEscape() *reNode {
	p.pos++ // backslash
	c := p.peek()
	if c == -1 {
		p.fail("\\ at end of pattern")
	}
	switch {
	case c >= '1' && c <= '9':
		// backreference or legacy octal
		start := p.pos
		n := p.parseInt()
		if n <= p.ncap || p.unicodeM || p.countGroups() >= n {
			return &reNode{kind: reBackref, group: n}
		}
		// annex B: octal escape or identity
		p.pos = start
		if c >= '8' {
			p.pos++
			return &reNode{kind: reChar, ch: c}
		}
		v := p.parseLegacyOctal()
		return &reNode{kind: reChar, ch: v}
	case c == '0':
		p.pos++
		if p.peek() >= '0' && p.peek() <= '9' {
			if p.unicodeM {
				p.fail("invalid decimal escape")
			}
			p.pos--
			v := p.parseLegacyOctal()
			return &reNode{kind: reChar, ch: v}
		}
		return &reNode{kind: reChar, ch: 0}
	case c == 'k':
		p.pos++
		if p.peek() == '<' && (p.hasNamed || p.unicodeM) {
			p.pos++
			name := p.parseGroupName()
			p.backrefNames = append(p.backrefNames, name)
			return &reNode{kind: reNamedBackref, name: name}
		}
		if p.unicodeM || p.hasNamed {
			p.fail("invalid named reference")
		}
		return &reNode{kind: reChar, ch: 'k'}
	case c == 'd' || c == 'D' || c == 'w' || c == 'W' || c == 's' || c == 'S':
		p.pos++
		return &reNode{kind: reClass, cls: builtinClass(c, p.ignoreCase, p.unicodeM)}
	case c == 'p' || c == 'P':
		if p.unicodeM {
			p.pos++
			cls := p.parsePropertyEscape(c == 'P')
			return &reNode{kind: reClass, cls: cls}
		}
		p.pos++
		return &reNode{kind: reChar, ch: c}
	}
	r := p.parseCharEscape(false)
	return &reNode{kind: reChar, ch: r}
}

func (p *reParser) countGroups() int {
	n := 0
	inClass := false
	for i := 0; i < len(p.src); i++ {
		c := p.src[i]
		if c == '\\' {
			i++
			continue
		}
		if c == '[' {
			inClass = true
		} else if c == ']' {
			inClass = false
		} else if c == '(' && !inClass {
			if i+1 < len(p.src) && p.src[i+1] == '?' {
				if i+2 < len(p.src) && p.src[i+2] == '<' && i+3 < len(p.src) && p.src[i+3] != '=' && p.src[i+3] != '!' {
					n++
				}
				continue
			}
			n++
		}
	}
	return n
}

func (p *reParser) parseLegacyOctal() rune {
	v := rune(0)
	n := 0
	for n < 3 && p.peek() >= '0' && p.peek() <= '7' {
		nv := v*8 + (p.peek() - '0')
		if nv > 0377 {
			break
		}
		v = nv
		p.pos++
		n++
	}
	return v
}

// parseCharEscape parses the escape after backslash (pos at the escape char)
func (p *reParser) parseCharEscape(inClass bool) rune {
	c := p.peek()
	p.pos++
	switch c {
	case 'n':
		return '\n'
	case 't':
		return '\t'
	case 'r':
		return '\r'
	case 'f':
		return '\f'
	case 'v':
		return '\v'
	case 'b':
		if inClass {
			return '\b'
		}
	case '-':
		if inClass {
			return '-'
		}
		if p.unicodeM {
			p.fail("invalid escape")
		}
		return '-'
	case 'c':
		n := p.peek()
		if (n >= 'a' && n <= 'z') || (n >= 'A' && n <= 'Z') {
			p.pos++
			return n % 32
		}
		if inClass && !p.unicodeM && ((n >= '0' && n <= '9') || n == '_') {
			p.pos++
			return n % 32
		}
		if p.unicodeM {
			p.fail("invalid escape")
		}
		p.pos--
		return '\\'
	case 'x':
		if p.pos+2 <= len(p.src) {
			d1, d2 := hexValRune(p.src[p.pos]), hexValRune(p.src[p.pos+1])
			if d1 >= 0 && d2 >= 0 {
				p.pos += 2
				return rune(d1*16 + d2)
			}
		}
		if p.unicodeM {
			p.fail("invalid escape")
		}
		return 'x'
	case 'u':
		if p.eat('{') {
			if !p.unicodeM {
				p.pos--
				return 'u'
			}
			v := rune(0)
			n := 0
			for p.peek() != '}' {
				d := hexValRune(p.peek())
				if d < 0 {
					p.fail("invalid unicode escape")
				}
				v = v*16 + rune(d)
				if v > 0x10FFFF {
					p.fail("invalid unicode escape")
				}
				p.pos++
				n++
			}
			p.pos++
			if n == 0 {
				p.fail("invalid unicode escape")
			}
			return v
		}
		if p.pos+4 <= len(p.src) {
			v := rune(0)
			ok := true
			for i := 0; i < 4; i++ {
				d := hexValRune(p.src[p.pos+i])
				if d < 0 {
					ok = false
					break
				}
				v = v*16 + rune(d)
			}
			if ok {
				p.pos += 4
				if p.unicodeM && v >= 0xD800 && v <= 0xDBFF && p.peek() == '\\' && p.pos+5 < len(p.src) && p.src[p.pos+1] == 'u' {
					lo := rune(0)
					ok2 := true
					for i := 0; i < 4; i++ {
						d := hexValRune(p.src[p.pos+2+i])
						if d < 0 {
							ok2 = false
							break
						}
						lo = lo*16 + rune(d)
					}
					if ok2 && lo >= 0xDC00 && lo <= 0xDFFF {
						p.pos += 6
						return utf16.DecodeRune(v, lo)
					}
				}
				return v
			}
		}
		if p.unicodeM {
			p.fail("invalid unicode escape")
		}
		return 'u'
	case '0':
		if p.peek() >= '0' && p.peek() <= '9' {
			if p.unicodeM {
				p.fail("invalid escape")
			}
			p.pos--
			return p.parseLegacyOctal()
		}
		return 0
	}
	if c >= '1' && c <= '9' {
		if inClass {
			if p.unicodeM {
				p.fail("invalid class escape")
			}
			if c >= '8' {
				return c
			}
			p.pos--
			return p.parseLegacyOctal()
		}
	}
	if p.unicodeM {
		// only syntax characters may be identity-escaped
		if strings.ContainsRune("^$\\.*+?()[]{}|/", c) {
			return c
		}
		p.fail("invalid escape")
	}
	if c == -1 {
		p.fail("\\ at end of pattern")
	}
	return c
}

func builtinClass(c rune, ignoreCase bool, unicodeM bool) *charClass {
	cls := &charClass{}
	switch c {
	case 'd', 'D':
		cls.addRange('0', '9')
		cls.negate = c == 'D'
	case 'w', 'W':
		cls.addRange('a', 'z')
		cls.addRange('A', 'Z')
		cls.addRange('0', '9')
		cls.addRange('_', '_')
		if ignoreCase && unicodeM {
			cls.addRange(0x017F, 0x017F)
			cls.addRange(0x212A, 0x212A)
		}
		cls.negate = c == 'W'
	case 's', 'S':
		for _, r := range []rune{0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x20, 0xA0, 0x1680, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000, 0xFEFF} {
			cls.addRange(r, r)
		}
		cls.addRange(0x2000, 0x200A)
		cls.negate = c == 'S'
	}
	cls.normalize()
	return cls
}

func (p *reParser) parsePropertyEscape(negate bool) *charClass {
	if !p.eat('{') {
		p.fail("invalid property name")
	}
	start := p.pos
	for p.peek() != '}' {
		if p.peek() == -1 {
			p.fail("invalid property name")
		}
		p.pos++
	}
	body := string(p.src[start:p.pos])
	p.pos++
	cls := unicodePropertyClass(body)
	if cls == nil {
		p.fail("invalid property name")
	}
	cls.negate = negate
	return cls
}

func tableToClass(t *unicode.RangeTable) *charClass {
	cls := &charClass{}
	for _, r := range t.R16 {
		if r.Stride == 1 {
			cls.addRange(rune(r.Lo), rune(r.Hi))
		} else {
			for c := rune(r.Lo); c <= rune(r.Hi); c += rune(r.Stride) {
				cls.addRange(c, c)
			}
		}
	}
	for _, r := range t.R32 {
		if r.Stride == 1 {
			cls.addRange(rune(r.Lo), rune(r.Hi))
		} else {
			for c := rune(r.Lo); c <= rune(r.Hi); c += rune(r.Stride) {
				cls.addRange(c, c)
			}
		}
	}
	cls.normalize()
	return cls
}

var gcAliases = map[string]string{
	"Letter": "L", "Cased_Letter": "LC", "Uppercase_Letter": "Lu", "Lowercase_Letter": "Ll", "Titlecase_Letter": "Lt", "Modifier_Letter": "Lm", "Other_Letter": "Lo",
	"Mark": "M", "Combining_Mark": "M", "Nonspacing_Mark": "Mn", "Spacing_Mark": "Mc", "Enclosing_Mark": "Me",
	"Number": "N", "Decimal_Number": "Nd", "digit": "Nd", "Letter_Number": "Nl", "Other_Number": "No",
	"Punctuation": "P", "punct": "P", "Connector_Punctuation": "Pc", "Dash_Punctuation": "Pd", "Open_Punctuation": "Ps", "Close_Punctuation": "Pe", "Initial_Punctuation": "Pi", "Final_Punctuation": "Pf", "Other_Punctuation": "Po",
	"Symbol": "S", "Math_Symbol": "Sm", "Currency_Symbol": "Sc", "Modifier_Symbol": "Sk", "Other_Symbol": "So",
	"Separator": "Z", "Space_Separator": "Zs", "Line_Separator": "Zl", "Paragraph_Separator": "Zp",
	"Other": "C", "Control": "Cc", "cntrl": "Cc", "Format": "Cf", "Surrogate": "Cs", "Private_Use": "Co", "Unassigned": "Cn",
}

func unicodePropertyClass(body string) *charClass {
	name := body
	value := ""
	if i := strings.IndexByte(body, '='); i >= 0 {
		name = body[:i]
		value = body[i+1:]
	}
	if value != "" {
		switch name {
		case "General_Category", "gc":
			return gcClass(value)
		case "Script", "sc", "Script_Extensions", "scx":
			if t, ok := unicode.Scripts[value]; ok {
				return tableToClass(t)
			}
			if full, ok := scriptAliases[value]; ok {
				if t, ok := unicode.Scripts[full]; ok {
					return tableToClass(t)
				}
			}
			return nil
		}
		return nil
	}
	if c := gcClass(name); c != nil {
		return c
	}
	switch name {
	case "Any":
		c := &charClass{}
		c.addRange(0, 0x10FFFF)
		return c
	case "ASCII":
		c := &charClass{}
		c.addRange(0, 0x7F)
		return c
	case "Assigned":
		c := tableToClass(unicode.Categories["Cn"])
		if c == nil {
			return nil
		}
		return c.inverted()
	case "Alphabetic", "Alpha":
		c := &charClass{}
		c.addClass(tableToClass(unicode.Letter))
		c.addClass(tableToClass(unicode.Nl))
		c.addClass(tableToClass(unicode.Other_Alphabetic))
		c.normalize()
		return c
	case "Uppercase", "Upper":
		c := &charClass{}
		c.addClass(tableToClass(unicode.Lu))
		c.addClass(tableToClass(unicode.Other_Uppercase))
