func (p *reParser) parseClass() *reNode {
	p.pos++ // [
	cls := &charClass{}
	if p.eat('^') {
		cls.negate = true
	}
	for {
		c := p.peek()
		if c == -1 {
			p.fail("unterminated character class")
		}
		if c == ']' {
			p.pos++
			break
		}
		lo, loCls := p.parseClassAtom()
		if p.peek() == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] != ']' {
			p.pos++
			hi, hiCls := p.parseClassAtom()
			if loCls != nil || hiCls != nil {
				if p.unicodeM {
					p.fail("invalid class range")
				}
				if loCls != nil {
					cls.addClass(loCls)
				} else {
					cls.addRange(lo, lo)
				}
				cls.addRange('-', '-')
				if hiCls != nil {
					cls.addClass(hiCls)
				} else {
					cls.addRange(hi, hi)
				}
				continue
			}
			if lo > hi {
				p.fail("invalid class range")
			}
			cls.addRange(lo, hi)
			continue
		}
		if loCls != nil {
			cls.addClass(loCls)
		} else {
			cls.addRange(lo, lo)
		}
	}
	cls.normalize()
	return &reNode{kind: reClass, cls: cls}
}

// parseClassAtom returns a single char or a class (for \d etc.)
func (p *reParser) parseClassAtom() (rune, *charClass) {
	c := p.peek()
	if c == '\\' {
		p.pos++
		e := p.peek()
		switch e {
		case 'd', 'D', 'w', 'W', 's', 'S':
			p.pos++
			return 0, builtinClass(e, p.ignoreCase, p.unicodeM)
		case 'p', 'P':
			if p.unicodeM {
				p.pos++
				return 0, p.parsePropertyEscape(e == 'P')
			}
		case -1:
			p.fail("\\ at end of pattern")
		}
		return p.parseCharEscape(true), nil
	}
	p.pos++
	return c, nil
}

// ---------- Matcher ----------

type reMatcher struct {
	re        *reCompiled
	input     []uint16
	caps      []int // 2*(ncap+1)
	steps     int
}

func (m *reMatcher) at(pos int) (rune, int) {
	if pos >= len(m.input) {
		return -1, 0
	}
	c := m.input[pos]
	if m.re.unicodeM && c >= 0xD800 && c <= 0xDBFF && pos+1 < len(m.input) {
		d := m.input[pos+1]
		if d >= 0xDC00 && d <= 0xDFFF {
			return utf16.DecodeRune(rune(c), rune(d)), 2
		}
	}
	return rune(c), 1
}

func (m *reMatcher) before(pos int) (rune, int) {
	if pos <= 0 {
		return -1, 0
	}
	c := m.input[pos-1]
	if m.re.unicodeM && c >= 0xDC00 && c <= 0xDFFF && pos-2 >= 0 {
		d := m.input[pos-2]
		if d >= 0xD800 && d <= 0xDBFF {
			return utf16.DecodeRune(rune(d), rune(c)), 2
		}
	}
	return rune(c), 1
}

func isWordChar(r rune) bool {
	return r == '_' || (r >= '0' && r <= '9') || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
}

func (m *reMatcher) isWordAt(pos int) bool {
	if pos < 0 || pos >= len(m.input) {
		return false
	}
	r := rune(m.input[pos])
	if isWordChar(r) {
		return true
	}
	if m.re.ignoreCase && m.re.unicodeM && (r == 0x017F || r == 0x212A) {
		return true
	}
	return false
}

func isLineTerminatorRune(r rune) bool {
	return r == '\n' || r == '\r' || r == 0x2028 || r == 0x2029
}

// match node at pos with continuation; direction: +1 forward, -1 backward (lookbehind)
func (m *reMatcher) match(n *reNode, pos int, dir int, k func(int) bool) bool {
	m.steps++
