				copy(m.caps, saved)
				return false
			}
			if k(pos) {
				return true
			}
			copy(m.caps, saved)
			return false
		}
		copy(m.caps, saved)
		if ok {
			return false
		}
		return k(pos)
	case reStar:
		return m.matchRepeat(n, pos, dir, 0, -1, k)
	}
	return false
}

func (m *reMatcher) matchSeq(items []*reNode, i int, pos int, dir int, k func(int) bool) bool {
	if i == len(items) {
		return k(pos)
	}
	return m.match(items[i], pos, dir, func(p int) bool {
		return m.matchSeq(items, i+1, p, dir, k)
	})
}

func (m *reMatcher) matchSeqRev(items []*reNode, i int, pos int, dir int, k func(int) bool) bool {
	if i < 0 {
		return k(pos)
	}
	return m.match(items[i], pos, dir, func(p int) bool {
		return m.matchSeqRev(items, i-1, p, dir, k)
	})
}

func (m *reMatcher) resetCaps(n *reNode) {
	for i := n.capStart; i <= n.capEnd; i++ {
		m.caps[2*i] = -1
		m.caps[2*i+1] = -1
	}
}

func (m *reMatcher) matchRepeat(n *reNode, pos int, dir int, count int, lastPos int, k func(int) bool) bool {
	child := n.children[0]
	// try another iteration
	tryMore := func() bool {
		if n.max != -1 && count >= n.max {
			return false
		}
		saved := make([]int, 0)
		if n.capEnd >= n.capStart {
			saved = make([]int, 2*(n.capEnd-n.capStart+1))
			copy(saved, m.caps[2*n.capStart:2*(n.capEnd+1)])
			m.resetCaps(n)
		}
		ok := m.match(child, pos, dir, func(p int) bool {
			if p == pos && count >= n.min {
				// empty iteration: stop to avoid infinite loop
				return false
			}
			return m.matchRepeat(n, p, dir, count+1, pos, k)
		})
		if !ok && len(saved) > 0 {
			copy(m.caps[2*n.capStart:2*(n.capEnd+1)], saved)
		}
		return ok
	}
	if count < n.min {
		return tryMore()
	}
	if n.greedy {
		if tryMore() {
			return true
		}
		return k(pos)
	}
	if k(pos) {
		return true
	}
	return tryMore()
}

// exec runs the regexp at the given start index; returns capture positions or nil
func (re *reCompiled) exec(input []uint16, start int) []int {
	m := &reMatcher{re: re, input: input}
	m.caps = make([]int, 2*(re.ncap+1))
	for i := start; i <= len(input); i++ {
		for j := range m.caps {
			m.caps[j] = -1
		}
		var end int
		ok := m.match(re.root, i, 1, func(e int) bool { end = e; return true })
		if ok {
			m.caps[0] = i
			m.caps[1] = end
			return m.caps
		}
		if re.sticky {
			return nil
		}
		// in unicode mode, advance by code point
		if re.unicodeM && i < len(input) {
			c := input[i]
			if c >= 0xD800 && c <= 0xDBFF && i+1 < len(input) && input[i+1] >= 0xDC00 && input[i+1] <= 0xDFFF {
				i++
			}
		}
	}
	return nil
}
