			throwTypeError("not an object")
		}
		s := toString(arg(args, 0))
		flags := toGoString(rx.Get(strKey("flags"), rx))
		if !strings.Contains(flags, "g") {
			return regexpExec(rx, s)
		}
		fullUnicode := strings.Contains(flags, "u") || strings.Contains(flags, "v")
		rx.Set(strKey("lastIndex"), float64(0), rx)
		var out []Value
		for {
			r := regexpExec(rx, s)
			if isNull(r) {
				break
			}
			ro := r.(*Object)
			ms := toString(ro.Get(strKey("0"), ro))
			out = append(out, ms)
			if ms.Len() == 0 {
				li := toLength(rx.Get(strKey("lastIndex"), rx))
				rx.Set(strKey("lastIndex"), float64(advanceStringIndex(s, li, fullUnicode)), rx)
			}
		}
		if len(out) == 0 {
			return Null
		}
		return newArrayObject(out)
	})
	proto.defineMethodSym(SymMatchAll, "[Symbol.matchAll]", 1, func(this Value, args []Value) Value {
		rx, ok := this.(*Object)
		if !ok {
			throwTypeError("not an object")
		}
		s := toString(arg(args, 0))
		C := speciesConstructor(rx, rt.Global.Get(strKey("RegExp"), rt.Global).(*Object))
		flags := toString(rx.Get(strKey("flags"), rx))
		matcher := construct(C, []Value{rx, flags}, nil).(*Object)
		li := toLength(rx.Get(strKey("lastIndex"), rx))
		matcher.Set(strKey("lastIndex"), float64(li), matcher)
		fs := flags.String()
		it := newObjectRaw(rt.RegExpStringIteratorPrototype, ClassIterator)
		it.internal = &regexpStringIterState{rx: matcher, s: s, global: strings.Contains(fs, "g"), unicode: strings.Contains(fs, "u") || strings.Contains(fs, "v")}
		return it
	})
	proto.defineMethodSym(SymSearch, "[Symbol.search]", 1, func(this Value, args []Value) Value {
		rx, ok := this.(*Object)
		if !ok {
			throwTypeError("not an object")
		}
		s := toString(arg(args, 0))
		prevLI := rx.Get(strKey("lastIndex"), rx)
		if !sameValue(prevLI, float64(0)) {
			rx.Set(strKey("lastIndex"), float64(0), rx)
		}
		r := regexpExec(rx, s)
		cur := rx.Get(strKey("lastIndex"), rx)
		if !sameValue(cur, prevLI) {
			rx.Set(strKey("lastIndex"), prevLI, rx)
		}
		if isNull(r) {
			return float64(-1)
		}
		ro := r.(*Object)
		return ro.Get(strKey("index"), ro)
	})
	proto.defineMethodSym(SymSplit, "[Symbol.split]", 2, func(this Value, args []Value) Value {
		rx, ok := this.(*Object)
		if !ok {
			throwTypeError("not an object")
		}
		s := toString(arg(args, 0))
		C := speciesConstructor(rx, rt.Global.Get(strKey("RegExp"), rt.Global).(*Object))
		flags := toGoString(rx.Get(strKey("flags"), rx))
		unicodeM := strings.Contains(flags, "u") || strings.Contains(flags, "v")
		newFlags := flags
		if !strings.Contains(flags, "y") {
			newFlags += "y"
		}
		splitter := construct(C, []Value{rx, NewStringFromGo(newFlags)}, nil).(*Object)
		lim := uint32(0xFFFFFFFF)
		if !isUndefined(arg(args, 1)) {
			lim = toUint32V(arg(args, 1))
		}
		var out []Value
		if lim == 0 {
			return newArrayObject(nil)
		}
		size := s.Len()
		if size == 0 {
			z := regexpExec(splitter, s)
			if !isNull(z) {
				return newArrayObject(nil)
			}
			return newArrayObject([]Value{s})
		}
		p := 0
		q := p
		for q < size {
			splitter.Set(strKey("lastIndex"), float64(q), splitter)
			z := regexpExec(splitter, s)
			if isNull(z) {
				q = advanceStringIndex(s, int64(q), unicodeM)
				continue
			}
			e := int(math.Min(float64(toLength(splitter.Get(strKey("lastIndex"), splitter))), float64(size)))
			if e == p {
				q = advanceStringIndex(s, int64(q), unicodeM)
				continue
			}
			out = append(out, s.Substring(p, q))
			if uint32(len(out)) == lim {
				return newArrayObject(out)
			}
			p = e
			zo := z.(*Object)
			ncap := lengthOfArrayLike(zo) - 1
			if ncap < 0 {
				ncap = 0
			}
			for i := int64(1); i <= ncap; i++ {
				out = append(out, zo.Get(idxKey(i), zo))
				if uint32(len(out)) == lim {
					return newArrayObject(out)
				}
			}
			q = p
		}
		out = append(out, s.Substring(p, size))
		return newArrayObject(out)
	})
	proto.defineMethodSym(SymReplace, "[Symbol.replace]", 2, func(this Value, args []Value) Value {
		rx, ok := this.(*Object)
		if !ok {
			throwTypeError("not an object")
		}
		s := toString(arg(args, 0))
		rv := arg(args, 1)
		var replFn *Object
		var replStr *String
		if isCallable(rv) {
			replFn = rv.(*Object)
		} else {
			replStr = toString(rv)
		}
		flags := toGoString(rx.Get(strKey("flags"), rx))
		global := strings.Contains(flags, "g")
		fullUnicode := strings.Contains(flags, "u") || strings.Contains(flags, "v")
		if global {
			rx.Set(strKey("lastIndex"), float64(0), rx)
		}
		var results []*Object
		for {
			r := regexpExec(rx, s)
			if isNull(r) {
				break
			}
			ro := r.(*Object)
			results = append(results, ro)
			if !global {
				break
			}
			ms := toString(ro.Get(strKey("0"), ro))
			if ms.Len() == 0 {
				li := toLength(rx.Get(strKey("lastIndex"), rx))
				rx.Set(strKey("lastIndex"), float64(advanceStringIndex(s, li, fullUnicode)), rx)
			}
		}
		sb := NewStringBuilder()
		nextPos := 0
		for _, ro := range results {
			ncap := lengthOfArrayLike(ro) - 1
			if ncap < 0 {
				ncap = 0
			}
			matched := toString(ro.Get(strKey("0"), ro))
			pos := int(math.Max(math.Min(toIntegerOrInfinity(ro.Get(strKey("index"), ro)), float64(s.Len())), 0))
			var captures []Value
			for i := int64(1); i <= ncap; i++ {
				c := ro.Get(idxKey(i), ro)
				if !isUndefined(c) {
					c = toString(c)
				}
				captures = append(captures, c)
			}
			named := ro.Get(strKey("groups"), ro)
			var replacement *String
			if replFn != nil {
				fargs := []Value{matched}
				fargs = append(fargs, captures...)
				fargs = append(fargs, float64(pos), s)
				if !isUndefined(named) {
					fargs = append(fargs, named)
				}
				replacement = toString(callFunction(replFn, Undefined, fargs))
			} else {
				if !isUndefined(named) {
					named = toObject(named)
				}
				replacement = getSubstitution(matched, s, pos, captures, named, replStr)
			}
			if pos >= nextPos {
				sb.WriteString(s.Substring(nextPos, pos))
				sb.WriteString(replacement)
				nextPos = pos + matched.Len()
			}
		}
		if nextPos < s.Len() {
			sb.WriteString(s.Substring(nextPos, s.Len()))
		}
		return sb.String()
	})

	// RegExp String Iterator
	rsip := newObjectRaw(rt.IteratorPrototype, ClassObject)
	rt.RegExpStringIteratorPrototype = rsip
	rsip.defineMethod("next", 0, func(this Value, args []Value) Value {
		o, ok := this.(*Object)
		if !ok {
			throwTypeError("not a RegExp String Iterator")
		}
		st, ok := o.internal.(*regexpStringIterState)
		if !ok {
			throwTypeError("not a RegExp String Iterator")
		}
		if st.done {
			return createIterResult(Undefined, true)
		}
		r := regexpExec(st.rx, st.s)
		if isNull(r) {
			st.done = true
			return createIterResult(Undefined, true)
		}
		if !st.global {
			st.done = true
			return createIterResult(r, false)
		}
		ro := r.(*Object)
		ms := toString(ro.Get(strKey("0"), ro))
		if ms.Len() == 0 {
			li := toLength(st.rx.Get(strKey("lastIndex"), st.rx))
			st.rx.Set(strKey("lastIndex"), float64(advanceStringIndex(st.s, li, st.unicode)), st.rx)
		}
		return createIterResult(r, false)
	})
	rsip.setOwnSym(SymToStringTag, NewStringFromGo("RegExp String Iterator"), PropConfigurable)
}

type regexpStringIterState struct {
	rx      *Object
	s       *String
	global  bool
	unicode bool
	done    bool
}

func hex2lower(v int) string {
	const h = "0123456789abcdef"
	return string([]byte{h[(v>>4)&0xf], h[v&0xf]})
}

func escapeRegExpSource(src string) string {
	if src == "" {
		return "(?:)"
	}
	var sb strings.Builder
	inClass := false
	for i := 0; i < len(src); i++ {
		c := src[i]
		switch c {
		case '\\':
			sb.WriteByte(c)
			if i+1 < len(src) {
				i++
				sb.WriteByte(src[i])
			}
			continue
		case '/':
			if !inClass {
				sb.WriteString("\\/")
				continue
			}
		case '[':
			inClass = true
		case ']':
			inClass = false
		case '\n':
			sb.WriteString("\\n")
			continue
		case '\r':
			sb.WriteString("\\r")
			continue
		}
		if c == 0xE2 && i+2 < len(src) && src[i+1] == 0x80 && (src[i+2] == 0xA8 || src[i+2] == 0xA9) {
			if src[i+2] == 0xA8 {
				sb.WriteString("\\u2028")
			} else {
				sb.WriteString("\\u2029")
			}
			i += 2
			continue
		}
		sb.WriteByte(c)
	}
	return sb.String()
}

func advanceStringIndex(s *String, idx int64, unicodeM bool) int {
	if !unicodeM {
		return int(idx) + 1
	}
	if idx+1 >= int64(s.Len()) {
		return int(idx) + 1
	}
	c := s.At(int(idx))
	if c >= 0xD800 && c <= 0xDBFF {
		d := s.At(int(idx) + 1)
		if d >= 0xDC00 && d <= 0xDFFF {
			return int(idx) + 2
		}
	}
	return int(idx) + 1
}

// regexpExec: calls user exec if overridden
func regexpExec(rx *Object, s *String) Value {
	exec := rx.Get(strKey("exec"), rx)
	if isCallable(exec) && exec != Value(rt.regexpBuiltinExec) {
		r := callFunction(exec.(*Object), rx, []Value{s})
		if _, ok := r.(*Object); !ok && !isNull(r) {
			throwTypeError("exec result must be an object or null")
		}
		return r
	}
	if rx.class != ClassRegExp {
		throwTypeError("not a RegExp")
	}
	return regexpBuiltinExec(rx, s)
}

func regexpBuiltinExec(rx *Object, s *String) Value {
	rd := rx.internal.(*RegExpData)
	re := rd.re
	li := int64(0)
	liv := rx.Get(strKey("lastIndex"), rx)
	if re.global || re.sticky {
		li = toLength(liv)
	} else {
		toLength(liv)
	}
	input := s.UTF16()
	if li > int64(len(input)) {
		if re.global || re.sticky {
			rx.Set(strKey("lastIndex"), float64(0), rx)
		}
		return Null
	}
	caps := re.exec(input, int(li))
	if caps == nil {
		if re.global || re.sticky {
			if !rx.Set(strKey("lastIndex"), float64(0), rx) {
				throwTypeError("lastIndex is read-only")
			}
		}
		return Null
	}
	if re.global || re.sticky {
		if !rx.Set(strKey("lastIndex"), float64(caps[1]), rx) {
			throwTypeError("lastIndex is read-only")
		}
	}
	return buildMatchResult(re, s, caps)
}

func buildMatchResult(re *reCompiled, s *String, caps []int) Value {
	n := re.ncap + 1
	elems := make([]Value, n)
	for i := 0; i < n; i++ {
		if caps[2*i] < 0 {
			elems[i] = Undefined
		} else {
			elems[i] = s.Substring(caps[2*i], caps[2*i+1])
		}
	}
	a := newArrayObject(elems)
	a.setOwn("index", float64(caps[0]), PropDefault)
	a.setOwn("input", s, PropDefault)
	var groups Value = Undefined
	if len(re.names) > 0 {
		g := newObjectRaw(nil, ClassObject)
		// in source order
		for i := 1; i < len(re.groupNames); i++ {
			name := re.groupNames[i]
			if name == "" {
				continue
			}
			g.setOwn(name, elems[i], PropDefault)
		}
		groups = g
	}
	a.setOwn("groups", groups, PropDefault)
	if re.hasIndices {
		ind := make([]Value, n)
		for i := 0; i < n; i++ {
			if caps[2*i] < 0 {
				ind[i] = Undefined
			} else {
				ind[i] = newArrayObject([]Value{float64(caps[2*i]), float64(caps[2*i+1])})
			}
		}
		ia := newArrayObject(ind)
		var ig Value = Undefined
		if len(re.names) > 0 {
			g := newObjectRaw(nil, ClassObject)
			for i := 1; i < len(re.groupNames); i++ {
				name := re.groupNames[i]
				if name == "" {
					continue
				}
				g.setOwn(name, ind[i], PropDefault)
			}
			ig = g
		}
		ia.setOwn("groups", ig, PropDefault)
		a.setOwn("indices", ia, PropDefault)
	}
	return a
}
