package main

import (
	"math"
	"strings"
)

type RegExpData struct {
	source  string
	flags   string
	re      *reCompiled
}

func isRegExp(v Value) bool {
	o, ok := v.(*Object)
	if !ok {
		return false
	}
	m := o.Get(symKey(SymMatch), o)
	if !isUndefined(m) {
		return toBoolean(m)
	}
	return o.class == ClassRegExp
}

func newRegExpObject(pattern, flags string) *Object {
	return regexpAlloc(rt.RegExpPrototype, pattern, flags)
}

func regexpAlloc(proto *Object, pattern, flags string) *Object {
	re := compileRegExp(pattern, flags)
	o := newObjectRaw(proto, ClassRegExp)
	o.internal = &RegExpData{source: pattern, flags: flags, re: re}
	o.setOwn("lastIndex", float64(0), PropWritable)
	return o
}

func regexpCreate(pattern Value, flags Value) *Object {
	p := ""
	if !isUndefined(pattern) {
		p = toGoString(pattern)
	}
	f := ""
	if !isUndefined(flags) {
		f = toGoString(flags)
	}
	return newRegExpObject(p, f)
}

func thisRegExp(v Value) (*Object, *RegExpData) {
	o, ok := v.(*Object)
	if !ok || o.class != ClassRegExp {
		throwTypeError("not a RegExp")
	}
	return o, o.internal.(*RegExpData)
}

func setupRegExp() {
	proto := newObjectRaw(rt.ObjectPrototype, ClassObject)
	rt.RegExpPrototype = proto
	ctorImpl := func(args []Value, nt *Object, isCall bool) Value {
		pattern := arg(args, 0)
		flags := arg(args, 1)
		patIsRe := isRegExp(pattern)
		if isCall && patIsRe && isUndefined(flags) {
			po := pattern.(*Object)
			c := po.Get(strKey("constructor"), po)
			if c == Value(rt.Global.Get(strKey("RegExp"), rt.Global)) {
				return pattern
			}
		}
		var P, F Value
		if po, ok := pattern.(*Object); ok && po.class == ClassRegExp {
			rd := po.internal.(*RegExpData)
			P = NewStringFromGo(rd.source)
			if isUndefined(flags) {
				F = NewStringFromGo(rd.flags)
			} else {
				F = flags
			}
		} else if patIsRe {
			po := pattern.(*Object)
			P = po.Get(strKey("source"), po)
			if isUndefined(flags) {
				F = po.Get(strKey("flags"), po)
			} else {
				F = flags
			}
		} else {
			P = pattern
			F = flags
		}
		ps := ""
		if !isUndefined(P) {
			ps = toGoString(P)
		}
		fs := ""
		if !isUndefined(F) {
			fs = toGoString(F)
		}
		pr := getPrototypeFromCtor(nt, rt.RegExpPrototype)
		return regexpAlloc(pr, ps, fs)
	}
	ctor := newNativeConstructor("RegExp", 2, func(this Value, args []Value) Value {
		return ctorImpl(args, nil, true)
	}, func(args []Value, nt *Object) Value {
		return ctorImpl(args, nt, false)
	}, proto)
	rt.Global.setOwn("RegExp", ctor, PropHidden)
	ctor.defineGetterSym(SymSpecies, "[Symbol.species]", func(this Value, args []Value) Value { return this })
	ctor.defineMethod("escape", 1, func(this Value, args []Value) Value {
		s, ok := arg(args, 0).(*String)
		if !ok {
			throwTypeError("not a string")
		}
		sb := NewStringBuilder()
		for i := 0; i < s.Len(); i++ {
			c := s.At(i)
			if i == 0 && ((c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
				sb.WriteGo("\\x" + hex2lower(int(c)))
				continue
			}
			if c < 128 && strings.IndexByte("^$\\.*+?()[]{}|/", byte(c)) >= 0 {
				sb.WriteUnit('\\')
				sb.WriteUnit(c)
				continue
			}
			if c < 128 && strings.IndexByte(",-=<>#&!%:;@~'`\"", byte(c)) >= 0 {
				sb.WriteGo("\\x" + hex2lower(int(c)))
				continue
			}
			if isStrWhitespace(c) || c == 0x2028 || c == 0x2029 {
				if c < 256 {
					sb.WriteGo("\\x" + hex2lower(int(c)))
				} else {
					sb.WriteGo("\\u" + hex4(int(c)))
				}
				continue
			}
			if c >= 0xD800 && c <= 0xDFFF {
				sb.WriteGo("\\u" + hex4(int(c)))
				continue
			}
			sb.WriteUnit(c)
		}
		return sb.String()
	})

	proto.defineMethod("compile", 2, func(this Value, args []Value) Value {
		o, rd := thisRegExp(this)
		pattern := arg(args, 0)
		flags := arg(args, 1)
		var ps, fs string
		if po, ok := pattern.(*Object); ok && po.class == ClassRegExp {
			if !isUndefined(flags) {
				throwTypeError("flags must be undefined")
			}
			prd := po.internal.(*RegExpData)
			ps, fs = prd.source, prd.flags
		} else {
			if !isUndefined(pattern) {
				ps = toGoString(pattern)
			}
			if !isUndefined(flags) {
				fs = toGoString(flags)
			}
		}
		re := compileRegExp(ps, fs)
		rd.source, rd.flags, rd.re = ps, fs, re
		o.Set(strKey("lastIndex"), float64(0), o)
		return o
	})
	proto.defineMethod("exec", 1, func(this Value, args []Value) Value {
		o, _ := thisRegExp(this)
		s := toString(arg(args, 0))
		return regexpBuiltinExec(o, s)
	})
	proto.defineMethod("test", 1, func(this Value, args []Value) Value {
		o, ok := this.(*Object)
		if !ok {
			throwTypeError("not an object")
		}
		s := toString(arg(args, 0))
		return !isNull(regexpExec(o, s))
	})
	proto.defineMethod("toString", 0, func(this Value, args []Value) Value {
		o, ok := this.(*Object)
		if !ok {
			throwTypeError("not an object")
		}
		src := toString(o.Get(strKey("source"), o))
		flags := toString(o.Get(strKey("flags"), o))
		return NewStringFromGo("/").Concat(src).Concat(NewStringFromGo("/")).Concat(flags)
	})
	proto.defineGetter("source", func(this Value, args []Value) Value {
		o, ok := this.(*Object)
		if !ok {
			throwTypeError("not an object")
		}
		if o == rt.RegExpPrototype {
			return NewStringFromGo("(?:)")
		}
		_, rd := thisRegExp(this)
		return NewStringFromGo(escapeRegExpSource(rd.source))
	})
	flagGetter := func(name string, ch byte) {
		proto.defineGetter(name, func(this Value, args []Value) Value {
			o, ok := this.(*Object)
			if !ok {
				throwTypeError("not an object")
			}
			if o.class != ClassRegExp {
				if o == rt.RegExpPrototype {
					return Undefined
				}
				throwTypeError("not a RegExp")
			}
			rd := o.internal.(*RegExpData)
			return strings.IndexByte(rd.flags, ch) >= 0
		})
	}
	flagGetter("global", 'g')
	flagGetter("ignoreCase", 'i')
	flagGetter("multiline", 'm')
	flagGetter("dotAll", 's')
	flagGetter("unicode", 'u')
	flagGetter("unicodeSets", 'v')
	flagGetter("sticky", 'y')
	flagGetter("hasIndices", 'd')
	proto.defineGetter("flags", func(this Value, args []Value) Value {
		o, ok := this.(*Object)
		if !ok {
			throwTypeError("not an object")
		}
		var sb strings.Builder
		for _, f := range []struct {
			name string
			ch   byte
		}{{"hasIndices", 'd'}, {"global", 'g'}, {"ignoreCase", 'i'}, {"multiline", 'm'}, {"dotAll", 's'}, {"unicode", 'u'}, {"unicodeSets", 'v'}, {"sticky", 'y'}} {
			if toBoolean(o.Get(strKey(f.name), o)) {
				sb.WriteByte(f.ch)
			}
		}
