		proto.defineMethod(name, 0, func(this Value, args []Value) Value {
			t := thisTimeValue(this)
			if t != t {
				return math.NaN()
			}
			if !utc {
				t = localTime(t)
			}
			return f(t)
		})
	}
	getter("getTime", true, func(t float64) float64 { return t })
	getter("valueOf", true, func(t float64) float64 { return t })
	getter("getFullYear", false, yearFromTime)
	getter("getUTCFullYear", true, yearFromTime)
	getter("getMonth", false, monthFromTime)
	getter("getUTCMonth", true, monthFromTime)
	getter("getDate", false, dateFromTime)
	getter("getUTCDate", true, dateFromTime)
	getter("getDay", false, weekDay)
	getter("getUTCDay", true, weekDay)
	getter("getHours", false, hourFromTime)
	getter("getUTCHours", true, hourFromTime)
	getter("getMinutes", false, minFromTime)
	getter("getUTCMinutes", true, minFromTime)
	getter("getSeconds", false, secFromTime)
	getter("getUTCSeconds", true, secFromTime)
	getter("getMilliseconds", false, msFromTime)
	getter("getUTCMilliseconds", true, msFromTime)
	proto.defineMethod("getYear", 0, func(this Value, args []Value) Value {
		t := thisTimeValue(this)
		if t != t {
			return math.NaN()
		}
		return yearFromTime(localTime(t)) - 1900
	})
	proto.defineMethod("getTimezoneOffset", 0, func(this Value, args []Value) Value {
		t := thisTimeValue(this)
		if t != t {
			return math.NaN()
		}
		return (t - localTime(t)) / 60000
	})
	proto.defineMethod("setTime", 1, func(this Value, args []Value) Value {
		o := this.(*Object)
		thisTimeValue(this)
		t := timeClip(toNumber(arg(args, 0)))
		o.internal = t
		return t
	})
	// setters
	type setterSpec struct {
		name  string
		utc   bool
		nargs int
		apply func(t float64, a []float64, n int) float64
	}
	setters := []setterSpec{
		{"setMilliseconds", false, 1, func(t float64, a []float64, n int) float64 {
			return makeDate(dayFromTime(t), makeTime(hourFromTime(t), minFromTime(t), secFromTime(t), a[0]))
		}},
		{"setUTCMilliseconds", true, 1, func(t float64, a []float64, n int) float64 {
			return makeDate(dayFromTime(t), makeTime(hourFromTime(t), minFromTime(t), secFromTime(t), a[0]))
		}},
		{"setSeconds", false, 2, func(t float64, a []float64, n int) float64 {
			ms := msFromTime(t)
			if n > 1 {
				ms = a[1]
			}
			return makeDate(dayFromTime(t), makeTime(hourFromTime(t), minFromTime(t), a[0], ms))
		}},
		{"setUTCSeconds", true, 2, func(t float64, a []float64, n int) float64 {
			ms := msFromTime(t)
			if n > 1 {
				ms = a[1]
			}
			return makeDate(dayFromTime(t), makeTime(hourFromTime(t), minFromTime(t), a[0], ms))
		}},
		{"setMinutes", false, 3, func(t float64, a []float64, n int) float64 {
			s, ms := secFromTime(t), msFromTime(t)
			if n > 1 {
				s = a[1]
			}
			if n > 2 {
				ms = a[2]
			}
			return makeDate(dayFromTime(t), makeTime(hourFromTime(t), a[0], s, ms))
		}},
		{"setUTCMinutes", true, 3, func(t float64, a []float64, n int) float64 {
			s, ms := secFromTime(t), msFromTime(t)
			if n > 1 {
				s = a[1]
			}
			if n > 2 {
				ms = a[2]
			}
			return makeDate(dayFromTime(t), makeTime(hourFromTime(t), a[0], s, ms))
		}},
		{"setHours", false, 4, func(t float64, a []float64, n int) float64 {
			m, s, ms := minFromTime(t), secFromTime(t), msFromTime(t)
			if n > 1 {
				m = a[1]
			}
			if n > 2 {
				s = a[2]
			}
			if n > 3 {
				ms = a[3]
			}
			return makeDate(dayFromTime(t), makeTime(a[0], m, s, ms))
		}},
		{"setUTCHours", true, 4, func(t float64, a []float64, n int) float64 {
			m, s, ms := minFromTime(t), secFromTime(t), msFromTime(t)
			if n > 1 {
				m = a[1]
			}
			if n > 2 {
				s = a[2]
			}
			if n > 3 {
				ms = a[3]
			}
			return makeDate(dayFromTime(t), makeTime(a[0], m, s, ms))
		}},
		{"setDate", false, 1, func(t float64, a []float64, n int) float64 {
			return makeDate(makeDay(yearFromTime(t), monthFromTime(t), a[0]), timeWithinDay(t))
		}},
		{"setUTCDate", true, 1, func(t float64, a []float64, n int) float64 {
			return makeDate(makeDay(yearFromTime(t), monthFromTime(t), a[0]), timeWithinDay(t))
		}},
		{"setMonth", false, 2, func(t float64, a []float64, n int) float64 {
			d := dateFromTime(t)
			if n > 1 {
				d = a[1]
			}
			return makeDate(makeDay(yearFromTime(t), a[0], d), timeWithinDay(t))
		}},
		{"setUTCMonth", true, 2, func(t float64, a []float64, n int) float64 {
			d := dateFromTime(t)
			if n > 1 {
				d = a[1]
			}
			return makeDate(makeDay(yearFromTime(t), a[0], d), timeWithinDay(t))
		}},
		{"setFullYear", false, 3, func(t float64, a []float64, n int) float64 {
			if t != t {
				t = 0
			}
			m, d := monthFromTime(t), dateFromTime(t)
			if n > 1 {
				m = a[1]
			}
			if n > 2 {
				d = a[2]
			}
			return makeDate(makeDay(a[0], m, d), timeWithinDay(t))
		}},
		{"setUTCFullYear", true, 3, func(t float64, a []float64, n int) float64 {
			if t != t {
				t = 0
			}
			m, d := monthFromTime(t), dateFromTime(t)
			if n > 1 {
				m = a[1]
			}
			if n > 2 {
				d = a[2]
			}
			return makeDate(makeDay(a[0], m, d), timeWithinDay(t))
		}},
	}
	for _, sp := range setters {
		sp := sp
		proto.defineMethod(sp.name, sp.nargs, func(this Value, args []Value) Value {
			o := this.(*Object)
			t := thisTimeValue(this)
			a := make([]float64, sp.nargs)
			n := len(args)
			if n > sp.nargs {
				n = sp.nargs
			}
			for i := 0; i < sp.nargs; i++ {
				if i < len(args) {
					a[i] = toNumber(args[i])
				}
			}
			if n == 0 {
				n = 1
				a[0] = math.NaN()
			}
			isFullYear := strings.Contains(sp.name, "FullYear")
			if t != t && !isFullYear {
				return math.NaN()
			}
			if !sp.utc {
				if t == t {
					t = localTime(t)
				}
			}
			r := sp.apply(t, a, n)
			if !sp.utc {
				r = utcTime(r)
			}
			r = timeClip(r)
			o.internal = r
			return r
		})
	}
	proto.defineMethod("setYear", 1, func(this Value, args []Value) Value {
		o := this.(*Object)
		t := thisTimeValue(this)
		y := toNumber(arg(args, 0))
		if y != y {
			o.internal = math.NaN()
			return math.NaN()
		}
		yi := math.Trunc(y)
		if yi >= 0 && yi <= 99 {
			yi += 1900
		}
		if t != t {
			t = 0
		} else {
			t = localTime(t)
		}
		r := utcTime(makeDate(makeDay(yi, monthFromTime(t), dateFromTime(t)), timeWithinDay(t)))
		r = timeClip(r)
		o.internal = r
		return r
	})
	proto.defineMethod("toString", 0, func(this Value, args []Value) Value {
		return NewStringFromGo(dateToString(thisTimeValue(this)))
	})
	proto.defineMethod("toDateString", 0, func(this Value, args []Value) Value {
		t := thisTimeValue(this)
		if t != t {
			return NewStringFromGo("Invalid Date")
		}
		lt := localTime(t)
		return NewStringFromGo(fmt.Sprintf("%s %s %02d %s", weekDays[int(weekDay(lt))], monthNames[int(monthFromTime(lt))], int(dateFromTime(lt)), formatYear(yearFromTime(lt))))
	})
	proto.defineMethod("toTimeString", 0, func(this Value, args []Value) Value {
		t := thisTimeValue(this)
		if t != t {
			return NewStringFromGo("Invalid Date")
		}
