		return NewStringFromGo(fmt.Sprintf("%02d:%02d:%02d %s", int(hourFromTime(lt)), int(minFromTime(lt)), int(secFromTime(lt)), tzString(t)))
	})
	proto.defineMethod("toISOString", 0, func(this Value, args []Value) Value {
		t := thisTimeValue(this)
		if t != t {
