package main

import (
	"fmt"
	"math"
	"strings"
	"time"
)

const msPerDay = 86400000.0

func dayFromTime(t float64) float64 { return math.Floor(t / msPerDay) }
func timeWithinDay(t float64) float64 {
	r := math.Mod(t, msPerDay)
	if r < 0 {
		r += msPerDay
	}
	return r
}

func daysInYear(y float64) float64 {
	yi := int64(y)
	if yi%4 != 0 {
		return 365
	}
	if yi%100 != 0 {
		return 366
	}
	if yi%400 != 0 {
		return 365
	}
	return 366
}

func dayFromYear(y float64) float64 {
	return 365*(y-1970) + math.Floor((y-1969)/4) - math.Floor((y-1901)/100) + math.Floor((y-1601)/400)
}

func timeFromYear(y float64) float64 { return msPerDay * dayFromYear(y) }

func yearFromTime(t float64) float64 {
	y := math.Floor(t/(msPerDay*365.2425)) + 1970
	for timeFromYear(y) > t {
		y--
	}
	for timeFromYear(y+1) <= t {
		y++
	}
	return y
}

func inLeapYear(t float64) bool { return daysInYear(yearFromTime(t)) == 366 }

func monthFromTime(t float64) float64 {
	d := dayFromTime(t) - dayFromYear(yearFromTime(t))
	leap := 0.0
	if inLeapYear(t) {
		leap = 1
	}
	switch {
	case d < 31:
		return 0
	case d < 59+leap:
		return 1
	case d < 90+leap:
		return 2
	case d < 120+leap:
		return 3
	case d < 151+leap:
		return 4
	case d < 181+leap:
		return 5
	case d < 212+leap:
		return 6
	case d < 243+leap:
		return 7
	case d < 273+leap:
		return 8
	case d < 304+leap:
		return 9
	case d < 334+leap:
		return 10
	}
	return 11
}

func dateFromTime(t float64) float64 {
	d := dayFromTime(t) - dayFromYear(yearFromTime(t))
	leap := 0.0
	if inLeapYear(t) {
		leap = 1
	}
	switch monthFromTime(t) {
	case 0:
		return d + 1
	case 1:
		return d - 30
	case 2:
		return d - 58 - leap
	case 3:
		return d - 89 - leap
	case 4:
		return d - 119 - leap
	case 5:
		return d - 150 - leap
	case 6:
		return d - 180 - leap
	case 7:
		return d - 211 - leap
	case 8:
		return d - 242 - leap
	case 9:
		return d - 272 - leap
	case 10:
		return d - 303 - leap
	}
	return d - 333 - leap
}

func weekDay(t float64) float64 {
	r := math.Mod(dayFromTime(t)+4, 7)
	if r < 0 {
		r += 7
	}
	return r
}

func hourFromTime(t float64) float64 { return math.Mod(math.Floor(t/3600000), 24) + boolF(math.Mod(math.Floor(t/3600000), 24) < 0)*24 }
func minFromTime(t float64) float64  { return posMod(math.Floor(t/60000), 60) }
func secFromTime(t float64) float64  { return posMod(math.Floor(t/1000), 60) }
func msFromTime(t float64) float64   { return posMod(t, 1000) }

func posMod(a, b float64) float64 {
	r := math.Mod(a, b)
	if r < 0 {
		r += b
	}
	return r
}

func boolF(b bool) float64 {
	if b {
		return 1
	}
	return 0
}

func makeTime(h, m, s, ms float64) float64 {
	if math.IsInf(h, 0) || math.IsInf(m, 0) || math.IsInf(s, 0) || math.IsInf(ms, 0) || h != h || m != m || s != s || ms != ms {
		return math.NaN()
	}
	return math.Trunc(h)*3600000 + math.Trunc(m)*60000 + math.Trunc(s)*1000 + math.Trunc(ms)
}

func makeDay(year, month, date float64) float64 {
	if math.IsInf(year, 0) || math.IsInf(month, 0) || math.IsInf(date, 0) || year != year || month != month || date != date {
		return math.NaN()
	}
	y := math.Trunc(year)
	m := math.Trunc(month)
	dt := math.Trunc(date)
	ym := y + math.Floor(m/12)
	mn := posMod(m, 12)
	if math.Abs(ym) > 400000 {
		return math.NaN()
	}
	t := timeFromYear(ym)
	// add months
	monthDays := []float64{31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}
	if daysInYear(ym) == 366 {
		monthDays[1] = 29
	}
	day := dayFromTime(t)
	for i := 0; i < int(mn); i++ {
		day += monthDays[i]
	}
	return day + dt - 1
}

func makeDate(day, tm float64) float64 {
	if math.IsInf(day, 0) || math.IsInf(tm, 0) || day != day || tm != tm {
		return math.NaN()
	}
	return day*msPerDay + tm
}

func timeClip(t float64) float64 {
	if t != t || math.Abs(t) > 8.64e15 {
		return math.NaN()
	}
	return math.Trunc(t) + 0 // +0 converts -0 to +0
}

// local time zone offset in ms for UTC time t
func localTZA(t float64, isUTC bool) float64 {
	if t != t {
		return 0
	}
	if isUTC {
		tt := time.UnixMilli(int64(t)).In(time.Local)
		_, off := tt.Zone()
		return float64(off) * 1000
	}
	// t is local time: approximate
	tt := time.UnixMilli(int64(t)).In(time.Local)
	_, off := tt.Zone()
	tt2 := time.UnixMilli(int64(t) - int64(off)*1000).In(time.Local)
	_, off2 := tt2.Zone()
	return float64(off2) * 1000
}

func localTime(t float64) float64 { return t + localTZA(t, true) }
func utcTime(t float64) float64   { return t - localTZA(t, false) }

func thisTimeValue(v Value) float64 {
