func localeDate(lt float64) string {
	return fmt.Sprintf("%02d/%02d/%s", int(monthFromTime(lt))+1, int(dateFromTime(lt)), formatYear(yearFromTime(lt)))
}

func localeTime(lt float64) string {
	h := int(hourFromTime(lt))
	ampm := "AM"
	if h >= 12 {
		ampm = "PM"
	}
	h12 := h % 12
	if h12 == 0 {
		h12 = 12
	}
	return fmt.Sprintf("%02d:%02d:%02d %s", h12, int(minFromTime(lt)), int(secFromTime(lt)), ampm)
}

func formatYear(y float64) string {
	yi := int(y)
	if yi >= 0 {
		return fmt.Sprintf("%04d", yi)
	}
	return fmt.Sprintf("-%06d", -yi)
}

func tzString(t float64) string {
	off := localTZA(t, true) / 60000
	sign := "+"
	if off < 0 {
		sign = "-"
		off = -off
	}
	return fmt.Sprintf("GMT%s%02d%02d", sign, int(off)/60, int(off)%60)
}

func dateToString(t float64) string {
	if t != t {
		return "Invalid Date"
	}
	lt := localTime(t)
	return fmt.Sprintf("%s %s %02d %s %02d:%02d:%02d %s", weekDays[int(weekDay(lt))], monthNames[int(monthFromTime(lt))], int(dateFromTime(lt)), formatYear(yearFromTime(lt)), int(hourFromTime(lt)), int(minFromTime(lt)), int(secFromTime(lt)), tzString(t))
}

func dateToISO(t float64) string {
	y := int(yearFromTime(t))
	var ys string
	if y >= 0 && y <= 9999 {
		ys = fmt.Sprintf("%04d", y)
	} else if y < 0 {
		ys = fmt.Sprintf("-%06d", -y)
	} else {
		ys = fmt.Sprintf("+%06d", y)
	}
	return fmt.Sprintf("%s-%02d-%02dT%02d:%02d:%02d.%03dZ", ys, int(monthFromTime(t))+1, int(dateFromTime(t)), int(hourFromTime(t)), int(minFromTime(t)), int(secFromTime(t)), int(msFromTime(t)))
}

func dateFromComponents(args []Value, local bool) float64 {
	nums := make([]float64, 7)
	nums[2] = 1
	for i := 0; i < 7 && i < len(args); i++ {
		nums[i] = toNumber(args[i])
	}
	y := nums[0]
	if y == y {
		yi := math.Trunc(y)
		if yi >= 0 && yi <= 99 {
			y = 1900 + yi
		}
	}
	day := makeDay(y, nums[1], nums[2])
	tm := makeTime(nums[3], nums[4], nums[5], nums[6])
	d := makeDate(day, tm)
	if local {
		d = utcTime(d)
	}
	return timeClip(d)
}

// ---------- parsing ----------

func parseDate(s string) float64 {
	s = strings.TrimSpace(s)
	if t, ok := parseISODate(s); ok {
		return t
	}
	if t, ok := parseLooseDate(s); ok {
		return t
	}
	return math.NaN()
}

func parseISODate(s string) (float64, bool) {
	p := 0
	n := len(s)
	readDigits := func(cnt int) (int, bool) {
		if p+cnt > n {
			return 0, false
		}
		v := 0
		for i := 0; i < cnt; i++ {
			c := s[p+i]
			if c < '0' || c > '9' {
				return 0, false
			}
			v = v*10 + int(c-'0')
		}
		p += cnt
		return v, true
	}
	var year int
	sign := 1
	if p < n && (s[p] == '+' || s[p] == '-') {
		if s[p] == '-' {
			sign = -1
		}
		p++
		y, ok := readDigits(6)
		if !ok {
			return 0, false
		}
		if y == 0 && sign == -1 {
			return 0, false
		}
		year = sign * y
	} else {
		y, ok := readDigits(4)
		if !ok {
			return 0, false
		}
		year = y
	}
	month, day := 1, 1
	if p < n && s[p] == '-' {
		p++
		m, ok := readDigits(2)
		if !ok {
			return 0, false
		}
		month = m
		if p < n && s[p] == '-' {
			p++
			d, ok := readDigits(2)
			if !ok {
				return 0, false
			}
			day = d
		}
	}
	hour, min, sec, ms := 0, 0, 0, 0
	hasTime := false
	tzOff := 0
	hasTZ := false
	if p < n && (s[p] == 'T' || s[p] == 't' || s[p] == ' ') {
		p++
		hasTime = true
		h, ok := readDigits(2)
		if !ok {
			return 0, false
		}
		if p >= n || s[p] != ':' {
			return 0, false
		}
		p++
		mi, ok := readDigits(2)
		if !ok {
			return 0, false
		}
		hour, min = h, mi
		if p < n && s[p] == ':' {
			p++
			se, ok := readDigits(2)
			if !ok {
				return 0, false
			}
			sec = se
			if p < n && (s[p] == '.' || s[p] == ',') {
				p++
				start := p
				v := 0
				for p < n && s[p] >= '0' && s[p] <= '9' {
					if p-start < 3 {
						v = v*10 + int(s[p]-'0')
					}
					p++
				}
				if p == start {
					return 0, false
				}
				for i := p - start; i < 3; i++ {
					v *= 10
				}
				ms = v
			}
		}
	}
	if p < n {
		if s[p] == 'Z' || s[p] == 'z' {
			hasTZ = true
			p++
		} else if s[p] == '+' || s[p] == '-' {
			sg := 1
			if s[p] == '-' {
				sg = -1
			}
			p++
			h, ok := readDigits(2)
			if !ok {
				return 0, false
			}
			if p < n && s[p] == ':' {
				p++
			}
			m, ok := readDigits(2)
			if !ok {
				return 0, false
			}
			tzOff = sg * (h*60 + m)
			hasTZ = true
		}
	}
	if p != n {
		return 0, false
	}
	if month < 1 || month > 12 || day < 1 || day > 31 || hour > 24 || min > 59 || sec > 59 {
		return 0, false
	}
	if hour == 24 && (min != 0 || sec != 0 || ms != 0) {
		return 0, false
	}
	t := makeDate(makeDay(float64(year), float64(month-1), float64(day)), makeTime(float64(hour), float64(min), float64(sec), float64(ms)))
	if hasTZ {
		t -= float64(tzOff) * 60000
	} else if hasTime {
		t = utcTime(t)
	}
	return timeClip(t), true
}

// parseLooseDate handles formats like "Jan 15 2024", "Mon, 15 Jan 2024 10:30:00 GMT", "2024/01/15", "1/15/2024"
func parseLooseDate(s string) (float64, bool) {
	// tokenize
	var toks []string
	i := 0
	for i < len(s) {
		c := s[i]
		switch {
		case c == ' ' || c == ',' || c == '\t':
			i++
		case c >= '0' && c <= '9':
			j := i
			for j < len(s) && (s[j] >= '0' && s[j] <= '9' || s[j] == ':' || s[j] == '.' || s[j] == '/' || s[j] == '-') {
				j++
			}
			toks = append(toks, s[i:j])
			i = j
		case c == '+' || c == '-':
			j := i + 1
			for j < len(s) && (s[j] >= '0' && s[j] <= '9' || s[j] == ':') {
				j++
			}
			toks = append(toks, s[i:j])
			i = j
		case c == '(':
			j := i
			for j < len(s) && s[j] != ')' {
				j++
			}
			i = j + 1
		default:
			j := i
			for j < len(s) && ((s[j] >= 'a' && s[j] <= 'z') || (s[j] >= 'A' && s[j] <= 'Z') || s[j] == '.') {
				j++
			}
			if j == i {
				return 0, false
			}
			toks = append(toks, s[i:j])
			i = j
		}
	}
	year, month, day := -1, -1, -1
	hour, min, sec, ms := 0, 0, 0, 0
	tzOff := 0
	hasTZ := false
	pm := -1
	var nums []int
	for _, t := range toks {
		lower := strings.ToLower(t)
		if strings.Contains(t, ":") && (t[0] >= '0' && t[0] <= '9') {
			// time
			parts := strings.Split(t, ":")
			if len(parts) < 2 || len(parts) > 3 {
				return 0, false
			}
			var ok bool
			hour, ok = atoiSafe(parts[0])
			if !ok {
				return 0, false
			}
			min, ok = atoiSafe(parts[1])
			if !ok {
				return 0, false
			}
			if len(parts) == 3 {
				sp := parts[2]
				if k := strings.IndexByte(sp, '.'); k >= 0 {
					frac := sp[k+1:]
					sp = sp[:k]
					for len(frac) < 3 {
						frac += "0"
					}
					ms, _ = atoiSafe(frac[:3])
				}
				sec, ok = atoiSafe(sp)
				if !ok {
					return 0, false
				}
			}
			continue
		}
		if (t[0] == '+' || t[0] == '-') && len(t) > 1 && year >= 0 {
			// timezone offset
			body := strings.ReplaceAll(t[1:], ":", "")
			v, ok := atoiSafe(body)
			if !ok {
				return 0, false
			}
			var h, m int
			if len(body) <= 2 {
				h, m = v, 0
			} else {
				h, m = v/100, v%100
			}
			tzOff = h*60 + m
			if t[0] == '-' {
				tzOff = -tzOff
			}
			hasTZ = true
			continue
		}
		if strings.Contains(t, "/") || (strings.Contains(t, "-") && t[0] >= '0' && t[0] <= '9') {
			sep := "/"
			if !strings.Contains(t, "/") {
				sep = "-"
			}
			parts := strings.Split(t, sep)
			if len(parts) != 3 {
				return 0, false
			}
			a, ok1 := atoiSafe(parts[0])
			b, ok2 := atoiSafe(parts[1])
			c, ok3 := atoiSafe(parts[2])
			if !ok1 || !ok2 || !ok3 {
				return 0, false
			}
			if len(parts[0]) >= 3 {
				year, month, day = a, b, c
			} else {
				month, day, year = a, b, c
			}
			continue
		}
		if t[0] >= '0' && t[0] <= '9' {
			v, ok := atoiSafe(t)
			if !ok {
				return 0, false
			}
			nums = append(nums, v)
			continue
		}
		switch {
		case lower == "am":
			pm = 0
		case lower == "pm":
			pm = 1
		case lower == "gmt" || lower == "utc" || lower == "ut" || lower == "z":
			hasTZ = true
		case strings.HasPrefix(lower, "gmt") || strings.HasPrefix(lower, "utc"):
			rest := t[3:]
			if rest[0] == '+' || rest[0] == '-' {
				body := strings.ReplaceAll(rest[1:], ":", "")
				v, ok := atoiSafe(body)
				if !ok {
					return 0, false
				}
				var h, m int
				if len(body) <= 2 {
					h, m = v, 0
				} else {
					h, m = v/100, v%100
				}
				tzOff = h*60 + m
				if rest[0] == '-' {
					tzOff = -tzOff
				}
				hasTZ = true
			}
		default:
			found := false
			for mi, mn := range monthNames {
				if strings.HasPrefix(lower, strings.ToLower(mn)) {
					month = mi + 1
					found = true
					break
				}
			}
			if found {
				continue
			}
			for _, wd := range weekDays {
				if strings.HasPrefix(lower, strings.ToLower(wd)) {
					found = true
					break
				}
			}
			if !found {
				// unknown word: ignore if it looks like a timezone abbreviation
				if len(t) <= 4 && strings.ToUpper(t) == t {
					continue
				}
				return 0, false
			}
		}
	}
	for _, v := range nums {
		if month >= 0 && day < 0 && v <= 31 && year < 0 {
			day = v
		} else if year < 0 && (v > 31 || day >= 0) {
			year = v
		} else if day < 0 {
			day = v
		} else if year < 0 {
			year = v
		} else {
			return 0, false
		}
	}
	if year < 0 || month < 0 {
		return 0, false
	}
	if day < 0 {
		day = 1
	}
	if year >= 0 && year <= 49 {
		year += 2000
	} else if year >= 50 && year <= 99 {
		year += 1900
	}
	if pm == 1 && hour < 12 {
		hour += 12
	} else if pm == 0 && hour == 12 {
		hour = 0
	}
	t := makeDate(makeDay(float64(year), float64(month-1), float64(day)), makeTime(float64(hour), float64(min), float64(sec), float64(ms)))
	if hasTZ {
		t -= float64(tzOff) * 60000
	} else {
		t = utcTime(t)
	}
	return timeClip(t), true
}

func atoiSafe(s string) (int, bool) {
	if s == "" {
		return 0, false
	}
	v := 0
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
		v = v*10 + int(s[i]-'0')
	}
	return v, true
}
