package main

import (
	"math"
	"math/big"
)

type mapKey struct {
	kind uint8
	f    float64
	s    string
	p    interface{}
}

func toMapKey(v Value) mapKey {
	switch x := v.(type) {
	case undefinedType:
		return mapKey{kind: 0}
	case nullType:
		return mapKey{kind: 1}
	case bool:
		if x {
			return mapKey{kind: 2, f: 1}
		}
		return mapKey{kind: 2, f: 0}
	case float64:
		if x != x {
			return mapKey{kind: 4}
		}
		if x == 0 {
			x = 0
		}
		return mapKey{kind: 3, f: x}
	case *String:
		return mapKey{kind: 5, s: x.Key()}
	case *big.Int:
		return mapKey{kind: 7, s: x.String()}
	case *Symbol:
		return mapKey{kind: 6, p: x}
	case *Object:
		return mapKey{kind: 6, p: x}
	}
	return mapKey{kind: 8}
}

type mapEntry struct {
	key, value Value
	next, prev *mapEntry
	deleted    bool
}

type MapData struct {
	head, tail *mapEntry
	index      map[mapKey]*mapEntry
	size       int
	isSet      bool
}

func newMapData(isSet bool) *MapData {
	return &MapData{index: map[mapKey]*mapEntry{}, isSet: isSet}
}

func (m *MapData) get(k Value) (*mapEntry, bool) {
	e, ok := m.index[toMapKey(k)]
	return e, ok
}

func (m *MapData) set(k, v Value) {
	if f, ok := k.(float64); ok && f == 0 {
		k = float64(0)
	}
	mk := toMapKey(k)
	if e, ok := m.index[mk]; ok {
		e.value = v
		return
	}
	e := &mapEntry{key: k, value: v}
	if m.tail == nil {
		m.head = e
		m.tail = e
	} else {
		m.tail.next = e
		e.prev = m.tail
		m.tail = e
	}
	m.index[mk] = e
	m.size++
}

func (m *MapData) delete(k Value) bool {
	mk := toMapKey(k)
	e, ok := m.index[mk]
	if !ok {
		return false
	}
	delete(m.index, mk)
	e.deleted = true
	// unlink but keep e.next for iterators
	if e.prev != nil {
		e.prev.next = e.next
	} else {
		m.head = e.next
	}
	if e.next != nil {
		e.next.prev = e.prev
	} else {
		m.tail = e.prev
	}
	m.size--
	return true
}

func (m *MapData) clear() {
	for e := m.head; e != nil; e = e.next {
		e.deleted = true
	}
	m.head = nil
	m.tail = nil
	m.index = map[mapKey]*mapEntry{}
	m.size = 0
}

type mapIterState struct {
	m    *MapData
	cur  *mapEntry
	kind int // 0 keys, 1 values, 2 entries
	started bool
	done bool
}

func (it *mapIterState) next() Value {
	if it.done {
		return createIterResult(Undefined, true)
	}
	var e *mapEntry
	if !it.started {
		it.started = true
		e = it.m.head
	} else {
		e = it.cur
		if e != nil {
			e = e.next
		}
	}
	for e != nil && e.deleted {
		e = e.next
	}
	if e == nil {
		it.done = true
		it.cur = nil
		return createIterResult(Undefined, true)
	}
	it.cur = e
	switch it.kind {
	case 0:
		return createIterResult(e.key, false)
	case 1:
		return createIterResult(e.value, false)
	}
	return createIterResult(newArrayObject([]Value{e.key, e.value}), false)
}

