// set-like record for Set methods
type setRecord struct {
	obj  *Object
	size float64
	has  Value
	keys Value
}

func getSetRecord(v Value) setRecord {
	o, ok := v.(*Object)
	if !ok {
		throwTypeError("not an object")
	}
	rawSize := o.Get(strKey("size"), o)
	num := toNumber(rawSize)
	if num != num {
		throwTypeError("invalid size")
	}
	size := toIntegerOrInfinity(num)
	if size < 0 {
		throwRangeError("invalid size")
	}
	has := o.Get(strKey("has"), o)
	if !isCallable(has) {
		throwTypeError("'has' is not a function")
	}
	keys := o.Get(strKey("keys"), o)
	if !isCallable(keys) {
		throwTypeError("'keys' is not a function")
	}
	return setRecord{obj: o, size: size, has: has, keys: keys}
}

func (sr setRecord) iterateKeys(f func(Value) bool) {
	itv := callValue(sr.keys, sr.obj, nil)
	ito, ok := itv.(*Object)
	if !ok {
		throwTypeError("keys() result is not an object")
	}
	next := ito.Get(strKey("next"), ito)
	it := &Iterator{obj: ito, next: next}
	for {
		v, ok := it.step()
		if !ok {
			return
		}
		if !f(v) {
			iteratorClose(it)
			return
		}
	}
}

func newSetFromData(md *MapData) *Object {
	o := newObjectRaw(rt.SetPrototype, ClassSet)
	o.internal = md
	return o
}

func setupSetMethods(proto *Object) {
	proto.defineMethod("union", 1, func(this Value, args []Value) Value {
		md := thisMap(this, ClassSet, "Set")
		other := getSetRecord(arg(args, 0))
		res := newMapData(true)
		for e := md.head; e != nil; e = e.next {
			if !e.deleted {
				res.set(e.key, e.key)
			}
		}
		other.iterateKeys(func(v Value) bool { res.set(v, v); return true })
		return newSetFromData(res)
	})
	proto.defineMethod("intersection", 1, func(this Value, args []Value) Value {
		md := thisMap(this, ClassSet, "Set")
		other := getSetRecord(arg(args, 0))
		res := newMapData(true)
		if float64(md.size) <= other.size {
			for e := md.head; e != nil; e = e.next {
				if e.deleted {
					continue
				}
				if toBoolean(callValue(other.has, other.obj, []Value{e.key})) {
					res.set(e.key, e.key)
				}
			}
		} else {
			other.iterateKeys(func(v Value) bool {
				if _, ok := md.get(v); ok {
					res.set(v, v)
				}
				return true
			})
		}
		return newSetFromData(res)
	})
	proto.defineMethod("difference", 1, func(this Value, args []Value) Value {
		md := thisMap(this, ClassSet, "Set")
		other := getSetRecord(arg(args, 0))
		res := newMapData(true)
		for e := md.head; e != nil; e = e.next {
			if !e.deleted {
				res.set(e.key, e.key)
			}
		}
		if float64(md.size) <= other.size {
			for e := md.head; e != nil; e = e.next {
				if e.deleted {
					continue
				}
				if toBoolean(callValue(other.has, other.obj, []Value{e.key})) {
					res.delete(e.key)
				}
			}
		} else {
			other.iterateKeys(func(v Value) bool { res.delete(v); return true })
		}
		return newSetFromData(res)
	})
	proto.defineMethod("symmetricDifference", 1, func(this Value, args []Value) Value {
		md := thisMap(this, ClassSet, "Set")
		other := getSetRecord(arg(args, 0))
		res := newMapData(true)
		for e := md.head; e != nil; e = e.next {
			if !e.deleted {
				res.set(e.key, e.key)
			}
		}
		other.iterateKeys(func(v Value) bool {
			if _, ok := md.get(v); ok {
				res.delete(v)
			} else {
				res.set(v, v)
			}
			return true
		})
		return newSetFromData(res)
	})
	proto.defineMethod("isSubsetOf", 1, func(this Value, args []Value) Value {
		md := thisMap(this, ClassSet, "Set")
		other := getSetRecord(arg(args, 0))
		if float64(md.size) > other.size {
			return false
		}
		for e := md.head; e != nil; e = e.next {
			if e.deleted {
				continue
			}
			if !toBoolean(callValue(other.has, other.obj, []Value{e.key})) {
				return false
			}
		}
		return true
	})
	proto.defineMethod("isSupersetOf", 1, func(this Value, args []Value) Value {
		md := thisMap(this, ClassSet, "Set")
		other := getSetRecord(arg(args, 0))
		if float64(md.size) < other.size {
			return false
		}
		result := true
		other.iterateKeys(func(v Value) bool {
			if _, ok := md.get(v); !ok {
				result = false
				return false
			}
			return true
		})
		return result
	})
	proto.defineMethod("isDisjointFrom", 1, func(this Value, args []Value) Value {
		md := thisMap(this, ClassSet, "Set")
		other := getSetRecord(arg(args, 0))
		result := true
		if float64(md.size) <= other.size {
			for e := md.head; e != nil; e = e.next {
				if e.deleted {
					continue
				}
				if toBoolean(callValue(other.has, other.obj, []Value{e.key})) {
					return false
				}
			}
		} else {
			other.iterateKeys(func(v Value) bool {
				if _, ok := md.get(v); ok {
					result = false
					return false
				}
				return true
			})
		}
		return result
	})
}

