type ProxyData struct {
	target  *Object
	handler *Object
}

func setupProxy() {
	ctor := newNativeConstructor("Proxy", 2, func(this Value, args []Value) Value {
		throwTypeError("Proxy constructor requires 'new'")
		return nil
	}, func(args []Value, nt *Object) Value {
