		revoke := newNativeFunction("", 0, func(this Value, a []Value) Value {
			pd := p.internal.(*ProxyData)
			pd.target = nil
			pd.handler = nil
			return Undefined
		})
		o := newObjectRaw(rt.ObjectPrototype, ClassObject)
		o.setOwn("proxy", p, PropDefault)
		o.setOwn("revoke", revoke, PropDefault)
		return o
	})
