func proxyCreate(target, handler Value) *Object {
	t, ok := target.(*Object)
	if !ok {
		throwTypeError("Proxy target must be an object")
	}
	h, ok := handler.(*Object)
	if !ok {
		throwTypeError("Proxy handler must be an object")
	}
	p := newObjectRaw(nil, ClassProxy)
	p.internal = &ProxyData{target: t, handler: h}
	p.callable = t.callable
	p.ctor = t.ctor
	if t.callable {
		fn := &Function{name: "", native: func(this Value, args []Value) Value {
			return proxyCall(p, this, args)
		}}
		if t.ctor {
			fn.nativeCtor = func(args []Value, nt *Object) Value {
				return proxyConstruct(p, args, nt)
			}
		}
		p.internal = &ProxyData{target: t, handler: h}
		p.proxyFn = fn
	}
	return p
}

func proxyCheck(o *Object) (*Object, *Object) {
	pd := o.internal.(*ProxyData)
	if pd.target == nil {
		throwTypeError("revoked proxy")
	}
	return pd.target, pd.handler
}

func proxyTrap(handler *Object, name string) *Object {
	m := handler.Get(strKey(name), handler)
	if isNullish(m) {
		return nil
	}
	if !isCallable(m) {
		throwTypeError("proxy trap '%s' is not a function", name)
	}
	return m.(*Object)
}

func proxyGetPrototypeOf(o *Object) *Object {
	target, handler := proxyCheck(o)
	trap := proxyTrap(handler, "getPrototypeOf")
	if trap == nil {
		return target.GetPrototypeOf()
	}
	r := callFunction(trap, handler, []Value{target})
	var p *Object
	switch x := r.(type) {
	case *Object:
		p = x
	case nullType:
	default:
		throwTypeError("proxy getPrototypeOf must return an object or null")
	}
	if target.IsExtensible() {
		return p
	}
	if target.GetPrototypeOf() != p {
		throwTypeError("proxy getPrototypeOf inconsistent")
	}
	return p
}

func proxySetPrototypeOf(o *Object, p *Object) bool {
	target, handler := proxyCheck(o)
	trap := proxyTrap(handler, "setPrototypeOf")
