func proxyGetOwnProperty(o *Object, k PropKey) *Prop {
	target, handler := proxyCheck(o)
	trap := proxyTrap(handler, "getOwnPropertyDescriptor")
	if trap == nil {
		return target.GetOwnProperty(k)
	}
	r := callFunction(trap, handler, []Value{target, k.ToValue()})
	targetDesc := target.GetOwnProperty(k)
	if isUndefined(r) {
		if targetDesc == nil {
			return nil
		}
		if !targetDesc.Configurable() {
			throwTypeError("proxy getOwnPropertyDescriptor: property is non-configurable")
		}
		if !target.IsExtensible() {
			throwTypeError("proxy getOwnPropertyDescriptor: target not extensible")
		}
		return nil
	}
	if _, ok := r.(*Object); !ok {
		throwTypeError("proxy getOwnPropertyDescriptor must return an object or undefined")
	}
	d := toPropertyDescriptor(r)
	// complete descriptor
	p := Prop{}
	if d.IsAccessor() {
		p.Flags = PropAccessor
		p.Getter, p.Setter = Undefined, Undefined
		if d.HasGet {
			p.Getter = d.Get
		}
		if d.HasSet {
			p.Setter = d.Set
		}
	} else {
		p.Value = Undefined
		if d.HasValue {
			p.Value = d.Value
		}
		if d.HasWritable && d.Writable {
			p.Flags |= PropWritable
		}
	}
	if d.HasEnumerable && d.Enumerable {
		p.Flags |= PropEnumerable
	}
	if d.HasConfigurable && d.Configurable {
		p.Flags |= PropConfigurable
	}
	if targetDesc == nil {
		if !target.IsExtensible() {
			throwTypeError("proxy getOwnPropertyDescriptor: target not extensible")
		}
		if !p.Configurable() {
			throwTypeError("proxy getOwnPropertyDescriptor: invalid non-configurable")
		}
	} else {
		// compatibility check
		tmp := *targetDesc
		if !applyDescToProp(&tmp, d) {
			throwTypeError("proxy getOwnPropertyDescriptor: incompatible descriptor")
		}
		if !p.Configurable() && targetDesc.Configurable() {
			throwTypeError("proxy getOwnPropertyDescriptor: invalid non-configurable")
		}
		if !p.Configurable() && !p.IsAccessor() && !p.Writable() && targetDesc.Writable() {
			throwTypeError("proxy getOwnPropertyDescriptor: invalid non-writable")
		}
	}
	return &p
}

func proxyDefineOwnProperty(o *Object, k PropKey, d PropDesc) bool {
	target, handler := proxyCheck(o)
	trap := proxyTrap(handler, "defineProperty")
	if trap == nil {
		return target.DefineOwnProperty(k, d)
	}
	descObj := descToObject(d)
	r := toBoolean(callFunction(trap, handler, []Value{target, k.ToValue(), descObj}))
	if !r {
		return false
	}
	targetDesc := target.GetOwnProperty(k)
	settingNonConfig := d.HasConfigurable && !d.Configurable
	if targetDesc == nil {
		if !target.IsExtensible() {
			throwTypeError("proxy defineProperty: target not extensible")
		}
		if settingNonConfig {
			throwTypeError("proxy defineProperty: invalid non-configurable")
		}
	} else {
		tmp := *targetDesc
		if !applyDescToProp(&tmp, d) {
			throwTypeError("proxy defineProperty: incompatible descriptor")
		}
		if settingNonConfig && targetDesc.Configurable() {
			throwTypeError("proxy defineProperty: invalid non-configurable")
		}
		if !targetDesc.IsAccessor() && !targetDesc.Configurable() && targetDesc.Writable() && d.HasWritable && !d.Writable {
			throwTypeError("proxy defineProperty: invalid non-writable")
		}
	}
	return true
}

func descToObject(d PropDesc) *Object {
	o := newObjectRaw(rt.ObjectPrototype, ClassObject)
	if d.HasValue {
		o.setOwn("value", d.Value, PropDefault)
	}
	if d.HasWritable {
		o.setOwn("writable", d.Writable, PropDefault)
	}
	if d.HasGet {
		o.setOwn("get", d.Get, PropDefault)
	}
	if d.HasSet {
		o.setOwn("set", d.Set, PropDefault)
	}
	if d.HasEnumerable {
		o.setOwn("enumerable", d.Enumerable, PropDefault)
	}
	if d.HasConfigurable {
		o.setOwn("configurable", d.Configurable, PropDefault)
	}
	return o
}

func proxyHas(o *Object, k PropKey) bool {
	target, handler := proxyCheck(o)
	trap := proxyTrap(handler, "has")
	if trap == nil {
		return target.HasProperty(k)
	}
	r := toBoolean(callFunction(trap, handler, []Value{target, k.ToValue()}))
	if !r {
		td := target.GetOwnProperty(k)
		if td != nil {
