		}
		if !target.IsExtensible() {
			throwTypeError("proxy deleteProperty: target not extensible")
		}
	}
	return true
}

func proxyOwnKeys(o *Object) []PropKey {
	target, handler := proxyCheck(o)
	trap := proxyTrap(handler, "ownKeys")
	if trap == nil {
		return target.OwnKeys()
	}
	r := callFunction(trap, handler, []Value{target})
	ro, ok := r.(*Object)
	if !ok {
		throwTypeError("proxy ownKeys must return an array")
	}
	n := lengthOfArrayLike(ro)
	var keys []PropKey
	seen := map[PropKey]bool{}
	for i := int64(0); i < n; i++ {
		v := ro.Get(idxKey(i), ro)
		switch v.(type) {
		case *String, *Symbol:
		default:
			throwTypeError("proxy ownKeys must return strings or symbols")
		}
		k := toPropertyKey(v)
		if seen[k] {
			throwTypeError("proxy ownKeys: duplicate key")
		}
		seen[k] = true
		keys = append(keys, k)
	}
	ext := target.IsExtensible()
	targetKeys := target.OwnKeys()
	var nonConfig, config []PropKey
	for _, tk := range targetKeys {
		p := target.GetOwnProperty(tk)
		if p != nil && !p.Configurable() {
			nonConfig = append(nonConfig, tk)
		} else {
			config = append(config, tk)
		}
	}
	if ext && len(nonConfig) == 0 {
		return keys
	}
	unchecked := map[PropKey]bool{}
	for _, k := range keys {
		unchecked[k] = true
	}
	for _, k := range nonConfig {
		if !unchecked[k] {
			throwTypeError("proxy ownKeys: missing non-configurable key")
		}
		delete(unchecked, k)
	}
	if ext {
		return keys
	}
	for _, k := range config {
		if !unchecked[k] {
			throwTypeError("proxy ownKeys: missing key")
		}
		delete(unchecked, k)
	}
	if len(unchecked) > 0 {
		throwTypeError("proxy ownKeys: extra keys")
	}
	return keys
}

func proxyCall(o *Object, this Value, args []Value) Value {
	target, handler := proxyCheck(o)
	trap := proxyTrap(handler, "apply")
	if trap == nil {
		return callFunction(target, this, args)
	}
	return callFunction(trap, handler, []Value{target, this, newArrayObject(append([]Value{}, args...))})
