func sortTypedValues(vals []Value, cmp Value) {
	if isUndefined(cmp) {
		sort.SliceStable(vals, func(i, j int) bool {
			switch a := vals[i].(type) {
			case float64:
				b := vals[j].(float64)
				if a != a {
					return false
				}
				if b != b {
					return true
				}
				if a == 0 && b == 0 {
					return math.Signbit(a) && !math.Signbit(b)
				}
				return a < b
			case *big.Int:
				return a.Cmp(vals[j].(*big.Int)) < 0
			}
			return false
		})
		return
	}
	sort.SliceStable(vals, func(i, j int) bool {
		r := toNumber(callValue(cmp, Undefined, []Value{vals[i], vals[j]}))
		return r < 0
	})
}

// ---------- DataView ----------

type DataViewData struct {
	buffer     *Object
	byteOffset int
	byteLength int
	tracking   bool
}

func (dv *DataViewData) curLength() int {
	ab := dv.buffer.internal.(*ArrayBufferData)
	if ab.detached {
		throwTypeError("ArrayBuffer is detached")
	}
	if dv.tracking {
		l := len(ab.data) - dv.byteOffset
		if l < 0 {
			throwTypeError("DataView out of bounds")
		}
		return l
	}
	if dv.byteOffset+dv.byteLength > len(ab.data) {
		throwTypeError("DataView out of bounds")
	}
	return dv.byteLength
}

func setupDataView() {
	proto := newObjectRaw(rt.ObjectPrototype, ClassObject)
	rt.DataViewPrototype = proto
	ctor := newNativeConstructor("DataView", 1, func(this Value, args []Value) Value {
		throwTypeError("DataView constructor requires 'new'")
		return nil
	}, func(args []Value, nt *Object) Value {
		bo, ok := arg(args, 0).(*Object)
		if !ok || bo.class != ClassArrayBuffer {
			throwTypeError("not an ArrayBuffer")
		}
		ab := bo.internal.(*ArrayBufferData)
		off := toIndex(arg(args, 1))
		if ab.detached {
			throwTypeError("ArrayBuffer is detached")
		}
		bufLen := int64(len(ab.data))
		if off > bufLen {
			throwRangeError("invalid byteOffset")
		}
		dv := &DataViewData{buffer: bo, byteOffset: int(off)}
		if isUndefined(arg(args, 2)) {
			if ab.maxLength >= 0 {
				dv.tracking = true
			} else {
				dv.byteLength = int(bufLen - off)
			}
		} else {
			l := toIndex(arg(args, 2))
			if off+l > bufLen {
				throwRangeError("invalid byteLength")
			}
			dv.byteLength = int(l)
		}
		o := newObjectRaw(getPrototypeFromCtor(nt, rt.DataViewPrototype), ClassDataView)
		o.internal = dv
		return o
	}, proto)
	rt.Global.setOwn("DataView", ctor, PropHidden)
	thisDV := func(v Value) *DataViewData {
		o, ok := v.(*Object)
		if !ok || o.class != ClassDataView {
			throwTypeError("not a DataView")
		}
		return o.internal.(*DataViewData)
	}
	proto.defineGetter("buffer", func(this Value, args []Value) Value { return thisDV(this).buffer })
	proto.defineGetter("byteLength", func(this Value, args []Value) Value { return float64(thisDV(this).curLength()) })
	proto.defineGetter("byteOffset", func(this Value, args []Value) Value {
		dv := thisDV(this)
		dv.curLength()
		return float64(dv.byteOffset)
	})
	proto.setOwnSym(SymToStringTag, NewStringFromGo("DataView"), PropConfigurable)
	for _, k := range taKinds {
		if k.name == "Uint8ClampedArray" {
			continue
		}
		kk := k
		tname := k.name[:len(k.name)-5]
		proto.defineMethod("get"+tname, 1, func(this Value, args []Value) Value {
			dv := thisDV(this)
			idx := toIndex(arg(args, 0))
			little := toBoolean(arg(args, 1))
			n := dv.curLength()
			if int(idx)+kk.size > n {
				throwRangeError("out of bound")
			}
			ab := dv.buffer.internal.(*ArrayBufferData)
			b := make([]byte, kk.size)
			copy(b, ab.data[dv.byteOffset+int(idx):])
			if !little {
				reverseBytes(b)
			}
			tmp := &TypedArray{kind: kk}
			_ = tmp
			return readElemBytes(kk, b)
		})
		proto.defineMethod("set"+tname, 2, func(this Value, args []Value) Value {
			dv := thisDV(this)
			idx := toIndex(arg(args, 0))
			var v Value
			if kk.isBig {
				v = toBigInt(arg(args, 1))
			} else {
				v = toNumber(arg(args, 1))
			}
			little := toBoolean(arg(args, 2))
			n := dv.curLength()
			if int(idx)+kk.size > n {
				throwRangeError("out of bound")
			}
			b := make([]byte, kk.size)
			writeElem(kk, b, v)
			if !little {
				reverseBytes(b)
			}
			ab := dv.buffer.internal.(*ArrayBufferData)
			copy(ab.data[dv.byteOffset+int(idx):], b)
			return Undefined
		})
	}
}

func reverseBytes(b []byte) {
	for i, j := 0, len(b)-1; i < j; i, j = i+1, j-1 {
		b[i], b[j] = b[j], b[i]
	}
}

func readElemBytes(k *taKind, b []byte) Value {
	buf := newArrayBuffer(len(b), nil)
	copy(buf.internal.(*ArrayBufferData).data, b)
	ta := &TypedArray{kind: k, buffer: buf, length: 1}
	return ta.getElem(0)
}

// ---------- Atomics ----------

func setupAtomics() {
	a := newObjectRaw(rt.ObjectPrototype, ClassObject)
	rt.Global.setOwn("Atomics", a, PropHidden)
	a.setOwnSym(SymToStringTag, NewStringFromGo("Atomics"), PropConfigurable)
	validate := func(v Value, idxV Value) (*Object, *TypedArray, int) {
		o, ta := validateTypedArray(v)
		switch ta.kind.name {
		case "Float16Array", "Float32Array", "Float64Array", "Uint8ClampedArray":
			throwTypeError("invalid typed array for Atomics")
		}
		idx := toIndex(idxV)
		if int(idx) >= ta.curLength() {
			throwRangeError("out of bound")
		}
		return o, ta, int(idx)
	}
	rmw := func(name string, op func(old, v Value, isBig bool) Value) {
		a.defineMethod(name, 3, func(this Value, args []Value) Value {
			_, ta, idx := validate(arg(args, 0), arg(args, 1))
			var v Value
			if ta.kind.isBig {
				v = toBigInt(arg(args, 2))
			} else {
				v = toNumber(arg(args, 2))
			}
			old := ta.getElem(idx)
			ta.setElemRaw(idx, op(old, v, ta.kind.isBig))
			return old
		})
	}
	intOp := func(f func(a, b int64) int64, bf func(a, b *big.Int) *big.Int) func(old, v Value, isBig bool) Value {
		return func(old, v Value, isBig bool) Value {
			if isBig {
				return bf(old.(*big.Int), v.(*big.Int))
			}
			return float64(f(int64(toInt32(old.(float64))), int64(toInt32(v.(float64)))))
		}
	}
	rmw("add", intOp(func(a, b int64) int64 { return a + b }, func(a, b *big.Int) *big.Int { return new(big.Int).Add(a, b) }))
	rmw("sub", intOp(func(a, b int64) int64 { return a - b }, func(a, b *big.Int) *big.Int { return new(big.Int).Sub(a, b) }))
	rmw("and", intOp(func(a, b int64) int64 { return a & b }, func(a, b *big.Int) *big.Int { return new(big.Int).And(a, b) }))
	rmw("or", intOp(func(a, b int64) int64 { return a | b }, func(a, b *big.Int) *big.Int { return new(big.Int).Or(a, b) }))
	rmw("xor", intOp(func(a, b int64) int64 { return a ^ b }, func(a, b *big.Int) *big.Int { return new(big.Int).Xor(a, b) }))
	rmw("exchange", func(old, v Value, isBig bool) Value { return v })
	a.defineMethod("load", 2, func(this Value, args []Value) Value {
		_, ta, idx := validate(arg(args, 0), arg(args, 1))
		return ta.getElem(idx)
	})
	a.defineMethod("store", 3, func(this Value, args []Value) Value {
		_, ta, idx := validate(arg(args, 0), arg(args, 1))
		var v Value
		if ta.kind.isBig {
			v = toBigInt(arg(args, 2))
		} else {
			v = toIntegerOrInfinity(arg(args, 2))
		}
		ta.setElemRaw(idx, v)
		return v
	})
	a.defineMethod("compareExchange", 4, func(this Value, args []Value) Value {
		_, ta, idx := validate(arg(args, 0), arg(args, 1))
		var expected, repl Value
		if ta.kind.isBig {
			expected = toBigInt(arg(args, 2))
			repl = toBigInt(arg(args, 3))
		} else {
			expected = toNumber(arg(args, 2))
			repl = toNumber(arg(args, 3))
		}
		old := ta.getElem(idx)
		// compare after conversion to element type
		b := make([]byte, ta.kind.size)
		writeElem(ta.kind, b, expected)
		expConv := readElemBytes(ta.kind, b)
		if strictEquals(old, expConv) {
			ta.setElemRaw(idx, repl)
		}
		return old
	})
	a.defineMethod("isLockFree", 1, func(this Value, args []Value) Value {
		n := toIntegerOrInfinity(arg(args, 0))
		return n == 1 || n == 2 || n == 4 || n == 8
	})
	a.defineMethod("wait", 4, func(this Value, args []Value) Value {
		throwTypeError("Atomics.wait not supported")
		return nil
	})
	a.defineMethod("notify", 3, func(this Value, args []Value) Value {
		return float64(0)
	})
	a.defineMethod("pause", 0, func(this Value, args []Value) Value {
		return Undefined
	})
}
EOF
echo ok"}

