package main

import (
	"encoding/binary"
	"math"
	"math/big"
	"sort"
)

type ArrayBufferData struct {
	data      []byte
	detached  bool
	maxLength int // -1 if not resizable
	shared    bool
}

func (ab *ArrayBufferData) isFixedLength() bool { return ab.maxLength < 0 }

type TypedArray struct {
	kind           *taKind
	buffer         *Object
	byteOffset     int
	length         int // element count (if !lengthTracking)
	lengthTracking bool
}

type taKind struct {
	name  string
	size  int
	isBig bool
	proto *Object
	ctor  *Object
}

var taKinds []*taKind

func (ta *TypedArray) bufData() *ArrayBufferData { return ta.buffer.internal.(*ArrayBufferData) }

func (ta *TypedArray) isOutOfBounds() bool {
	ab := ta.bufData()
	if ab.detached {
		return true
	}
	bufLen := len(ab.data)
	if ta.byteOffset > bufLen {
		return true
	}
	if !ta.lengthTracking && ta.byteOffset+ta.length*ta.kind.size > bufLen {
		return true
	}
	return false
}

func (ta *TypedArray) curLength() int {
	if ta.isOutOfBounds() {
		return 0
	}
	if ta.lengthTracking {
		return (len(ta.bufData().data) - ta.byteOffset) / ta.kind.size
	}
	return ta.length
}

func typedArrayLength(o *Object) int {
	return o.internal.(*TypedArray).curLength()
}

func typedArrayIsOutOfBounds(o *Object) bool {
	return o.internal.(*TypedArray).isOutOfBounds()
}

func typedArrayValidIndex(o *Object, num float64) bool {
	ta := o.internal.(*TypedArray)
	if ta.isOutOfBounds() {
		return false
	}
	if num != math.Trunc(num) || math.IsInf(num, 0) {
		return false
	}
	if num == 0 && math.Signbit(num) {
		return false
	}
	if num < 0 || num >= float64(ta.curLength()) {
		return false
	}
	return true
}

func typedArrayGetIndex(o *Object, num float64) Value {
	if !typedArrayValidIndex(o, num) {
		return nil
	}
	ta := o.internal.(*TypedArray)
	return ta.getElem(int(num))
}

func typedArraySetIndex(o *Object, num float64, v Value) {
	ta := o.internal.(*TypedArray)
	var nv Value
	if ta.kind.isBig {
		nv = toBigInt(v)
	} else {
		nv = toNumber(v)
	}
	if !typedArrayValidIndex(o, num) {
		return
	}
	ta.setElemRaw(int(num), nv)
}

func (ta *TypedArray) getElem(i int) Value {
	ab := ta.bufData()
	off := ta.byteOffset + i*ta.kind.size
	b := ab.data[off : off+ta.kind.size]
	switch ta.kind.name {
	case "Int8Array":
		return float64(int8(b[0]))
	case "Uint8Array", "Uint8ClampedArray":
		return float64(b[0])
	case "Int16Array":
		return float64(int16(binary.LittleEndian.Uint16(b)))
	case "Uint16Array":
		return float64(binary.LittleEndian.Uint16(b))
	case "Int32Array":
		return float64(int32(binary.LittleEndian.Uint32(b)))
	case "Uint32Array":
		return float64(binary.LittleEndian.Uint32(b))
	case "Float16Array":
		return float16ToFloat64(binary.LittleEndian.Uint16(b))
	case "Float32Array":
		return float64(math.Float32frombits(binary.LittleEndian.Uint32(b)))
	case "Float64Array":
		return math.Float64frombits(binary.LittleEndian.Uint64(b))
	case "BigInt64Array":
		return big.NewInt(int64(binary.LittleEndian.Uint64(b)))
	case "BigUint64Array":
		return new(big.Int).SetUint64(binary.LittleEndian.Uint64(b))
	}
	return Undefined
}

func (ta *TypedArray) setElemRaw(i int, v Value) {
	ab := ta.bufData()
	off := ta.byteOffset + i*ta.kind.size
	b := ab.data[off : off+ta.kind.size]
	writeElem(ta.kind, b, v)
}

func writeElem(k *taKind, b []byte, v Value) {
	switch k.name {
	case "Int8Array", "Uint8Array":
		b[0] = byte(toInt32(v.(float64)))
	case "Uint8ClampedArray":
		f := v.(float64)
		if f != f {
			b[0] = 0
		} else if f <= 0 {
			b[0] = 0
		} else if f >= 255 {
			b[0] = 255
		} else {
			b[0] = byte(math.RoundToEven(f))
		}
	case "Int16Array", "Uint16Array":
		binary.LittleEndian.PutUint16(b, uint16(toInt32(v.(float64))))
	case "Int32Array", "Uint32Array":
		binary.LittleEndian.PutUint32(b, uint32(toInt32(v.(float64))))
	case "Float16Array":
		binary.LittleEndian.PutUint16(b, float64ToFloat16(v.(float64)))
	case "Float32Array":
		binary.LittleEndian.PutUint32(b, math.Float32bits(float32(v.(float64))))
	case "Float64Array":
		binary.LittleEndian.PutUint64(b, math.Float64bits(v.(float64)))
	case "BigInt64Array", "BigUint64Array":
		bi := v.(*big.Int)
		m := new(big.Int).And(bi, new(big.Int).SetUint64(math.MaxUint64))
		binary.LittleEndian.PutUint64(b, m.Uint64())
	}
}

func newArrayBuffer(n int, proto *Object) *Object {
	if proto == nil {
		proto = rt.ArrayBufferPrototype
	}
	o := newObjectRaw(proto, ClassArrayBuffer)
	o.internal = &ArrayBufferData{data: make([]byte, n), maxLength: -1}
	return o
}

func thisArrayBuffer(v Value) (*Object, *ArrayBufferData) {
	o, ok := v.(*Object)
	if !ok || o.class != ClassArrayBuffer {
		throwTypeError("not an ArrayBuffer")
	}
	return o, o.internal.(*ArrayBufferData)
}

func thisTypedArray(v Value) (*Object, *TypedArray) {
	o, ok := v.(*Object)
	if !ok || o.class != ClassTypedArray {
		throwTypeError("not a TypedArray")
	}
	return o, o.internal.(*TypedArray)
}

func validateTypedArray(v Value) (*Object, *TypedArray) {
	o, ta := thisTypedArray(v)
	if ta.isOutOfBounds() {
		throwTypeError("typed array is detached or out of bounds")
	}
	return o, ta
}

func newTypedArray(k *taKind, proto *Object, buffer *Object, byteOffset int, length int, tracking bool) *Object {
	if proto == nil {
		proto = k.proto
	}
	o := newObjectRaw(proto, ClassTypedArray)
	o.internal = &TypedArray{kind: k, buffer: buffer, byteOffset: byteOffset, length: length, lengthTracking: tracking}
	return o
}

func allocTypedArray(k *taKind, proto *Object, n int) *Object {
	if n < 0 || n > 1<<31 {
		throwRangeError("invalid array length")
	}
	buf := newArrayBuffer(n*k.size, nil)
	return newTypedArray(k, proto, buf, 0, n, false)
}

// typedArraySpeciesCreate
func typedArraySpeciesCreate(o *Object, args []Value) *Object {
	ta := o.internal.(*TypedArray)
	C := speciesConstructor(o, ta.kind.ctor)
	return typedArrayCreateFromCtor(C, args, ta.kind.isBig)
}

func typedArrayCreateFromCtor(C *Object, args []Value, expectBig bool) *Object {
	r := construct(C, args, nil)
	no, nta := validateTypedArray(r)
	if len(args) == 1 {
		if n, ok := args[0].(float64); ok && float64(nta.curLength()) < n {
			throwTypeError("typed array too small")
		}
	}
	if nta.kind.isBig != expectBig {
		throwTypeError("content type mismatch")
	}
	return no
}

func setupTypedArrays() {
	// ArrayBuffer
	abProto := newObjectRaw(rt.ObjectPrototype, ClassObject)
	rt.ArrayBufferPrototype = abProto
	abCtor := newNativeConstructor("ArrayBuffer", 1, func(this Value, args []Value) Value {
		throwTypeError("ArrayBuffer constructor requires 'new'")
