func constructTypedArray(k *taKind, args []Value, nt *Object) Value {
	proto := getPrototypeFromCtor(nt, k.proto)
	first := arg(args, 0)
	fo, isObj := first.(*Object)
	if !isObj {
		n := toIndex(first)
		return allocTypedArray(k, proto, int(n))
	}
	switch fo.class {
	case ClassArrayBuffer:
		ab := fo.internal.(*ArrayBufferData)
		off := toIndex(arg(args, 1))
		if off%int64(k.size) != 0 {
			throwRangeError("invalid offset")
		}
		if ab.detached {
			throwTypeError("ArrayBuffer is detached")
		}
		bufLen := int64(len(ab.data))
		if isUndefined(arg(args, 2)) {
			if ab.maxLength >= 0 {
				if off > bufLen {
					throwRangeError("invalid offset")
				}
				return newTypedArray(k, proto, fo, int(off), 0, true)
			}
			if bufLen%int64(k.size) != 0 {
				throwRangeError("invalid length")
			}
			if off > bufLen {
				throwRangeError("invalid offset")
			}
			return newTypedArray(k, proto, fo, int(off), int((bufLen-off)/int64(k.size)), false)
		}
		n := toIndex(arg(args, 2))
		if off+n*int64(k.size) > bufLen {
			throwRangeError("invalid length")
		}
		return newTypedArray(k, proto, fo, int(off), int(n), false)
	case ClassTypedArray:
		src := fo.internal.(*TypedArray)
		if src.isOutOfBounds() {
			throwTypeError("typed array is detached or out of bounds")
		}
		n := src.curLength()
		o := allocTypedArray(k, proto, n)
		if src.kind.isBig != k.isBig {
			throwTypeError("content type mismatch")
		}
		ta := o.internal.(*TypedArray)
		for i := 0; i < n; i++ {
			ta.setElemRaw(i, src.getElem(i))
		}
		return o
	default:
		var vals []Value
		if m := getMethod(fo, symKey(SymIterator)); m != nil {
			it := getIteratorFromMethod(fo, m)
			for {
				v, ok := it.step()
				if !ok {
					break
				}
				vals = append(vals, v)
			}
		} else {
			n := lengthOfArrayLike(fo)
			for i := int64(0); i < n; i++ {
				vals = append(vals, fo.Get(idxKey(i), fo))
			}
		}
		o := allocTypedArray(k, proto, len(vals))
		for i, v := range vals {
			typedArraySetIndex(o, float64(i), v)
		}
		return o
	}
}

