func sortTypedValues(vals []Value, cmp Value) {
	if isUndefined(cmp) {
		sort.SliceStable(vals, func(i, j int) bool {
			switch a := vals[i].(type) {
			case float64:
				b := vals[j].(float64)
				if a != a {
					return false
				}
				if b != b {
					return true
				}
				if a == 0 && b == 0 {
					return math.Signbit(a) && !math.Signbit(b)
				}
				return a < b
			case *big.Int:
				return a.Cmp(vals[j].(*big.Int)) < 0
			}
			return false
		})
		return
	}
	sort.SliceStable(vals, func(i, j int) bool {
		r := toNumber(callValue(cmp, Undefined, []Value{vals[i], vals[j]}))
		return r < 0
	})
}

// ---------- DataView ----------

type DataViewData struct {
	buffer     *Object
	byteOffset int
	byteLength int
	tracking   bool
}

func (dv *DataViewData) curLength() int {
	ab := dv.buffer.internal.(*ArrayBufferData)
	if ab.detached {
		throwTypeError("ArrayBuffer is detached")
	}
	if dv.tracking {
		l := len(ab.data) - dv.byteOffset
		if l < 0 {
			throwTypeError("DataView out of bounds")
		}
		return l
	}
	if dv.byteOffset+dv.byteLength > len(ab.data) {
		throwTypeError("DataView out of bounds")
	}
	return dv.byteLength
}

func setupDataView() {
	proto := newObjectRaw(rt.ObjectPrototype, ClassObject)
	rt.DataViewPrototype = proto
	ctor := newNativeConstructor("DataView", 1, func(this Value, args []Value) Value {
