		if ab.detached {
			throwTypeError("ArrayBuffer is detached")
		}
		bufLen := int64(len(ab.data))
		if off > bufLen {
			throwRangeError("invalid byteOffset")
		}
		dv := &DataViewData{buffer: bo, byteOffset: int(off)}
		if isUndefined(arg(args, 2)) {
			if ab.maxLength >= 0 {
				dv.tracking = true
			} else {
				dv.byteLength = int(bufLen - off)
			}
		} else {
			l := toIndex(arg(args, 2))
			if off+l > bufLen {
				throwRangeError("invalid byteLength")
			}
			dv.byteLength = int(l)
		}
		o := newObjectRaw(getPrototypeFromCtor(nt, rt.DataViewPrototype), ClassDataView)
		o.internal = dv
		return o
	}, proto)
	rt.Global.setOwn("DataView", ctor, PropHidden)
	thisDV := func(v Value) *DataViewData {
