func reverseBytes(b []byte) {
	for i, j := 0, len(b)-1; i < j; i, j = i+1, j-1 {
		b[i], b[j] = b[j], b[i]
	}
}

func readElemBytes(k *taKind, b []byte) Value {
	buf := newArrayBuffer(len(b), nil)
	copy(buf.internal.(*ArrayBufferData).data, b)
	ta := &TypedArray{kind: k, buffer: buf, length: 1}
	return ta.getElem(0)
}

