package main

import (
	"strings"
)

const inspectMaxDepth = 2
const inspectMaxItems = 100

type inspector struct {
	sb    *StringBuilder
	stack []*Object
}

func inspectValue(v Value) *String {
	// top-level: strings are raw
	if s, ok := v.(*String); ok {
		return s
	}
	in := &inspector{sb: NewStringBuilder()}
	in.print(v, 0)
	return in.sb.String()
}

func isIdentLike(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '_' || c == '$' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') {
			continue
		}
		if i > 0 && c >= '0' && c <= '9' {
			continue
		}
		return false
	}
	return true
}

func (in *inspector) writeKey(k PropKey) {
	var s string
	if k.Sym != nil {
		if k.Sym.hasDesc {
			s = k.Sym.desc.String()
		} else {
			s = ""
		}
	} else {
		s = k.S
	}
	if isIdentLike(s) || (k.Sym == nil && isIntegerIndexString(s)) {
		in.sb.WriteGo(s)
	} else {
		in.quoteString(NewStringFromGo(s))
	}
}

func (in *inspector) quoteString(s *String) {
	in.sb.WriteUnit('"')
	n := s.Len()
	for i := 0; i < n; i++ {
		c := s.At(i)
		switch c {
		case '"':
			in.sb.WriteGo("\\\"")
		case '\\':
			in.sb.WriteGo("\\\\")
		case '\n':
			in.sb.WriteGo("\\n")
		case '\r':
			in.sb.WriteGo("\\r")
		case '\t':
			in.sb.WriteGo("\\t")
		case '\b':
			in.sb.WriteGo("\\b")
		case '\f':
			in.sb.WriteGo("\\f")
		default:
			if c < 0x20 || c == 0x7f {
				in.sb.WriteGo("\\u" + hex4(int(c)))
			} else if c >= 0xD800 && c <= 0xDFFF {
				if c <= 0xDBFF && i+1 < n && s.At(i+1) >= 0xDC00 && s.At(i+1) <= 0xDFFF {
					in.sb.WriteUnit(c)
					in.sb.WriteUnit(s.At(i + 1))
					i++
				} else {
					in.sb.WriteGo("\\u" + hex4(int(c)))
				}
			} else {
				in.sb.WriteUnit(c)
			}
		}
	}
	in.sb.WriteUnit('"')
}

func classDisplayName(o *Object) string {
	switch o.class {
	case ClassObject:
		return "Object"
	case ClassArray:
		return "Array"
	case ClassFunction:
		return "Function"
	case ClassError:
		return "Error"
	case ClassBoolean:
		return "Boolean"
	case ClassNumber:
		return "Number"
	case ClassString:
		return "String"
	case ClassSymbol:
		return "Symbol"
	case ClassBigInt:
		return "BigInt"
	case ClassDate:
		return "Date"
	case ClassRegExp:
		return "RegExp"
	case ClassMap:
		return "Map"
	case ClassSet:
		return "Set"
	case ClassWeakMap:
		return "WeakMap"
	case ClassWeakSet:
		return "WeakSet"
	case ClassWeakRef:
		return "WeakRef"
	case ClassFinReg:
		return "FinalizationRegistry"
	case ClassArrayBuffer:
		if o.internal.(*ArrayBufferData).shared {
			return "SharedArrayBuffer"
		}
		return "ArrayBuffer"
	case ClassTypedArray:
		return o.internal.(*TypedArray).kind.name
	case ClassDataView:
		return "DataView"
	case ClassPromise:
		return "Promise"
	case ClassProxy:
		return "Object"
	case ClassGenerator:
		return "Generator"
	case ClassAsyncGenerator:
		return "AsyncGenerator"
	case ClassArguments:
		return "Arguments"
	case ClassModuleNS:
		return "Module"
	case ClassIterator:
		switch o.internal.(type) {
		case *arrayIterState:
			return "Array Iterator"
		case *stringIterState:
			return "String Iterator"
		case *mapIterState:
			if o.internal.(*mapIterState).m.isSet {
				return "Set Iterator"
			}
			return "Map Iterator"
		case *regexpStringIterState:
			return "RegExp String Iterator"
		}
		return "Iterator"
	case ClassAsyncFromSyncIterator:
		return "AsyncFromSyncIterator"
	case ClassIteratorHelper:
		return "Iterator Helper"
	}
	return "Object"
}

func (in *inspector) writeClassName(name string) {
	if isIdentLike(name) {
		in.sb.WriteGo(name)
	} else {
		in.quoteString(NewStringFromGo(name))
	}
}

func (in *inspector) print(v Value, depth int) {
	switch x := v.(type) {
	case *String:
		in.quoteString(x)
	case *Symbol:
		in.sb.WriteGo("Symbol(")
		if x.hasDesc {
			in.quoteString(x.desc)
		} else {
			in.sb.WriteGo("\"\"")
		}
		in.sb.WriteGo(")")
	case float64:
		if x == 0 && 1/x < 0 {
			in.sb.WriteGo("-0")
		} else {
			in.sb.WriteGo(numberToString(x))
		}
	case *Object:
		in.printObject(x, depth)
	default:
		if b, ok := v.(interface{ String() string }); ok && isBigInt(v) {
			in.sb.WriteGo(b.String() + "n")
			return
		}
		in.sb.WriteString(toString(v))
	}
}

func (in *inspector) printObject(o *Object, depth int) {
	// circular check
	for i, s := range in.stack {
		if s == o {
			in.sb.WriteGo("[circular " + itoa(i) + "]")
			return
		}
	}
	if depth >= inspectMaxDepth {
		in.sb.WriteGo("[")
		in.writeClassName(classDisplayName(o))
		in.sb.WriteGo("]")
		return
	}
	in.stack = append(in.stack, o)
	defer func() { in.stack = in.stack[:len(in.stack)-1] }()

	switch o.class {
	case ClassFunction:
		in.sb.WriteGo("[Function ")
		nv := o.GetOwnProperty(strKey("name"))
		name := ""
		if nv != nil && !nv.IsAccessor() {
			if ns, ok := nv.Value.(*String); ok {
				name = ns.String()
			}
		}
		if name == "" {
			in.sb.WriteGo("(anonymous)")
		} else {
			in.sb.WriteGo(name)
		}
		in.sb.WriteGo("]")
		in.printExtraProps(o, depth, true, nil)
		return
	case ClassError:
		in.printError(o, depth)
		return
	case ClassDate:
		t := o.internal.(float64)
		if t == t {
			in.sb.WriteGo(dateToISO(t))
			in.printExtraProps(o, depth, true, nil)
			return
		}
	case ClassRegExp:
		rd := o.internal.(*RegExpData)
		in.sb.WriteGo("/" + escapeRegExpSource(rd.source) + "/" + rd.flags)
		in.printExtraProps(o, depth, true, nil)
		return
	case ClassArray:
		in.printArray(o, depth)
		return
	case ClassTypedArray:
		ta := o.internal.(*TypedArray)
		n := ta.curLength()
		in.sb.WriteGo(ta.kind.name + "(" + itoa(n) + ") [")
		count := 0
		for i := 0; i < n; i++ {
			if count >= inspectMaxItems {
				in.sb.WriteGo(", ... " + itoa(n-count) + moreItems(n-count))
				break
			}
			if count > 0 {
				in.sb.WriteGo(",")
			}
			in.sb.WriteGo(" ")
			in.print(ta.getElem(i), depth+1)
			count++
		}
		in.printExtraPropsInline(o, depth, count > 0, func(k PropKey) bool { return k.Sym == nil && isIntegerIndexString(k.S) })
		in.sb.WriteGo(" ]")
		return
	case ClassMap, ClassSet:
		md := o.internal.(*MapData)
		if o.class == ClassMap {
			in.sb.WriteGo("Map(" + itoa(md.size) + ") {")
		} else {
			in.sb.WriteGo("Set(" + itoa(md.size) + ") {")
		}
		count := 0
		for e := md.head; e != nil; e = e.next {
			if e.deleted {
				continue
			}
			if count >= inspectMaxItems {
				in.sb.WriteGo(", ... " + itoa(md.size-count) + moreItems(md.size-count))
				break
			}
			if count > 0 {
				in.sb.WriteGo(",")
			}
			in.sb.WriteGo(" ")
			in.print(e.key, depth+1)
			if o.class == ClassMap {
				in.sb.WriteGo(" => ")
				in.print(e.value, depth+1)
			}
			count++
		}
		in.printExtraPropsInline(o, depth, count > 0, nil)
		in.sb.WriteGo(" }")
		return
	}
	// generic object
	if o.class != ClassObject {
		in.writeClassName(classDisplayName(o))
		in.sb.WriteGo(" ")
	}
	in.sb.WriteGo("{")
	var skip func(PropKey) bool
	if o.class == ClassString {
		skip = func(k PropKey) bool { return k.Sym == nil && isIntegerIndexString(k.S) }
	}
	if o.class == ClassProxy || o.class == ClassModuleNS {
		in.sb.WriteGo("  }")
		return
	}
	in.printExtraPropsInline(o, depth, false, skip)
	in.sb.WriteGo(" }")
}

func moreItems(n int) string {
	if n == 1 {
		return " more item"
	}
	return " more items"
}

// enumerable own keys (string + symbol), excluding skipped
func enumerableKeysForInspect(o *Object, skip func(PropKey) bool) []PropKey {
	var keys []PropKey
	for _, k := range o.OwnKeys() {
		if skip != nil && skip(k) {
			continue
		}
		p := o.GetOwnProperty(k)
		if p == nil || !p.Enumerable() {
			continue
		}
		keys = append(keys, k)
	}
	return keys
}

func (in *inspector) printProp(o *Object, k PropKey, depth int) {
	in.writeKey(k)
	in.sb.WriteGo(": ")
	p := o.GetOwnProperty(k)
	if p == nil {
		in.sb.WriteGo("undefined")
		return
	}
	if p.IsAccessor() {
		hasG := !isUndefined(p.Getter)
		hasS := !isUndefined(p.Setter)
		switch {
		case hasG && hasS:
			in.sb.WriteGo("[Getter/Setter]")
		case hasG:
			in.sb.WriteGo("[Getter]")
		case hasS:
			in.sb.WriteGo("[Setter]")
		default:
			in.sb.WriteGo("undefined")
		}
		return
	}
	in.print(p.Value, depth+1)
}

// printExtraPropsInline prints "key: value" entries inside an already-open bracket.
// hasItems indicates whether items were already printed (for comma separation).
func (in *inspector) printExtraPropsInline(o *Object, depth int, hasItems bool, skip func(PropKey) bool) {
	// private fields first
	count := 0
	if hasItems {
		count = 1
	}
	first := !hasItems
	writeSep := func() {
		if !first {
			in.sb.WriteGo(",")
		}
		in.sb.WriteGo(" ")
		first = false
	}
	for _, pf := range o.privFields {
		if pf.name.kind != 0 {
			continue
		}
		writeSep()
		in.quoteString(NewStringFromGo("#" + pf.name.name))
		in.sb.WriteGo(": ")
		in.print(pf.val, depth+1)
	}
	keys := enumerableKeysForInspect(o, skip)
	shown := 0
	for _, k := range keys {
		if shown >= inspectMaxItems {
			writeSep()
			in.sb.WriteGo("... " + itoa(len(keys)-shown) + moreItems(len(keys)-shown))
			break
		}
		writeSep()
		in.printProp(o, k, depth)
		shown++
	}
	if first {
		// nothing printed: "{  }" style requires an extra space
		in.sb.WriteGo(" ")
	}
	_ = count
}

// printExtraProps prints " { ... }" after a primary representation if there are enumerable props
func (in *inspector) printExtraProps(o *Object, depth int, needSpace bool, skip func(PropKey) bool) {
	keys := enumerableKeysForInspect(o, skip)
	hasPriv := false
	for _, pf := range o.privFields {
		if pf.name.kind == 0 {
			hasPriv = true
		}
	}
	if len(keys) == 0 && !hasPriv {
		return
	}
	if needSpace {
		in.sb.WriteGo(" ")
	}
	in.sb.WriteGo("{")
	in.printExtraPropsInline(o, depth, false, skip)
	in.sb.WriteGo(" }")
}

func (in *inspector) printArray(o *Object, depth int) {
	n := int(arrayLength(o))
	// collect index keys
	var idxKeys []uint32
	if !ad_sparse(o) {
		for i, v := range o.arr {
			if v != hole {
				idxKeys = append(idxKeys, uint32(i))
			}
		}
	} else {
		for _, k := range o.OwnKeys() {
			if k.Sym == nil {
				if idx, ok := arrayIndexFromKey(k.S); ok {
					idxKeys = append(idxKeys, idx)
				}
			}
		}
	}
	dense := true
	if len(idxKeys) > 0 && int(idxKeys[len(idxKeys)-1])+1 != len(idxKeys) {
		dense = false
	}
	in.sb.WriteGo("[")
	count := 0
	first := true
	writeSep := func() {
		if !first {
			in.sb.WriteGo(",")
		}
		in.sb.WriteGo(" ")
		first = false
	}
	if dense {
		for _, idx := range idxKeys {
			if count >= inspectMaxItems {
				writeSep()
				in.sb.WriteGo("... " + itoa(n-count) + moreItems(n-count))
				break
			}
			writeSep()
			in.print(o.Get(idxKey(int64(idx)), o), depth+1)
			count++
		}
		if count < inspectMaxItems && n > len(idxKeys) {
			empty := n - len(idxKeys)
			writeSep()
			in.sb.WriteGo("<" + itoa(empty) + " empty item")
			if empty != 1 {
				in.sb.WriteGo("s")
			}
			in.sb.WriteGo(">")
		}
	} else {
		for _, idx := range idxKeys {
			if count >= inspectMaxItems {
				writeSep()
				in.sb.WriteGo("... " + itoa(len(idxKeys)-count) + moreItems(len(idxKeys)-count))
				break
			}
			writeSep()
			in.sb.WriteGo(uint32ToString(idx) + ": ")
			in.print(o.Get(idxKey(int64(idx)), o), depth+1)
			count++
		}
	}
	// extra props
	keys := enumerableKeysForInspect(o, func(k PropKey) bool { return k.Sym == nil && isIntegerIndexString(k.S) })
	for _, k := range keys {
		writeSep()
		in.printProp(o, k, depth)
	}
	if first {
		in.sb.WriteGo(" ")
	}
	in.sb.WriteGo(" ]")
}

func lookupDataProp(o *Object, name string) (Value, bool) {
	k := strKey(name)
	for obj := o; obj != nil; obj = obj.proto {
		if obj.class == ClassProxy {
			return nil, false
		}
		p := obj.GetOwnProperty(k)
		if p != nil {
			if p.IsAccessor() {
				return nil, false
			}
			return p.Value, true
		}
	}
	return nil, false
}

func errorHeadline(o *Object) string {
	name := "Error"
	if nv, ok := lookupDataProp(o, "name"); ok && !isUndefined(nv) {
		name = toGoString(nv)
	}
	msg := ""
	if mv, ok := lookupDataProp(o, "message"); ok && !isUndefined(mv) {
		msg = toGoString(mv)
	}
	if msg == "" {
		return name
	}
	if name == "" {
		return msg
	}
	return name + ": " + msg
}

func (in *inspector) printError(o *Object, depth int) {
	in.sb.WriteGo(errorHeadline(o))
	if sv, ok := lookupDataProp(o, "stack"); ok {
		if ss, ok := sv.(*String); ok {
			in.sb.WriteGo("\n")
			st := ss.String()
			st = strings.TrimSuffix(st, "\n")
			in.sb.WriteGo(st)
		}
	}
	in.printExtraProps(o, depth, true, nil)
}

// formatErrorForUncaught: used when reporting uncaught exceptions
func formatUncaught(v Value) string {
	if o, ok := v.(*Object); ok && o.class == ClassError {
		s := errorHeadline(o)
		if sv, ok := lookupDataProp(o, "stack"); ok {
			if ss, ok := sv.(*String); ok {
				s += "\n" + ss.String()
				return s
			}
		}
		return s + "\n"
	}
	return inspectValue(v).String() + "\n"
}
