		}
		if i > 0 && c >= '0' && c <= '9' {
			continue
		}
		return false
	}
	return true
}

func (in *inspector) writeKey(k PropKey) {
	var s string
	if k.Sym != nil {
		if k.Sym.hasDesc {
			s = k.Sym.desc.String()
		} else {
			s = ""
		}
	} else {
		s = k.S
	}
	if isIdentLike(s) || (k.Sym == nil && isIntegerIndexString(s)) {
		in.sb.WriteGo(s)
	} else {
		in.quoteString(NewStringFromGo(s))
	}
}

func (in *inspector) quoteString(s *String) {
	in.sb.WriteUnit('"')
	n := s.Len()
	for i := 0; i < n; i++ {
		c := s.At(i)
		switch c {
		case '"':
			in.sb.WriteGo("\\\"")
		case '\\':
			in.sb.WriteGo("\\\\")
		case '\n':
			in.sb.WriteGo("\\n")
		case '\r':
			in.sb.WriteGo("\\r")
		case '\t':
			in.sb.WriteGo("\\t")
		case '\b':
			in.sb.WriteGo("\\b")
		case '\f':
			in.sb.WriteGo("\\f")
		default:
			if c < 0x20 || c == 0x7f {
				in.sb.WriteGo("\\u" + hex4(int(c)))
			} else if c >= 0xD800 && c <= 0xDFFF {
				if c <= 0xDBFF && i+1 < n && s.At(i+1) >= 0xDC00 && s.At(i+1) <= 0xDFFF {
					in.sb.WriteUnit(c)
					in.sb.WriteUnit(s.At(i + 1))
					i++
				} else {
					in.sb.WriteGo("\\u" + hex4(int(c)))
				}
			} else {
				in.sb.WriteUnit(c)
			}
		}
	}
	in.sb.WriteUnit('"')
}

