func (in *inspector) print(v Value, depth int) {
	switch x := v.(type) {
	case *String:
		in.quoteString(x)
	case *Symbol:
		in.sb.WriteGo("Symbol(")
		if x.hasDesc {
			in.quoteString(x.desc)
		} else {
			in.sb.WriteGo("\"\"")
		}
		in.sb.WriteGo(")")
	case float64:
		if x == 0 && 1/x < 0 {
			in.sb.WriteGo("-0")
		} else {
			in.sb.WriteGo(numberToString(x))
		}
	case *Object:
		in.printObject(x, depth)
	default:
		if b, ok := v.(interface{ String() string }); ok && isBigInt(v) {
			in.sb.WriteGo(b.String() + "n")
			return
		}
		in.sb.WriteString(toString(v))
	}
}

func (in *inspector) printObject(o *Object, depth int) {
	// circular check
	for i, s := range in.stack {
		if s == o {
			in.sb.WriteGo("[circular " + itoa(i) + "]")
			return
		}
	}
	if depth >= inspectMaxDepth {
		in.sb.WriteGo("[")
		in.writeClassName(classDisplayName(o))
		in.sb.WriteGo("]")
		return
	}
	in.stack = append(in.stack, o)
	defer func() { in.stack = in.stack[:len(in.stack)-1] }()

	switch o.class {
	case ClassFunction:
		in.sb.WriteGo("[Function ")
		nv := o.GetOwnProperty(strKey("name"))
		name := ""
		if nv != nil && !nv.IsAccessor() {
			if ns, ok := nv.Value.(*String); ok {
				name = ns.String()
			}
		}
		if name == "" {
			in.sb.WriteGo("(anonymous)")
		} else {
			in.sb.WriteGo(name)
		}
		in.sb.WriteGo("]")
		in.printExtraProps(o, depth, true, nil)
		return
	case ClassError:
		in.printError(o, depth)
		return
	case ClassDate:
		t := o.internal.(float64)
		if t == t {
			in.sb.WriteGo(dateToISO(t))
			in.printExtraProps(o, depth, true, nil)
			return
		}
	case ClassRegExp:
		rd := o.internal.(*RegExpData)
		in.sb.WriteGo("/" + escapeRegExpSource(rd.source) + "/" + rd.flags)
		in.printExtraProps(o, depth, true, nil)
		return
	case ClassArray:
		in.printArray(o, depth)
		return
	case ClassTypedArray:
		ta := o.internal.(*TypedArray)
		n := ta.curLength()
		in.sb.WriteGo(ta.kind.name + "(" + itoa(n) + ") [")
		count := 0
		for i := 0; i < n; i++ {
			if count >= inspectMaxItems {
				in.sb.WriteGo(", ... " + itoa(n-count) + moreItems(n-count))
				break
			}
			if count > 0 {
				in.sb.WriteGo(",")
			}
			in.sb.WriteGo(" ")
			in.print(ta.getElem(i), depth+1)
			count++
		}
		in.printExtraPropsInline(o, depth, count > 0, func(k PropKey) bool { return k.Sym == nil && isIntegerIndexString(k.S) })
		in.sb.WriteGo(" ]")
		return
	case ClassMap, ClassSet:
		md := o.internal.(*MapData)
		if o.class == ClassMap {
			in.sb.WriteGo("Map(" + itoa(md.size) + ") {")
		} else {
			in.sb.WriteGo("Set(" + itoa(md.size) + ") {")
		}
		count := 0
		for e := md.head; e != nil; e = e.next {
			if e.deleted {
				continue
			}
			if count >= inspectMaxItems {
				in.sb.WriteGo(", ... " + itoa(md.size-count) + moreItems(md.size-count))
				break
			}
			if count > 0 {
				in.sb.WriteGo(",")
			}
			in.sb.WriteGo(" ")
			in.print(e.key, depth+1)
			if o.class == ClassMap {
				in.sb.WriteGo(" => ")
				in.print(e.value, depth+1)
			}
			count++
		}
		in.printExtraPropsInline(o, depth, count > 0, nil)
		in.sb.WriteGo(" }")
		return
	}
	// generic object
	if o.class != ClassObject {
		in.writeClassName(classDisplayName(o))
		in.sb.WriteGo(" ")
	}
	in.sb.WriteGo("{")
	var skip func(PropKey) bool
	if o.class == ClassString {
		skip = func(k PropKey) bool { return k.Sym == nil && isIntegerIndexString(k.S) }
	}
	if o.class == ClassProxy || o.class == ClassModuleNS {
		in.sb.WriteGo("  }")
		return
	}
	in.printExtraPropsInline(o, depth, false, skip)
	in.sb.WriteGo(" }")
}

func moreItems(n int) string {
	if n == 1 {
		return " more item"
	}
	return " more items"
}

// enumerable own keys (string + symbol), excluding skipped
func enumerableKeysForInspect(o *Object, skip func(PropKey) bool) []PropKey {
	var keys []PropKey
	for _, k := range o.OwnKeys() {
		if skip != nil && skip(k) {
			continue
		}
		p := o.GetOwnProperty(k)
		if p == nil || !p.Enumerable() {
			continue
		}
		keys = append(keys, k)
	}
	return keys
}

func (in *inspector) printProp(o *Object, k PropKey, depth int) {
	in.writeKey(k)
	in.sb.WriteGo(": ")
	p := o.GetOwnProperty(k)
	if p == nil {
		in.sb.WriteGo("undefined")
		return
	}
	if p.IsAccessor() {
		hasG := !isUndefined(p.Getter)
		hasS := !isUndefined(p.Setter)
		switch {
		case hasG && hasS:
			in.sb.WriteGo("[Getter/Setter]")
		case hasG:
			in.sb.WriteGo("[Getter]")
		case hasS:
			in.sb.WriteGo("[Setter]")
		default:
			in.sb.WriteGo("undefined")
		}
		return
	}
	in.print(p.Value, depth+1)
}

// printExtraPropsInline prints "key: value" entries inside an already-open bracket.
// hasItems indicates whether items were already printed (for comma separation).
func (in *inspector) printExtraPropsInline(o *Object, depth int, hasItems bool, skip func(PropKey) bool) {
	// private fields first
	count := 0
	if hasItems {
		count = 1
	}
	first := !hasItems
	writeSep := func() {
		if !first {
			in.sb.WriteGo(",")
		}
		in.sb.WriteGo(" ")
		first = false
	}
	for _, pf := range o.privFields {
		if pf.name.kind != 0 {
			continue
		}
		writeSep()
		in.quoteString(NewStringFromGo("#" + pf.name.name))
		in.sb.WriteGo(": ")
		in.print(pf.val, depth+1)
	}
	keys := enumerableKeysForInspect(o, skip)
	shown := 0
	for _, k := range keys {
		if shown >= inspectMaxItems {
			writeSep()
			in.sb.WriteGo("... " + itoa(len(keys)-shown) + moreItems(len(keys)-shown))
			break
		}
		writeSep()
		in.printProp(o, k, depth)
		shown++
	}
	if first {
		// nothing printed: "{  }" style requires an extra space
		in.sb.WriteGo(" ")
	}
	_ = count
}

// printExtraProps prints " { ... }" after a primary representation if there are enumerable props
func (in *inspector) printExtraProps(o *Object, depth int, needSpace bool, skip func(PropKey) bool) {
	keys := enumerableKeysForInspect(o, skip)
	hasPriv := false
	for _, pf := range o.privFields {
		if pf.name.kind == 0 {
			hasPriv = true
		}
	}
	if len(keys) == 0 && !hasPriv {
		return
	}
	if needSpace {
		in.sb.WriteGo(" ")
	}
	in.sb.WriteGo("{")
	in.printExtraPropsInline(o, depth, false, skip)
	in.sb.WriteGo(" }")
}

func (in *inspector) printArray(o *Object, depth int) {
	n := int(arrayLength(o))
	// collect index keys
	var idxKeys []uint32
	if !ad_sparse(o) {
		for i, v := range o.arr {
