func lookupDataProp(o *Object, name string) (Value, bool) {
	k := strKey(name)
	for obj := o; obj != nil; obj = obj.proto {
		if obj.class == ClassProxy {
			return nil, false
		}
		p := obj.GetOwnProperty(k)
		if p != nil {
			if p.IsAccessor() {
				return nil, false
			}
			return p.Value, true
		}
	}
	return nil, false
}

func errorHeadline(o *Object) string {
	name := "Error"
	if nv, ok := lookupDataProp(o, "name"); ok && !isUndefined(nv) {
		name = toGoString(nv)
	}
	msg := ""
	if mv, ok := lookupDataProp(o, "message"); ok && !isUndefined(mv) {
		msg = toGoString(mv)
	}
	if msg == "" {
		return name
	}
	if name == "" {
		return msg
	}
	return name + ": " + msg
}

func (in *inspector) printError(o *Object, depth int) {
	in.sb.WriteGo(errorHeadline(o))
	if sv, ok := lookupDataProp(o, "stack"); ok {
		if ss, ok := sv.(*String); ok {
			in.sb.WriteGo("\n")
			st := ss.String()
			st = strings.TrimSuffix(st, "\n")
			in.sb.WriteGo(st)
		}
	}
	in.printExtraProps(o, depth, true, nil)
}

// formatErrorForUncaught: used when reporting uncaught exceptions
func formatUncaught(v Value) string {
	if o, ok := v.(*Object); ok && o.class == ClassError {
		s := errorHeadline(o)
		if sv, ok := lookupDataProp(o, "stack"); ok {
			if ss, ok := sv.(*String); ok {
				s += "\n" + ss.String()
				return s
			}
		}
		return s + "\n"
	}
	return inspectValue(v).String() + "\n"
}
