		fd := thisFile(this)
		buf, ok := arg(args, 0).(*Object)
		if !ok || buf.class != ClassArrayBuffer {
			throwTypeError("not an ArrayBuffer")
		}
		ab := buf.internal.(*ArrayBufferData)
		pos := int(toIntegerOrInfinity(arg(args, 1)))
		n := int(toIntegerOrInfinity(arg(args, 2)))
		if pos+n > len(ab.data) {
			throwRangeError("read/write array buffer overflow")
		}
		wr, _ := fd.w.Write(ab.data[pos : pos+n])
		return float64(wr)
	})
	p.defineMethod("setvbuf", 2, func(this Value, args []Value) Value { return Undefined })
}

func errnoOf(err error) int {
	if err == nil {
		return 0
	}
	if pe, ok := err.(*os.PathError); ok {
		err = pe.Err
	}
	if le, ok := err.(*os.LinkError); ok {
		err = le.Err
	}
	if se, ok := err.(*os.SyscallError); ok {
		err = se.Err
	}
	if en, ok := err.(syscall.Errno); ok {
		return int(en)
	}
	return int(syscall.EIO)
}

// ---------- printf ----------

func jsPrintf(args []Value) string {
	if len(args) == 0 {
		return ""
	}
	fmtStr := toString(args[0]).String()
	var sb strings.Builder
	ai := 1
	nextArg := func() Value {
		if ai < len(args) {
			v := args[ai]
			ai++
			return v
		}
		return Undefined
	}
	i := 0
	for i < len(fmtStr) {
		c := fmtStr[i]
		if c != '%' {
			sb.WriteByte(c)
			i++
			continue
		}
		start := i
		i++
		if i >= len(fmtStr) {
			sb.WriteByte('%')
			break
		}
		if fmtStr[i] == '%' {
			sb.WriteByte('%')
			i++
			continue
		}
		// flags
		flags := ""
		for i < len(fmtStr) && strings.IndexByte("-+ #0", fmtStr[i]) >= 0 {
			flags += string(fmtStr[i])
			i++
		}
		width := ""
		if i < len(fmtStr) && fmtStr[i] == '*' {
			width = strconv.Itoa(int(toInt32V(nextArg())))
			i++
		} else {
			for i < len(fmtStr) && fmtStr[i] >= '0' && fmtStr[i] <= '9' {
				width += string(fmtStr[i])
				i++
			}
		}
		prec := ""
		hasPrec := false
		if i < len(fmtStr) && fmtStr[i] == '.' {
			hasPrec = true
			i++
			if i < len(fmtStr) && fmtStr[i] == '*' {
				prec = strconv.Itoa(int(toInt32V(nextArg())))
				i++
			} else {
				for i < len(fmtStr) && fmtStr[i] >= '0' && fmtStr[i] <= '9' {
					prec += string(fmtStr[i])
					i++
				}
			}
		}
		// length modifiers
		for i < len(fmtStr) && strings.IndexByte("hlLqjzt", fmtStr[i]) >= 0 {
			i++
		}
		if i >= len(fmtStr) {
			sb.WriteString(fmtStr[start:])
			break
		}
		conv := fmtStr[i]
		i++
		spec := "%" + flags + width
		if hasPrec {
			spec += "." + prec
		}
		switch conv {
		case 'd', 'i':
			v := nextArg()
			if b, ok := v.(*big.Int); ok {
				sb.WriteString(fmt.Sprintf(spec+"d", b))
			} else {
				n := toNumber(v)
				sb.WriteString(fmt.Sprintf(spec+"d", int64(n)))
			}
		case 'u':
			n := toNumber(nextArg())
			sb.WriteString(fmt.Sprintf(spec+"d", uint64(int64(n))))
		case 'x', 'X', 'o':
			v := nextArg()
			if b, ok := v.(*big.Int); ok {
				sb.WriteString(fmt.Sprintf(spec+string(conv), b))
			} else {
				n := toNumber(v)
				sb.WriteString(fmt.Sprintf(spec+string(conv), uint64(int64(n))))
			}
		case 'c':
			v := nextArg()
			var r rune
			if s, ok := v.(*String); ok {
				if s.Len() > 0 {
					r, _ = s.CodePointAt(0)
				}
			} else {
				r = rune(toInt32V(v))
			}
			sb.WriteString(fmt.Sprintf("%"+flags+width+"c", r))
		case 's':
			s := toString(nextArg()).String()
			sb.WriteString(fmt.Sprintf(spec+"s", s))
		case 'f', 'F', 'e', 'E', 'g', 'G', 'a', 'A':
			n := toNumber(nextArg())
			if conv == 'a' || conv == 'A' {
				sb.WriteString(fmt.Sprintf(spec+"x", n))
			} else {
				sb.WriteString(cFormatFloat(spec, conv, n))
			}
		default:
			sb.WriteString(fmtStr[start:i])
		}
	}
	return sb.String()
}

// cFormatFloat emulates C printf for %f/%e/%g (Go's %g differs from C's)
func cFormatFloat(spec string, conv byte, n float64) string {
	if math.IsInf(n, 0) || n != n {
		s := "nan"
		if math.IsInf(n, 1) {
			s = "inf"
		} else if math.IsInf(n, -1) {
			s = "-inf"
		}
		if conv >= 'A' && conv <= 'Z' {
			s = strings.ToUpper(s)
		}
		return fmt.Sprintf(strings.Replace(spec, "0", "", -1)+"s", s)
	}
	// parse spec
	flags := ""
	width := ""
	prec := -1
	i := 1
	for i < len(spec) && strings.IndexByte("-+ #0", spec[i]) >= 0 {
		flags += string(spec[i])
		i++
	}
	for i < len(spec) && spec[i] >= '0' && spec[i] <= '9' {
		width += string(spec[i])
		i++
	}
	if i < len(spec) && spec[i] == '.' {
		i++
		p := ""
		for i < len(spec) && spec[i] >= '0' && spec[i] <= '9' {
			p += string(spec[i])
			i++
		}
		if p == "" {
			prec = 0
		} else {
			prec, _ = strconv.Atoi(p)
		}
	}
	if prec < 0 {
		prec = 6
	}
	var body string
	switch conv {
	case 'f', 'F':
		body = strconv.FormatFloat(math.Abs(n), 'f', prec, 64)
	case 'e', 'E':
		body = strconv.FormatFloat(math.Abs(n), 'e', prec, 64)
		body = fixExp(body)
	case 'g', 'G':
		if prec == 0 {
			prec = 1
		}
		exp := 0
		if n != 0 {
			exp = int(math.Floor(math.Log10(math.Abs(n))))
			// correct rounding effect
			t := strconv.FormatFloat(math.Abs(n), 'e', prec-1, 64)
			epos := strings.IndexByte(t, 'e')
			exp, _ = strconv.Atoi(t[epos+1:])
		}
		if exp < -4 || exp >= prec {
			body = strconv.FormatFloat(math.Abs(n), 'e', prec-1, 64)
			if !strings.Contains(flags, "#") {
				// strip trailing zeros in mantissa
				epos := strings.IndexByte(body, 'e')
				mant := body[:epos]
				if strings.Contains(mant, ".") {
					mant = strings.TrimRight(mant, "0")
					mant = strings.TrimSuffix(mant, ".")
				}
				body = mant + body[epos:]
			}
			body = fixExp(body)
		} else {
			body = strconv.FormatFloat(math.Abs(n), 'f', prec-1-exp, 64)
			if !strings.Contains(flags, "#") && strings.Contains(body, ".") {
				body = strings.TrimRight(body, "0")
				body = strings.TrimSuffix(body, ".")
			}
		}
	}
	if conv >= 'A' && conv <= 'Z' {
		body = strings.ToUpper(body)
	}
	sign := ""
	if n < 0 || (n == 0 && math.Signbit(n)) {
		sign = "-"
	} else if strings.Contains(flags, "+") {
		sign = "+"
	} else if strings.Contains(flags, " ") {
		sign = " "
	}
	s := sign + body
	w, _ := strconv.Atoi(width)
	if len(s) < w {
		pad := w - len(s)
		if strings.Contains(flags, "-") {
			s += strings.Repeat(" ", pad)
		} else if strings.Contains(flags, "0") {
			s = sign + strings.Repeat("0", pad) + body
		} else {
			s = strings.Repeat(" ", pad) + s
		}
	}
	return s
}

func fixExp(s string) string {
	// Go prints e+07 style already with at least 2 digits; C does the same
	return s
}

// ---------- std module ----------

func getStdModule() *Object {
	if rt.stdModule != nil {
		return rt.stdModule
	}
	setupFilePrototype()
	m := newObjectRaw(nil, ClassObject)
	rt.stdModule = m
	m.defineMethod("printf", 1, func(this Value, args []Value) Value {
		s := jsPrintf(args)
		stdoutWriter.WriteString(s)
		stdoutWriter.Flush()
		return float64(len(s))
	})
	m.defineMethod("sprintf", 1, func(this Value, args []Value) Value {
		return NewStringFromGo(jsPrintf(args))
	})
	m.defineMethod("puts", 1, func(this Value, args []Value) Value {
		for _, a := range args {
			stdoutWriter.WriteString(toString(a).String())
		}
		stdoutWriter.Flush()
		return Undefined
	})
	m.defineMethod("exit", 1, func(this Value, args []Value) Value {
		code := 0
		if len(args) > 0 {
			code = int(toInt32V(args[0]))
		}
		flushAll()
		os.Exit(code)
		return Undefined
	})
	m.defineMethod("gc", 0, func(this Value, args []Value) Value {
		runtime.GC()
		return Undefined
	})
	m.defineMethod("getenv", 1, func(this Value, args []Value) Value {
		v, ok := os.LookupEnv(toGoString(arg(args, 0)))
		if !ok {
			return Undefined
		}
		return NewStringFromGo(v)
	})
	m.defineMethod("setenv", 2, func(this Value, args []Value) Value {
		os.Setenv(toGoString(arg(args, 0)), toGoString(arg(args, 1)))
		return Undefined
	})
	m.defineMethod("unsetenv", 1, func(this Value, args []Value) Value {
		os.Unsetenv(toGoString(arg(args, 0)))
		return Undefined
	})
	m.defineMethod("getenviron", 0, func(this Value, args []Value) Value {
		o := newObjectRaw(rt.ObjectPrototype, ClassObject)
		for _, kv := range os.Environ() {
			i := strings.IndexByte(kv, '=')
			if i < 0 {
				continue
			}
			o.CreateDataProperty(strKey(kv[:i]), NewStringFromGo(kv[i+1:]))
		}
		return o
	})
	m.defineMethod("strerror", 1, func(this Value, args []Value) Value {
		return NewStringFromGo(syscall.Errno(toInt32V(arg(args, 0))).Error())
	})
	m.defineMethod("loadFile", 1, func(this Value, args []Value) Value {
		data, err := os.ReadFile(toGoString(arg(args, 0)))
		if err != nil {
			return Null
		}
		if opts, ok := arg(args, 1).(*Object); ok {
			if toBoolean(opts.Get(strKey("binary"), opts)) {
				ab := newArrayBuffer(len(data), nil)
				copy(ab.internal.(*ArrayBufferData).data, data)
				return ab
			}
		}
		return NewStringFromGo(string(data))
	})
	m.defineMethod("writeFile", 2, func(this Value, args []Value) Value {
		name := toGoString(arg(args, 0))
		var data []byte
		switch d := arg(args, 1).(type) {
		case *Object:
			if d.class == ClassArrayBuffer {
				data = d.internal.(*ArrayBufferData).data
			} else if d.class == ClassTypedArray {
				ta := d.internal.(*TypedArray)
				data = ta.bufData().data[ta.byteOffset : ta.byteOffset+ta.curLength()*ta.kind.size]
			} else {
				data = []byte(toGoString(d))
			}
		default:
			data = []byte(toGoString(d))
		}
		if err := os.WriteFile(name, data, 0644); err != nil {
			throwError("Error", "could not write file '%s'", name)
		}
		return Undefined
	})
	m.defineMethod("loadScript", 1, func(this Value, args []Value) Value {
		name := toGoString(arg(args, 0))
		data, err := os.ReadFile(name)
		if err != nil {
			throwReferenceError("could not load '%s'", name)
		}
		return evalScriptText(string(data), name, false)
	})
	m.defineMethod("evalScript", 2, func(this Value, args []Value) Value {
		code := toGoString(arg(args, 0))
		asModule := false
		backtraceBarrier := false
		if opts, ok := arg(args, 1).(*Object); ok {
			asModule = toBoolean(opts.Get(strKey("async"), opts))
			backtraceBarrier = toBoolean(opts.Get(strKey("backtrace_barrier"), opts))
		}
		_ = asModule
		_ = backtraceBarrier
		return evalScriptText(code, "<evalScript>", false)
	})
	m.defineMethod("open", 2, func(this Value, args []Value) Value {
		name := toGoString(arg(args, 0))
		mode := toGoString(arg(args, 1))
		flags, ok := parseFopenMode(mode)
		if !ok {
			throwTypeError("invalid file mode")
		}
		f, err := os.OpenFile(name, flags, 0666)
		if err != nil {
			setErrnoArg(args, 2, errnoOf(err))
			return Null
		}
		setErrnoArg(args, 2, 0)
		return newFileObject(f, false)
	})
	m.defineMethod("popen", 2, func(this Value, args []Value) Value {
		command := toGoString(arg(args, 0))
		mode := toGoString(arg(args, 1))
		cmd := exec.Command("/bin/sh", "-c", command)
		var f *os.File
		if strings.HasPrefix(mode, "r") {
			r, w, err := os.Pipe()
			if err != nil {
				setErrnoArg(args, 2, errnoOf(err))
				return Null
			}
			cmd.Stdout = w
			cmd.Stdin = os.Stdin
			cmd.Stderr = os.Stderr
			flushAll()
			if err := cmd.Start(); err != nil {
				setErrnoArg(args, 2, errnoOf(err))
				return Null
			}
			w.Close()
			f = r
		} else {
			r, w, err := os.Pipe()
			if err != nil {
				setErrnoArg(args, 2, errnoOf(err))
				return Null
			}
			cmd.Stdin = r
			cmd.Stdout = os.Stdout
			cmd.Stderr = os.Stderr
			flushAll()
			if err := cmd.Start(); err != nil {
				setErrnoArg(args, 2, errnoOf(err))
				return Null
			}
			r.Close()
			f = w
		}
		fo := newFileObject(f, false)
		fo.internal.(*FileData).cmd = cmd
		setErrnoArg(args, 2, 0)
		return fo
	})
	m.defineMethod("fdopen", 2, func(this Value, args []Value) Value {
		fd := int(toInt32V(arg(args, 0)))
		f := os.NewFile(uintptr(fd), "fd")
		if f == nil {
			setErrnoArg(args, 2, int(syscall.EBADF))
			return Null
		}
		return newFileObject(f, false)
	})
	m.defineMethod("tmpfile", 0, func(this Value, args []Value) Value {
		f, err := os.CreateTemp("", "qjs")
		if err != nil {
			return Null
		}
		os.Remove(f.Name())
		return newFileObject(f, false)
	})
	m.defineMethod("parseExtJSON", 1, func(this Value, args []Value) Value {
		s := toString(arg(args, 0))
		return parseExtJSON(s)
	})
	m.defineMethod("urlGet", 2, func(this Value, args []Value) Value {
		throwError("Error", "urlGet not supported")
		return nil
	})
	m.setOwn("in", newFileObject(os.Stdin, true), PropDefault)
	m.setOwn("out", newFileObject(os.Stdout, true), PropDefault)
	m.setOwn("err", newFileObject(os.Stderr, true), PropDefault)
	m.setOwn("SEEK_SET", float64(0), PropDefault)
	m.setOwn("SEEK_CUR", float64(1), PropDefault)
	m.setOwn("SEEK_END", float64(2), PropDefault)
	errObj := newObjectRaw(rt.ObjectPrototype, ClassObject)
	for name, v := range map[string]syscall.Errno{"EINVAL": syscall.EINVAL, "EIO": syscall.EIO, "EACCES": syscall.EACCES, "EEXIST": syscall.EEXIST, "ENOSPC": syscall.ENOSPC, "ENOSYS": syscall.ENOSYS, "EBUSY": syscall.EBUSY, "ENOENT": syscall.ENOENT, "EPERM": syscall.EPERM, "EPIPE": syscall.EPIPE, "EBADF": syscall.EBADF} {
		errObj.setOwn(name, float64(v), PropDefault)
	}
	m.setOwn("Error", errObj, PropDefault)
	m.defineMethod("__printObject", 1, func(this Value, args []Value) Value {
		return inspectValue(arg(args, 0))
	})
	return m
}

func setErrnoArg(args []Value, i int, errno int) {
	if i < len(args) {
		if o, ok := args[i].(*Object); ok {
			o.Set(strKey("errno"), float64(errno), o)
		}
	}
}

func parseFopenMode(mode string) (int, bool) {
	if mode == "" {
		return 0, false
	}
	plus := strings.Contains(mode, "+")
	switch mode[0] {
	case 'r':
		if plus {
			return os.O_RDWR, true
		}
		return os.O_RDONLY, true
	case 'w':
		if plus {
			return os.O_RDWR | os.O_CREATE | os.O_TRUNC, true
		}
		return os.O_WRONLY | os.O_CREATE | os.O_TRUNC, true
	case 'a':
		if plus {
			return os.O_RDWR | os.O_CREATE | os.O_APPEND, true
		}
		return os.O_WRONLY | os.O_CREATE | os.O_APPEND, true
	}
	return 0, false
}

func evalScriptText(code string, name string, isModule bool) Value {
	p := NewParser(code, name, isModule)
	prog, err := p.ParseProgram()
	if err != nil {
		se := err.(*SyntaxError)
		e := makeError("SyntaxError", se.Msg)
		e.setOwn("stack", NewStringFromGo(formatSyntaxStack(name, se)), PropHidden)
		panic(&Throw{Val: e})
	}
	src := NewSource(name, code)
	return runScript(src, prog, "<eval>")
}

func parseExtJSON(s *String) Value {
	// Extended JSON: accept JS-like syntax by evaluating as expression in a sandboxed way
	code := "(" + s.String() + ")"
	p := NewParser(code, "<input>", false)
	prog, err := p.ParseProgram()
	if err != nil {
		se := err.(*SyntaxError)
		e := makeError("SyntaxError", se.Msg)
		e.setOwn("stack", NewStringFromGo(formatSyntaxStack("<input>", se)), PropHidden)
		panic(&Throw{Val: e})
	}
	src := NewSource("<input>", code)
	return runScript(src, prog, "<eval>")
}

// ---------- os module ----------

func getOsModule() *Object {
	if rt.osModule != nil {
		return rt.osModule
	}
	m := newObjectRaw(nil, ClassObject)
	rt.osModule = m
	consts := map[string]float64{
		"O_RDONLY": float64(os.O_RDONLY), "O_WRONLY": float64(os.O_WRONLY), "O_RDWR": float64(os.O_RDWR), "O_APPEND": float64(os.O_APPEND),
		"O_CREAT": float64(os.O_CREATE), "O_EXCL": float64(os.O_EXCL), "O_TRUNC": float64(os.O_TRUNC),
		"SIGINT": float64(syscall.SIGINT), "SIGABRT": float64(syscall.SIGABRT), "SIGFPE": float64(syscall.SIGFPE), "SIGILL": float64(syscall.SIGILL), "SIGSEGV": float64(syscall.SIGSEGV), "SIGTERM": float64(syscall.SIGTERM),
		"SIGQUIT": float64(syscall.SIGQUIT), "SIGPIPE": float64(syscall.SIGPIPE), "SIGALRM": float64(syscall.SIGALRM), "SIGUSR1": float64(syscall.SIGUSR1), "SIGUSR2": float64(syscall.SIGUSR2), "SIGCHLD": float64(syscall.SIGCHLD),
		"SIGCONT": float64(syscall.SIGCONT), "SIGSTOP": float64(syscall.SIGSTOP), "SIGTSTP": float64(syscall.SIGTSTP), "SIGTTIN": float64(syscall.SIGTTIN), "SIGTTOU": float64(syscall.SIGTTOU),
		"S_IFMT": float64(syscall.S_IFMT), "S_IFIFO": float64(syscall.S_IFIFO), "S_IFCHR": float64(syscall.S_IFCHR), "S_IFDIR": float64(syscall.S_IFDIR), "S_IFBLK": float64(syscall.S_IFBLK), "S_IFREG": float64(syscall.S_IFREG), "S_IFSOCK": float64(syscall.S_IFSOCK), "S_IFLNK": float64(syscall.S_IFLNK), "S_ISGID": float64(syscall.S_ISGID), "S_ISUID": float64(syscall.S_ISUID),
		"WNOHANG": float64(syscall.WNOHANG),
	}
	for k, v := range consts {
		m.setOwn(k, v, PropDefault)
	}
	m.setOwn("platform", NewStringFromGo("linux"), PropDefault)
	m.defineMethod("open", 3, func(this Value, args []Value) Value {
		name := toGoString(arg(args, 0))
		flags := int(toInt32V(arg(args, 1)))
		mode := uint32(0666)
		if !isUndefined(arg(args, 2)) {
			mode = uint32(toInt32V(args[2]))
		}
		fd, err := syscall.Open(name, flags, mode)
		if err != nil {
			return float64(-errnoOf(err))
		}
		return float64(fd)
	})
	m.defineMethod("close", 1, func(this Value, args []Value) Value {
		err := syscall.Close(int(toInt32V(arg(args, 0))))
		if err != nil {
			return float64(-errnoOf(err))
		}
		return float64(0)
	})
	m.defineMethod("seek", 3, func(this Value, args []Value) Value {
		fd := int(toInt32V(arg(args, 0)))
		off := int64(toNumber(arg(args, 1)))
		whence := int(toInt32V(arg(args, 2)))
		r, err := syscall.Seek(fd, off, whence)
		if err != nil {
			return float64(-errnoOf(err))
		}
		if _, isBig := arg(args, 1).(*big.Int); isBig {
			return big.NewInt(r)
		}
		return float64(r)
	})
	rw := func(name string, write bool) {
		m.defineMethod(name, 4, func(this Value, args []Value) Value {
			fd := int(toInt32V(arg(args, 0)))
			buf, ok := arg(args, 1).(*Object)
			if !ok || buf.class != ClassArrayBuffer {
				throwTypeError("not an ArrayBuffer")
			}
			ab := buf.internal.(*ArrayBufferData)
			pos := int(toIntegerOrInfinity(arg(args, 2)))
			n := int(toIntegerOrInfinity(arg(args, 3)))
			if pos+n > len(ab.data) {
				throwRangeError("read/write array buffer overflow")
			}
			var r int
			var err error
			if write {
				if fd == 1 {
					stdoutWriter.Flush()
				} else if fd == 2 {
					stderrWriter.Flush()
				}
				r, err = syscall.Write(fd, ab.data[pos:pos+n])
			} else {
				r, err = syscall.Read(fd, ab.data[pos:pos+n])
			}
			if err != nil {
				return float64(-errnoOf(err))
			}
			return float64(r)
		})
	}
