func osExec(args []Value) Value {
	argv := createListFromArrayLike(arg(args, 0))
	var sargs []string
	for _, a := range argv {
		sargs = append(sargs, toGoString(a))
	}
	if len(sargs) == 0 {
		throwTypeError("exec: empty argument list")
	}
	block := true
	usePath := true
	var cwd string
	var file string
	var env []string
	stdin, stdout, stderr := 0, 1, 2
	if opts, ok := arg(args, 1).(*Object); ok {
		if v := opts.Get(strKey("block"), opts); !isUndefined(v) {
			block = toBoolean(v)
		}
		if v := opts.Get(strKey("usePath"), opts); !isUndefined(v) {
			usePath = toBoolean(v)
		}
		if v := opts.Get(strKey("cwd"), opts); !isUndefined(v) {
			cwd = toGoString(v)
		}
		if v := opts.Get(strKey("file"), opts); !isUndefined(v) {
			file = toGoString(v)
		}
		if v := opts.Get(strKey("stdin"), opts); !isUndefined(v) {
			stdin = int(toInt32V(v))
		}
		if v := opts.Get(strKey("stdout"), opts); !isUndefined(v) {
			stdout = int(toInt32V(v))
		}
		if v := opts.Get(strKey("stderr"), opts); !isUndefined(v) {
			stderr = int(toInt32V(v))
		}
		if v, ok := opts.Get(strKey("env"), opts).(*Object); ok {
			for _, k := range v.OwnKeys() {
				if k.Sym == nil {
					env = append(env, k.S+"="+toGoString(v.Get(k, v)))
				}
			}
		}
	}
	if file == "" {
		file = sargs[0]
	}
	path := file
	if usePath && !strings.Contains(file, "/") {
		if p, err := exec.LookPath(file); err == nil {
			path = p
		}
	}
	cmd := &exec.Cmd{Path: path, Args: sargs, Dir: cwd}
	if env != nil {
		cmd.Env = env
	}
	cmd.Stdin = os.NewFile(uintptr(stdin), "stdin")
	cmd.Stdout = os.NewFile(uintptr(stdout), "stdout")
	cmd.Stderr = os.NewFile(uintptr(stderr), "stderr")
	flushAll()
	if err := cmd.Start(); err != nil {
		return float64(-errnoOf(err))
	}
	if !block {
		return float64(cmd.Process.Pid)
	}
	err := cmd.Wait()
	if err != nil {
		if ee, ok := err.(*exec.ExitError); ok {
			return float64(ee.ExitCode())
		}
		return float64(-1)
	}
	return float64(0)
}

// ---------- event loop ----------

// runOneJobOrTimer runs pending microtasks; if none, fires the next timer (sleeping if needed). Returns false if nothing to do.
func runOneJobOrTimer() bool {
	if len(rt.jobQueue) > 0 {
		runJobs()
		return true
	}
	if len(rt.timers) == 0 {
		return false
	}
	// pick earliest
	idx := 0
	for i, t := range rt.timers {
		if t.deadline.Before(rt.timers[idx].deadline) {
			idx = i
		}
	}
	t := rt.timers[idx]
	rt.timers = append(rt.timers[:idx], rt.timers[idx+1:]...)
	d := time.Until(t.deadline)
	if d > 0 {
		flushAll()
		time.Sleep(d)
	}
	callFunction(t.fn, Undefined, nil)
	runJobs()
	return true
}

func runEventLoop() {
	for {
		runJobs()
		checkUnhandledRejections()
		if len(rt.timers) == 0 {
			break
		}
		if !runOneJobOrTimer() {
			break
		}
	}
	runJobs()
	checkUnhandledRejections()
}

func checkUnhandledRejections() {
	if rt.noUnhandledRejection {
		rt.rejectionTracker = nil
		return
	}
	for len(rt.rejectionTracker) > 0 {
		p := rt.rejectionTracker[0]
		rt.rejectionTracker = rt.rejectionTracker[1:]
		pd := p.internal.(*PromiseData)
		if pd.handled || pd.reported {
			continue
		}
		pd.reported = true
		flushAll()
		stderrWriter.WriteString("Possibly unhandled promise rejection: ")
		stderrWriter.WriteString(formatUncaught(pd.value))
		stderrWriter.Flush()
		rt.exitCode = 1
	}
}

