	for _, inc := range includes {
		runFile(inc, 0, true)
	}
	exitCode := 0
	if hasEval {
		exitCode = runEvalString(evalExpr)
	} else if len(rest) > 0 {
		exitCode = runFile(rest[0], moduleMode, false)
