func exposeStd() {
	rt.Global.setOwn("std", getStdModule(), PropHidden)
	rt.Global.setOwn("os", getOsModule(), PropHidden)
}

// reportUncaught prints an uncaught exception
func reportUncaught(t *Throw) {
	flushAll()
	stderrWriter.WriteString(formatUncaught(t.Val))
	stderrWriter.Flush()
}

func runProtected(f func()) (exitCode int) {
	defer func() {
		if r := recover(); r != nil {
			if t, ok := r.(*Throw); ok {
				reportUncaught(t)
				exitCode = 1
				return
			}
			if _, ok := r.(*genReturnSignal); ok {
				exitCode = 0
				return
			}
			flushAll()
			fmt.Fprintf(os.Stderr, "InternalError: %v\n", r)
			exitCode = 1
		}
	}()
	f()
	return 0
}

func runEvalString(code string) int {
	rc := runProtected(func() {
		p := NewParser(code, "<cmdline>", false)
		if rt.strictMode {
			p.forceStrict = true
		}
		prog, err := p.ParseProgram()
		if err != nil {
			se := err.(*SyntaxError)
			e := makeError("SyntaxError", se.Msg)
			e.setOwn("stack", NewStringFromGo(formatSyntaxStack("<cmdline>", se)), PropHidden)
			panic(&Throw{Val: e})
		}
		src := NewSource("<cmdline>", code)
		runScript(src, prog, "<eval>")
	})
	if rc != 0 {
		return rc
	}
	return afterScript()
}

// afterScript drains jobs and checks for unhandled rejections; returns exit code
func afterScript() int {
	rc := runProtected(func() {
		runJobs()
	})
	if rc != 0 {
		return rc
	}
	checkUnhandledRejections()
	if rt.exitCode != 0 {
		return rt.exitCode
	}
	return 0
}

func detectModule(name string, text string) bool {
	if strings.HasSuffix(name, ".mjs") {
		return true
	}
	// quick scan for top-level import/export keywords
	p := NewParser(text, name, false)
	lx := p.lex
	depth := 0
	for {
		var tok Token
		ok := func() bool {
			defer func() {
				if r := recover(); r != nil {
					ok := false
					_ = ok
				}
			}()
			tok = lx.Next()
			return true
		}()
		if !ok || tok.Kind == TEOF {
			return false
		}
		if tok.Kind == TPunct {
			switch tok.Val {
			case "{", "(", "[":
				depth++
			case "}", ")", "]":
				depth--
			}
		}
		if tok.Kind == TKeyword && depth == 0 && (tok.Val == "import" || tok.Val == "export") {
			if tok.Val == "import" {
				// import( or import. is not a declaration
				save := lx.State()
				nt := lx.Next()
				lx.ResetTo(save)
				if nt.Kind == TPunct && (nt.Val == "(" || nt.Val == ".") {
					continue
				}
			}
			return true
		}
	}
}

func (l *Lexer) ResetTo(st [3]int) {
	l.pos, l.line, l.lineStart = st[0], st[1], st[2]
}

func (l *Lexer) State() [3]int { return [3]int{l.pos, l.line, l.lineStart} }

func runFile(name string, moduleMode int, isInclude bool) int {
	data, err := os.ReadFile(name)
	if err != nil {
		flushAll()
		fmt.Fprintf(os.Stderr, "%s: %s\n", name, syscallErrString(err))
		return 1
	}
	text := string(data)
	isModule := false
	if moduleMode == 1 {
		isModule = true
	} else if moduleMode == -1 {
		isModule = detectModule(name, text)
	}
	rc := runProtected(func() {
		if isModule {
			m := parseModule(name, text)
			rt.mainModule = m
			linkModule(m)
			evaluateModule(m)
		} else {
			p := NewParser(text, name, false)
			if rt.strictMode {
				p.forceStrict = true
			}
			prog, err := p.ParseProgram()
			if err != nil {
				se := err.(*SyntaxError)
				e := makeError("SyntaxError", se.Msg)
				e.setOwn("stack", NewStringFromGo(formatSyntaxStack(name, se)), PropHidden)
				panic(&Throw{Val: e})
			}
			src := NewSource(name, text)
			runScript(src, prog, "<eval>")
		}
	})
	if rc != 0 {
		return rc
	}
	if isInclude {
		return 0
	}
	return afterScript()
}

func syscallErrString(err error) string {
	if pe, ok := err.(*os.PathError); ok {
		err = pe.Err
	}
	s := err.Error()
	if len(s) > 0 {
		s = strings.ToUpper(s[:1]) + s[1:]
	}
	return s
}

func runREPL() {
	flushAll()
	fmt.Print("QuickJS - Type \"\\h\" for help\n")
	reader := bufio.NewReader(os.Stdin)
	for {
		fmt.Print("qjs > ")
		line, err := reader.ReadString('\n')
		if err != nil && line == "" {
			fmt.Print("\n")
			break
		}
		line = strings.TrimRight(line, "\r\n")
		if line == "" {
			continue
		}
		if line == "\\q" {
			break
		}
		if line == "\\h" {
			fmt.Print("\\h          this help\n\\q          exit\n")
			continue
		}
		runProtected(func() {
			p := NewParser(line, "<evalScript>", false)
			prog, err := p.ParseProgram()
			if err != nil {
				se := err.(*SyntaxError)
				e := makeError("SyntaxError", se.Msg)
				e.setOwn("stack", NewStringFromGo(formatSyntaxStack("<evalScript>", se)), PropHidden)
				panic(&Throw{Val: e})
			}
			src := NewSource("<evalScript>", line)
			v := runScript(src, prog, "<eval>")
			runJobs()
			s := inspectValueQuoted(v)
			stdoutWriter.WriteString(s.String() + "\n")
			flushAll()
		})
		runJobs()
		flushAll()
	}
}

func dumpMemoryStats() {
	fmt.Fprintf(os.Stdout, "QuickJS memory usage -- %s version, 64-bit, malloc limit: -1\n", versionString)
}

