// normalizeString: minimal Unicode normalization supporting common Latin composed characters
func normalizeString(s *String, form string) *String {
	if s.isASCII {
		return s
	}
	switch form {
	case "NFD", "NFKD":
		sb := NewStringBuilder()
		for i := 0; i < s.Len(); {
			cp, n := s.CodePointAt(i)
			i += n
			if d, ok := decompTable[cp]; ok {
				for _, r := range d {
					sb.WriteRune(r)
				}
			} else {
				sb.WriteRune(cp)
			}
		}
		return sb.String()
	default:
		// compose: base + combining mark -> composed
		var cps []rune
		for i := 0; i < s.Len(); {
			cp, n := s.CodePointAt(i)
			i += n
			cps = append(cps, cp)
		}
		sb := NewStringBuilder()
		for i := 0; i < len(cps); i++ {
