package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

const versionString = "2025-09-13"

func usage(out *os.File) {
	fmt.Fprintf(out, "QuickJS version %s\n", versionString)
	fmt.Fprint(out, `usage: qjs [options] [file [args]]
-h  --help         list options
-e  --eval EXPR    evaluate EXPR
-i  --interactive  go to interactive mode
-m  --module       load as ES6 module (default=autodetect)
    --script       load as ES6 script (default=autodetect)
    --strict       force strict mode
-I  --include file include an additional file
    --std          make 'std' and 'os' available to the loaded script
-T  --trace        trace memory allocation
-d  --dump         dump the memory usage stats
    --memory-limit n  limit the memory usage to 'n' bytes (SI suffixes allowed)
    --stack-size n    limit the stack size to 'n' bytes (SI suffixes allowed)
    --no-unhandled-rejection  ignore unhandled promise rejections
-s                    strip all the debug info
    --strip-source    strip the source code
-q  --quit         just instantiate the interpreter and quit
`)
}

func main() {
	args := os.Args[1:]
	var evalExpr string
	hasEval := false
	interactive := false
	moduleMode := -1 // -1 autodetect, 0 script, 1 module
	forceStrict := false
	loadStd := false
	dump := false
	quit := false
	noUnhandled := false
	var includes []string
	i := 0
	for i < len(args) {
		a := args[i]
		if !strings.HasPrefix(a, "-") || a == "-" {
			break
		}
		if a == "--" {
			i++
			break
		}
		opt := a
		longopt := ""
		if strings.HasPrefix(a, "--") {
			longopt = a[2:]
		}
		needArg := func(name string) string {
			if i+1 >= len(args) {
				fmt.Fprintf(os.Stderr, "qjs: missing %s for %s\n", name, a)
				os.Exit(2)
			}
			i++
			return args[i]
		}
		switch {
		case opt == "-h" || longopt == "help":
			usage(os.Stdout)
			os.Exit(1)
		case opt == "-e" || longopt == "eval":
			evalExpr = needArg("expression")
			hasEval = true
		case opt == "-i" || longopt == "interactive":
			interactive = true
		case opt == "-m" || longopt == "module":
			moduleMode = 1
		case longopt == "script":
			moduleMode = 0
		case longopt == "strict":
			forceStrict = true
		case opt == "-I" || longopt == "include":
			includes = append(includes, needArg("filename"))
		case longopt == "std":
			loadStd = true
		case opt == "-T" || longopt == "trace":
		case opt == "-d" || longopt == "dump":
			dump = true
		case longopt == "memory-limit":
			needArg("memory limit")
		case longopt == "stack-size":
			needArg("stack size")
		case longopt == "no-unhandled-rejection":
			noUnhandled = true
		case opt == "-s":
		case longopt == "strip-source":
		case opt == "-q" || longopt == "quit":
			quit = true
		default:
			// combined short options like -ie ?
			if len(opt) > 2 && opt[1] != '-' {
				// expand
				rest := []string{}
				for _, c := range opt[1:] {
					rest = append(rest, "-"+string(c))
				}
				args = append(args[:i], append(rest, args[i+1:]...)...)
				continue
			}
			fmt.Fprintf(os.Stderr, "qjs: unknown option '%s'\n", a)
			usage(os.Stderr)
			os.Exit(1)
		}
		i++
	}
	rest := args[i:]
	setupRealm()
	rt.noUnhandledRejection = noUnhandled
	rt.strictMode = forceStrict
	rt.dumpMemory = dump
	defer flushAll()
	if quit {
		flushAll()
		os.Exit(0)
	}
	// scriptArgs
	var scriptArgs []string
	if len(rest) > 0 {
		scriptArgs = rest
	}
	setScriptArgs(scriptArgs)
	if loadStd {
		exposeStd()
	}
	for _, inc := range includes {
		runFile(inc, 0, true)
	}
	exitCode := 0
	if hasEval {
		exitCode = runEvalString(evalExpr)
