// shortestDigitsRadix implements the Steele & White / Dragon4 free-format algorithm in an arbitrary radix.
// Returns digit string and exponent k such that value = 0.digits * radix^k
func shortestDigitsRadix(v float64, radix int) (string, int) {
	bits := math.Float64bits(v)
	exp := int((bits >> 52) & 0x7FF)
	mant := bits & ((1 << 52) - 1)
	var f uint64
	var e int
	if exp == 0 {
		f = mant
		e = -1074
	} else {
		f = mant | (1 << 52)
		e = exp - 1075
	}
	// value = f * 2^e
	R := new(big.Int).SetUint64(f)
	S := big.NewInt(1)
	Mp := big.NewInt(1)
	Mm := big.NewInt(1)
