	tmp := new(big.Int)
	for {
		tmp.Lsh(R, 1)
		tmp.Add(tmp, Mp)
		s2 := new(big.Int).Lsh(S, 1)
		c := tmp.Cmp(s2)
		if c > 0 || (c == 0 && even) {
