// shortestDigitsRadix implements the Steele & White / Dragon4 free-format algorithm in an arbitrary radix.
// Returns digit string and exponent k such that value = 0.digits * radix^k
func shortestDigitsRadix(v float64, radix int) (string, int) {
	bits := math.Float64bits(v)
	exp := int((bits >> 52) & 0x7FF)
	mant := bits & ((1 << 52) - 1)
	var f uint64
	var e int
	if exp == 0 {
		f = mant
		e = -1074
	} else {
		f = mant | (1 << 52)
		e = exp - 1075
	}
	// value = f * 2^e
	R := new(big.Int).SetUint64(f)
	S := big.NewInt(1)
	Mp := big.NewInt(1)
	Mm := big.NewInt(1)
	if e >= 0 {
		R.Lsh(R, uint(e))
		Mp.Lsh(Mp, uint(e))
		Mm.Lsh(Mm, uint(e))
	} else {
		S.Lsh(S, uint(-e))
	}
	// handle unequal gaps when f is a power of two (and not the smallest exponent)
	if mant == 0 && exp > 1 {
		R.Lsh(R, 1)
		S.Lsh(S, 1)
		Mp.Lsh(Mp, 1)
	}
	// R/S = v, M+/S and M-/S are half gaps... Actually Mp,Mm represent full ulp; we use 2R comparisons below.
	even := f%2 == 0
	bigRadix := big.NewInt(int64(radix))
	// estimate k = ceil(log_radix(v))
	k := int(math.Ceil(math.Log(v) / math.Log(float64(radix))))
	// scale so that R/S < 1 : if k>=0, S *= radix^k else R,Mp,Mm *= radix^-k
	if k >= 0 {
		S.Mul(S, new(big.Int).Exp(bigRadix, big.NewInt(int64(k)), nil))
	} else {
		p := new(big.Int).Exp(bigRadix, big.NewInt(int64(-k)), nil)
		R.Mul(R, p)
		Mp.Mul(Mp, p)
		Mm.Mul(Mm, p)
	}
	// fixup: ensure (2R + M+) < 2S  i.e. high boundary < 1, else k++
	tmp := new(big.Int)
	for {
		tmp.Lsh(R, 1)
		tmp.Add(tmp, Mp)
		s2 := new(big.Int).Lsh(S, 1)
		c := tmp.Cmp(s2)
		if c > 0 || (c == 0 && even) {
			S.Mul(S, bigRadix)
			k++
		} else {
			break
		}
	}
	// also ensure first digit is nonzero: (2R + M+) * radix >= 2S
	for {
		tmp.Lsh(R, 1)
		tmp.Add(tmp, Mp)
		tmp.Mul(tmp, bigRadix)
		s2 := new(big.Int).Lsh(S, 1)
		c := tmp.Cmp(s2)
		if c < 0 || (c == 0 && !even) {
			R.Mul(R, bigRadix)
			Mp.Mul(Mp, bigRadix)
			Mm.Mul(Mm, bigRadix)
			k--
		} else {
			break
		}
	}
	var sb strings.Builder
	q := new(big.Int)
	for {
		R.Mul(R, bigRadix)
		Mp.Mul(Mp, bigRadix)
		Mm.Mul(Mm, bigRadix)
		q.QuoRem(R, S, R)
		d := int(q.Int64())
		// low: 2R < M-  (<= if even)
		r2 := new(big.Int).Lsh(R, 1)
		c1 := r2.Cmp(Mm)
		low := c1 < 0 || (c1 == 0 && even)
		// high: 2R + M+ > 2S (>= if even)
		t2 := new(big.Int).Add(r2, Mp)
		s2 := new(big.Int).Lsh(S, 1)
		c2 := t2.Cmp(s2)
		high := c2 > 0 || (c2 == 0 && even)
		if !low && !high {
			sb.WriteByte(digitChars[d])
			continue
		}
		if low && !high {
			sb.WriteByte(digitChars[d])
		} else if high && !low {
			sb.WriteByte(digitChars[d+1])
		} else {
			// both: compare 2R with S
			c := r2.Cmp(S)
			if c < 0 || (c == 0 && d%2 == 0) {
				sb.WriteByte(digitChars[d])
			} else {
				sb.WriteByte(digitChars[d+1])
			}
		}
		break
	}
	return sb.String(), k
}

