func toArrayLengthValue(v Value) (uint32, bool) {
	n := toNumber(v)
	u := toUint32(n)
	if float64(u) != n {
		return 0, false
	}
	return u, true
}

func isFullDataDesc(d PropDesc) bool {
	return !d.IsAccessor() && d.HasWritable && d.Writable && d.HasEnumerable && d.Enumerable && d.HasConfigurable && d.Configurable
}

func arrayDefineIndex(o *Object, idx uint32, d PropDesc) bool {
	ad := o.arrayData()
	if idx >= ad.length && !ad.lengthWritable {
		return false
	}
	if !ad.sparse {
		if int(idx) < len(o.arr) {
			// existing element: plain data update keeps fast mode
			if !d.IsAccessor() && (!d.HasWritable || d.Writable) && (!d.HasEnumerable || d.Enumerable) && (!d.HasConfigurable || d.Configurable) {
				if d.HasValue {
					o.arr[idx] = d.Value
				}
				return true
			}
			arrayMakeSparse(o)
		} else if int(idx) == len(o.arr) && isFullDataDesc(d) && o.extensible {
			v := d.Value
			if !d.HasValue {
				v = Undefined
			}
			o.arr = append(o.arr, v)
			if idx >= ad.length {
				ad.length = idx + 1
			}
			return true
		} else {
			if !o.extensible {
				return false
			}
			arrayMakeSparse(o)
		}
	}
	if !o.defineOrdinary(strKey(uint32ToString(idx)), d) {
		return false
	}
	if idx >= ad.length {
		ad.length = idx + 1
	}
	return true
}

