new = '''func (in *inspector) printArray(o *Object, depth int) {
	n := int(arrayLength(o))
	in.sb.WriteGo("[")
	count := 0
	first := true
	writeSep := func() {
		if !first {
			in.sb.WriteGo(",")
		}
		in.sb.WriteGo(" ")
		first = false
	}
	if !ad_sparse(o) {
		for _, v := range o.arr {
			if count >= inspectMaxItems {
				writeSep()
				in.sb.WriteGo("... " + itoa(n-count) + moreItems(n-count))
				break
			}
			writeSep()
			in.print(v, depth+1)
			count++
		}
		if count < inspectMaxItems && n > len(o.arr) {
			empty := n - len(o.arr)
			writeSep()
			in.sb.WriteGo("<" + itoa(empty) + " empty item")
			if empty != 1 {
				in.sb.WriteGo("s")
			}
			in.sb.WriteGo(">")
		}
	} else {
		// insertion order of index properties
		var idxKeys []PropKey
		for i := range o.props.entries {
			k := o.props.entries[i].key
			if k.Sym == nil && isIntegerIndexString(k.S) {
				idxKeys = append(idxKeys, k)
			}
		}
		for _, k := range idxKeys {
			if count >= inspectMaxItems {
				writeSep()
				in.sb.WriteGo("... " + itoa(len(idxKeys)-count) + moreItems(len(idxKeys)-count))
				break
			}
			p := o.props.Get(k)
			if p == nil || !p.Enumerable() {
				continue
			}
			writeSep()
			in.sb.WriteGo(k.S + ": ")
			in.printPropValue(p, depth)
			count++
		}
	}
	// extra props
	keys := enumerableKeysForInspect(o, func(k PropKey) bool { return k.Sym == nil && isIntegerIndexString(k.S) })
	for _, k := range keys {
		writeSep()
		in.printProp(o, k, depth)
	}
	if first {
		in.sb.WriteGo(" ")
	}
	in.sb.WriteGo(" ]")
}

func (in *inspector) printPropValue(p *Prop, depth int) {
	if p.IsAccessor() {
		hasG := !isUndefined(p.Getter)
		hasS := !isUndefined(p.Setter)
		switch {
		case hasG && hasS:
			in.sb.WriteGo("[Getter/Setter]")
		case hasG:
			in.sb.WriteGo("[Getter]")
		case hasS:
			in.sb.WriteGo("[Setter]")
		default:
			in.sb.WriteGo("undefined")
		}
		return
	}
	in.print(p.Value, depth+1)
}

