// fast mode: o.arr holds elements 0..len(arr)-1 with no holes; ad.length >= len(arr)
// sparse mode: elements live in o.props; ad.length is the length

func newArrayObject(elems []Value) *Object {
	o := newObjectRaw(rt.ArrayPrototype, ClassArray)
	o.arr = elems
	o.internal = &ArrayData{length: uint32(len(elems)), lengthWritable: true}
	return o
}

// newArrayFromLiteral builds an array from elements which may contain the hole marker
func newArrayFromLiteral(elems []Value) *Object {
	hasHole := false
	for _, v := range elems {
		if v == hole {
			hasHole = true
			break
		}
	}
	if !hasHole {
		return newArrayObject(elems)
	}
	o := newArrayObject(nil)
	ad := o.arrayData()
	ad.sparse = true
	ad.length = uint32(len(elems))
	for i, v := range elems {
		if v != hole {
			o.props.Set(strKey(uint32ToString(uint32(i))), Prop{Value: v, Flags: PropDefault})
		}
	}
	return o
}

func arrayLength(o *Object) uint32 {
	return o.arrayData().length
}

// arrayAppend appends to a fast array (caller ensures fast mode and no trailing empties)
func arrayAppend(o *Object, v Value) {
	o.arr = append(o.arr, v)
	o.arrayData().length = uint32(len(o.arr))
}

// arrayIsDenseFast reports whether o is a fast array with length == element count
func arrayIsDenseFast(o *Object) bool {
	ad := o.arrayData()
	return !ad.sparse && int(ad.length) == len(o.arr)
}

func arrayMakeSparse(o *Object) {
	ad := o.arrayData()
	if ad.sparse {
		return
	}
	for i, v := range o.arr {
		o.props.Set(strKey(uint32ToString(uint32(i))), Prop{Value: v, Flags: PropDefault})
	}
	o.arr = nil
	ad.sparse = true
}

func arraySetLength(o *Object, d PropDesc) bool {
	ad := o.arrayData()
	if d.IsAccessor() {
		return false
	}
	if d.HasConfigurable && d.Configurable {
		return false
	}
	if d.HasEnumerable && d.Enumerable {
		return false
	}
	if !d.HasValue {
		if d.HasWritable {
			if d.Writable && !ad.lengthWritable {
				return false
			}
			if !d.Writable {
				ad.lengthWritable = false
			}
		}
		return true
	}
	newLen, ok := toArrayLengthValue(d.Value)
	if !ok {
		throwRangeError("invalid array length")
	}
	oldLen := ad.length
