			count++
		}
	}
	// extra props
	keys := enumerableKeysForInspect(o, func(k PropKey) bool { return k.Sym == nil && isIntegerIndexString(k.S) })
	for _, k := range keys {
		writeSep()
		in.printProp(o, k, depth)
	}
	if first {
		in.sb.WriteGo(" ")
	}
	in.sb.WriteGo(" ]")
}

func (in *inspector) printPropValue(p *Prop, depth int) {
	if p.IsAccessor() {
		hasG := !isUndefined(p.Getter)
		hasS := !isUndefined(p.Setter)
		switch {
		case hasG && hasS:
			in.sb.WriteGo("[Getter/Setter]")
		case hasG:
			in.sb.WriteGo("[Getter]")
		case hasS:
			in.sb.WriteGo("[Setter]")
		default:
			in.sb.WriteGo("undefined")
		}
		return
	}
	in.print(p.Value, depth+1)
}

