package main

// applyBuiltinPropOrder reorders own properties of builtin objects to match the reference implementation
func applyBuiltinPropOrder() {
	g := rt.Global
	resolve := func(path string) *Object {
		switch path {
		case "globalThis":
			return g
		case "ArrayIteratorPrototype":
			return rt.ArrayIteratorPrototype
		case "StringIteratorPrototype":
			return rt.StringIteratorPrototype
		case "MapIteratorPrototype":
			return rt.MapIteratorPrototype
		case "SetIteratorPrototype":
			return rt.SetIteratorPrototype
		case "RegExpStringIteratorPrototype":
			return rt.RegExpStringIteratorPrototype
		case "GeneratorPrototype":
			return rt.GeneratorPrototype
		case "AsyncGeneratorPrototype":
			return rt.AsyncGeneratorPrototype
		case "GeneratorFunction":
			return rt.GeneratorFunctionPrototype.props.Get(strKey("constructor")).Value.(*Object)
		case "GeneratorFunction.prototype":
			return rt.GeneratorFunctionPrototype
		case "AsyncFunction":
			return rt.AsyncFunctionPrototype.props.Get(strKey("constructor")).Value.(*Object)
		case "AsyncFunction.prototype":
			return rt.AsyncFunctionPrototype
		case "AsyncGeneratorFunction":
			return rt.AsyncGeneratorFunctionPrototype.props.Get(strKey("constructor")).Value.(*Object)
		case "AsyncGeneratorFunction.prototype":
			return rt.AsyncGeneratorFunctionPrototype
		case "TypedArray":
			return rt.TypedArrayCtor
		case "TypedArray.prototype":
			return rt.TypedArrayPrototype
		case "IteratorHelperPrototype":
			return rt.IteratorHelperPrototype
		case "AsyncIteratorPrototype":
			return rt.AsyncIteratorPrototype
		case "WrapForValidIteratorPrototype":
			return rt.WrapForValidIteratorPrototype
		case "FILE.prototype":
			return filePrototype
		}
		name := path
		isProto := false
		if len(path) > 10 && path[len(path)-10:] == ".prototype" {
			name = path[:len(path)-10]
			isProto = true
		}
		p := g.props.Get(strKey(name))
		if p == nil {
			return nil
		}
		o, ok := p.Value.(*Object)
		if !ok {
			return nil
		}
		if isProto {
			pp := o.props.Get(strKey("prototype"))
			if pp == nil {
				return nil
			}
			po, ok := pp.Value.(*Object)
			if !ok {
				return nil
			}
			return po
		}
		return o
	}
	for path, order := range builtinPropOrder {
		o := resolve(path)
		if o == nil {
			continue
		}
		reorderProps(o, order)
	}
}

var wellKnownSymbolsByName = map[string]*Symbol{
	"Symbol.iterator": SymIterator, "Symbol.asyncIterator": SymAsyncIterator, "Symbol.hasInstance": SymHasInstance, "Symbol.toPrimitive": SymToPrimitive,
	"Symbol.toStringTag": SymToStringTag, "Symbol.species": SymSpecies, "Symbol.isConcatSpreadable": SymIsConcatSpreadable, "Symbol.unscopables": SymUnscopables,
	"Symbol.match": SymMatch, "Symbol.matchAll": SymMatchAll, "Symbol.replace": SymReplace, "Symbol.search": SymSearch, "Symbol.split": SymSplit,
}

func reorderProps(o *Object, order []string) {
	var entries []propEntry
	used := map[PropKey]bool{}
	for _, name := range order {
		var k PropKey
		if len(name) > 2 && name[:2] == "@@" {
			sym := wellKnownSymbolsByName[name[2:]]
			if sym == nil {
				continue
			}
			k = symKey(sym)
		} else {
			k = strKey(name)
		}
		i := o.props.find(k)
		if i < 0 {
			continue
		}
		entries = append(entries, o.props.entries[i])
		used[k] = true
	}
	for _, e := range o.props.entries {
		if !used[e.key] {
			entries = append(entries, e)
		}
	}
	o.props.entries = entries
	if o.props.index != nil {
		o.props.index = make(map[PropKey]int, len(entries))
		for i, e := range entries {
			o.props.index[e.key] = i
		}
	}
}
