	"==": opEq, "!=": opNe, "===": opStrictEq, "!==": opStrictNe, "<": opLt, ">": opGt, "<=": opLe, ">=": opGe, "instanceof": opInstanceof, "in": opIn}

// binaryOpCode evaluates a binary operator given its opcode
func binaryOpCode(opc int, l, r Value) Value {
	switch opc {
	case opAdd:
		if x, ok := l.(float64); ok {
			if y, ok := r.(float64); ok {
				return boxNum(x + y)
			}
		}
		return jsAdd(l, r)
	case opSub, opMul, opDiv, opMod, opPow, opBitAnd, opBitOr, opBitXor, opShl, opShr, opUShr:
		if x, ok := l.(float64); ok {
			if y, ok := r.(float64); ok {
				return boxNum(numArithCode(opc, x, y))
			}
		}
		return jsArith(opNames[opc], l, r)
	case opEq:
		return looseEquals(l, r)
	case opNe:
		return !looseEquals(l, r)
	case opStrictEq:
		return strictEquals(l, r)
	case opStrictNe:
		return !strictEquals(l, r)
	case opLt:
