package main

import (
	"encoding/binary"
	"fmt"
	"time"
)

func tzifFromPosix(tz string) []byte {
	hdr := func(ver byte) []byte {
		b := make([]byte, 44)
		copy(b, "TZif")
		b[4] = ver
		// counts: isutcnt, isstdcnt, leapcnt, timecnt, typecnt, charcnt
		binary.BigEndian.PutUint32(b[20:], 0)
		binary.BigEndian.PutUint32(b[24:], 0)
		binary.BigEndian.PutUint32(b[28:], 0)
		binary.BigEndian.PutUint32(b[32:], 0)
		binary.BigEndian.PutUint32(b[36:], 1)
		binary.BigEndian.PutUint32(b[40:], 4)
		return b
	}
	body := func() []byte {
		// one ttinfo: utoff=0, isdst=0, abbrind=0 ; chars "UTC\0"
		b := make([]byte, 6)
		return append(b, []byte("UTC\x00")...)
	}
	out := append(hdr('2'), body()...)
	out = append(out, hdr('2')...)
	out = append(out, body()...)
	out = append(out, '\n')
	out = append(out, []byte(tz)...)
	out = append(out, '\n')
	return out
}

func main() {
	loc, err := time.LoadLocationFromTZData("EST5EDT", tzifFromPosix("EST5EDT,M3.2.0,M11.1.0"))
	fmt.Println(err)
	if err == nil {
		t := time.Date(2024, 7, 4, 16, 30, 0, 0, time.UTC).In(loc)
		fmt.Println(t)
		t2 := time.Date(2024, 1, 15, 13, 0, 0, 0, time.UTC).In(loc)
