func tzifFromPosix(tz string) []byte {
	hdr := func(ver byte) []byte {
		b := make([]byte, 44)
		copy(b, "TZif")
		b[4] = ver
		// counts: isutcnt, isstdcnt, leapcnt, timecnt, typecnt, charcnt
		binary.BigEndian.PutUint32(b[20:], 0)
		binary.BigEndian.PutUint32(b[24:], 0)
		binary.BigEndian.PutUint32(b[28:], 0)
		binary.BigEndian.PutUint32(b[32:], 0)
		binary.BigEndian.PutUint32(b[36:], 1)
		binary.BigEndian.PutUint32(b[40:], 4)
		return b
	}
